
:root{
  --bg:#F2F4F7; --surface:#FFFFFF; --surface-2:#E9EDF2; --surface-3:#DDE3EA;
  --ink:#141D2B; --ink-2:#4A566B; --ink-3:#7A8599; --line:#D5DBE3; --line-2:#E4E8EE;
  --accent:#0E9BD8; --accent-hover:#0B84B8; --accent-ink:#FFFFFF; --accent-soft:#DCF1FB;
  --side:#141D2B; --side-ink:#C9D3E0; --side-ink-strong:#FFFFFF; --side-hover:#1F2B3E; --side-active:#0E9BD8;
  --danger:#D9483F; --danger-soft:#FDE7E5; --ok:#0F8C78; --ok-soft:#DDF4EF; --warn:#C27C00; --warn-soft:#FEF1D5;
  --shadow:0 1px 2px rgba(20,29,43,.06),0 4px 14px rgba(20,29,43,.06);
  --display:"Archivo","Arial Narrow",system-ui,sans-serif;
  --body:"Public Sans",system-ui,-apple-system,"Segoe UI",sans-serif;
  --mono:"IBM Plex Mono",ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  --r:8px;
}
@media (prefers-color-scheme: dark){
  :root:not([data-theme="light"]){
    color-scheme:dark;
    --bg:#0D131C; --surface:#141C28; --surface-2:#1B2533; --surface-3:#243041;
    --ink:#E5EAF1; --ink-2:#A3AFC1; --ink-3:#77849A; --line:#2A3648; --line-2:#212C3B;
    --accent:#38AFDA; --accent-hover:#5BC0E4; --accent-ink:#04202C; --accent-soft:#123447;
    --side:#090E15; --side-ink:#9FACBF; --side-ink-strong:#FFFFFF; --side-hover:#152031; --side-active:#0E9BD8;
    --danger:#F2766F; --danger-soft:#3B1C1B; --ok:#3CC7AE; --ok-soft:#0F2E29; --warn:#FCB122; --warn-soft:#3A2C0D;
    --shadow:0 1px 2px rgba(0,0,0,.3),0 6px 18px rgba(0,0,0,.25);
  }
}
:root[data-theme="dark"]{
  color-scheme:dark;
  --bg:#0D131C; --surface:#141C28; --surface-2:#1B2533; --surface-3:#243041;
  --ink:#E5EAF1; --ink-2:#A3AFC1; --ink-3:#77849A; --line:#2A3648; --line-2:#212C3B;
  --accent:#38AFDA; --accent-hover:#5BC0E4; --accent-ink:#04202C; --accent-soft:#123447;
  --side:#090E15; --side-ink:#9FACBF; --side-ink-strong:#FFFFFF; --side-hover:#152031; --side-active:#0E9BD8;
  --danger:#F2766F; --danger-soft:#3B1C1B; --ok:#3CC7AE; --ok-soft:#0F2E29; --warn:#FCB122; --warn-soft:#3A2C0D;
  --shadow:0 1px 2px rgba(0,0,0,.3),0 6px 18px rgba(0,0,0,.25);
}
*{box-sizing:border-box}
html,body{height:100%}
body{background:var(--bg);color:var(--ink);font-family:var(--body);font-size:14px;line-height:1.45;-webkit-font-smoothing:antialiased}
button,input,select,textarea{font:inherit;color:inherit}
a{color:var(--accent)}
.app{display:grid;grid-template-columns:220px 1fr;min-height:100%}
/* sidebar */
.side{background:var(--side);color:var(--side-ink);padding:18px 12px;display:flex;flex-direction:column;gap:18px;position:sticky;top:0;height:100vh}
.brand{display:flex;flex-direction:column;gap:2px;padding:4px 10px 10px;border-bottom:1px solid rgba(255,255,255,.08)}
.brand b{font-family:var(--display);font-stretch:75%;font-weight:800;font-size:24px;letter-spacing:.01em;color:var(--side-ink-strong);line-height:1}
.brand span{font-family:var(--mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--side-ink)}
.nav{display:flex;flex-direction:column;gap:2px}
.nav a{display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:6px;color:var(--side-ink);text-decoration:none;font-weight:500}
.nav a:hover{background:var(--side-hover);color:var(--side-ink-strong)}
.nav a.on{background:var(--side-active);color:#fff}
.nav svg{width:17px;height:17px;flex:none;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.nav .count{margin-left:auto;font-family:var(--mono);font-size:11px;opacity:.8}
.side .btn-new{margin-top:auto}
.side .btn-side{text-transform:uppercase;letter-spacing:.06em;font-weight:800;text-align:center;justify-content:center;text-decoration:none}
@media (min-width:821px){.side .btn-side+.btn-side{margin-top:-8px}}
.btn-ship{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:10px;border:2px solid #2E9D5B;background:color-mix(in srgb,#2E9D5B 18%,transparent);color:var(--side-ink-strong);font-weight:700;font-size:14px;text-decoration:none;margin-top:-8px}
.btn-ship:hover,.btn-ship.on{background:#2E9D5B;color:#fff}
.btn-ship svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;flex:none}
.btn-ship .badge{margin-left:auto}
.side-foot{font-size:11px;color:var(--side-ink);opacity:.7;padding:0 10px}
/* main */
.main{padding-block:24px 60px;padding-inline:28px;min-width:0}
.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:18px}
h1{font-family:var(--display);font-stretch:80%;font-weight:750;font-size:30px;line-height:1.05;margin:0;letter-spacing:-.005em;text-wrap:balance}
h2{font-family:var(--display);font-stretch:85%;font-weight:700;font-size:17px;margin:0;letter-spacing:.005em}
.eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--ink-3)}
.muted{color:var(--ink-2)}
.faint{color:var(--ink-3)}
.mono{font-family:var(--mono)}
.num{font-variant-numeric:tabular-nums}
/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:1px solid var(--line);background:var(--surface);color:var(--ink);padding:7px 13px;border-radius:6px;cursor:pointer;font-weight:600;font-size:13px;text-decoration:none;white-space:nowrap}
.btn:hover{border-color:var(--ink-3)}
.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}
.btn.primary:hover{background:var(--accent-hover);border-color:var(--accent-hover)}
.btn.ghost{background:transparent;border-color:transparent;color:var(--ink-2)}
.btn.ghost:hover{background:var(--surface-2);color:var(--ink)}
.btn.danger{color:var(--danger)}
.btn.danger.armed{background:var(--danger);border-color:var(--danger);color:#fff}
.btn.sm{padding:4px 9px;font-size:12px}
.btn.icon{padding:5px 7px}
.btn:focus-visible,.nav a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,.card-job:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.btn-new{width:100%}
/* inputs */
.field{display:flex;flex-direction:column;gap:4px;min-width:0}
.field label,.lbl{font-size:11.5px;font-weight:600;color:var(--ink-2);letter-spacing:.02em}
input[type=text],input[type=number],input[type=date],input[type=email],input[type=tel],input[type=search],select,textarea{background:var(--surface);border:1px solid var(--line);border-radius:6px;padding:7px 9px;width:100%;min-width:0}
textarea{resize:vertical;min-height:70px}
input:focus,select:focus,textarea:focus{border-color:var(--accent);outline:none}
input[type=number]{font-variant-numeric:tabular-nums}
.check{display:inline-flex;align-items:center;gap:7px;font-size:13px;cursor:pointer}
.check input{width:15px;height:15px;accent-color:var(--accent)}
/* panels */
.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--r)}
.panel-h{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line-2)}
.panel-b{padding:16px}
.grid{display:grid;gap:12px}
.g2{grid-template-columns:repeat(2,minmax(0,1fr))}
.g3{grid-template-columns:repeat(3,minmax(0,1fr))}
.g4{grid-template-columns:repeat(4,minmax(0,1fr))}
.stack{display:flex;flex-direction:column;gap:14px}
.row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.spacer{flex:1}
/* stats */
.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;margin-bottom:18px}
.stat{background:var(--surface);padding:14px 16px;display:flex;flex-direction:column;gap:4px;cursor:pointer;text-align:left;border:0}
.stat:hover{background:var(--surface-2)}
.stat .v{font-family:var(--display);font-stretch:85%;font-weight:700;font-size:24px;font-variant-numeric:tabular-nums;line-height:1.1}
.stat .k{font-size:12px;color:var(--ink-2)}
.stat .v.alert{color:var(--danger)}
/* filters */
.toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:12px}
.chips{display:flex;gap:4px;flex-wrap:wrap;background:var(--surface-2);padding:3px;border-radius:7px}
.chip{border:0;background:transparent;padding:5px 11px;border-radius:5px;font-weight:600;font-size:12.5px;color:var(--ink-2);cursor:pointer}
.chip.on{background:var(--surface);color:var(--ink);box-shadow:0 1px 2px rgba(0,0,0,.08)}
.toolbar input[type=search]{max-width:260px}
.toolbar select{width:auto}
/* tables */
.tbl-wrap{overflow-x:auto;background:var(--surface);border:1px solid var(--line);border-radius:var(--r)}
table.tbl{width:100%;border-collapse:collapse;min-width:720px}
.tbl th{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3);font-weight:600;text-align:left;padding:10px 14px;border-bottom:1px solid var(--line);background:var(--surface);white-space:nowrap}
.tbl td{padding:11px 14px;border-bottom:1px solid var(--line-2);vertical-align:middle}
.tbl tbody tr{cursor:pointer}
.tbl tbody tr:hover td{background:var(--surface-2)}
.tbl tbody tr:last-child td{border-bottom:0}
.tbl .r{text-align:right}
.tbl td.r{font-variant-numeric:tabular-nums}
.ordno{font-family:var(--mono);font-weight:600;font-size:13px}
.sub{font-size:12px;color:var(--ink-3)}
.empty{padding:40px 20px;text-align:center;color:var(--ink-2)}
/* status pill */
.pill{display:inline-flex;align-items:center;gap:6px;padding:3px 9px 3px 8px;border-radius:99px;font-size:12px;font-weight:600;white-space:nowrap;color:var(--sc);background:color-mix(in srgb,var(--sc) 14%,transparent)}
.pill::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--sc)}
.due-late{color:var(--danger);font-weight:600}
.due-soon{color:var(--warn);font-weight:600}
.bal{font-weight:600}
.bal.paid{color:var(--ok)}
.tag{display:inline-block;font-size:10.5px;font-family:var(--mono);letter-spacing:.06em;text-transform:uppercase;padding:2px 6px;border-radius:4px;background:var(--surface-2);color:var(--ink-2)}
.tag.q{background:var(--surface-3)}
.tag.i{background:var(--accent-soft);color:var(--accent)}
/* board */
.board{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(250px,1fr);gap:12px;overflow-x:auto;padding-bottom:10px;align-items:start}
.col{background:var(--surface-2);border-radius:var(--r);display:flex;flex-direction:column;min-height:200px;border-top:3px solid var(--sc)}
.col-h{display:flex;align-items:center;gap:8px;padding:10px 12px 8px}
.col-h b{font-family:var(--display);font-stretch:85%;font-size:14.5px;font-weight:700}
.col-h .n{font-family:var(--mono);font-size:11.5px;color:var(--ink-3)}
.col-h .sum{margin-left:auto;font-size:11.5px;color:var(--ink-2);font-variant-numeric:tabular-nums}
.col-b{display:flex;flex-direction:column;gap:8px;padding:4px 8px 10px;flex:1;min-height:80px;border-radius:0 0 var(--r) var(--r)}
.col.drop .col-b{background:color-mix(in srgb,var(--sc) 12%,transparent)}
.card-job{background:var(--surface);border:1px solid var(--line);border-radius:7px;padding:10px 11px;display:flex;flex-direction:column;gap:6px;cursor:grab;box-shadow:0 1px 1px rgba(0,0,0,.03)}
.card-job:hover{border-color:var(--ink-3)}
.card-job.dragging{opacity:.4}
.card-job .t{font-weight:600;line-height:1.3}
.card-job .meta{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-2);flex-wrap:wrap}
.card-job .foot{display:flex;align-items:center;gap:6px}
.card-job .adv{margin-left:auto}
.col-empty{font-size:12px;color:var(--ink-3);text-align:center;padding:14px 4px}
/* calendar */
.cal-wrap{overflow-x:auto}
.cal{display:grid;grid-template-columns:repeat(7,minmax(90px,1fr));gap:1px;background:var(--line);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;min-width:680px}
.cal .dow{background:var(--surface);font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3);padding:8px 10px;font-weight:600}
.cal .day{background:var(--surface);min-height:108px;padding:6px 6px 8px;display:flex;flex-direction:column;gap:4px}
.cal .day.out{background:var(--surface-2)}
.cal .day.today .d{background:var(--accent);color:var(--accent-ink);border-radius:4px;padding:0 5px}
.cal .d{font-family:var(--mono);font-size:12px;color:var(--ink-2);align-self:flex-start;padding:0 2px}
.cal-chip{display:block;border:0;text-align:left;width:100%;font-size:11.5px;padding:3px 6px;border-radius:4px;cursor:pointer;color:var(--ink);background:color-mix(in srgb,var(--sc) 16%,transparent);border-left:3px solid var(--sc);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.cal-chip:hover{background:color-mix(in srgb,var(--sc) 26%,transparent)}
/* editor */
.ed-head{display:flex;align-items:flex-start;gap:14px;flex-wrap:wrap;margin-bottom:18px}
.ed-title{display:flex;flex-direction:column;gap:6px;min-width:0}
.ed-title h1 .mono{font-family:var(--mono);font-weight:500;font-size:.85em;letter-spacing:-.02em;color:var(--ink-2)}
.ed-actions{margin-left:auto;display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.save-state{font-size:12px;color:var(--ink-3);min-width:64px;text-align:right}
.status-select{font-weight:600;color:var(--sc);background:color-mix(in srgb,var(--sc) 12%,var(--surface));border-color:color-mix(in srgb,var(--sc) 40%,var(--line));width:auto}
.ed-grid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:18px;align-items:start}
.ed-aside{position:sticky;top:16px;display:flex;flex-direction:column;gap:14px}
.line{border:1px solid var(--line);border-radius:var(--r);background:var(--surface)}
.line-h{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line-2);background:var(--surface-2);border-radius:var(--r) var(--r) 0 0}
.line-h .idx{font-family:var(--mono);font-size:12px;color:var(--ink-3)}
.line-b{padding:14px;display:flex;flex-direction:column;gap:14px}
.garment{display:grid;grid-template-columns:2fr 1.1fr 1.1fr .8fr;gap:10px}
.sizes-wrap{overflow-x:auto}
table.sizes{border-collapse:separate;border-spacing:0;width:100%;min-width:560px}
.sizes th{font-family:var(--mono);font-size:11px;font-weight:600;color:var(--ink-2);padding:0 2px 4px;text-align:center}
.sizes th small{display:block;font-weight:400;color:var(--warn);font-size:10px}
.sizes td{padding:0 2px}
.sizes input{text-align:center;padding:6px 2px}
.sizes input.has{background:var(--accent-soft);border-color:color-mix(in srgb,var(--accent) 40%,var(--line));font-weight:600}
.sizes .tot{font-family:var(--mono);font-weight:600;text-align:center;font-size:14px;padding-top:6px}
.decos{display:flex;flex-direction:column;gap:6px}
.deco{display:grid;grid-template-columns:140px minmax(0,1fr) 110px 90px 32px;gap:8px;align-items:center}
.deco .each{font-family:var(--mono);font-size:12.5px;text-align:right;color:var(--ink-2)}
.deco-h{display:grid;grid-template-columns:140px minmax(0,1fr) 110px 90px 32px;gap:8px}
.deco-h span{font-size:11px;font-weight:600;color:var(--ink-3);letter-spacing:.04em}
.deco-h span:nth-child(4){text-align:right}
.price-strip{display:flex;align-items:center;gap:14px;flex-wrap:wrap;background:var(--surface-2);border-radius:6px;padding:10px 12px}
.price-strip .calc{font-family:var(--mono);font-size:12.5px;color:var(--ink-2)}
.price-strip .calc b{color:var(--ink);font-weight:600}
.price-strip .ov{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--ink-2)}
.price-strip .ov input{width:90px}
.price-strip .lt{margin-left:auto;text-align:right}
.price-strip .lt b{font-family:var(--display);font-stretch:85%;font-size:19px;font-weight:700;font-variant-numeric:tabular-nums}
.warnline{font-size:12px;color:var(--warn);background:var(--warn-soft);padding:6px 10px;border-radius:5px}
.totals{display:flex;flex-direction:column}
.totals .tr{display:flex;justify-content:space-between;gap:10px;padding:6px 0;font-variant-numeric:tabular-nums}
.totals .tr span:first-child{color:var(--ink-2)}
.totals .tr.big{border-top:1px solid var(--line);margin-top:6px;padding-top:10px;font-weight:700;font-size:15px}
.totals .tr.bal{font-family:var(--display);font-stretch:85%;font-size:22px;font-weight:750}
.totals .tr.bal span:first-child{color:var(--ink);font-size:15px;align-self:center}
.pay-row{display:flex;justify-content:space-between;gap:8px;font-size:13px;padding:6px 0;border-bottom:1px dashed var(--line);align-items:center}
.pay-add{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.hist{font-size:12px;color:var(--ink-2);display:flex;flex-direction:column;gap:5px}
.hist div{display:flex;gap:8px;align-items:center}
.fee-row{display:grid;grid-template-columns:minmax(0,1fr) 110px 32px;gap:8px;align-items:center}
.newcust{border:1px dashed var(--accent);border-radius:6px;padding:10px;background:var(--accent-soft);display:grid;grid-template-columns:repeat(3,minmax(0,1fr)) auto;gap:8px;align-items:end}
/* pricing */
.matrix-wrap{overflow-x:auto}
table.matrix{border-collapse:collapse;min-width:560px;width:100%}
.matrix th{font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);font-weight:600;padding:6px;text-align:center}
.matrix th:first-child{text-align:left}
.matrix td{padding:3px}
.matrix input{text-align:right;padding:6px 7px}
.matrix td.tier input{text-align:left;font-family:var(--mono);font-weight:600}
.preview{background:var(--surface-2);border-radius:6px;padding:12px 14px;font-size:13px}
.preview b{font-variant-numeric:tabular-nums}
/* customers */
.cust-grid{display:grid;grid-template-columns:minmax(0,380px) minmax(0,1fr);gap:18px;align-items:start}
/* misc */
.banner{background:var(--warn-soft);color:var(--warn);padding:10px 14px;border-radius:6px;margin-bottom:14px;font-size:13px;font-weight:500}
.toast{position:fixed;left:50%;bottom:calc(20px + env(safe-area-inset-bottom,0px));transform:translateX(-50%);background:var(--ink);color:var(--bg);padding:9px 16px;border-radius:7px;font-weight:600;font-size:13px;box-shadow:var(--shadow);z-index:50;transition:opacity .2s}
.loading{padding:60px;text-align:center;color:var(--ink-3)}
.back{font-size:13px;text-decoration:none;color:var(--ink-2);font-weight:500}
.back:hover{color:var(--accent)}
@media (max-width: 1100px){
  .ed-grid{grid-template-columns:1fr}
  .ed-aside{position:static}
  .cust-grid{grid-template-columns:1fr}
}
@media (max-width: 820px){
  .app{grid-template-columns:1fr}
  .side{position:sticky;top:0;height:auto;flex-direction:row;align-items:center;padding:10px 16px;gap:12px;z-index:20;overflow-x:auto}
  .brand{border:0;padding:0}
  .brand span,.side-foot{display:none}
  .nav{flex-direction:row}
  .nav a{padding:7px 9px}
  .nav a .lbl-t{display:none}
  .btn-ship{margin:0;flex:none;padding:7px 9px}.btn-ship .lbl-t{display:none}
  .nav .count{display:none}
  .side .btn-new{margin:0 0 0 auto;width:auto}
  .main{padding-inline:16px}
  .stats{grid-template-columns:repeat(2,minmax(0,1fr))}
  .garment{grid-template-columns:1fr 1fr}
  .g3,.g4{grid-template-columns:1fr 1fr}
  .deco,.deco-h{grid-template-columns:1fr 1fr}
  .deco-h{display:none}
  .deco .each{text-align:left}
  .newcust{grid-template-columns:1fr}
}
@media (max-width: 480px){
  .g2,.g3,.g4{grid-template-columns:1fr}
  h1{font-size:25px}
}
@media (prefers-reduced-motion: reduce){*{transition:none!important;animation:none!important}}

/* ---------- additions for the hosted app ---------- */
body{margin:0}
.nav .badge{margin-left:auto;background:var(--danger);color:#fff;font-family:var(--mono);font-size:10.5px;border-radius:99px;padding:1px 6px}
.nav .badge.soft{background:var(--side-hover);color:var(--side-ink-strong);border:1px solid rgba(255,255,255,.25)}
.side-user{font-size:11.5px;color:var(--side-ink);padding:0 10px;display:flex;flex-direction:column;gap:4px;word-break:break-all}
.side-user a{color:var(--side-ink);opacity:.8}
.tbl a.rowlink{color:inherit;text-decoration:none}
.unread{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--danger);margin-left:6px;vertical-align:middle}

/* login */
.auth-wrap{min-height:100%;display:grid;place-items:center;padding-inline:16px;padding-block:40px;background:var(--bg)}
.auth-card{width:100%;max-width:400px;background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:28px;display:flex;flex-direction:column;gap:14px;box-shadow:var(--shadow)}
.auth-card h1{font-size:26px}
.auth-card .shopname{font-family:var(--display);font-stretch:75%;font-weight:800;font-size:20px;letter-spacing:.02em}
.code-input{font-family:var(--mono);font-size:22px;letter-spacing:.3em;text-align:center}
.err{color:var(--danger);font-size:13px}
.okmsg{color:var(--ok);font-size:13px}

/* proofs + messages (shared) */
.proofs{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:12px}
.proof{border:1px solid var(--line);border-radius:var(--r);overflow:hidden;background:var(--surface);display:flex;flex-direction:column}
.proof .img{aspect-ratio:4/3;background:var(--surface-2);display:grid;place-items:center;overflow:hidden;max-width:100%}
.proof .img img{width:100%;height:100%;object-fit:contain}
.proof .img .file{font-family:var(--mono);font-size:12px;color:var(--ink-2);padding:12px;text-align:center}
.proof .pb{padding:10px 12px;display:flex;flex-direction:column;gap:6px;font-size:13px}
.proof-status{font-size:12px;font-weight:600}
.proof-status.pending{color:var(--warn)}
.proof-status.approved{color:var(--ok)}
.proof-status.changes{color:var(--danger)}
.thread{display:flex;flex-direction:column;gap:10px;max-height:420px;overflow-y:auto;padding:2px}
.msg{max-width:85%;padding:9px 12px;border-radius:10px;font-size:13.5px;white-space:pre-wrap;word-wrap:break-word}
.msg.me{align-self:flex-end;background:var(--accent);color:var(--accent-ink);border-bottom-right-radius:3px}
.msg.them{align-self:flex-start;background:var(--surface-2);border-bottom-left-radius:3px}
.msg .who{font-size:11px;opacity:.75;margin-bottom:2px}
.composer{display:flex;gap:8px;align-items:flex-end}
.composer textarea{min-height:44px}

/* ---------- customer portal ---------- */
.portal{min-height:100%;background:var(--bg)}
.p-top{background:var(--surface);border-bottom:1px solid var(--line);position:sticky;top:env(safe-area-inset-top,0px);z-index:10}
.p-top-in{max-width:980px;margin:0 auto;padding-inline:20px;padding-block:14px;display:flex;align-items:center;gap:14px}
.p-top .logo{max-height:36px;width:auto}
.p-top .shop{font-family:var(--display);font-stretch:75%;font-weight:800;font-size:21px;letter-spacing:.015em;color:var(--ink);text-decoration:none}
.p-top .who{margin-left:auto;font-size:12.5px;color:var(--ink-2);display:flex;gap:12px;align-items:center}
.p-main{max-width:1120px;margin:0 auto;padding-inline:20px;padding-block:28px 64px;display:flex;flex-direction:column;gap:20px}
.preview-bar{background:var(--warn-soft);color:var(--warn);font-size:13px;font-weight:600;text-align:center;padding:8px 16px}
.action-list{display:flex;flex-direction:column;gap:10px}
.action{display:flex;align-items:center;gap:14px;background:var(--surface);border:1px solid var(--line);border-left:4px solid var(--sc);border-radius:var(--r);padding:14px 16px;text-decoration:none;color:inherit}
.action:hover{border-color:var(--ink-3);border-left-color:var(--sc)}
.action .t{font-weight:600}
.action .d{font-size:13px;color:var(--ink-2)}
.action .go{margin-left:auto}
.ocards{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px}
.ocard{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:14px 16px;display:flex;flex-direction:column;gap:8px;text-decoration:none;color:inherit}
.ocard:hover{border-color:var(--ink-3)}
.ocard .n{font-family:var(--mono);font-size:12px;color:var(--ink-3)}
.ocard .t{font-weight:600;font-size:15px}
.ocard .f{display:flex;justify-content:space-between;align-items:center;font-size:13px;color:var(--ink-2);margin-top:auto}
.stepper{display:flex;gap:0;overflow-x:auto;padding:2px 0}
.step{flex:1;min-width:92px;display:flex;flex-direction:column;align-items:center;gap:6px;position:relative;font-size:11.5px;color:var(--ink-3);text-align:center}
.step::before{content:"";position:absolute;top:9px;left:-50%;width:100%;height:2px;background:var(--line)}
.step:first-child::before{display:none}
.step .dot{width:20px;height:20px;border-radius:50%;background:var(--surface);border:2px solid var(--line);position:relative;z-index:1;display:grid;place-items:center;font-size:11px;color:#fff}
.step.done{color:var(--ink-2)}
.step.done .dot{background:var(--accent);border-color:var(--accent)}
.step.done::before{background:var(--accent)}
.step.cur{color:var(--ink);font-weight:700}
.step.cur .dot{border-color:var(--accent);background:var(--surface);box-shadow:0 0 0 4px var(--accent-soft)}
.step.cur::before{background:var(--accent)}
.callout{border:1px solid color-mix(in srgb,var(--accent) 45%,var(--line));background:var(--accent-soft);border-radius:var(--r);padding:16px 18px;display:flex;flex-direction:column;gap:12px}
.callout h2{font-size:18px}
.callout.good{border-color:color-mix(in srgb,var(--ok) 45%,var(--line));background:var(--ok-soft)}
.items{width:100%;border-collapse:collapse;min-width:520px}
.items th{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3);font-weight:600;text-align:left;padding:8px 10px;border-bottom:1px solid var(--line)}
.items td{padding:12px 10px;border-bottom:1px solid var(--line-2);vertical-align:top}
.items .r{text-align:right;font-variant-numeric:tabular-nums}
.sizechips{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}
.sizechips span{font-family:var(--mono);font-size:11px;background:var(--surface-2);border-radius:4px;padding:2px 6px}
.two{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:18px;align-items:start}
.sig{display:flex;flex-direction:column;gap:10px}
.sig input[type=text]{font-family:var(--display);font-size:18px;font-style:italic}
@media (max-width: 820px){ .two{grid-template-columns:1fr} .p-top .who span{display:none} }

/* printable invoice */
.print-page{max-width:800px;margin:0 auto;padding-inline:24px;padding-block:32px;background:var(--surface);color:var(--ink)}
.print-bar{max-width:800px;margin:0 auto;padding-inline:24px;padding-block:14px 0;display:flex;gap:8px}
@media print{ .print-bar{display:none} body{background:#fff} .print-page{padding:0} }

/* ---------- Printavo-style order entry ---------- */
.top2{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);gap:14px;align-items:start}
@media (max-width: 1100px){ .top2{grid-template-columns:1fr} }
.cust-card{display:flex;flex-direction:column;gap:3px;font-size:13px;background:var(--surface-2);border-radius:6px;padding:10px 12px}
.rush{display:inline-block;margin-left:10px;vertical-align:middle;background:var(--danger);color:#fff;font-family:var(--mono);font-size:12px;font-weight:600;letter-spacing:.1em;padding:3px 8px;border-radius:4px}
table.pv-grid{border-collapse:separate;border-spacing:0;width:100%}
.pv-grid th{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);font-weight:600;text-align:left;padding:0 3px 5px;white-space:nowrap}
.pv-grid th.c{text-align:center;font-family:var(--mono);letter-spacing:0;min-width:48px}
