.pv-grid input.sz{text-align:center;padding:6px 2px;min-width:44px}
.pv-grid input.sz.has{background:var(--accent-soft);border-color:color-mix(in srgb,var(--accent) 40%,var(--line));font-weight:600}
.pv-grid td.r input{text-align:right;width:84px}
.pv-grid input.ov{border-color:var(--warn);background:var(--warn-soft)}
.linkbtn{background:none;border:0;padding:2px 0;color:var(--accent);font-size:11px;cursor:pointer;text-decoration:underline}
.imprints{border-top:1px dashed var(--line);padding-top:12px;display:flex;flex-direction:column;gap:6px}
.artlist{display:flex;flex-direction:column;gap:6px}
.artrow{display:flex;align-items:center;gap:10px}
.artthumb{width:44px;height:44px;border-radius:6px;background:var(--surface-2);display:grid;place-items:center;overflow:hidden;font-family:var(--mono);font-size:10px;color:var(--ink-2);text-decoration:none;flex:none}
.artthumb img{width:100%;height:100%;object-fit:cover}
.artname{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}
/* work order */
.wo h1{font-size:28px}
.wo .wo-rush{background:#C0392B;color:#fff;font-weight:800;letter-spacing:.12em;padding:6px 12px;display:inline-block;border-radius:4px}
.wo table{width:100%;border-collapse:collapse;margin:8px 0 14px}
.wo th,.wo td{border:1px solid #C9D0DA;padding:6px 8px;font-size:13px;text-align:left}
.wo th{background:#F0F2F5;font-size:11px;text-transform:uppercase;letter-spacing:.05em}
.wo td.c,.wo th.c{text-align:center}
.wo .box{border:2px solid #141D2B;border-radius:6px;padding:10px 12px;margin-bottom:12px}
.wo .artgrid{display:flex;flex-wrap:wrap;gap:10px}
.wo .artgrid img{max-width:220px;max-height:220px;border:1px solid #C9D0DA}
.pv-grid th.ysep,.pv-grid td.ysep{border-right:2px solid var(--line);padding-right:6px}
.pv-grid td.os-cell{background:var(--surface-2);white-space:nowrap}
.pv-grid td.os-cell .os-lbl{font-size:10px;letter-spacing:.08em;color:var(--ink-3);font-weight:700;margin-right:8px}
.pv-grid td.os-cell input.os{width:84px;display:inline-block}

/* Garment rows: info on top, a wrapping size strip beneath, so the editor never scrolls sideways */
.line{container-type:inline-size}
.gl-list{display:flex;flex-direction:column}
.gl-row{display:grid;gap:6px;align-items:start;grid-template-columns:minmax(0,.75fr) minmax(0,.8fr) minmax(0,1fr) minmax(0,1.3fr) 72px 58px 88px 92px 30px;grid-template-areas:"st br co de cs qt ea to x"}
.gl-list.ws .gl-row{grid-template-columns:minmax(0,.75fr) minmax(0,.8fr) minmax(0,1fr) minmax(0,1.3fr) 58px 88px 92px 30px;grid-template-areas:"st br co de qt ea to x"}
.a-st{grid-area:st;min-width:0}.a-br{grid-area:br;min-width:0}.a-co{grid-area:co;min-width:0}.a-de{grid-area:de;min-width:0}.a-cs{grid-area:cs;min-width:0}.a-qt{grid-area:qt}.a-ea{grid-area:ea;min-width:0}.a-to{grid-area:to}.a-x{grid-area:x}
.gl-head{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);font-weight:600;padding-bottom:2px}
.gl-head .c,.gl-row .c{text-align:center}
.gl-head .r,.gl-row .r{text-align:right}
.gl-row .tot{font-family:var(--mono);font-weight:600;padding-top:8px}
.gl-row .a-to{padding-top:8px;white-space:nowrap}
.gl-head.gl-row .a-to{padding-top:0}
.gl-row .a-ea input{text-align:right}
.gl-row input.ov{border-color:var(--warn);background:var(--warn-soft)}
.gl{padding:8px 0 10px;display:flex;flex-direction:column;gap:6px}
.gl + .gl{border-top:1px solid var(--line-2)}
@container (max-width: 700px){
  .gl-row{grid-template-columns:minmax(0,1fr) minmax(0,1fr) 64px 44px 78px 84px 28px;grid-template-areas:"st co cs qt ea to x" "br de . . . . ."}
  .gl-list.ws .gl-row{grid-template-columns:minmax(0,1fr) minmax(0,1fr) 44px 78px 84px 28px;grid-template-areas:"st co qt ea to x" "br de . . . ."}
  .gl-head .a-de,.gl-head .a-br{display:none}
  .gl-row.grp-total{grid-template-areas:"de de cs qt ea to x"}
  .gl-row.grp-total > .a-de{grid-area:1 / 1 / 2 / 3}
  .gl-row.grp-total.ws{grid-template-columns:minmax(0,1fr) minmax(0,1fr) 44px 78px 84px 28px;grid-template-areas:"de de qt ea to x"}
}
