.gl-row.grp-total{border-top:2px solid var(--line);padding-top:8px;align-items:baseline;font-size:13px}
.gl-row.grp-total.ws{grid-template-columns:minmax(0,.75fr) minmax(0,.8fr) minmax(0,1fr) minmax(0,1.3fr) 58px 88px 92px 30px;grid-template-areas:"st br co de qt ea to x"}
.grp-total .lbl2{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);font-weight:600}
