.ss-hits{display:flex;flex-direction:column;border:1px solid var(--line);border-radius:8px;max-height:360px;overflow:auto}
.ss-hit{display:grid;grid-template-columns:180px 1fr auto;gap:10px;align-items:center;padding:6px 10px;font-size:13px;border-bottom:1px solid var(--line-2)}
.ss-hit span{color:var(--ink-2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ss-sup{font-style:normal;font-size:10px;font-weight:700;color:var(--accent);letter-spacing:.05em;margin-left:6px;text-transform:uppercase}
.color-menu{width:min(260px,70vw)}
.color-menu .sm-item{grid-template-columns:1fr}
.color-menu .sm-item b{font-weight:500}
.color-menu .sm-item.cur b{font-weight:700}
.fee-head{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);font-weight:600}
.fee-head > span{padding-left:2px}
.fees-notes{align-items:start}
.comm-sum{display:flex;flex-direction:column;gap:4px;background:var(--surface-2);border-radius:6px;padding:8px 10px;font-size:12.5px}
.comm-sum > div{display:flex;justify-content:space-between;gap:10px}
.comm-sum span{color:var(--ink-3)}
.comm-sum b{font-weight:600;text-align:right}
#messages .thread{max-height:280px;overflow:auto}
.design-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:12px}
.design-card{display:flex;flex-direction:column;border:1px solid var(--line);border-radius:var(--r);background:var(--surface);text-decoration:none;color:inherit;overflow:hidden}
.design-card:hover{border-color:var(--accent)}
.dc-img{aspect-ratio:4/3;display:flex;align-items:center;justify-content:center;background:#fff;padding:10px}
.dc-img img{max-width:100%;max-height:100%;object-fit:contain}
.dc-img span{font-weight:700;color:var(--ink-3);font-size:13px}
.dc-b{display:flex;flex-direction:column;gap:2px;padding:8px 10px;font-size:13px}
.dc-b span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.imp-table tr.imp-design td{padding-top:0;padding-bottom:8px;border-bottom:1px solid var(--line-2)}
.dp{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:13px;padding-left:4px}
.dp-l{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);font-weight:600}
.dp-th{width:34px;height:34px;object-fit:contain;border:1px solid var(--line);border-radius:4px;background:#fff}
.dp-th.empty{display:inline-block}
.dp select{width:auto;max-width:320px}
.dp-size{color:var(--ink-2)}
.dp-size b{color:var(--ink)}
.wo-design{display:inline-flex;align-items:center;gap:6px}
.wo-design img{width:44px;height:44px;object-fit:contain;border:1px solid #C9D0DA;border-radius:3px}
.mk{display:grid;grid-template-columns:minmax(0,934px) minmax(200px,1fr) 340px;gap:18px;align-items:start}
.mk-mini{display:flex;flex-direction:column;gap:14px;min-width:0}
.mk-mini > .lbl{margin-bottom:-6px}
.mk-views{display:flex;gap:14px;flex-wrap:nowrap}
.mk-stage{flex:1 1 0;min-width:0}
.mk-photo{position:relative;container-type:inline-size;width:100%;background:#fff;border:1px solid var(--line);border-radius:8px;overflow:hidden;touch-action:pan-y;user-select:none}
.mk-bg{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;pointer-events:none}
.mk-art{position:absolute;cursor:grab;outline:1px dashed transparent}
.mk-art > img{width:100%;height:100%;display:block;pointer-events:none}
.mk-art.sel{outline:1.5px solid var(--accent)}
.mk-handle{position:absolute;right:-7px;bottom:-7px;width:14px;height:14px;background:#fff;border:2px solid var(--accent);border-radius:3px;cursor:nwse-resize}
.mk-pop{position:fixed;z-index:50;background:var(--surface);border:1px solid var(--line);border-radius:8px;box-shadow:var(--shadow);padding:8px;width:290px}
.mk-pop .sw{flex:none;width:20px;height:20px;border-radius:4px;border:1px solid var(--line)}

.mk-missing{display:flex;align-items:center;justify-content:center;border:2px dashed var(--danger);color:var(--danger);font-weight:800;font-size:20px;background:color-mix(in srgb,var(--danger-soft) 70%,transparent)}
.mk-label{font-size:10.5px;letter-spacing:.08em;padding-left:.08em;text-transform:uppercase;color:var(--ink-3);font-weight:700;margin-top:4px;text-align:center}
.mk-imp{display:flex;flex-direction:column;gap:6px;padding-bottom:10px;border-bottom:1px solid var(--line-2)}
.mk-imp select{width:auto}
.mk-saved{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}
.mk-saved a{display:flex;flex-direction:column;gap:4px;width:180px;font-size:12px;color:var(--ink-2);text-decoration:none}
.mk-saved img{width:100%;border:1px solid var(--line);border-radius:6px}
.mk-area{position:absolute;border:1.5px dashed rgba(10,123,166,.7);pointer-events:none}
.mk-norm{position:absolute;inset:0;transform-origin:0 0}
.mk-measure{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible;z-index:3}
.mk-colors{display:flex;flex-direction:column;gap:5px;background:var(--surface-2);border-radius:6px;padding:8px}
.mk-color{display:flex;align-items:center;gap:6px}
.mk-color .sw{flex:none;width:22px;height:22px;border-radius:4px;border:1px solid var(--line);background-image:linear-gradient(45deg,#ccc 25%,transparent 25%,transparent 75%,#ccc 75%),linear-gradient(45deg,#ccc 25%,transparent 25%,transparent 75%,#ccc 75%);background-size:8px 8px;background-position:0 0,4px 4px;background-blend-mode:normal}
.mk-color .sw[style*="background: #"],.mk-color .sw[style*="background:#"]{background-image:none}
.mk-color .arrow{color:var(--ink-3)}
.mk-color select{font-size:12.5px}
.mk-wh label{display:inline-flex;align-items:center;gap:4px;font-size:12px;color:var(--ink-2)}
.mk-wh input{width:64px}
.mk-canvas{display:flex;flex-direction:column;gap:12px}
.mk-canvas .mk-views{min-width:0;max-width:934px}
.mk-closeups{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px 14px;align-items:start;min-width:0;max-width:934px}
.mk-sleeve{display:flex;flex-direction:column;gap:4px}
.mk-sleeve-box{position:relative;border:1px solid var(--line);border-radius:8px;overflow:hidden;touch-action:pan-y;user-select:none}
/* phones: a finger on the photo scrolls the page, even on a logo; tap a logo to pick it, then a finger on the picked logo (or its resize corner) moves it */
.mk-photo .mk-hit,.mk-sleeve-box .mk-art{touch-action:pan-y}
.mk-photo .mk-hit.sel,.mk-sleeve-box .mk-art.sel,.mk-handle{touch-action:none}
.mk-sleeve-max{position:absolute;border:1.5px dashed rgba(255,255,255,.55);outline:1px dashed rgba(0,0,0,.25);pointer-events:none}
.mk-sleeve-seam{position:absolute;left:50%;top:0;bottom:0;border-left:1px dashed rgba(255,255,255,.4);pointer-events:none}

/* Imprints section waits for a mockup */
.imp-top{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:2px}
.mk-lock{position:relative}
.mk-lock.on .mk-body{opacity:.4;filter:grayscale(1);user-select:none}
.mk-cover{position:absolute;inset:0;z-index:2;background:transparent;border:1px dashed transparent;border-radius:6px;cursor:pointer;display:flex;align-items:center;justify-content:center;padding:0;font:inherit}
.mk-cover span{opacity:0;background:var(--panel,#fff);border:1px solid var(--line);border-radius:6px;padding:6px 10px;font-size:13px;color:var(--ink,#222);transition:opacity .12s}
.mk-cover:hover,.mk-cover:focus-visible{border-color:var(--accent)}
.mk-cover:hover span,.mk-cover:focus-visible span{opacity:1}

.mk-off{opacity:.4;filter:grayscale(1);pointer-events:none;user-select:none}
.mk-hem{position:absolute;border-top:2px solid rgba(255,255,255,.75);box-shadow:0 -1px 0 rgba(0,0,0,.25);pointer-events:none;text-align:center}
.mk-hem span,.mk-side-l,.mk-side-r{display:inline-block;font-size:10px;font-weight:700;letter-spacing:.08em;color:#fff;background:rgba(0,0,0,.45);padding:1px 5px;border-radius:3px;margin-top:3px}
.mk-side-l,.mk-side-r{position:absolute;top:6px;pointer-events:none}
.mk-side-l{left:6px}.mk-side-r{right:6px}
.mk-artlayer{position:absolute;inset:0;pointer-events:none;mask-size:100% 100%;-webkit-mask-size:100% 100%;mask-repeat:no-repeat;-webkit-mask-repeat:no-repeat}
.mk-artv{position:absolute}
.mk-artv > img{width:100%;height:100%;display:block}
.mk-hit{background:transparent}
.mk-cu-h{display:flex;align-items:baseline;justify-content:space-between;gap:8px}
.mk-cu-max{font-size:11px;color:var(--faint,#8a93a3)}
.mk-cu-dim{font-size:12px;font-weight:600}
.mk-cu-colors{display:flex;flex-direction:column;gap:3px;font-size:12px}
.mk-cu-color{display:flex;align-items:center;gap:6px}
.mk-cu-color .sw{flex:none;width:14px;height:14px;border-radius:3px;border:1px solid var(--line)}
.mk-near .sw{width:12px;height:12px;border-radius:3px;border:1px solid var(--line)}
.mk-match{display:flex;flex-direction:column;gap:3px;margin:4px 0 8px;padding:6px 8px;box-sizing:border-box;width:100%;border:1px solid var(--line-2,var(--line));border-radius:6px;background:var(--bg,#f6f7f9)}
.mk-match-h{display:flex;justify-content:space-between;font-size:10px;font-weight:700;letter-spacing:.06em;color:var(--faint,#8a93a3)}
.mk-match-h .mono{font-weight:500;letter-spacing:0}
.mk-near{display:grid;grid-template-columns:58px 14px 1fr auto;align-items:center;gap:6px;width:100%;text-align:left;font-size:12px;padding:3px 6px;border:1px solid transparent;border-radius:5px;background:transparent;cursor:pointer;font-family:inherit;color:inherit}
.mk-near:hover{border-color:var(--line);background:var(--surface,#fff)}
.mk-near.on{border-color:var(--accent);background:var(--accent-soft)}
.mk-near .k{font-size:11px;color:var(--faint,#8a93a3)}
.mk-near .sw{width:14px;height:14px;border-radius:3px;border:1px solid var(--line)}
.mk-near .n{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mk-near .q{font-size:11px;color:var(--faint,#8a93a3);white-space:nowrap}
.mk-pop .mk-match{margin:8px 0 0}
.mk-tabs{margin:8px 12px 0}
.mk-tabs .chip{flex:1}
.mk-setup{display:flex;flex-wrap:wrap;gap:10px 14px;align-items:flex-end;padding:12px 14px;margin-bottom:14px}
.mk-f{display:flex;flex-direction:column;gap:4px;min-width:0}
.mk-f > span{font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--faint,#8a93a3)}
.mk-f select,.mk-f input{width:auto;min-width:190px;max-width:260px}
.mk-setup-g select{min-width:0}
.mk-add{align-self:flex-end;margin-bottom:2px}
.mk-tools{gap:10px;flex-wrap:wrap}
.mk-pop{width:320px}
.mk-pop-row{padding:4px 0;border-top:1px solid var(--line-2,var(--line))}
.mk-pop-row:first-of-type{border-top:0}
.mk-pop-k{display:inline-flex;align-items:center;gap:5px;border:0;background:transparent;padding:0;cursor:pointer;font:inherit;color:inherit;flex:none}
.mk-pop-row .mk-match{margin:6px 0 2px}
.mk-srcs{display:inline-flex;gap:2px}
.mk-united{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:11px;color:var(--faint,#8a93a3);margin:2px 0 6px}
.mk-thumb{display:inline-block;border:1px solid var(--line);border-radius:6px;overflow:hidden;background:#fff;line-height:0}
.mk-thumb img{height:64px;width:auto;display:block}
.mk-thumb:hover{border-color:var(--accent)}
/* Design picker (starred first, searchable) */
.ds{position:relative;flex:1 1 220px;min-width:0}
.mk-imp > .ds{flex:0 0 auto}
.ds-field{display:flex;align-items:center;gap:8px;width:100%;min-height:34px;padding:3px 8px;border:1px solid var(--line);border-radius:6px;background:var(--surface,#fff);cursor:pointer;font:inherit;color:inherit;text-align:left}
.ds-field:hover{border-color:var(--accent)}
.ds-th{flex:none;width:26px;height:26px;border-radius:4px;object-fit:contain;background:#fff;border:1px solid var(--line-2,var(--line))}
.ds-name{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:13px}
.ds-caret{color:var(--faint,#8a93a3);font-size:11px}
.ds-pop{position:absolute;z-index:40;top:calc(100% + 4px);left:0;right:0;min-width:280px;background:var(--surface,#fff);border:1px solid var(--line);border-radius:8px;box-shadow:var(--shadow);padding:6px;display:flex;flex-direction:column}
.ds-pop input[type=search]{width:100%}
.ds-sub{font-size:11px;color:var(--faint,#8a93a3);padding:6px 4px 4px}
.ds-list{max-height:280px;overflow:auto;display:flex;flex-direction:column}
.ds-item{display:flex;align-items:center;gap:8px;padding:5px 6px;border-radius:5px;cursor:pointer}
.ds-item:hover{background:var(--surface-2)}
.ds-item.on{background:var(--accent-soft)}
.ds-star{flex:none;border:0;background:transparent;cursor:pointer;font-size:16px;line-height:1;color:var(--faint,#b8bfca);padding:2px 4px}
.ds-star.on{color:#E0A100}
.ds-empty{padding:10px 6px;font-size:13px}
/* Account areas (customer page + portal), styled like a clean dashboard */
.aa{display:flex;flex-direction:column;gap:18px}
.aa-nav{display:flex;gap:4px;flex-wrap:nowrap;overflow-x:auto;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:8px;scrollbar-width:thin}
.aa-tab{flex:1 0 auto;display:inline-flex;align-items:center;justify-content:center;gap:6px;border:0;background:transparent;padding:9px 10px;border-radius:11px;font:inherit;font-size:12.5px;font-weight:700;letter-spacing:.03em;text-transform:uppercase;color:var(--ink-3);cursor:pointer;white-space:nowrap}
.aa-tab:hover{color:var(--ink);background:var(--surface-2)}
.aa-tab.on{background:var(--accent-soft);color:var(--accent)}
.aa-n{font-size:11px;font-weight:700;min-width:20px;text-align:center;padding:1px 6px;border-radius:10px;background:var(--surface-2);color:var(--ink-3);letter-spacing:0}
.aa-tab.on .aa-n{background:var(--surface);color:var(--accent)}
.aa-body{min-width:0;display:flex;flex-direction:column;gap:14px}
.aa-card{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px}
.aa-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}
.aa-bar-l{display:flex;align-items:baseline;gap:14px;flex-wrap:wrap}
.aa-bar h2{margin:0;font-size:22px}
.aa-search{display:flex;align-items:center;gap:8px;width:min(380px,100%);border:1px solid var(--line);border-radius:10px;background:var(--surface);padding:0 12px;color:var(--ink-3)}
.aa-search:focus-within{border-color:var(--accent)}
.aa-search input{border:0;outline:0;background:transparent;box-shadow:none;padding:9px 0;flex:1;min-width:0}
.aa-sum{font-size:13px;color:var(--ink-3)}
.aa-sum b{color:var(--ink)}
.aa-empty{padding:22px;text-align:center;color:var(--ink-3);font-size:13px}
.aa-tblcard{padding:0;overflow:auto}
.aa-tbl{width:100%;border-collapse:collapse;font-size:14px;min-width:620px}
.aa-tbl thead th{background:color-mix(in srgb,var(--accent) 7%,var(--surface));color:var(--accent);font-size:12.5px;font-weight:700;text-align:left;padding:12px 14px;border-bottom:1px solid var(--line)}
.aa-tbl thead th.r,.aa-tbl td.r{text-align:right}
.aa-tbl td{padding:12px 14px;border-bottom:1px solid var(--line-2,var(--line));vertical-align:middle}
.aa-tbl tbody tr{cursor:pointer}
.aa-tbl tbody tr:hover{background:var(--surface-2)}
.aa-tbl tbody tr.late{background:#FDECEC}
.aa-tbl tbody tr.late:hover{background:#FADADA}
.aa-tbl tbody tr:last-child td{border-bottom:0}
.aa-tbl td a{font-weight:700}
.aa-tbl td.b{font-weight:700}
.aa-t{font-weight:600}
.aa-s{font-size:12px;color:var(--ink-3)}
.aa-pill{display:inline-block;font-size:12px;font-weight:700;padding:3px 10px;border-radius:999px;color:var(--sc);background:color-mix(in srgb,var(--sc) 14%,transparent);white-space:nowrap}
.aa-due{color:#c2410c;font-weight:700}
/* home: stat cards, tabbed table, attention panel */
.aa-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.aa-stat{display:flex;flex-direction:column;gap:6px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:18px 20px}
.aa-stat .ic{color:var(--accent);display:inline-flex;width:40px;height:40px;align-items:center;justify-content:center;border-radius:10px;background:var(--accent-soft);margin-bottom:6px}
.aa-stat b{font-size:26px;letter-spacing:-.01em}
.aa-stat > span:last-child{color:var(--ink-2);font-size:14px}
.aa-stat.red{background:#EF4444;border-color:#EF4444;color:#fff}
.aa-stat.red .ic{background:rgba(255,255,255,.2);color:#fff}
.aa-stat.red > span:last-child{color:#fff}
.aa-home{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:16px;align-items:start}
.aa-home-main{min-width:0}
.aa-htabs{display:flex;gap:4px}
.aa-htabs button{border:1px solid var(--line);border-bottom:0;background:var(--surface-2);padding:11px 22px;border-radius:12px 12px 0 0;font:inherit;font-size:17px;font-weight:700;color:var(--ink-3);cursor:pointer}
.aa-htabs button.on{background:var(--surface);color:var(--accent)}
.aa-htab-body{background:var(--surface);border:1px solid var(--line);border-radius:0 14px 14px 14px;padding:14px;display:flex;flex-direction:column;gap:12px}
.aa-htab-body .aa-tblcard{border-radius:10px}
.aa-attn{background:#FFF4E0;border:1px solid #F6DDB0;border-radius:14px;padding:16px;display:flex;flex-direction:column;gap:14px}
.aa-attn-h{font-size:17px;font-weight:800;color:#B7791F}
.aa-attn-g{display:flex;flex-direction:column;gap:8px}
.aa-attn-t{font-size:14px;font-weight:700;color:var(--ink-2)}
.aa-attn-i{display:grid;grid-template-columns:1fr 1.2fr auto;align-items:center;gap:10px;background:#fff;border:1px solid #F3E2C2;border-radius:10px;padding:10px 12px;text-decoration:none;color:inherit}
.aa-attn-i:hover{border-color:#E9B45C;box-shadow:0 2px 8px rgba(183,121,31,.12)}
.aa-attn-i .k{display:block;font-size:12px;font-weight:700;color:#D08A1E}
.aa-attn-i .v{display:block;font-size:14px;color:var(--ink)}
.aa-attn-i .go{display:inline-flex;width:34px;height:34px;align-items:center;justify-content:center;border-radius:50%;background:#FDE7C2;color:#D97706}
.aa-attn-none{font-size:13px;color:#8a6a2f}
/* artwork + messages */
.aa-sec-h{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:12px}
.aa-sec-h h3{margin:0;font-size:16px}
.aa-sec-h .faint{font-size:12px}
.dc-img{position:relative}
.dc-tools{position:absolute;top:6px;right:6px;display:flex;flex-direction:column;gap:4px;align-items:flex-end}
.dc-star{border:1px solid var(--line);background:rgba(255,255,255,.95);border-radius:8px;cursor:pointer;font-size:18px;line-height:1;padding:4px 7px;color:#9aa3b0}
.dc-star:hover{color:#E0A100;border-color:#E0A100}
.dc-star.on{color:#E0A100;border-color:#F3D27A;background:#FFF8E1}
.design-card.starred{border-color:#F3D27A}
.dc-img.mock img{object-fit:contain}
.aa-send{display:flex;flex-direction:column;gap:8px}
.aa-msgs{display:flex;flex-direction:column;gap:8px}
.aa-msg{border:1px solid var(--line);border-radius:12px;padding:12px 14px;background:var(--surface)}
.aa-msg.shop{border-left:4px solid var(--accent)}
.aa-msg.cust{border-left:4px solid #2E9D5B}
.aa-msg-h{display:flex;gap:10px;align-items:baseline;flex-wrap:wrap;font-size:13px}
.aa-msg-b{margin-top:4px;white-space:pre-wrap;font-size:14px}
.aa-ord{margin-left:auto;font-size:12px;font-weight:600}
.aa-ord.gen{color:var(--ink-3)}
@media (max-width: 1000px){ .aa-home{grid-template-columns:1fr} .aa-stats{grid-template-columns:repeat(2,minmax(0,1fr))} }
@media (max-width: 640px){ .aa-nav{justify-content:flex-start;flex-wrap:nowrap;overflow-x:auto} .aa-tab{padding:9px 12px} }
.aa-favs{gap:10px}
.aa-fav{display:grid;grid-template-columns:48px 1fr auto;gap:10px;align-items:center;background:#fff;border:1px solid #F3E2C2;border-radius:10px;padding:8px}
.aa-fav img,.aa-fav-ph{width:48px;height:48px;object-fit:contain;border-radius:6px;background:#fff;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:var(--ink-3)}
.aa-fav-t{display:flex;flex-direction:column;min-width:0;font-size:13px}
.aa-fav-t span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aa-fav .dc-star{position:static}
