/* small controls sitting in the corners of the shirt photos: plain text, no boxes */
.mk-corner{position:absolute;bottom:1.8cqw;display:flex;gap:2.4cqw;font-size:clamp(9px,2.5cqw,13px);align-items:center;z-index:5}
.mk-corner.l{left:2.2cqw}.mk-corner.r{right:2.2cqw}
.mk-pill{display:inline-flex;align-items:center;gap:.45em;font:inherit;font-size:inherit;font-weight:500;color:var(--ink-3);background:none;border:0;padding:0;cursor:pointer;line-height:1.4}
.mk-pill input{margin:0;width:1.1em;height:1.1em}
button.mk-pill:hover{color:var(--ink)}
.mk-corner.r .mk-pill{cursor:default}
/* first-hover tip over a logo */
.mk-hint{position:absolute;z-index:6;transform:translate(-50%,calc(-100% - 8px));background:#1b1b1b;color:#fff;font-size:12px;font-weight:600;line-height:1.35;padding:7px 10px;border-radius:8px;box-shadow:0 4px 14px rgba(0,0,0,.22);white-space:nowrap;pointer-events:none;display:flex;flex-direction:column;animation:mkHint .18s ease-out}
.mk-hint span{font-weight:400;font-size:11px;opacity:.8}
.mk-hint::after{content:"";position:absolute;left:50%;bottom:-5px;margin-left:-5px;border:5px solid transparent;border-bottom:0;border-top-color:#1b1b1b}
@keyframes mkHint{from{opacity:0;transform:translate(-50%,calc(-100% - 2px))}to{opacity:1}}

