.mk.mk-one .mk-viewsw,.mk.mk-stack .mk-viewsw{margin-inline:auto}

/* ---------- shirt designer ---------- */
.sd{display:flex;flex-direction:column;gap:10px;min-width:0}
.sd-top{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.sd-name{font-size:15px;font-weight:600;min-width:220px;flex:0 1 300px}
.sd-shirts{display:flex;align-items:center;gap:4px;font-size:12px}
.sd-shirts .faint{margin-right:2px}
.sd-shirt{width:20px;height:20px;border-radius:50%;border:1px solid rgba(0,0,0,.25);padding:0;cursor:pointer}
.sd-shirt.on{outline:2px solid var(--accent);outline-offset:2px}
.sd-body{display:grid;grid-template-columns:250px minmax(0,1fr) 290px;gap:14px;align-items:start}
.sd-tools,.sd-props{min-width:0;overflow:hidden}
.sd-tabs{display:grid;grid-template-columns:1fr 1fr;gap:2px;padding:6px;border-bottom:1px solid var(--line-2)}
.sd-tab{border:0;background:none;font:inherit;font-size:12.5px;font-weight:600;color:var(--ink-2);padding:7px 6px;border-radius:6px;cursor:pointer}
.sd-tab:hover{background:var(--surface-2)}
.sd-tab.on{background:var(--accent-soft);color:var(--accent)}
.sd-tool-b{padding:10px;display:flex;flex-direction:column;gap:8px;max-height:calc(100vh - 230px);overflow:auto}
.sd-addtext{border:1px solid var(--line);background:var(--surface);border-radius:8px;padding:10px;text-align:left;cursor:pointer;color:var(--ink);font-family:var(--body)}
.sd-addtext:hover{border-color:var(--accent)}
.sd-addtext.big{font-size:20px;font-weight:800}.sd-addtext.mid{font-size:15px;font-weight:600}.sd-addtext.small{font-size:12.5px}
.sd-fontgrid{display:grid;grid-template-columns:1fr 1fr;gap:4px}
.sd-fontgrid.tight{max-height:170px;overflow:auto;padding-right:2px}
.sd-font{border:1px solid var(--line);background:var(--surface);border-radius:6px;padding:7px 6px;font-size:15px;line-height:1.1;cursor:pointer;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sd-font:hover{border-color:var(--accent)}
.sd-font.on{border-color:var(--accent);background:var(--accent-soft)}
.sd-artgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin:4px 0 8px}
.sd-art{aspect-ratio:1;border:1px solid var(--line);background:#fff;border-radius:6px;padding:8px;cursor:pointer}
.sd-art:hover{border-color:var(--accent)}
.sd-art svg{width:100%;height:100%;display:block}
.sd-logos{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.sd-logo{border:1px solid var(--line);background:#fff;border-radius:6px;padding:6px;cursor:pointer;display:flex;flex-direction:column;gap:4px;align-items:center;font-size:11px;color:var(--ink-2)}
.sd-logo img{width:100%;height:60px;object-fit:contain}
.sd-logo span{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sd-tpls{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.sd-tpl{border:1px solid var(--line);background:#fff;border-radius:8px;padding:6px;cursor:pointer;display:flex;flex-direction:column;gap:4px;font-size:12px;font-weight:600;color:var(--ink-2)}
.sd-tpl:hover{border-color:var(--accent)}
.sd-tpl svg{width:100%;aspect-ratio:600/520;display:block}
.sd-stage{display:flex;flex-direction:column;align-items:center;gap:6px;min-width:0}
.sd-svg{width:100%;max-width:min(640px,calc((100vh - 190px) * 0.857));aspect-ratio:600/700;border-radius:10px;box-shadow:var(--shadow);touch-action:none;user-select:none;display:block}
.sd-under{font-size:12px;text-align:center}
.sd-prop-b{padding:12px;display:flex;flex-direction:column;gap:8px;border-bottom:1px solid var(--line-2)}
.sd-prop-b textarea{width:100%;box-sizing:border-box;font:inherit;font-size:14px;resize:vertical;min-height:40px}
.sd-inks{display:grid;grid-template-columns:repeat(9,1fr);gap:3px}
.sd-ink{aspect-ratio:1;border-radius:4px;border:1px solid rgba(0,0,0,.2);padding:0;cursor:pointer;position:relative;display:grid;place-items:center;font-size:13px;color:var(--ink-2)}
.sd-ink.on{outline:2px solid var(--accent);outline-offset:1px}
.sd-ink.custom{background:conic-gradient(red,yellow,lime,cyan,blue,magenta,red);color:#fff;font-weight:700;overflow:hidden}
.sd-ink.custom input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%;height:100%}
.sd-range{display:grid;grid-template-columns:62px 1fr 64px;align-items:center;gap:6px;font-size:12.5px;color:var(--ink-2)}
.sd-range span{font-size:12px;text-align:right;color:var(--ink-3)}
.sd-actions{display:flex;flex-wrap:wrap;gap:4px}
.sd-layers{padding:10px 12px;display:flex;flex-direction:column;gap:2px}
.sd-layer{display:flex;align-items:center;gap:2px;border-radius:6px}
.sd-layer.on{background:var(--accent-soft)}
.sd-layer-n{flex:1;min-width:0;border:0;background:none;font:inherit;font-size:13px;text-align:left;padding:5px 6px;cursor:pointer;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sd-layer-k{display:inline-block;width:18px;color:var(--ink-3);font-size:11px}
@media (max-width: 1150px){
  .sd-body{grid-template-columns:minmax(0,1fr) 280px}
  .sd-tools{grid-column:1 / -1}
  .sd-tabs{grid-template-columns:repeat(4,1fr)}
  .sd-tool-b{max-height:230px}
  .sd-artgrid{grid-template-columns:repeat(auto-fill,minmax(48px,1fr))}
  .sd-tpls{grid-template-columns:repeat(auto-fill,minmax(120px,1fr))}
  .sd-fontgrid:not(.tight){grid-template-columns:repeat(auto-fill,minmax(130px,1fr))}
}
@media (max-width: 760px){
  .sd-body{grid-template-columns:minmax(0,1fr)}
  .sd-svg{max-width:100%}
}
/* the designer opened from the mockup builder */
.sd-modal-back{position:fixed;inset:0;z-index:60;background:rgba(10,15,25,.55);display:flex;align-items:flex-start;justify-content:center;padding:18px;overflow:auto}
.sd-modal{background:var(--bg);border-radius:12px;padding:16px;width:min(1400px,100%);box-shadow:0 10px 40px rgba(0,0,0,.3)}
.sp-card > .btn{grid-column:1 / -1;justify-self:start}
/* Mockup Creator: logo or quick text on an imprint */
.mk-kind{display:inline-grid;grid-template-columns:1fr 1fr;background:var(--surface-2);border-radius:8px;padding:2px;width:fit-content}
.mk-kind button{border:0;background:none;font:inherit;font-size:12.5px;font-weight:600;padding:4px 16px;border-radius:6px;cursor:pointer;color:var(--ink-2)}
.mk-kind button.on{background:var(--surface);color:var(--ink);box-shadow:0 1px 2px rgba(0,0,0,.12)}
.mk-qt{display:flex;flex-direction:column;gap:6px}
.mk-qt textarea{width:100%;box-sizing:border-box;font:inherit;font-size:14px;resize:vertical;min-height:38px}
.mk-qt-row{display:flex;gap:6px;align-items:center}
.mk-qt-row select{flex:1;min-width:0}
.mk-qt-row .sw{flex:none;width:22px;height:22px;border-radius:5px;border:1px solid var(--line)}
.mk-more{display:flex;flex-direction:column;gap:2px;text-align:left;border:1px dashed var(--accent);background:var(--accent-soft);color:var(--accent);border-radius:8px;padding:8px 10px;cursor:pointer;font:inherit}
.mk-more b{font-size:13px}
.mk-more span{font-size:12px;opacity:.85}
.mk-more:hover{border-style:solid}
/* Mockup Creator: open this side in the Idea Lab */
.mk-lab{display:flex;gap:10px;align-items:flex-start;text-align:left;width:100%;border:1px solid color-mix(in srgb,var(--accent) 45%,transparent);background:linear-gradient(135deg,var(--accent-soft),var(--surface));color:var(--ink);border-radius:10px;padding:10px 12px;cursor:pointer;font:inherit}
.mk-lab:hover{border-color:var(--accent)}
.mk-lab-ic{flex:none;width:26px;height:26px;border-radius:50%;background:var(--accent);color:var(--accent-ink);display:grid;place-items:center;font-size:14px}
.mk-lab b{display:block;font-size:13px;color:var(--accent)}
.mk-lab span span{display:block;font-size:12px;color:var(--ink-2);margin-top:1px}

/* ---------- Idea Lab ---------- */
.il-inkchip{font-size:12px;font-weight:600;background:var(--surface-2);color:var(--ink-2);border-radius:999px;padding:4px 10px}
.il-body{display:grid;grid-template-columns:72px minmax(0,1fr) 290px;gap:12px;align-items:start}
.il-body.open{grid-template-columns:72px 310px minmax(0,1fr) 290px}
.il-rail{display:flex;flex-direction:column;gap:4px;background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:6px;position:sticky;top:8px}
.il-rail-b{display:flex;flex-direction:column;align-items:center;gap:3px;border:0;background:none;border-radius:9px;padding:9px 2px;font:inherit;font-size:11px;font-weight:600;color:var(--ink-2);cursor:pointer;line-height:1.15;text-align:center}
.il-rail-b svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.il-rail-b:hover{background:var(--surface-2);color:var(--ink)}
.il-rail-b.on{background:var(--accent-soft);color:var(--accent)}
.il-panel{min-width:0;overflow:hidden;display:flex;flex-direction:column;max-height:calc(100vh - 150px)}
.il-panel-h{display:flex;align-items:center;justify-content:space-between;padding:10px 12px;border-bottom:1px solid var(--line-2)}
.il-panel-b{padding:10px 12px;display:flex;flex-direction:column;gap:8px;overflow:auto;min-height:0}
.il-search{display:flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:9px;padding:0 10px;background:var(--surface)}
.il-search:focus-within{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.il-search svg{width:16px;height:16px;flex:none;fill:none;stroke:var(--ink-3);stroke-width:2;stroke-linecap:round}
.il-search input{border:0;outline:0;background:none;flex:1;min-width:0;padding:9px 0;font:inherit;font-size:14px;box-shadow:none}
.il-seg{display:grid;grid-template-columns:repeat(3,1fr);background:var(--surface-2);border-radius:8px;padding:2px}
.il-seg button{border:0;background:none;font:inherit;font-size:12px;font-weight:600;padding:5px 4px;border-radius:6px;cursor:pointer;color:var(--ink-2)}
.il-seg button.on{background:var(--surface);color:var(--ink);box-shadow:0 1px 2px rgba(0,0,0,.12)}
.il-cats{display:grid;grid-template-columns:1fr 1fr;gap:5px}
.il-cat{display:flex;align-items:center;gap:7px;border:1px solid var(--line);background:var(--surface);border-radius:9px;padding:8px;font:inherit;font-size:12.5px;font-weight:600;color:var(--ink);cursor:pointer;text-align:left;line-height:1.2}
.il-cat:hover{border-color:var(--accent)}
.il-cat-e{font-size:18px;flex:none}
.il-back{border:0;background:none;font:inherit;font-size:12.5px;color:var(--accent);cursor:pointer;padding:0;text-align:left;font-weight:600}
.il-subs{display:flex;flex-wrap:wrap;gap:4px}
.il-subs .chip{font-size:12px;padding:4px 9px}
.il-count{font-size:12px}
.il-clipgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}
.il-clip{aspect-ratio:1;border:1px solid var(--line);background:#fff;border-radius:8px;padding:9px;cursor:pointer;position:relative}
.il-clip:hover{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft)}
.il-clip svg{width:100%;height:100%;display:block}
.il-full{position:absolute;right:3px;bottom:1px;font-size:9px;background:conic-gradient(#f43,#fc3,#3c6,#39f,#c3f,#f43);-webkit-background-clip:text;background-clip:text;color:transparent}
.il-fonts{display:flex;flex-direction:column;gap:6px;min-height:0}
.il-fontlist{display:flex;flex-direction:column;gap:3px;max-height:360px;overflow:auto;padding-right:2px}
.sd-props .il-fontlist{max-height:300px}
.il-font{display:flex;flex-direction:column;align-items:stretch;gap:0;border:1px solid var(--line);background:var(--surface);border-radius:7px;padding:5px 9px;cursor:pointer;text-align:left;color:var(--ink);flex:none}
.il-font:hover{border-color:var(--accent)}
.il-font.on{border-color:var(--accent);background:var(--accent-soft)}
.il-font-s{display:block;font-size:21px;line-height:1.35;padding:1px 0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
.il-font-n{font-size:10.5px;color:var(--ink-3);font-family:var(--body)}
.il-tpls{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.il-tpl{border:1px solid var(--line);background:#fff;border-radius:9px;padding:6px;cursor:pointer;display:flex;flex-direction:column;gap:4px;font:inherit;font-size:12px;font-weight:600;color:var(--ink-2)}
.il-tpl:hover{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft)}
.il-tpl svg{width:100%;aspect-ratio:600/540;display:block}
.il-soon{display:flex;flex-direction:column;gap:6px;border:1px dashed var(--accent);background:var(--accent-soft);border-radius:10px;padding:12px;font-size:13px}
.il-soon b{color:var(--accent)}
.il-stage{position:relative}
.il-empty{position:absolute;top:30%;left:50%;transform:translateX(-50%);z-index:2;background:var(--surface);border:1px solid var(--line);box-shadow:var(--shadow);border-radius:12px;padding:14px 16px;display:flex;flex-direction:column;gap:10px;align-items:center;text-align:center;width:min(420px,90%)}
.il-credit{font-size:10.5px;text-align:center}
.il-fontbtn-row{display:flex;gap:6px}
.il-fontbtn{flex:1;min-width:0;display:flex;justify-content:space-between;align-items:center;gap:6px;border:1px solid var(--line);background:var(--surface);border-radius:8px;padding:7px 10px;cursor:pointer;font-size:17px;color:var(--ink)}
.il-fontbtn span:first-child{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.il-presets{display:flex;flex-wrap:wrap;gap:4px}
.il-presets .chip{font-size:11.5px;padding:3px 8px}
.il-size{display:flex;gap:8px;flex-wrap:wrap}
.il-size label{display:inline-flex;align-items:center;gap:4px;font-size:12px;color:var(--ink-2)}
.il-size input{width:58px;padding:4px 6px}
@media (max-width: 1250px){
  .il-body,.il-body.open{grid-template-columns:minmax(0,1fr) 280px}
  .il-rail{grid-column:1 / -1;flex-direction:row;position:static;overflow-x:auto}
  .il-rail-b{flex-direction:row;gap:6px;padding:8px 12px;font-size:12.5px;flex:none}
  .il-panel{grid-column:1 / -1;max-height:max(420px,55vh)}
  .il-cats{grid-template-columns:repeat(auto-fill,minmax(170px,1fr))}
  .il-clipgrid{grid-template-columns:repeat(auto-fill,minmax(64px,1fr))}
  .il-tpls{grid-template-columns:repeat(auto-fill,minmax(140px,1fr))}
}
@media (max-width: 760px){
  .il-body,.il-body.open{grid-template-columns:minmax(0,1fr)}
}
.il-vintage{font-size:12.5px;white-space:nowrap}
.il-roster{display:flex;flex-direction:column;gap:4px}
.il-roster-row{display:grid;grid-template-columns:minmax(0,1fr) 52px 64px 28px;gap:4px;align-items:center}
.il-roster-row input,.il-roster-row select{min-width:0;padding:5px 6px;font-size:13px}
.il-paste summary{cursor:pointer;font-size:12.5px;font-weight:600;color:var(--accent)}
.il-paste textarea{width:100%;box-sizing:border-box;margin:6px 0;font:inherit;font-size:13px}
.il-zoom{display:flex;gap:2px;align-items:center;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:1px}

/* ---------- Assistant (follow-ups, to-dos, AI suggestions) ---------- */
.as-ai{font-size:11.5px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;padding:4px 10px;border-radius:99px;background:var(--surface-2);color:var(--ink-3)}
.as-ai.on{background:var(--ok-soft);color:var(--ok)}
.as-top{display:flex;gap:10px;align-items:stretch;flex-wrap:wrap;margin-bottom:14px}
.as-sum{display:flex;flex-direction:column;justify-content:center;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:8px 16px;min-width:92px}
.as-sum b{font-family:var(--display);font-stretch:85%;font-size:24px;line-height:1.1;font-variant-numeric:tabular-nums}
.as-sum b.alert{color:var(--danger)}
.as-sum span{font-size:12px;color:var(--ink-2)}
.as-todo{flex:1 1 360px;display:flex;gap:8px;align-items:center;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:8px 10px}
.as-todo input[type=text]{flex:1}
.as-todo input[type=date]{width:auto}
.as-list{display:flex;flex-direction:column;gap:8px}
.as-card{display:flex;gap:12px;align-items:flex-start;background:var(--surface);border:1px solid var(--line);border-left:4px solid var(--line);border-radius:var(--r);padding:12px 14px}
.as-card.p1{border-left-color:var(--danger)}
.as-card.p2{border-left-color:var(--warn)}
.as-card.p3{border-left-color:var(--ink-3)}
.as-card.snz{opacity:.85}
.as-dot{display:none}
.as-main{flex:1;min-width:0;display:flex;flex-direction:column;gap:4px}
.as-t{font-weight:650}
.as-t a{color:inherit;text-decoration:none}
.as-t a:hover{color:var(--accent);text-decoration:underline}
.as-b{font-size:13px;color:var(--ink-2);white-space:pre-line}
.as-meta{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:12px;color:var(--ink-3)}
.as-acts{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end;align-items:center;max-width:360px}
.as-snz{width:auto;padding:4px 6px;font-size:12px}
.as-draft{display:flex;flex-direction:column;gap:6px;margin-top:8px;background:var(--surface-2);border-radius:6px;padding:10px}
.as-strip{display:flex;align-items:center;gap:12px;flex-wrap:wrap;background:var(--surface);border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:var(--r);padding:10px 14px;margin-bottom:14px;font-size:13.5px}
.as-strip b{font-weight:700}
.as-strip .as-chip{font-size:12px;padding:2px 8px;border-radius:99px;background:var(--surface-2);color:var(--ink-2)}
.as-strip .as-chip.u{background:var(--danger-soft);color:var(--danger);font-weight:700}
@media (max-width: 820px){
  .as-card{flex-direction:column}
  .as-acts{justify-content:flex-start;max-width:none}
}

/* ---------- Order checks, AI helpers, activity timeline ---------- */
.chk-list{display:flex;flex-direction:column;gap:6px;font-size:13px}
.chk{display:flex;gap:8px;align-items:flex-start}
.chk::before{content:"";flex:none;width:8px;height:8px;border-radius:50%;margin-top:6px;background:var(--ink-3)}
.chk.high::before{background:var(--danger)}
.chk.medium::before{background:var(--warn)}
.chk.ok{color:var(--ok)}
.chk.ok::before{background:var(--ok)}
.ai-box{border:1px dashed color-mix(in srgb,var(--accent) 55%,var(--line));background:color-mix(in srgb,var(--accent) 5%,var(--surface));border-radius:var(--r);padding:12px 14px;display:flex;flex-direction:column;gap:8px}
.ai-box h3{margin:0;font-size:14px;font-family:var(--display);font-stretch:85%}
.ai-off{font-size:12px;color:var(--ink-3)}
.tl{display:flex;flex-direction:column;gap:10px}
.tl-i{display:grid;grid-template-columns:auto minmax(0,1fr);gap:4px 10px;font-size:13px}
.tl-k{grid-row:span 2;font-size:10.5px;font-family:var(--mono);letter-spacing:.06em;text-transform:uppercase;padding:2px 6px;border-radius:4px;background:var(--surface-2);color:var(--ink-2);align-self:start}
.tl-k.email{background:var(--accent-soft);color:var(--accent)}
.tl-k.call{background:var(--ok-soft);color:var(--ok)}
.tl-k.task{background:var(--warn-soft);color:var(--warn)}
.tl-h{display:flex;gap:8px;flex-wrap:wrap;align-items:baseline}
.tl-h b{font-weight:600}
.tl-h span{font-size:12px;color:var(--ink-3)}
.tl-b{white-space:pre-wrap;color:var(--ink-2);max-height:9.5em;overflow:hidden}
.tl-b.open{max-height:none}
.tl-form{display:flex;flex-direction:column;gap:6px;background:var(--surface-2);border-radius:6px;padding:10px}
.tag-edit{display:flex;gap:4px;flex-wrap:wrap;align-items:center}
.tag-edit .tg{display:inline-flex;align-items:center;gap:4px;font-size:12px;padding:2px 4px 2px 8px;border-radius:99px;background:var(--accent-soft);color:var(--accent);font-weight:600}
.tag-edit .tg button{border:0;background:transparent;color:inherit;cursor:pointer;padding:0 4px;font-size:12px}
.tag-edit input{flex:1;min-width:120px}
.cc-extra{margin-top:6px;padding-top:6px;border-top:1px dashed var(--line);display:flex;flex-direction:column;gap:3px}
.cc-note{white-space:pre-line;color:var(--ink-2);font-size:12.5px}
.qr-row{display:flex;gap:6px;align-items:center;flex-wrap:wrap}
.qr-row select{width:auto;font-size:12.5px;padding:4px 6px}
.as-strip a.as-chip{text-decoration:none;max-width:320px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.as-strip a.as-chip:hover{color:var(--accent)}
/* Settings: one sidebar item, tabs inside */
.set-tabs{display:flex;gap:4px;flex-wrap:wrap;margin:-4px 0 14px;border-bottom:1px solid var(--line);padding-bottom:0}
.set-tabs a{padding:8px 12px;font-size:13.5px;font-weight:600;color:var(--ink-2);text-decoration:none;border-bottom:2px solid transparent;margin-bottom:-1px}
.set-tabs a:hover{color:var(--ink)}
.set-tabs a.on{color:var(--accent);border-bottom-color:var(--accent)}
.stack > section.panel[id]{scroll-margin-top:16px}
.conn-row{display:flex;gap:10px;align-items:flex-start}
.conn-dot{flex:none;width:10px;height:10px;border-radius:50%;background:var(--line);margin-top:5px}
.conn-dot.ok{background:var(--ok)}.conn-dot.bad{background:var(--danger)}
a.as-ai{text-decoration:none}

/* ---------- Printavo archive (read-only old orders, laid out like Printavo) ---------- */
.pv{display:flex;flex-direction:column;gap:14px}
.pv-main{display:flex;flex-direction:column;gap:14px;min-width:0}
.pva-grid{grid-template-columns:minmax(0,1fr) 330px}
.pv-note{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px;padding:10px 14px;border-radius:10px;background:var(--warn-soft);color:var(--ink);font-size:13px;border:1px solid color-mix(in srgb,var(--warn) 30%,transparent)}
.pv-note .spacer{flex:1}
.pv-note a{font-weight:600}
.pv-head{display:flex;flex-wrap:wrap;gap:14px 24px;justify-content:space-between;align-items:flex-start;background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:18px 20px}
.pv-kind{font-size:26px;font-weight:800;letter-spacing:-.01em;line-height:1.1}
.pv-kind span{color:var(--accent)}
.pv-nick{font-size:16px;color:var(--ink-2);margin-top:4px}
.pv-tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}
.pv-tags span{font-size:11.5px;padding:2px 8px;border-radius:99px;background:var(--surface-2);color:var(--ink-2)}
.pv-head-r{display:flex;flex-wrap:wrap;align-items:center;gap:10px 22px}
.pv-status{display:inline-block;padding:6px 14px;border-radius:6px;font-weight:700;font-size:13px;text-transform:uppercase;letter-spacing:.03em}
.pv-bal{display:flex;flex-direction:column;align-items:flex-end}
.pv-bal span{font-size:11.5px;color:var(--ink-3);text-transform:uppercase;letter-spacing:.06em}
.pv-bal b{font-size:20px;font-variant-numeric:tabular-nums}
.pv-bal b.due,.pv-totals .pvt-due b{color:var(--danger)}
.pv-info{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,160px),1fr));gap:16px;overflow-wrap:anywhere;background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:16px 20px;font-size:13.5px}
.pv-info h4{margin:0 0 6px;font-size:11.5px;text-transform:uppercase;letter-spacing:.07em;color:var(--ink-3);font-weight:700}
.pv-strong{font-weight:700;font-size:14.5px}
.pv-dates{display:grid;grid-template-columns:auto 1fr;gap:3px 12px;margin:0}
.pv-dates dt{color:var(--ink-3)}
.pv-dates dd{margin:0;font-weight:600;white-space:nowrap}
.pv-card{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:16px 18px;min-width:0}
.pv-card h3{margin:0 0 10px;font-size:14px;font-weight:700}
.pv-card h3:not(:first-child){margin-top:14px}
.pv-group{padding:0;overflow:hidden}
.pv-gno{padding:10px 16px 0;font-size:11.5px;text-transform:uppercase;letter-spacing:.07em;color:var(--ink-3);font-weight:700}
.pv-scroll{overflow-x:auto}
.pv-tbl{width:100%;border-collapse:collapse;font-size:13.5px}
.pv-tbl th{background:var(--surface-2);color:var(--ink-2);font-size:12px;font-weight:700;text-align:left;padding:9px 8px;border-bottom:1px solid var(--line);white-space:nowrap}
.pv-tbl td{padding:9px 8px;border-bottom:1px solid var(--line-2);vertical-align:top}
.pv-tbl tfoot td{border-bottom:0;border-top:1px solid var(--line);background:color-mix(in srgb,var(--surface-2) 50%,var(--surface))}
.pv-tbl .r{text-align:right}.pv-tbl .c{text-align:center}.pv-tbl .b{font-weight:700}.pv-tbl .nowrap{white-space:nowrap}
.pv-tbl .num{font-variant-numeric:tabular-nums}
.pv-items th.sz,.pv-items td.c.num{min-width:30px}
.pv-items .desc{min-width:200px}
.pv-items tbody tr:last-child td{border-bottom:0}
.pv-desc{display:flex;gap:8px;align-items:flex-start}
.pv-pre{white-space:pre-wrap;word-break:break-word;margin:0}
.pv-pers{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}
.pv-pers span{font-size:11.5px;padding:1px 7px;border-radius:4px;background:var(--surface-2)}
.pv-chip{display:inline-block;font-size:11px;padding:1px 7px;border-radius:99px;background:var(--surface-2);color:var(--ink-2);margin-left:6px;font-weight:600;text-transform:capitalize}
.pv-chip.approved{background:var(--ok-soft);color:var(--ok)}.pv-chip.declined,.pv-chip.revoked{background:var(--danger-soft);color:var(--danger)}
.pv-imprint{border-top:1px solid var(--line);padding:12px 16px;background:color-mix(in srgb,var(--accent) 3%,var(--surface))}
.pv-imp-t{display:flex;align-items:center;gap:8px;margin-bottom:6px}
.pv-imp-k{font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--accent);font-weight:800}
.pv-imp-b{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:14px;align-items:start;font-size:13.5px}
@media (max-width:700px){.pv-imp-b{grid-template-columns:1fr}}
.pv-mocks{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end}
.pv-thumb{display:grid;place-items:center;width:120px;height:120px;padding:4px;border:1px solid var(--line);border-radius:8px;background:#fff;cursor:zoom-in;overflow:hidden}
.pv-thumb img{max-width:100%;max-height:100%;object-fit:contain}
.pv-thumb.sm{width:48px;height:48px;flex:none;padding:2px}
.pv-doc{font-size:12px;font-weight:800;color:#555}
.pv-bottom{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:14px;align-items:start}
@media (max-width:1180px){.pv-bottom{grid-template-columns:1fr}.pv-bottom .pv-totals{max-width:420px;margin-left:auto;width:100%}}
.pv-stack{display:flex;flex-direction:column;gap:14px;min-width:0}
.pv-totals{display:flex;flex-direction:column;gap:6px;font-size:13.5px}
.pv-totals>div{display:flex;justify-content:space-between;gap:12px}
.pv-totals b{font-variant-numeric:tabular-nums}
.pv-totals .pvt-sub{color:var(--ink-3)}
.pv-totals .pvt-line{border-top:1px solid var(--line);padding-top:6px}
.pv-totals .pvt-big{font-size:16px;border-top:1px solid var(--line);padding-top:6px}
.pv-files{display:flex;flex-wrap:wrap;gap:12px}
.pv-file{display:flex;flex-direction:column;gap:4px;width:120px;font-size:12px;word-break:break-all}
.pv-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px;font-size:13.5px}
.pv-list li.done{color:var(--ink-3)}
.pv-box{display:inline-grid;place-items:center;width:16px;height:16px;border:1.5px solid var(--line);border-radius:4px;font-size:11px;color:var(--ok);vertical-align:-3px}
.pv-msgs{display:flex;flex-direction:column;gap:10px}
.pv-appr{display:inline-block;padding:5px 11px;border-radius:99px;font-size:12.5px;font-weight:700;background:var(--surface-2);color:var(--ink-2)}
.pv-appr.ok{background:var(--ok-soft);color:var(--ok)}.pv-appr.bad{background:var(--danger-soft);color:var(--danger)}.pv-appr.wait{background:var(--warn-soft);color:var(--warn)}
.pvh{display:flex;flex-direction:column;gap:10px;position:relative}
.pvh-ev.pvh-appr-row{padding-left:2px}
.pvh-ev .pv-msg{max-width:none;margin:0}
.pvh-panel .panel-h{flex-wrap:wrap;gap:2px 10px}
.pvh-panel .pv-msg{font-size:13px;padding:9px 10px}
.pvh-panel .pv-pre.clamp{-webkit-line-clamp:5}
.pvh-appr{display:flex;gap:10px;align-items:flex-start;font-size:13.5px}
.pvh-dot{flex:none;width:24px;height:24px;border-radius:50%;display:grid;place-items:center;font-size:12px;font-weight:700;background:var(--surface-2);color:var(--ink-2)}
.pvh-appr.ok .pvh-dot{background:var(--ok-soft);color:var(--ok)}.pvh-appr.bad .pvh-dot{background:var(--danger-soft);color:var(--danger)}
.pvh-appr .faint{font-size:12px}
.pvh-reason{margin-top:3px;font-style:italic}
.pvh-to{font-size:12px;margin:-2px 0 4px;word-break:break-word}
.pv-pre.clamp{display:-webkit-box;-webkit-line-clamp:8;-webkit-box-orient:vertical;overflow:hidden}
.pvh-att{display:flex;flex-wrap:wrap;gap:6px 12px;margin-top:6px;font-size:12.5px}
.pvh-att a{color:var(--accent);text-decoration:none}.pvh-att a:hover{text-decoration:underline}
.pv-chip.st-opened,.pv-chip.st-clicked{background:var(--ok-soft);color:var(--ok)}.pv-chip.st-bounced,.pv-chip.st-failed,.pv-chip.st-dropped{background:var(--danger-soft);color:var(--danger)}
.pv-msg{border:1px solid var(--line);border-radius:10px;padding:10px 12px;font-size:13.5px;max-width:860px}
.pv-msg.in{background:var(--surface-2)}
.pv-msg-h{display:flex;flex-wrap:wrap;gap:4px 10px;align-items:center;margin-bottom:4px}
.pv-msg-s{font-weight:600;margin-bottom:4px}
.pv-zoom{position:fixed;inset:0;z-index:80;background:rgba(10,14,20,.82);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:24px}
.pv-zoom img{max-width:min(1100px,94vw);max-height:80vh;object-fit:contain;background:#fff;border-radius:8px}
.pv-zoom-bar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;justify-content:center}
.pv-zoom-name{color:#fff;font-weight:600;max-width:min(60vw,640px);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pv-zoom>.pv-doc{background:#fff;border-radius:8px;padding:48px 64px;font-size:28px}
.pv-zoom-bar a{color:#fff;font-weight:600}
.pv-dot{display:inline-flex;align-items:center;gap:7px;font-size:13px;font-weight:600}
.pv-dot::before{content:"";width:10px;height:10px;border-radius:50%;background:var(--sc)}
.pv-err{margin:10px 0;padding:10px 14px;border-radius:8px;background:var(--danger-soft);color:var(--danger)}
.pv-prog{display:grid;grid-template-columns:190px 1fr;align-items:center;gap:12px;font-size:13px}
.pv-prog i{height:8px;border-radius:99px;background:var(--surface-2);position:relative;overflow:hidden}
.psy-state{font-size:12.5px;font-weight:700;color:var(--ink-3)}.psy-state.on{color:var(--ok)}
.psy-phase{font-size:14px}
.pvc-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.pvc-kpis>div{border:1px solid var(--line);border-radius:10px;padding:10px 12px;display:flex;flex-direction:column;gap:2px;min-width:0}
.pvc-kpis span{font-size:12px;color:var(--ink-3)}
.pvc-kpis b{font-size:20px}
.pvc-kpis small{font-size:12px;color:var(--ink-3)}
.pvc-kpis .hi{border-color:var(--accent);background:var(--accent-soft)}
@media (max-width:700px){.pvc-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}
.pv-prog i::after{content:"";position:absolute;inset:0 auto 0 0;width:var(--p);background:var(--accent);transition:width .3s}
.pv-log{list-style:none;margin:0;padding:0;max-height:320px;overflow:auto;font-size:12.5px;display:flex;flex-direction:column;gap:3px}
.pv-log li span{color:var(--ink-3);font-family:var(--mono);font-size:11px;margin-right:8px}
.pv-log li.bad{color:var(--danger)}
.pv-arch{display:inline-block;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;padding:2px 8px;border-radius:99px;background:var(--surface);color:var(--ink-2);border:1px solid var(--line)}
.aa-arch{display:inline-block;margin-left:8px;font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;padding:1px 7px;border-radius:99px;background:var(--surface-2);color:var(--ink-3);vertical-align:1px}
.aa-pill.arch{--sc:var(--ink-3)}
@media print{
  .side,.p-top,.back,.preview-bar,.pv-note,.pv-zoom,nav{display:none!important}
  .app{display:block}
  body{background:#fff}
  .pv-card,.pv-head,.pv-info{break-inside:avoid;border-color:#ccc}
  .pv-group{break-inside:auto}
}
/* production notes & files (shop only) */
.prod-lock{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;padding:2px 8px;border-radius:99px;background:var(--warn-soft);color:var(--warn)}
.prod-note{white-space:pre-wrap;word-break:break-word;padding:10px 12px;border:1px solid var(--line-2);border-radius:8px;background:var(--surface-2);min-height:44px}
.prod-files{display:grid;grid-template-columns:repeat(auto-fill,minmax(132px,1fr));gap:12px;padding:10px;border:1.5px dashed transparent;border-radius:10px;margin:-10px}
.prod-files.over{border-color:var(--accent);background:var(--accent-soft)}
.prod-file{display:flex;flex-direction:column;gap:4px;min-width:0}
.prod-thumb{display:grid;place-items:center;aspect-ratio:1;width:100%;padding:6px;border:1px solid var(--line);border-radius:8px;background:#fff;cursor:pointer;overflow:hidden}
.prod-thumb img{max-width:100%;max-height:100%;object-fit:contain}
.prod-thumb span{font-weight:800;font-size:14px;color:#556}
.prod-fname{font-size:12.5px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.prod-facts{display:flex;gap:10px;font-size:12px}
.prod-facts .linkish{background:none;border:0;padding:0;color:var(--danger);cursor:pointer;font-size:12px}
.prod-facts .linkish.armed{font-weight:700;text-decoration:underline}
.prod-drop{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;aspect-ratio:1;border:1.5px dashed var(--line);border-radius:8px;background:var(--surface-2);color:var(--ink-2);cursor:pointer;font-size:12.5px}
.prod-drop:hover{border-color:var(--accent);color:var(--accent)}
.prod-drop b{font-size:13.5px}
@media print{.prod-drop{display:none}}
.pv-pays{display:flex;flex-direction:column;gap:10px}
.pv-pay{display:flex;flex-direction:column;gap:1px;font-size:13px;padding-bottom:10px;border-bottom:1px solid var(--line-2)}
.pv-pay>div:first-child{display:flex;justify-content:space-between;gap:8px}
.pv-pay b{font-variant-numeric:tabular-nums;font-size:14px}
.pv-pay-d{font-size:12.5px;color:var(--ink-2)}
.pv-pay-bal{display:flex;justify-content:space-between;font-size:14px}
.pv-pay-bal b.due{color:var(--danger)}
.pv-aside .pv-msgs{max-height:520px;overflow:auto}
.pv-aside .pv-msg{font-size:12.5px}
.prod-compact .prod-files{grid-template-columns:repeat(auto-fill,minmax(88px,1fr));gap:10px}
.prod-compact .prod-thumb span{font-size:12px}
@media (max-width:1280px){.pva-grid{grid-template-columns:1fr}.pv-aside{position:static}}
@media print{.pv-aside,.ed-aside{display:none!important}.ed-grid{display:block}}
.prod .panel-h{flex-wrap:wrap;gap:6px}
.prod-lock{white-space:nowrap}
.prod-compact .panel-h h2{font-size:15px}

/* ---------- Messages hub (portal dashboard centerpiece + shop customer page) ---------- */
.mh-box{container-type:inline-size;min-width:0}
.mh{display:grid;grid-template-columns:290px minmax(0,1fr);height:var(--mh-h,620px);min-height:460px;background:var(--surface);border:1px solid var(--line);border-radius:16px;overflow:hidden;box-shadow:var(--shadow)}
.mh-loading{display:grid;place-items:center;color:var(--ink-3);grid-template-columns:1fr}
.mh-list{display:flex;flex-direction:column;border-right:1px solid var(--line);min-height:0;background:color-mix(in srgb,var(--surface-2) 45%,var(--surface))}
.mh-list-h{padding:16px 14px 10px;display:flex;flex-direction:column;gap:10px}
.mh-list-h h2{margin:0;font-size:19px;display:flex;align-items:center;gap:8px}
.mh-badge{font-size:12px;font-weight:800;background:var(--danger);color:#fff;border-radius:99px;padding:1px 8px}
.mh-list-h input{width:100%;padding:8px 11px;border-radius:9px;border:1px solid var(--line);background:var(--surface)}
.mh-convos{flex:1;overflow:auto;padding:0 8px 8px;display:flex;flex-direction:column;gap:2px}
.mh-c{flex:none;display:grid;grid-template-columns:38px minmax(0,1fr) auto;gap:10px;align-items:center;text-align:left;border:0;background:none;border-radius:10px;padding:9px 8px;cursor:pointer;color:inherit}
.mh-c:hover{background:var(--surface)}
.mh-c.on{background:var(--accent-soft)}
.mh-av{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:var(--surface-3);color:var(--ink-2);font-weight:800;font-size:15px}
.mh-av.gen{background:var(--accent);color:#fff;font-size:17px}
.mh-c-main{display:flex;flex-direction:column;min-width:0;gap:1px}
.mh-c-top{display:flex;justify-content:space-between;gap:6px;align-items:baseline}
.mh-c-top b{font-size:13.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mh-c-t{font-size:11.5px;color:var(--ink-3);flex:none}
.mh-c-sub{font-size:12.5px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mh-c.is-unread .mh-c-top b,.mh-c.is-unread .mh-c-sub{color:var(--ink);font-weight:700}
.mh-dot{min-width:20px;height:20px;border-radius:99px;background:var(--danger);color:#fff;font-size:11px;font-weight:800;display:grid;place-items:center;padding:0 6px}
.mh-none{padding:14px;color:var(--ink-3);font-size:13px}
.mh-new{display:flex;flex-direction:column;gap:4px;padding:10px 14px 14px;border-top:1px solid var(--line);font-size:12px;font-weight:700;color:var(--ink-3)}
.mh-new select{font-weight:500;color:var(--ink)}
.mh-thread{position:relative;display:flex;flex-direction:column;min-height:0;min-width:0}
.mh-th{display:flex;align-items:center;gap:10px;padding:14px 18px;border-bottom:1px solid var(--line)}
.mh-th-t{display:flex;flex-direction:column;min-width:0;flex:1}
.mh-th-t b{font-size:16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mh-th-t span{font-size:12.5px;color:var(--ink-3)}
.mh-back{display:none;border:0;background:none;color:var(--ink-2);padding:4px;cursor:pointer}
.mh-scroll{flex:1;overflow:auto;padding:18px 20px;display:flex;flex-direction:column;gap:6px;background:linear-gradient(180deg,var(--surface),color-mix(in srgb,var(--surface-2) 40%,var(--surface)))}
.mh-empty{margin:auto;max-width:380px;text-align:center;display:flex;flex-direction:column;gap:6px;color:var(--ink-2);font-size:14px;padding:30px 10px}
.mh-empty b{font-size:17px;color:var(--ink)}
.mh-day{display:flex;justify-content:center;margin:10px 0 6px}
.mh-day span{font-size:11.5px;font-weight:700;color:var(--ink-3);background:var(--surface-2);padding:3px 10px;border-radius:99px}
.mh-m{display:flex;flex-direction:column;align-items:flex-start;max-width:78%;margin:2px 0}
.mh-m.me{align-self:flex-end;align-items:flex-end;margin-left:auto}
.mh-who{font-size:11.5px;font-weight:700;color:var(--ink-3);margin:0 0 3px 4px}
.mh-b{background:var(--surface);border:1px solid var(--line);border-radius:16px 16px 16px 4px;padding:9px 13px;font-size:14.5px;line-height:1.45;box-shadow:0 1px 1px rgba(0,0,0,.03)}
.mh-m.me .mh-b{background:var(--accent);border-color:var(--accent);color:#fff;border-radius:16px 16px 4px 16px}
.mh-text{white-space:pre-wrap;word-break:break-word}
.mh-files{display:flex;flex-wrap:wrap;gap:6px;margin-top:6px}
.mh-text:empty+.mh-files,.mh-b>.mh-files:first-child{margin-top:0}
.mh-img{display:block;border-radius:10px;overflow:hidden;background:#fff;max-width:240px}
.mh-img img{display:block;max-width:240px;max-height:200px;object-fit:contain}
.mh-file{display:flex;align-items:center;gap:8px;padding:7px 10px;border-radius:10px;background:var(--surface-2);color:var(--ink);text-decoration:none;max-width:260px}
.mh-m.me .mh-file{background:rgba(255,255,255,.18);color:#fff}
.mh-file .ext{font-size:10.5px;font-weight:800;background:var(--surface);color:var(--ink-2);padding:3px 5px;border-radius:5px}
.mh-file .nm{display:flex;flex-direction:column;font-size:12.5px;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mh-file small{opacity:.7}
.mh-time{font-size:11px;color:var(--ink-3);margin:3px 6px 0}
.mh-compose{border-top:1px solid var(--line);padding:10px 14px 8px;background:var(--surface)}
.mh-pending{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px}
.mh-pf{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;background:var(--surface-2);border-radius:8px;padding:4px 6px 4px 10px;max-width:260px}
.mh-pf small{color:var(--ink-3)}
.mh-pf.up small{color:var(--accent)}
.mh-pf.bad{background:var(--danger-soft);color:var(--danger)}
.mh-pf button{border:0;background:none;cursor:pointer;color:var(--ink-3);padding:2px 4px}
.mh-row{display:flex;align-items:flex-end;gap:8px}
.mh-row textarea{flex:1;resize:none;min-height:44px;max-height:160px;padding:11px 14px;border-radius:12px;border:1px solid var(--line);background:var(--surface-2);font-size:14.5px;line-height:1.4}
.mh-row textarea:focus{outline:2px solid var(--accent);outline-offset:-1px;background:var(--surface)}
.mh-att{width:44px;height:44px;flex:none;border-radius:12px;border:1px solid var(--line);background:var(--surface);color:var(--ink-2);display:grid;place-items:center;cursor:pointer}
.mh-att:hover{color:var(--accent);border-color:var(--accent)}
.mh-send{height:44px;flex:none;display:inline-flex;align-items:center;gap:6px;padding:0 16px;border-radius:12px;border:0;background:var(--accent);color:#fff;font-weight:700;cursor:pointer}
.mh-send:disabled,.mh-att:disabled{opacity:.45;cursor:default}
.mh-hint{font-size:11.5px;color:var(--ink-3);margin-top:5px;min-height:15px}
.mh-hint .bad{color:var(--danger)}
.mh-drop{position:absolute;inset:8px;border:2px dashed var(--accent);border-radius:14px;background:color-mix(in srgb,var(--accent-soft) 85%,transparent);display:grid;place-items:center;font-weight:800;color:var(--accent);font-size:16px;pointer-events:none}
@container (max-width:680px){
  .mh{grid-template-columns:1fr;height:min(var(--mh-h,620px),78vh)}
  .mh:not(.thread-open){height:auto;min-height:0}
  .mh:not(.thread-open) .mh-convos{max-height:420px}
  .mh-list{border-right:0}
  .mh.thread-open .mh-list{display:none}
  .mh:not(.thread-open) .mh-thread{display:none}
  .mh-back{display:inline-flex}
  .mh-m{max-width:88%}
  .mh-send span{display:none}
  .mh-send{padding:0 13px}
}

/* ---------- Portal dashboard ---------- */
.pd{display:flex;flex-direction:column;gap:16px}
.pd-top{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:14px}
.pd-hello h2{margin:0;font-size:24px;letter-spacing:-.01em}
.pd-hello span{color:var(--ink-2);font-size:14px}
.pd-actions{display:flex;flex-wrap:wrap;gap:10px}
.pd-act{display:flex;align-items:center;gap:10px;padding:8px 16px 8px 10px;border-radius:12px;border:1px solid var(--line);background:var(--surface);cursor:pointer;text-align:left;color:inherit;text-decoration:none}
.pd-act:hover{border-color:var(--accent)}
.pd-act.main{background:var(--accent);border-color:var(--accent);color:#fff}
.pd-act.main .ic{background:rgba(255,255,255,.2);color:#fff}
.pd-act.main small{color:rgba(255,255,255,.85)}
.pd-act:disabled{opacity:.6;cursor:default}
.pd-act .ic{width:34px;height:34px;border-radius:9px;display:grid;place-items:center;background:var(--accent-soft);color:var(--accent)}
.pd-act b{display:block;font-size:14px}
.pd-act small{display:block;font-size:12px;color:var(--ink-3)}
.pd-act.pay{border-color:#F6DDB0;background:#FFF7E8}
.pd-act.pay .ic{background:#FDE7C2;color:#B7791F}
.pd-grid{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:16px;align-items:start}
.pd-main{min-width:0}
.pd-side{display:flex;flex-direction:column;gap:14px;min-width:0}
.pd-card{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:14px}
.pd-card-h{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px}
.pd-card-h h3{margin:0;font-size:15px}
.pd-link{border:0;background:none;color:var(--accent);font-weight:700;font-size:13px;cursor:pointer;padding:0}
.pd-attn{background:#FFF7E8;border-color:#F6DDB0}
.pd-attn .pd-card-h h3{color:#9A5B0B}
.pd-attn-i{display:grid;grid-template-columns:1fr auto auto;align-items:center;gap:8px;padding:9px 10px;margin-top:6px;border-radius:10px;background:#fff;border:1px solid #F3E2C2;color:inherit;text-decoration:none;font-size:13.5px}
.pd-attn-i:hover{border-color:#E9B45C}
.pd-attn-i .k{font-weight:700;color:#9A5B0B}
.pd-attn-i .v{color:var(--ink-2)}
.pd-glance{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px;padding:8px}
.pd-glance button{display:flex;flex-direction:column;gap:2px;align-items:flex-start;border:0;background:var(--surface-2);border-radius:10px;padding:10px;cursor:pointer;color:inherit;text-align:left;min-width:0}
.pd-glance b{font-size:15px;white-space:nowrap}
.pd-glance span{font-size:11.5px;color:var(--ink-3);line-height:1.2}
.pd-glance .late{background:var(--danger-soft)}
.pd-glance .late b{color:var(--danger)}
.pd-tabs{display:flex;gap:4px;margin-bottom:8px;background:var(--surface-2);padding:3px;border-radius:9px}
.pd-tabs button{flex:1;border:0;background:none;border-radius:7px;padding:6px 4px;font-size:12.5px;font-weight:700;color:var(--ink-2);cursor:pointer;display:inline-flex;justify-content:center;gap:5px}
.pd-tabs button.on{background:var(--surface);color:var(--ink);box-shadow:0 1px 2px rgba(0,0,0,.08)}
