@media (max-width:700px){.st-page{padding:18px}.st-to{grid-template-columns:1fr}.st-aging{grid-template-columns:repeat(2,1fr)}.st-tbl{font-size:12px}.st-tbl th:nth-child(4),.st-tbl td:nth-child(4),.st-tbl th:nth-child(7),.st-tbl td:nth-child(7){display:none}}
