.pj-cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:12px}
.pj-card{display:flex;flex-direction:column;gap:6px;background:var(--surface);border:1px solid var(--line);border-top:4px solid var(--pc);border-radius:14px;padding:14px 16px;color:inherit;text-decoration:none}
.pj-card:hover{box-shadow:var(--shadow);border-color:color-mix(in srgb,var(--pc) 40%,var(--line))}
.pj-top{display:flex;justify-content:space-between;align-items:center;gap:8px}
.pj-st{font-size:11.5px;font-weight:800;color:var(--pc);background:color-mix(in srgb,var(--pc) 12%,transparent);padding:2px 9px;border-radius:99px}
.pj-cd{font-size:12px;font-weight:700;color:var(--ink-3)}
.pj-cd.soon{color:var(--danger)}
.pj-name{font-size:17px}
.pj-co{font-size:12.5px;color:var(--ink-3);margin-top:-4px}
.pj-dates{display:flex;flex-direction:column;gap:2px;font-size:13px;color:var(--ink-2)}
.pj-foot{display:flex;justify-content:space-between;gap:8px;font-size:12.5px;color:var(--ink-3);border-top:1px solid var(--line-2);padding-top:8px;margin-top:2px}
.pj-next{font-size:12.5px;color:var(--ink-2);background:var(--surface-2);border-radius:8px;padding:5px 8px}
.pv2{display:flex;flex-direction:column;gap:14px}
.pv2-h{display:flex;flex-wrap:wrap;justify-content:space-between;gap:14px;background:var(--surface);border:1px solid var(--line);border-left:5px solid var(--pc);border-radius:14px;padding:16px 20px}
.pv2-t{display:flex;flex-direction:column;gap:4px;min-width:0;flex:1}
.pv2-eyebrow{font-size:11.5px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--ink-3)}
.pv2 input.pv2-name{font-size:24px;font-weight:800;border:1px solid transparent;box-shadow:none;border-radius:8px;padding:2px 6px;margin-left:-7px;background:none;width:100%}
.pv2 input.pv2-name:hover:not(:disabled),.pv2 input.pv2-name:focus{border-color:var(--line);background:var(--surface-2);outline:0}
.pv2-when{display:flex;flex-wrap:wrap;gap:6px 18px;font-size:13.5px;color:var(--ink-2)}
.pv2-when i{font-style:normal;color:var(--accent);font-weight:700;margin-left:4px}
.pv2-r{display:flex;flex-direction:column;align-items:flex-end;gap:6px}
.pv2-st{font-weight:700}
.pv2-stp{font-size:12.5px;font-weight:800;color:var(--pc);background:color-mix(in srgb,var(--pc) 12%,transparent);padding:4px 12px;border-radius:99px}
.pv2-money{display:flex;flex-direction:column;align-items:flex-end;font-size:12.5px;color:var(--ink-3)}
.pv2-money b{font-size:20px;color:var(--ink)}
.pv2-money small{color:var(--danger);font-weight:700}
.pv2-grid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:14px;align-items:start}
.pv2-main,.pv2-side{display:flex;flex-direction:column;gap:14px;min-width:0}
.pv2-orders{min-width:0}
.pv2-link{display:flex;gap:8px;margin-top:10px}
.pv2-link select{flex:1}
.pv2-dates{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}
.pv2-dates li{display:grid;grid-template-columns:auto 1fr;gap:0 10px;font-size:13px}
.pv2-dates .d{font-weight:700;white-space:nowrap}
.pv2-dates .c{grid-column:2;font-size:11.5px;color:var(--ink-3)}
.pv2-dates li.event .t,.pv2-dates li.hands .t{font-weight:800;color:var(--accent)}
.pv2-tasks{display:flex;flex-direction:column;gap:8px}
.pv2-task{display:grid;grid-template-columns:auto 1fr auto;gap:8px;align-items:start;font-size:13.5px}
.pv2-task input{margin-top:3px}
.pv2-task .tt{display:block}
.pv2-task.done .tt{text-decoration:line-through;color:var(--ink-3)}
.pv2-task .tm{display:flex;gap:6px;align-items:center;font-size:11.5px;color:var(--ink-3)}
.pv2-task .tm i{font-style:normal;font-weight:700;padding:0 6px;border-radius:99px;background:var(--surface-2)}
.pv2-task .tm i.customer{background:#FEF3C7;color:#92400E}
.pv2-task .tm i.so{background:var(--danger-soft);color:var(--danger)}
.pv2-task.late .tm span{color:var(--danger);font-weight:700}
.pv2-add{display:flex;flex-direction:column;gap:6px;border-top:1px dashed var(--line);padding-top:10px}
.pv2-add .row{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.pv2-add input[type=date]{width:auto}
.pv2-msgs h2{font-size:17px;margin:4px 0 10px}
@media (max-width:1000px){.pv2-grid{grid-template-columns:1fr}}
@media (max-width:560px){.pj-grid,.pv2-details{grid-template-columns:1fr}}

/* ---------- Program pricing ---------- */
.pg-none{display:flex;flex-direction:column;align-items:center;text-align:center;gap:10px;padding:40px 20px;background:var(--surface);border:1px dashed var(--line);border-radius:16px;max-width:620px;margin:0 auto}
.pg-none h3{margin:0}
.pg-none p{margin:0;color:var(--ink-2)}
.pg-none-ic{width:56px;height:56px;border-radius:50%;display:grid;place-items:center;background:#FEF3C7;color:#D97706;font-size:28px}
.pg-notes{background:var(--accent-soft);border-radius:10px;padding:10px 14px;font-size:13.5px;margin-bottom:12px}
.pg-wrap{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:16px;align-items:start}
.pg-items{display:flex;flex-direction:column;gap:12px}
.pg-item{display:grid;grid-template-columns:120px minmax(0,1fr);gap:14px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:12px}
.pg-item.on{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft)}
.pg-img{aspect-ratio:1;border-radius:10px;background:var(--surface-2);display:grid;place-items:center;overflow:hidden;font-size:40px}
.pg-img img{width:100%;height:100%;object-fit:contain;background:#fff}
.pg-body{display:flex;flex-direction:column;gap:6px;min-width:0}
.pg-top{display:flex;justify-content:space-between;gap:10px;align-items:baseline}
.pg-top b{font-size:16px}
.pg-price{font-size:18px;font-weight:800;color:var(--accent);white-space:nowrap}
.pg-price small{font-size:11.5px;font-weight:600;color:var(--ink-3);margin-left:3px}
.pg-sub{font-size:12.5px;color:var(--ink-3)}
.pg-colors{display:flex;flex-wrap:wrap;gap:6px}
.pg-colors button{border:1px solid var(--line);background:var(--surface);border-radius:99px;padding:4px 11px;font-size:12.5px;font-weight:600;cursor:pointer}
.pg-colors button.on{background:var(--ink);color:var(--surface);border-color:var(--ink)}
.pg-sizes{display:flex;flex-wrap:wrap;gap:6px}
.pg-sizes label{display:flex;flex-direction:column;align-items:center;gap:2px;font-size:11px;font-weight:700;color:var(--ink-3)}
.pg-sizes input{width:52px;text-align:center;padding:6px 4px}
.pg-line{font-size:13px}
.pg-line .bad{color:var(--danger)}
.pg-cart{position:sticky;top:16px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px;display:flex;flex-direction:column;gap:10px}
.pg-cart h3{margin:0}
.pg-cart label{display:flex;flex-direction:column;gap:4px;font-size:12.5px;font-weight:700;color:var(--ink-2)}
.pg-cart-list{display:flex;flex-direction:column;gap:4px;font-size:13px;max-height:220px;overflow:auto}
.pg-cart-list div{display:flex;justify-content:space-between;gap:8px}
.pg-total{display:flex;justify-content:space-between;font-size:16px;border-top:1px solid var(--line);padding-top:8px}
.pg-total b{font-size:20px}
@media (max-width:900px){.pg-wrap{grid-template-columns:1fr}.pg-cart{position:static}}
@media (max-width:520px){.pg-item{grid-template-columns:80px minmax(0,1fr)}}
.pga{display:flex;flex-direction:column;gap:12px}
.pga-head{display:grid;grid-template-columns:1fr 2fr;gap:10px}
.pga-head label,.pga-row label{display:flex;flex-direction:column;gap:4px;font-size:12px;font-weight:700;color:var(--ink-2)}
.pga-items{display:flex;flex-direction:column;gap:12px}
.pga-item{display:grid;grid-template-columns:120px minmax(0,1fr);gap:14px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:14px}
.pga-item.off{opacity:.6}
.pga-img{display:flex;flex-direction:column;gap:6px;align-items:stretch}
.pga-img>img,.pga-img>span{aspect-ratio:1;border-radius:10px;background:var(--surface-2);display:grid;place-items:center;font-size:36px;object-fit:contain;width:100%}
.pga-fields{display:flex;flex-direction:column;gap:8px;min-width:0}
.pga-row{display:flex;flex-wrap:wrap;gap:8px;align-items:flex-end}
.pga-row label{flex:0 1 160px}
.pga-row label.grow{flex:1 1 220px}
.pga-row .qp-amt-in{width:auto}
.pga-price{margin-left:auto;font-weight:800;color:var(--accent)}
.pga-sizes,.pga-imps{display:flex;flex-wrap:wrap;gap:6px;align-items:center;font-size:12px;font-weight:700;color:var(--ink-2)}
.pga-sizes button{border:1px solid var(--line);background:var(--surface);border-radius:6px;padding:3px 7px;font-size:12px;font-weight:700;cursor:pointer;color:var(--ink-3)}
.pga-sizes button.on{background:var(--accent);border-color:var(--accent);color:#fff}
.pga-imps{flex-direction:column;align-items:stretch}
.pga-imp{display:flex;flex-wrap:wrap;gap:6px}
.pga-imp select,.pga-imp input{flex:1 1 130px;width:auto}
@media (max-width:700px){.pga-item{grid-template-columns:1fr}.pga-head{grid-template-columns:1fr}}

/* customer contacts (staff) */
.cc{display:flex;flex-direction:column;gap:6px;margin-top:4px}
.cc-h{display:flex;justify-content:space-between;align-items:baseline;gap:10px;flex-wrap:wrap}
.cc-row{display:grid;grid-template-columns:1.1fr 1.4fr 1fr auto 30px;gap:6px;align-items:center}
.cc-row input[type=text],.cc-row input[type=email],.cc-row input[type=tel]{min-width:0}
.cc-row .check{font-size:12.5px;white-space:nowrap}
.cc-tag{font-size:11px;font-weight:700;color:var(--ink-3);text-align:center}
.cc .btn.sm{align-self:flex-start}
@media (max-width:700px){.cc-row{grid-template-columns:1fr 1fr}.cc-row input[type=email]{grid-column:span 2}}

/* shipping center */
.sc-scan{width:280px;max-width:60vw;font-size:15px;padding:9px 12px;border:2px solid var(--accent);border-radius:10px}
.sc-set{margin-bottom:14px}
.sc-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}
.sc-nums{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 12px}
.sc-nums label,.sw-addr label,.sw-acct label,.sw-note{display:flex;flex-direction:column;gap:3px;font-size:12.5px;color:var(--ink-2);font-weight:600}
.sc-box{display:grid;grid-template-columns:1.3fr repeat(3,70px) 30px;gap:6px;margin-bottom:6px}
.sc-box input{min-width:0}
@media (max-width:860px){.sc-grid{grid-template-columns:1fr}}
.pp-sheet.sw{width:min(1180px,100%)}
.sw-scan{width:170px;font-size:13px;padding:6px 10px}
.sw-cols{display:grid;grid-template-columns:minmax(0,1fr) 330px}
.sw-main{padding:16px 22px;border-right:1px solid var(--line);min-width:0}
.sw-side{padding:16px 18px;display:flex;flex-direction:column;gap:8px;background:var(--surface-2)}
.sw-side select,.sw-side input[type=text],.sw-side textarea{width:100%}
.sw-h{font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;color:var(--ink-3);margin-top:6px}
.sw-addr{display:grid;grid-template-columns:1fr 1fr;gap:6px 8px}
.sw-addr .wide{grid-column:span 2}
.sw-st{display:grid;grid-template-columns:70px 1fr;gap:8px}
.sw-warn{font-size:12.5px;color:var(--warn);font-weight:600}
.sw-bill{display:flex;flex-direction:column;gap:4px}
.sw-billopt{display:flex;gap:8px;align-items:center;padding:7px 10px;border:1px solid var(--line);border-radius:8px;background:var(--surface);font-size:13.5px;cursor:pointer}
.sw-billopt.on{border-color:var(--accent);background:var(--accent-soft)}
.sw-acct{display:grid;grid-template-columns:1.4fr 1fr;gap:8px}
.sw-est{display:flex;flex-direction:column;gap:8px;margin-bottom:10px;font-size:14px}
.sw-presets{display:flex;flex-wrap:wrap;gap:6px;align-items:center;font-size:12.5px}
.chip{border:1px solid var(--line);background:var(--surface);border-radius:99px;padding:4px 10px;font-size:12.5px;cursor:pointer;color:var(--ink-2)}
.chip:hover{border-color:var(--accent);color:var(--accent)}
.sw-boxes{width:100%;border-collapse:collapse;font-size:14px}
.sw-boxes th{text-align:left;font-size:12px;color:var(--ink-3);font-weight:700;padding:6px 6px;border-bottom:1px solid var(--line)}
.sw-boxes td{padding:6px;border-bottom:1px solid var(--line-2,var(--line));vertical-align:middle}
.sw-boxes tr.ok .sw-n{color:var(--ok)}
.sw-n{font-weight:700;white-space:nowrap}
.sw-n small{display:block;font-weight:500;color:var(--ink-3);font-size:11.5px}
.sw-in{display:flex;align-items:center;gap:4px}
.sw-in input{width:64px;text-align:right}
.sw-in.w input{width:78px;font-weight:700}
.sw-in span{font-size:12px;color:var(--ink-3)}
.sw-trk{width:190px;font-family:var(--mono);font-size:12.5px}
.sw-act{white-space:nowrap;text-align:right}
.sw-foot{display:flex;align-items:center;gap:12px;margin:10px 0 16px;font-size:13px}
.sw-rates{border-top:1px solid var(--line);padding-top:12px;display:flex;flex-direction:column;gap:8px}
.sw-rate-list{display:flex;flex-direction:column;gap:6px;max-height:280px;overflow:auto}
.sw-rate{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;padding:9px 12px;border:1px solid var(--line);border-radius:10px;cursor:pointer}
.sw-rate.on{border-color:var(--accent);background:var(--accent-soft)}
.sw-rate-n,.sw-rate-p{display:flex;flex-direction:column}
.sw-rate-p{text-align:right}
.sw-rate small{font-size:12px;color:var(--ink-3)}
.sw-bar{display:flex;align-items:center;gap:8px;padding:12px 22px;border-top:1px solid var(--line);flex-wrap:wrap}
@media (max-width:900px){.sw-cols{grid-template-columns:1fr}.sw-main{border-right:0;border-bottom:1px solid var(--line)}.sw-boxes{font-size:13px}.sw-in input{width:52px}}
.pp-sheet.sw .pp-sheet-h{gap:12px}
.pp-sheet.sw .pp-sheet-h>.row{flex-wrap:nowrap;flex:none}
.pp-sheet.sw .sw-scan{width:170px;flex:none}
.sc-panes{display:grid;grid-template-columns:1fr 1fr;gap:14px;align-items:start}
.sc-pane{background:var(--surface);border:1px solid var(--line);border-radius:14px;display:flex;flex-direction:column;max-height:calc(100vh - 220px);min-height:240px}
.sc-pane.warn{border-color:color-mix(in srgb,var(--warn) 45%,var(--line))}
.sc-pane-h{display:flex;align-items:center;gap:8px;padding:12px 14px;border-bottom:1px solid var(--line);font-size:14.5px;flex-wrap:wrap}
.sc-pane.warn .sc-pane-h{background:var(--warn-soft);border-radius:14px 14px 0 0}
.sc-pane-h .faint{font-size:12.5px}
.sc-pane-b{overflow:auto;padding:10px;display:flex;flex-direction:column;gap:8px}
.sc-card{all:unset;box-sizing:border-box;display:flex;flex-direction:column;gap:4px;padding:11px 13px;border:1px solid var(--line);border-radius:10px;cursor:pointer;background:var(--surface);font-size:13.5px}
.sc-card:hover,.sc-card:focus-visible{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.sc-card.late{border-left:4px solid var(--danger)}
.sc-card-t{display:flex;align-items:center;gap:6px;font-size:15px}
.sc-tag{font-size:11px;font-weight:700;padding:1px 7px;border-radius:99px;background:var(--surface-2);color:var(--ink-3)}
.sc-tag.draft{background:var(--accent-soft);color:var(--accent)}
.sc-due{font-size:12.5px;color:var(--ink-2);font-weight:600}.sc-due.late{color:var(--danger)}
.sc-card-c{font-weight:600}
.sc-card-m{display:flex;flex-wrap:wrap;gap:4px 14px;color:var(--ink-3);font-size:12.5px}
.sc-missing{font-size:12.5px;font-weight:700;color:var(--warn)}
@media (max-width:900px){.sc-panes{grid-template-columns:1fr}.sc-pane{max-height:none}}
.sw-rec{border:2px solid var(--ok);background:var(--ok-soft);border-radius:12px;padding:10px 14px;display:flex;flex-direction:column;gap:2px}
.sw-rec.late{border-color:var(--danger);background:var(--danger-soft)}
.sw-rec-t{font-size:11.5px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;color:var(--ok)}
.sw-rec.late .sw-rec-t{color:var(--danger)}
.sw-rec-b{font-size:15px}
.sw-rec-w{font-size:12.5px;color:var(--ink-2)}
.sw-rate{grid-template-columns:auto 1fr auto auto}
.sw-rate.late{opacity:.75}
.sw-tags{display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end}
.sw-tag{font-size:11px;font-weight:700;padding:2px 8px;border-radius:99px;background:var(--surface-2);color:var(--ink-2)}
.sw-tag.recommended{background:var(--ok);color:#fff}
.sw-tag.cheapest{background:var(--accent-soft);color:var(--accent)}
.sw-tag.fastest{background:var(--warn-soft);color:var(--warn)}
.sw-tag.late{background:var(--danger-soft);color:var(--danger)}
.sw-picks{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px}
.sw-pick{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;gap:1px;padding:10px 14px;border:2px solid var(--line);border-radius:12px;background:var(--surface)}
.sw-pick:hover{border-color:var(--accent)}
.sw-pick.on{border-color:var(--accent);background:var(--accent-soft)}
.sw-pick.late{border-style:dashed}
.sw-pick-t{font-size:11.5px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;color:var(--accent)}
.sw-pick.late .sw-pick-t{color:var(--danger)}
.sw-pick b{font-size:16px}
.sw-pick-s{font-size:12.5px;color:var(--ink-2)}
.sw-pick-p{font-size:18px;font-weight:800;margin-top:2px}
.sw-day{display:flex;flex-direction:column;gap:6px}
.sw-day+.sw-day{margin-top:6px}
.sw-day-h{font-size:12.5px;font-weight:800;color:var(--ink-2);padding:2px 2px 0}
.sw-day-h.late{color:var(--danger)}
.sw-beaten{margin-top:8px;display:flex;flex-direction:column;gap:6px}
.sw-beaten summary{font-size:12.5px;color:var(--ink-3);cursor:pointer;padding:4px 2px}
.sw-beaten[open] summary{margin-bottom:6px}
.sw-rate.dim{opacity:.55;background:var(--surface-2)}
.sw-rate.dim.on{opacity:1}
.sw-rate-list{max-height:none}
.chip.on{border-color:var(--accent);background:var(--accent-soft);color:var(--accent)}
.sw-ask{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:10px;padding:10px 12px;border:1px solid var(--accent);background:var(--accent-soft);border-radius:10px;font-size:13.5px}
.sw-ask>span{flex:1 1 220px}
.sw-many{width:80px}
.gi{display:flex;flex-direction:column;gap:8px}
.gi-l{font-size:13px;font-weight:700}
.gi-chips{display:flex;flex-wrap:wrap;gap:6px}
.gi-chips .chip{font-size:13.5px;padding:6px 12px}
.gi-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px}
.gi-grid label{display:flex;flex-direction:column;gap:3px;font-size:12.5px;font-weight:600;color:var(--ink-2)}
.gi-grid small{font-weight:400;color:var(--ink-3)}
.gc-from{display:flex;align-items:center;gap:8px;flex-wrap:wrap;font-size:13px;color:var(--ink-2);padding:6px 0}
.gc-from.need{color:var(--warn);font-weight:600}
.gc-track{font-size:12.5px;margin:2px 0}
.gc-track b{color:var(--accent)}
.gc-track.t-delivered b{color:var(--ok)}
.gc-track.t-failure b,.gc-track.t-return_to_sender b,.gc-track.t-error b{color:var(--danger)}
.gc-count{display:flex;flex-direction:column;gap:10px}
.gc-count-l{display:flex;flex-direction:column;gap:6px}
.gc-count-l>b{font-size:13.5px}
.gc-count-sz{display:flex;flex-wrap:wrap;gap:6px}
.gc-count-sz label{display:flex;flex-direction:column;align-items:center;gap:2px;padding:6px;border:1px solid var(--line);border-radius:8px;min-width:62px;font-size:12px;font-weight:700}
.gc-count-sz label input{width:56px;text-align:center;font-weight:700}
.gc-count-sz label small{font-weight:500;color:var(--ink-3)}
.gc-count-sz label.ok{border-color:var(--ok);background:var(--ok-soft)}
.gc-count-sz label.bad{border-color:var(--danger);background:var(--danger-soft)}
