.rv-stages>a,.rv-stages>button{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;gap:1px;padding:7px 9px;border:1px solid var(--line-2);border-radius:9px;background:var(--surface-2)}
