.side-search{display:flex;align-items:center;gap:7px;margin:0 4px;padding:0 10px;border-radius:8px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1)}
.side-search:focus-within{border-color:rgba(255,255,255,.35);background:rgba(255,255,255,.1)}
.side-search svg{width:15px;height:15px;flex:none;stroke:var(--side-ink);fill:none;stroke-width:2;stroke-linecap:round}
.side-search input{background:transparent!important;border:0!important;box-shadow:none!important;color:var(--side-ink-strong);padding:8px 0;font-size:13px}
.side-search input::placeholder{color:var(--side-ink);opacity:.8}
.nav-g{display:flex;flex-direction:column;gap:2px;margin-top:10px}
.nav-h{font-family:var(--mono);font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--side-ink);opacity:.75;padding:4px 10px 3px}
.side .btn-new{margin-top:auto}
.nav-foot{margin-top:-4px}
@media (max-width: 820px){
  .side-hello,.side-search,.nav-h{display:none}
  .nav-g{flex-direction:row;margin:0}
  .brand.brand-logo{padding:0}
  .brand.brand-logo span{display:none}
}
.srch-box{display:flex;gap:8px;max-width:720px;margin-bottom:16px}
.srch-box input{font-size:15px;padding:10px 12px}
.srch-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:14px;align-items:start}
.srch-list{list-style:none;margin:0;padding:6px}
.srch-list a{display:block;padding:8px 10px;border-radius:8px;text-decoration:none;color:var(--ink);font-size:13.5px}
.srch-list a:hover{background:var(--accent-soft)}
.srch-list .rv-tag{margin-left:6px}
.srch-list .faint{font-size:12.5px}
.brand-prev{background:var(--side);border-radius:12px;padding:16px;min-height:120px}
/* stronger section headers in the left menu */
.nav-h{display:flex;align-items:center;font-family:var(--display, inherit);font-stretch:125%;font-size:11.5px;font-weight:800;letter-spacing:.2em;color:var(--side-ink-strong);opacity:.9;padding:6px 10px 4px;border-top:1px solid rgba(255,255,255,.08);margin-top:4px;padding-top:10px}
.nav-hb{all:unset;cursor:pointer;font-family:var(--mono);font-size:10px;letter-spacing:.08em;font-weight:600;color:var(--side-ink);opacity:.8}
.nav-hb:hover{opacity:1;color:#fff}
.nav-mine .nav{gap:2px}
.nav-mine-i{display:flex;align-items:center;gap:2px}
.nav-mine-i>a{flex:1;min-width:0}
.nav-mine-i>a .lbl-t{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.nav-mine-x{display:flex;gap:1px}
.nav-mine-x button{all:unset;cursor:pointer;font-size:12px;padding:2px 5px;border-radius:4px;color:var(--side-ink)}
.nav-mine-x button:hover{background:var(--side-hover);color:#fff}
.nav-mine-x button:disabled{opacity:.3;cursor:default}
.nav-mine-empty{font-size:12px;color:var(--side-ink);opacity:.75;padding:2px 10px 4px;line-height:1.35}
.nav-add-btns{display:flex;gap:10px;padding:2px 10px}
.nav-add-btns button{all:unset;cursor:pointer;font-size:11.5px;font-weight:600;color:var(--side-ink);opacity:.85}
.nav-add-btns button:hover{opacity:1;color:#fff;text-decoration:underline}
.nav-add{display:flex;flex-direction:column;gap:6px;padding:4px 6px}
.nav-add input{background:rgba(255,255,255,.08)!important;border:1px solid rgba(255,255,255,.15)!important;color:#fff;font-size:12.5px;padding:6px 8px}
.side .nav-foot{margin-top:auto}
.nav-h{font-family:inherit;font-stretch:normal;font-size:11px;font-weight:800;letter-spacing:.12em}
.nav-add-btns{flex-wrap:wrap}

/* ---------- FBS brand bars: the blue / salmon / orange under the logo, used as a signature across the site ---------- */
:root{--fbs-blue:#0e9bd8;--fbs-salmon:#f26660;--fbs-orange:#fcb122;
  --fbs-bars:linear-gradient(90deg,var(--fbs-blue) 0 32%,transparent 32% 34%,var(--fbs-salmon) 34% 66%,transparent 66% 68%,var(--fbs-orange) 68% 100%);
  --fbs-strip:linear-gradient(90deg,var(--fbs-blue) 0 33.33%,var(--fbs-salmon) 33.33% 66.66%,var(--fbs-orange) 66.66% 100%)}
/* under every page title */
.page-head h1::after{content:"";display:block;width:84px;height:5px;margin-top:9px;background:var(--fbs-bars)}
/* across the top of pop-ups and the customer portal header */
.pp-sheet{border-top:0;position:relative}
.pp-sheet::before{content:"";display:block;height:4px;background:var(--fbs-strip)}
.p-top::after{content:"";display:block;height:3px;background:var(--fbs-strip)}
/* section headings inside panels */
.panel-h h2{position:relative;padding-left:12px}
.panel-h h2::before{content:"";position:absolute;left:0;top:.18em;bottom:.18em;width:4px;border-radius:2px;background:linear-gradient(180deg,var(--fbs-blue) 0 33.33%,var(--fbs-salmon) 33.33% 66.66%,var(--fbs-orange) 66.66% 100%)}
/* the thin line under the menu logo */
.brand.brand-logo{border-bottom:0;position:relative}
.side-hello{position:relative;padding-top:2px}

/* the FBS blue is the site's blue; group headers take the three logo colors */
.nav-h-sales{color:var(--fbs-blue)}
.nav-h-production{color:var(--fbs-salmon)}
.nav-h-shoptools{color:var(--fbs-orange)}
/* page titles: the color bars run the full width of the title and a little past */
.page-head h1{display:inline-block}
.page-head h1::after{width:calc(100% + 28px);min-width:84px;height:5px}
/* two- and more-word headings and buttons: Every Word Capitalized */
.nav .lbl-t,.panel-h h2,.rv-sec span,.rv-kpis span,.rv-views button,.rv-via-h,.pp-sheet-h b,.btn:not(.icon){text-transform:capitalize}
/* the selected page takes its group's logo color: Sales blue, Production salmon, Shop Tools orange */
.nav-g-sales .nav a.on,.nav-g-sales a.on{background:var(--fbs-blue);color:#fff}
.nav-g-production a.on{background:var(--fbs-salmon);color:#fff}
.nav-g-shoptools a.on{background:var(--fbs-orange);color:#1a1405}
.nav-g-shoptools a.on .badge{background:#1a1405;color:#fff}
/* one smooth fade (blue → salmon → orange) instead of three separate bars */
:root{--fbs-fade:linear-gradient(90deg,var(--fbs-blue) 0%,var(--fbs-salmon) 52%,var(--fbs-orange) 100%)}
.page-head h1::after{background:var(--fbs-fade);height:4px;border-radius:4px;width:calc(100% + 60px);min-width:140px;margin-top:10px}
.pp-sheet::before,.p-top::after{background:var(--fbs-fade)}
.panel-h h2::before{background:linear-gradient(180deg,var(--fbs-blue) 0%,var(--fbs-salmon) 52%,var(--fbs-orange) 100%)}
@supports (background: linear-gradient(in oklab 90deg, red, blue)){
  :root{--fbs-fade:linear-gradient(in oklab 90deg,var(--fbs-blue) 0%,var(--fbs-salmon) 52%,var(--fbs-orange) 100%)}
}
.page-head h1::after{height:5px}
/* group headers: white and bold again; the line above each takes its color (Sales blue, Production salmon, Shop Tools orange) */
.nav-h-sales,.nav-h-production,.nav-h-shoptools{color:var(--side-ink-strong)}
.nav-h-sales{border-top:2px solid var(--fbs-blue)}
.nav-h-production{border-top:2px solid var(--fbs-salmon)}
.nav-h-shoptools{border-top:2px solid var(--fbs-orange)}
.rv-grid col.c-ord{width:130px}

/* ======================= Customer portal: FBS colors ======================= */
.portal{background:linear-gradient(180deg,color-mix(in srgb,var(--fbs-blue) 5%,var(--bg)) 0,var(--bg) 420px)}
/* header: dark bar with the white logo, the color fade under it */
.portal .p-top{background:var(--side);border-bottom:0;box-shadow:0 2px 14px rgba(0,0,0,.12)}
.portal .p-top::after{height:4px;background:var(--fbs-fade)}
.portal .p-top-in{padding-block:12px}
.p-brand{display:flex;align-items:center;gap:12px;text-decoration:none}
.portal .p-top .logo{max-height:40px}
.p-brand-t{font-family:var(--mono);font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--side-ink);border-left:1px solid rgba(255,255,255,.2);padding-left:12px}
.portal .p-top .who{color:var(--side-ink)}
.portal .p-top .who .btn{background:transparent;color:#fff;border-color:rgba(255,255,255,.3)}
.portal .p-top .who .btn:hover{background:rgba(255,255,255,.1)}
/* welcome band */
.p-hero{position:relative;overflow:hidden;background:var(--surface);border:1px solid var(--line);border-radius:18px;padding:26px 28px 24px;box-shadow:0 1px 3px rgba(20,29,43,.05)}
.p-hero::before{content:"";position:absolute;inset:0;background:linear-gradient(115deg,color-mix(in srgb,var(--fbs-blue) 12%,transparent) 0%,color-mix(in srgb,var(--fbs-salmon) 9%,transparent) 55%,color-mix(in srgb,var(--fbs-orange) 12%,transparent) 100%);pointer-events:none}
.p-hero>*{position:relative}
.p-hero .eyebrow{color:var(--fbs-blue);font-weight:700}
.p-hero h1{font-size:34px;display:inline-block}
.p-hero-sub{margin:10px 0 0;color:var(--ink-2);font-size:14.5px}
/* every page title in the portal gets the fade bar */
.portal .p-main h1{display:inline-block}
.portal .p-main h1::after{content:"";display:block;height:5px;border-radius:4px;margin-top:10px;width:calc(100% + 60px);min-width:140px;background:var(--fbs-fade)}
/* area tabs: the chosen one in the fade */
.portal .aa-nav{box-shadow:0 1px 3px rgba(20,29,43,.05)}
.portal .aa-tab.on{background:var(--fbs-fade);color:#fff;box-shadow:0 3px 10px color-mix(in srgb,var(--fbs-salmon) 30%,transparent)}
.portal .aa-tab.on .aa-n{background:rgba(255,255,255,.25);color:#fff}
/* stat cards: one logo color each */
.portal .aa-stat{position:relative;overflow:hidden;box-shadow:0 1px 3px rgba(20,29,43,.05)}
.portal .aa-stat::before{content:"";position:absolute;left:0;right:0;top:0;height:4px;background:var(--c,var(--fbs-blue))}
.portal .aa-stat:nth-child(1){--c:var(--fbs-blue)}
.portal .aa-stat:nth-child(2){--c:var(--fbs-salmon)}
.portal .aa-stat:nth-child(3){--c:var(--fbs-orange)}
.portal .aa-stat:nth-child(4){--c:var(--ok)}
.portal .aa-stat .ic{color:var(--c);background:color-mix(in srgb,var(--c) 14%,transparent)}
.portal .aa-stat.red{background:var(--fbs-salmon);border-color:var(--fbs-salmon)}
/* home tabs + table */
.portal .aa-htabs button.on{color:var(--ink);box-shadow:inset 0 3px 0 var(--fbs-blue)}
.portal .aa-htab-body,.portal .aa-card,.portal .panel{box-shadow:0 1px 3px rgba(20,29,43,.05)}
.portal .aa-tbl thead th{background:color-mix(in srgb,var(--fbs-blue) 8%,var(--surface));color:var(--ink-2);border-bottom:2px solid transparent;border-image:var(--fbs-fade) 1}
/* "requires your attention": white card with the fade down its left edge */
.portal .aa-attn{position:relative;background:var(--surface);border:1px solid var(--line);padding-left:20px;box-shadow:0 1px 3px rgba(20,29,43,.05)}
.portal .aa-attn::before{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;border-radius:14px 0 0 14px;background:linear-gradient(180deg,var(--fbs-blue),var(--fbs-salmon) 52%,var(--fbs-orange))}
.portal .aa-attn-h{color:var(--ink)}
.portal .aa-attn-i{background:var(--surface);border-color:var(--line)}
.portal .aa-attn-i:hover{border-color:var(--fbs-salmon);box-shadow:0 2px 10px color-mix(in srgb,var(--fbs-salmon) 18%,transparent)}
.portal .aa-attn-i .k{color:var(--fbs-salmon)}
.portal .aa-attn-i .go{background:color-mix(in srgb,var(--fbs-orange) 20%,transparent);color:#b36d00}
.portal .aa-attn-none{color:var(--ink-3)}
/* section headings */
.portal .aa-sec-h h3{position:relative;padding-bottom:6px}
.portal .aa-sec-h h3::after{content:"";position:absolute;left:0;bottom:0;width:56px;height:3px;border-radius:3px;background:var(--fbs-fade)}
.portal .aa-due{color:var(--danger)}
/* footer */
.p-foot{background:var(--side);color:var(--side-ink);margin-top:20px}
.p-foot::before{content:"";display:block;height:4px;background:var(--fbs-fade)}
.p-foot-in{max-width:1120px;margin:0 auto;padding:18px 20px 26px;display:flex;align-items:center;gap:14px;font-size:12.5px}
.p-foot-logo{height:26px;width:auto;opacity:.9}
.portal .p-top-in{max-width:1120px}
.p-brand-t{white-space:nowrap}

/* page titles: the small label moves under the title (below the color bar) as a quiet subtitle */
.page-head > div:first-child{display:flex;flex-direction:column;align-items:flex-start}
.page-head > div:first-child > .eyebrow{order:2;margin-top:8px;font-family:inherit;font-size:13px;letter-spacing:0;text-transform:none;color:var(--ink-3)}
/* portal tabs: the chosen tab in a solid logo color (blue, salmon, orange in turn) */
.portal .aa-tab.on{box-shadow:none}
.portal .aa-tab.on:nth-child(3n+1){background:var(--fbs-blue);color:#fff}
.portal .aa-tab.on:nth-child(3n+2){background:var(--fbs-salmon);color:#fff}
.portal .aa-tab.on:nth-child(3n){background:var(--fbs-orange);color:#1f1605}
.portal .aa-tab.on:nth-child(3n) .aa-n{background:rgba(0,0,0,.12);color:#1f1605}

/* ---------- phones: a slim top bar (logo + menu button); the full menu opens below it ---------- */
.side-menu-btn{display:none}
.side-drawer{display:contents}
@media (max-width: 820px){
  .side{position:sticky;top:0;z-index:40;height:auto;flex-direction:row;flex-wrap:wrap;align-items:center;justify-content:space-between;padding:10px 16px;gap:0;overflow:visible}
  .side::after{content:"";position:absolute;left:0;right:0;bottom:-3px;height:3px;background:var(--fbs-fade)}
  .brand.brand-logo{flex-direction:row;align-items:center;gap:10px;padding:0}
  .brand.brand-logo img{width:40px!important}
  .brand.brand-logo span{display:inline;font-size:9.5px}
  .side-menu-btn{display:inline-flex;align-items:center;justify-content:center;width:42px;height:42px;border-radius:10px;border:1px solid rgba(255,255,255,.18);background:transparent;color:#fff;cursor:pointer}
  .side-menu-btn svg{width:22px;height:22px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round}
  .side-drawer{display:none}
  .side-drawer.open{display:flex;flex-direction:column;gap:10px;flex-basis:100%;max-height:calc(100dvh - 64px);overflow-y:auto;padding:14px 0 8px}
  .side-drawer .side-hello,.side-drawer .side-search,.side-drawer .nav-h{display:flex}
  .side-drawer .nav{flex-direction:column}
  .side-drawer .nav-g{flex-direction:column;margin-top:8px}
  .side-drawer .nav a{padding:11px 12px;font-size:15px}
  .side-drawer .nav a .lbl-t{display:inline}
  .side-drawer .nav-mine-empty{display:block}
  .side-drawer .side-user{padding-top:6px}
  .main{padding-top:18px}
}
/* ---------- daily dashboard ---------- */
.db-kpis{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;margin-bottom:16px}
.db-kpis>a{display:flex;flex-direction:column;gap:3px;padding:12px 14px;border-radius:12px;background:var(--surface);border:1px solid var(--line);text-decoration:none;color:var(--ink);position:relative;overflow:hidden}
.db-kpis>a::before{content:"";position:absolute;left:0;right:0;top:0;height:3px;background:var(--fbs-blue)}
.db-kpis>a:nth-child(2)::before{background:var(--fbs-salmon)}.db-kpis>a:nth-child(3)::before{background:var(--fbs-orange)}
.db-kpis>a:nth-child(4)::before{background:var(--fbs-salmon)}.db-kpis>a:nth-child(5)::before{background:var(--fbs-orange)}.db-kpis>a:nth-child(6)::before{background:var(--ok)}
.db-kpis>a:hover{border-color:var(--accent)}
.db-kpis span{font-size:12px;color:var(--ink-3);font-weight:600}
.db-kpis b{font-size:24px;line-height:1.1}
.db-kpis b small{font-size:15px;color:var(--ink-3);font-weight:600}
.db-kpis .hot b{color:var(--fbs-blue)}.db-kpis .bad b small{color:var(--danger)}
.db-grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:16px;align-items:start}
.db-col{display:flex;flex-direction:column;gap:16px;min-width:0}
.db-card{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:14px 16px;box-shadow:0 1px 3px rgba(20,29,43,.05);border-top:4px solid var(--c,var(--fbs-blue))}
.db-blue{--c:var(--fbs-blue)}.db-salmon{--c:var(--fbs-salmon)}.db-orange{--c:var(--fbs-orange)}.db-teal{--c:var(--ok)}.db-bad{--c:var(--danger)}
.db-card-h{display:flex;align-items:center;gap:8px;margin-bottom:8px}
.db-card-h h2{margin:0;font-size:16px}
.db-n{font-size:12px;font-weight:700;background:color-mix(in srgb,var(--c) 15%,transparent);color:var(--ink);border-radius:99px;padding:1px 9px}
.db-empty{font-size:13px;color:var(--ink-3);padding:6px 0}
.db-note{font-size:12.5px;color:var(--ink-3);margin:-8px 4px 0}
.db-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.db-scroll{max-height:420px;overflow:auto}
.db-row{display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--line-2);font-size:13.5px}
.db-row:last-child{border-bottom:0}
.db-num{font-weight:800;color:var(--accent);text-decoration:none;min-width:58px}
.db-main{display:flex;flex-direction:column;min-width:0;flex:1}
.db-main b{font-weight:600}
.db-main .faint{font-size:12.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.db-sub{font-size:13px;font-weight:600;color:var(--ink-2)}
.db-body{font-size:12.5px;color:var(--ink-2);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.db-side{display:flex;align-items:center;gap:8px;flex:none}
.db-st{font-size:11.5px;font-weight:600;background:var(--surface-2);border-radius:99px;padding:2px 8px;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.db-sub-h{font-size:11.5px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--ink-3);margin:6px 0 2px}
.db-sub-h.bad{color:var(--danger)}
.db-attach{display:flex;gap:6px}
.db-attach select{width:auto;max-width:170px;padding:4px 6px;font-size:12.5px}
@media (max-width: 1100px){.db-kpis{grid-template-columns:repeat(3,minmax(0,1fr))}.db-grid{grid-template-columns:1fr}}
@media (max-width: 560px){.db-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.db-row{flex-wrap:wrap}.db-side{width:100%;justify-content:space-between}}
@media (max-width: 820px){
  .app{grid-template-rows:auto 1fr;align-content:start}
  .side{align-self:start}
}
/* ---------- dashboard: sales analytics ---------- */
.an{position:relative;overflow:hidden;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:20px 18px 16px;margin-bottom:16px;box-shadow:0 1px 3px rgba(20,29,43,.05)}
.an::before{content:"";position:absolute;left:0;right:0;top:0;height:4px;background:var(--fbs-fade)}
.an-h{display:flex;align-items:baseline;gap:10px;margin-bottom:12px}.an-h h2{margin:0;font-size:18px}.an-h .faint{font-size:12.5px}
.an-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:16px}
.an-kpis>div{display:flex;flex-direction:column;gap:2px;padding:10px 12px;border-radius:10px;background:var(--surface-2)}
.an-kpis span{font-size:12px;color:var(--ink-3);font-weight:600}
.an-kpis b{font-size:26px;line-height:1.15;font-variant-numeric:tabular-nums;color:var(--ink)}
.an-d{font-size:12.5px!important;font-weight:700!important}
.an-d.up{color:var(--ok)!important}.an-d.down{color:var(--danger)!important}
.an-d>span{color:var(--ink-3);font-weight:500}
.an-grid{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);gap:18px;align-items:start}
.an-ch-h{display:flex;align-items:center;gap:12px;margin-bottom:6px;font-size:14px}
.an-legend{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;color:var(--ink-2)}
.an-legend i,.an-tip i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-left:6px}
.k1{background:var(--fbs-blue)}.k2{background:#C3CBD6}
.an-svg-wrap{position:relative}
.an-svg-wrap svg{width:100%;height:auto;display:block}
.an-grid-l{stroke:var(--line-2);stroke-width:1}
.an-ax{font-size:11px;fill:var(--ink-3);font-variant-numeric:tabular-nums}
.an-ax.now{fill:var(--ink);font-weight:700}
.an-b1{fill:var(--fbs-blue)}.an-b2{fill:#C3CBD6}
