/* Production → Employees */
.tp-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:14px;align-items:start}
.tp-col{min-width:0}
.tp-run{font-size:12.5px;font-weight:700;color:#7C5CD6;background:color-mix(in srgb,#7C5CD6 10%,transparent);border-radius:8px;padding:5px 8px}
.tp-list{list-style:none;margin:0 0 8px;padding:0;display:flex;flex-direction:column;gap:6px}
