.tp-l{flex:1;min-width:0;display:flex;flex-direction:column}
.tp-l b{font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tp-l small{font-size:11.5px;color:var(--ink-3)}
.tp-a{display:flex;gap:0}
.tp-add{display:flex;flex-direction:column;gap:6px}
.tp-add ul{list-style:none;margin:0;padding:0;max-height:240px;overflow:auto;border:1px solid var(--line);border-radius:10px}
