.tp-add li button:hover{background:var(--accent-soft)}
.tj-void td{text-decoration:line-through;opacity:.5}
.tj-steps{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.jl-k{display:flex;flex-wrap:wrap;gap:6px 18px}
.jl-k span{font-weight:800;font-size:17px;font-variant-numeric:tabular-nums}
.jl-k small{font-weight:500;font-size:12px;color:var(--ink-3)}
.jl-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:3px;font-size:12.5px}

/* ---------- production calendar (machine lanes) ---------- */
.ms{display:flex;flex-direction:column;gap:10px}
.ms-bar{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.ms-title{margin:0;font-size:20px;margin-right:6px}
.ms-wrap{display:grid;grid-template-columns:260px minmax(0,1fr);gap:12px;align-items:start}
.ms-tray{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:10px;display:flex;flex-direction:column;gap:8px;position:sticky;top:10px;max-height:calc(100vh - 40px);overflow-y:auto;border-top:4px solid var(--fbs-orange)}
.ms-tray-h{display:flex;align-items:center;gap:6px}
.ms-tray-h .btn{margin-left:auto}
.ms-tray ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}
.ms-t{border:1px solid var(--line);border-left:4px solid var(--fbs-blue);border-radius:10px;padding:8px 9px;display:flex;flex-direction:column;gap:4px;cursor:grab;background:var(--surface);font-size:12.5px}
.ms-t.embroidery{border-left-color:#7C5CD6}.ms-t.heat{border-left-color:var(--fbs-orange)}
.ms-t.late{background:var(--danger-soft)}
.ms-t-h{display:flex;gap:6px;align-items:baseline;flex-wrap:wrap}
.ms-t-h span{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:140px}
.ms-t-h small{margin-left:auto;color:var(--ink-3)}
.ms-t-n{color:var(--ink-2)}
.ms-t-s{color:var(--ink)}
.ms-late{color:var(--danger);font-weight:700}
.ms-coming{font-size:12px}
.ms-grid-wrap{min-width:0;overflow-x:auto}
.ms-grid{display:grid;gap:1px;background:var(--line-2,var(--line));border:1px solid var(--line-2,var(--line));border-radius:12px;overflow:hidden}
.ms-h{background:var(--surface-2);padding:7px 6px;font-size:12px;font-weight:700;text-align:center}
.ms-h.today{background:var(--accent-soft);color:var(--accent)}
.ms-m{background:var(--surface);padding:8px;display:flex;flex-direction:column;gap:2px;border-left:4px solid var(--fbs-blue)}
.ms-m.embroidery{border-left-color:#7C5CD6}.ms-m.heat{border-left-color:var(--fbs-orange)}
.ms-m b{font-size:12.5px}
.ms-m small{font-size:11px;color:var(--ink-3)}
.ms-cell{background:var(--surface);min-height:70px;padding:4px;display:flex;flex-direction:column;gap:4px;min-width:0}
.ms-cell.today{background:color-mix(in srgb,var(--accent) 4%,var(--surface))}
.ms-cell.off{background:var(--surface-2)}
.ms-cell.over{outline:2px dashed var(--accent);outline-offset:-3px;background:var(--accent-soft)}
.ms-cell.no{outline:2px dashed var(--danger);outline-offset:-3px;background:var(--danger-soft)}
.ms-cap{height:5px;border-radius:3px;background:var(--surface-2);overflow:hidden;flex:none}
.ms-cap i{display:block;height:100%;background:var(--ok)}
.ms-cap.warn i{background:var(--fbs-orange)}.ms-cap.full i{background:var(--danger)}
.ms-card{all:unset;box-sizing:border-box;cursor:grab;display:flex;flex-direction:column;gap:0;padding:4px 6px;border-radius:7px;background:color-mix(in srgb,var(--fbs-blue) 12%,var(--surface));border-left:3px solid var(--fbs-blue);font-size:11.5px;min-width:0}
.ms-card.embroidery{background:color-mix(in srgb,#7C5CD6 12%,var(--surface));border-left-color:#7C5CD6}
.ms-card.heat{background:color-mix(in srgb,var(--fbs-orange) 16%,var(--surface));border-left-color:var(--fbs-orange)}
.ms-card.pv{border-left-style:dashed}
.ms-card.run{box-shadow:inset 0 0 0 2px var(--ok)}
.ms-card.done{opacity:.5;text-decoration:line-through}
.ms-card.late{box-shadow:inset 0 0 0 2px var(--danger)}
.ms-card .ms-c b{font-size:12px;margin-right:2px}.ms-card small b{color:var(--ink-2)}
.ms-card .ms-c{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ms-card small{color:var(--ink-3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ms-parts{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:3px;font-size:12.5px}
.ms-parts li{display:flex;justify-content:space-between;gap:10px;border-bottom:1px solid var(--line-2,var(--line));padding:3px 0}
.ms-parts li.tot{font-weight:700;border-bottom:0}
.ms-phone{display:none}
@media (max-width: 1000px){.ms-wrap{grid-template-columns:minmax(0,1fr)}.ms-tray{position:static;max-height:none}}
@media (max-width: 700px){
  .ms-grid-wrap,.ms-dv,.ms-weeks{display:none}
  .ms-phone{display:flex;flex-direction:column;gap:8px}
  .ms-days{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:4px}
  .ms-days button{border:1px solid var(--line);background:var(--surface);border-radius:8px;padding:5px 2px;font:inherit;font-size:12px;font-weight:700;display:flex;flex-direction:column;align-items:center;cursor:pointer}
  .ms-days button small{font-weight:500;color:var(--ink-3)}
  .ms-days button.on{background:var(--accent);color:#fff;border-color:var(--accent)}.ms-days button.on small{color:#fff}
  .ms-pm{background:var(--surface);border:1px solid var(--line);border-left:4px solid var(--fbs-blue);border-radius:10px;padding:8px;display:flex;flex-direction:column;gap:5px}
  .ms-pm.embroidery{border-left-color:#7C5CD6}.ms-pm.heat{border-left-color:var(--fbs-orange)}
  .ms-pm-h{display:flex;justify-content:space-between;gap:8px;font-size:13px}
}
/* Ready To Schedule band (full width, cards across) */
.ms-band{border:1px solid var(--line);border-top:4px solid var(--fbs-orange);border-radius:12px;background:var(--surface);padding:8px 10px;display:flex;flex-direction:column;gap:8px}
.ms-band.closed{padding-bottom:8px}
.ms-band-h{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.ms-band-t{all:unset;cursor:pointer;display:inline-flex;align-items:center;gap:6px;font-size:14px}
.ms-band-t .car{width:12px;color:var(--ink-3)}
.ms-band-sub{font-size:12px}
.ms-band-l{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:8px}
.ms-band-l .ms-t{gap:3px;padding:7px 9px}
.ms-t-a{display:flex;gap:6px;align-items:center;flex-wrap:wrap}
.ms-t-a .btn{padding:3px 8px;font-size:12px}
.ms-t-a .linkbtn{font-size:12px;margin-left:auto}
.ms-t-w{font-size:11.5px}
.ms-band-more{align-self:flex-start}
/* week list: machines across (grouped by type), days down, jobs listed in run order */
.ms-lw{overflow-x:auto;border:1px solid var(--line);border-radius:12px;background:var(--surface)}
.ms-lg{display:grid}
.ms-lg-corner{grid-row:span 2;display:flex;align-items:flex-end;padding:6px;border-bottom:1px solid var(--line);font-size:11px;position:sticky;top:0;background:var(--surface-2)}
.ms-lg-corner .linkbtn{font-size:11px;text-align:left}
.ms-lg-corner2{display:none}
.ms-lg-grp{padding:4px 8px;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;color:#fff;background:var(--fbs-blue);border-left:1px solid rgba(255,255,255,.4)}
.ms-lg-grp.embroidery{background:#7C5CD6}.ms-lg-grp.heat{background:var(--fbs-orange)}
.ms-lg-m{padding:6px 8px;border-left:1px solid var(--line);border-bottom:2px solid var(--line);background:var(--surface-2);display:flex;flex-direction:column;min-width:0}
.ms-lg-m b{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ms-lg-m small{font-size:10.5px;color:var(--ink-3);white-space:nowrap}
.ms-lg-wk{padding:5px 10px;font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;background:var(--surface-2);border-bottom:1px solid var(--line);border-top:2px solid var(--line);color:var(--ink-2)}
.ms-lg-d{padding:7px 8px;border-bottom:1px solid var(--line);display:flex;flex-direction:column;gap:0;font-size:12px}
.ms-lg-d b{font-size:14px}
.ms-lg-d small{color:var(--ink-3);font-size:11px}
.ms-lg-d.today{background:var(--accent-soft);box-shadow:inset 4px 0 0 var(--accent)}
.ms-lg-d.today b{color:var(--accent)}
.ms-lg-d.past{color:var(--ink-3)}
.ms-lc{border-left:1px solid var(--line);border-bottom:1px solid var(--line);padding:5px;display:flex;flex-direction:column;gap:4px;min-width:0;min-height:52px}
.ms-lc.today{background:color-mix(in srgb,var(--accent) 5%,var(--surface))}
.ms-lc.past{background:color-mix(in srgb,var(--ink) 3%,var(--surface))}
.ms-lc.off{background:repeating-linear-gradient(135deg,color-mix(in srgb,var(--ink) 4%,transparent) 0 6px,transparent 6px 12px)}
.ms-lc.over{background:var(--accent-soft);outline:2px dashed var(--accent);outline-offset:-3px}
.ms-lc.no{background:var(--danger-soft);outline:2px dashed var(--danger);outline-offset:-3px}
.ms-lc-off{font-size:11px;color:var(--ink-3);text-align:center;margin:auto}
.ms-lc-cap{position:relative;height:14px;border-radius:4px;background:var(--surface-2);overflow:hidden;flex:none}
.ms-lc-cap i{position:absolute;left:0;top:0;bottom:0;background:color-mix(in srgb,var(--ok) 45%,var(--surface))}
.ms-lc-cap.warn i{background:color-mix(in srgb,var(--fbs-orange) 55%,var(--surface))}.ms-lc-cap.full i{background:color-mix(in srgb,var(--danger) 55%,var(--surface))}
.ms-lc-cap span{position:relative;font-size:10px;font-weight:700;padding:0 5px;line-height:14px;color:var(--ink-2);font-variant-numeric:tabular-nums}
.ms-chip{all:unset;-webkit-user-drag:element;user-select:none;box-sizing:border-box;position:relative;cursor:grab;display:flex;align-items:baseline;gap:4px;padding:2px 5px 2px 6px;border-radius:5px;border-left:3px solid var(--fbs-blue);background:color-mix(in srgb,var(--fbs-blue) 11%,var(--surface));font-size:11.5px;line-height:1.35;min-width:0;white-space:nowrap}
.ms-chip.embroidery{border-left-color:#7C5CD6;background:color-mix(in srgb,#7C5CD6 11%,var(--surface))}
.ms-chip.heat{border-left-color:var(--fbs-orange);background:color-mix(in srgb,var(--fbs-orange) 13%,var(--surface))}
.ms-chip.pv{background-image:repeating-linear-gradient(135deg,rgba(255,255,255,.5) 0 4px,transparent 4px 8px)}
.ms-chip.late{box-shadow:inset 0 0 0 1.5px var(--danger)}
.ms-chip.run{box-shadow:inset 0 0 0 2px var(--ok)}
.ms-chip.done{opacity:.5}
.ms-chip.cont{border-left-style:dotted}
.ms-chip.other{opacity:.28;filter:grayscale(1)}
.ms-chip:hover{filter:brightness(.96)}
.ms-chip b{font-size:11.5px;flex:none}
.ms-chip em{font-style:normal;font-size:10.5px;flex:none}.ms-chip em.ok,.ms-chip em.rn{color:var(--ok)}
.ms-cn{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;color:var(--ink-2);font-weight:600}
.ms-cn em{color:var(--ink-3);font-weight:500}
.ms-chip small{flex:none;font-size:10px;color:var(--ink-3);font-variant-numeric:tabular-nums}
.ms-lc{gap:3px}
.ms-band-l{grid-template-columns:repeat(auto-fill,minmax(430px,1fr))!important;gap:4px 10px!important}
.ms-r{display:grid;grid-template-columns:48px minmax(0,1fr) 24px 64px auto;align-items:center;gap:8px;padding:3px 4px 3px 8px;border-radius:7px;border-left:4px solid var(--fbs-blue);background:var(--surface-2);cursor:grab;font-size:12px;min-height:34px}
.ms-r.embroidery{border-left-color:#7C5CD6}.ms-r.heat{border-left-color:var(--fbs-orange)}
.ms-r.late{background:var(--danger-soft)}
.ms-r-n{font-weight:800;color:var(--ink);text-decoration:none}
.ms-r-n:hover{text-decoration:underline}
.ms-r-c{display:flex;flex-direction:column;min-width:0;line-height:1.25}
.ms-r-c b,.ms-r-c small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ms-r-c small{color:var(--ink-3);font-size:11px}
.ms-own{width:22px;height:22px;border-radius:50%;background:var(--ink-2);color:#fff;font-size:9.5px;font-weight:800;display:inline-flex;align-items:center;justify-content:center}
.ms-r-d{font-size:11.5px;white-space:nowrap;color:var(--ink-2);font-variant-numeric:tabular-nums;text-align:right}
.ms-r-d.late{color:var(--danger);font-weight:700}
.ms-r-b{padding:3px 8px!important;font-size:11.5px!important;white-space:nowrap}
.ms-ins{position:absolute;left:0;right:0;top:-4px;height:3px;border-radius:2px;background:var(--accent)}
@media (max-width: 700px){.ms-lw{display:none}.ms-band-l{grid-template-columns:minmax(0,1fr)}}
/* week view: two stacked weeks, one row per machine, each day a 6a–6p timeline with one lane per job */
.ms-weeks{display:flex;flex-direction:column;gap:14px}
.ms-wk{border:1px solid var(--line);border-radius:12px;background:var(--surface);overflow:hidden}
.ms-wk-h{display:flex;gap:10px;align-items:baseline;padding:8px 12px;border-bottom:1px solid var(--line);background:var(--surface-2)}
.ms-wk-h b{font-size:14px}
.ms-wg{display:grid}
.ms-wg-c{border-bottom:1px solid var(--line)}
