.ms-wg-m{padding:4px 8px;border-bottom:1px solid var(--line);border-left:4px solid var(--fbs-blue);display:flex;flex-direction:column;gap:2px;justify-content:center;min-width:0}
.ms-wg-m.embroidery{border-left-color:#7C5CD6}.ms-wg-m.heat{border-left-color:var(--fbs-orange)}
