.ms-wg-m small{font-size:10.5px;color:var(--ink-3)}
.ms-wg-m .ms-used{font-variant-numeric:tabular-nums}
.ms-wc{position:relative;border-left:1px solid var(--line);border-bottom:1px solid var(--line);overflow:hidden;min-width:0;background-image:linear-gradient(to right,var(--line-2,var(--line)) 1px,transparent 1px)}
