.ms-past{position:absolute;top:0;bottom:0;left:0;background:color-mix(in srgb,var(--ink) 4%,transparent);pointer-events:none}
.ms-lane{position:absolute;left:0;right:0;height:22px}
.ms-wg-m .ms-cap{height:4px}
.ms-blk.bar{top:0;bottom:auto;height:18px;left:auto;right:auto;padding:0;border-left-width:0;border-radius:5px;min-width:4px;background:color-mix(in srgb,var(--fbs-blue) 55%,var(--surface));box-shadow:none}
