.ms-blk.bar.cont-r::after{content:"";position:absolute;right:-1px;top:4px;border:5px solid transparent;border-left-color:rgba(0,0,0,.35);border-right:0}
.ms-lbl{position:absolute;z-index:3;top:1px;font-size:11px;line-height:16px;white-space:nowrap;pointer-events:none;color:#0B2233;text-shadow:0 0 3px rgba(255,255,255,.9),0 0 2px rgba(255,255,255,.9);overflow:hidden;text-overflow:ellipsis}
