.sep-new-ic{width:38px;height:38px;border-radius:10px;display:grid;place-items:center;background:var(--surface-2);color:var(--accent);flex:none}
.sep-new-t{display:flex;flex-direction:column;gap:2px;flex:1;min-width:0}
.sep-new-t small{font-size:12.5px}
.sep-new-form{display:grid;grid-template-columns:64px minmax(0,1.4fr) minmax(0,1fr) auto;gap:12px;align-items:end;border:1px solid var(--line);border-radius:12px;padding:12px 14px;background:var(--surface)}
.sep-new-form .sep-f{flex-direction:column;align-items:stretch;gap:4px}
.sep-new-form .sep-f input{width:100%}
.sep-new-th{width:64px;height:64px;border-radius:8px;display:grid;place-items:center;overflow:hidden;background:#fff}
.sep-new-th img{max-width:100%;max-height:100%;object-fit:contain}
.sep-new-go{display:flex;gap:8px}
.sep-ask{display:inline-flex;align-items:center;gap:6px;font-size:13px}
.tmx-drop.over{border-color:var(--accent)}
@media (max-width:640px){
  .sep-new-drop .btn{display:none}
  .sep-new-form{grid-template-columns:64px minmax(0,1fr)}
  .sep-new-form .sep-f:nth-of-type(2),.sep-new-go{grid-column:1/-1}
  .sep-new-go .btn{flex:1}
}

/* Suggested colors: standard vs PMS, with our pick */
.mk-near{grid-template-columns:58px 14px 1fr auto auto}
.mk-near .q-exact,.mk-near .q-very-close{color:var(--ok,#2E9D5B);font-weight:600}
.mk-near .q-not-very-close{color:var(--warn,#C98A0C)}
.mk-rec{font-size:9.5px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;padding:1px 6px;border-radius:999px;background:var(--accent-soft);color:var(--accent)}
.mk-near:not(.rec){grid-template-columns:58px 14px 1fr auto}
.mk-match-why{font-size:11px;color:var(--ink-2,#556);padding:2px 6px 0;line-height:1.35}
.sep-chip-m{all:unset;cursor:pointer;display:block;font-size:10px;line-height:1.2;text-align:center;padding:0 3px 5px;color:var(--faint,#8a93a3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sep-chip-m:hover,.sep-chip-m.on{color:var(--accent);text-decoration:underline}
.sep-chip-m.q-exact,.sep-chip-m.q-very-close{color:var(--ok,#2E9D5B)}
.sep-chip-m.q-not-very-close{color:var(--warn,#C98A0C)}
.sep-matchbox{position:relative;max-width:440px;margin:-4px 0 10px}
.sep-matchbox .mk-match{margin:0;background:var(--surface);box-shadow:0 2px 8px rgba(0,0,0,.08)}
.sep-matchbox-x{all:unset;cursor:pointer;position:absolute;top:3px;right:8px;font-size:15px;color:var(--faint,#8a93a3)}
.sep-matchbox .mk-match-h{padding-right:18px}
.sep-chip{width:118px}
.sep-res{font-size:11.5px;line-height:1.35;padding:6px 8px;border-radius:6px;margin:2px 0 4px;background:var(--surface-2);color:var(--ink-2)}
.sep-res.ok{background:color-mix(in srgb,var(--ok,#2E9D5B) 12%,var(--surface))}
.sep-res.warn{background:color-mix(in srgb,var(--warn,#C98A0C) 14%,var(--surface))}
.sep-res.bad{background:color-mix(in srgb,var(--bad,#D64545) 14%,var(--surface));color:var(--ink)}
.sep-f b{white-space:nowrap}
.sep-new-form{grid-template-columns:64px minmax(0,1.4fr) minmax(0,1fr) 120px auto}
.sep-new-form .sep-res{grid-column:1/-1;margin:0}
@media (max-width:640px){.sep-new-form{grid-template-columns:64px minmax(0,1fr)}.sep-new-form .sep-f:nth-of-type(3){grid-column:1/-1}}
.sep-base{all:unset;cursor:pointer;margin-left:6px;font-size:11px;font-weight:600;padding:1px 7px 1px 4px;border-radius:999px;border:1px solid var(--line);color:var(--faint,#8a93a3);line-height:1.5;display:inline-flex;align-items:center;gap:3px}
.sep-base input{margin:0;width:12px;height:12px}
.sep-base.on{background:var(--ink,#1c2230);color:#fff;border-color:transparent}
.sep-basefor{display:flex;flex-direction:column;gap:4px;margin:8px 0;font-size:12.5px}
.sep-basefor .sep-f-h{font-weight:600;color:var(--ink-2)}
.sep-basefor .sep-sw{display:inline-block;width:12px;height:12px;border-radius:3px;border:1px solid var(--line);vertical-align:middle}
.sep-base:hover{border-color:var(--accent)}
.sep-base.fixed{cursor:default;opacity:.7}.sep-base.fixed:hover{border-color:var(--line)}
/* separations: small type & thin lines (fine detail underbase) */
.sep-fine{display:flex;flex-direction:column;gap:6px}
.sep-fine .sep-f{display:grid;grid-template-columns:1fr auto;gap:2px 8px;padding-left:22px;font-weight:500}
.sep-fine .sep-f input[type=range]{grid-column:1/-1;grid-row:2;width:100%}
.sep-fine .sep-f b{grid-column:2;grid-row:1}
/* separations: film close-up (loupe) */
.sep-loupe{display:flex;flex-direction:column;align-items:flex-start;gap:4px;margin-top:10px}
.sep-loupe canvas{width:min(100%,360px);height:auto;image-rendering:pixelated;border:1px solid var(--line,#d8dde6);border-radius:8px;background:#fff}
.sep-loupe-hint{width:min(100%,360px);aspect-ratio:3/1;display:grid;place-items:center;border:1px dashed var(--line,#d8dde6);border-radius:8px;color:var(--ink-3,#7c8799);font-size:13px}
.sep-loupe small{color:var(--ink-3,#7c8799)}
.sep-canvases canvas.zoom{cursor:zoom-in}
/* sizes on a phone: one entry box walks the sizes (type, pause, it moves on with the keypad still up) */
.sz-walk{position:relative}
.szc .sz-tap{width:100%;min-width:0;box-sizing:border-box;text-align:center;padding:0 2px;height:38px;line-height:36px;border:1px solid var(--line);border-radius:var(--r-sm,6px);background:var(--surface,#fff);font:inherit;font-size:16px;color:var(--ink);font-variant-numeric:tabular-nums}
.szc .sz-tap.has{background:var(--accent-soft);border-color:color-mix(in srgb,var(--accent) 40%,var(--line));font-weight:600}
.szc .sz-tap.on{visibility:hidden}
.sz-entry{position:absolute;left:0;top:0;width:1px;height:1px;opacity:0;pointer-events:none;box-sizing:border-box;text-align:center;font-size:16px;font-weight:600;padding:0 2px;border:2px solid var(--accent);border-radius:var(--r-sm,6px);background:var(--surface,#fff);color:var(--ink);font-variant-numeric:tabular-nums;transition:left .12s ease}
.sz-entry.on{opacity:1;pointer-events:auto;z-index:2}
.sz-wait{position:absolute;height:3px;border-radius:2px;background:var(--accent);transform-origin:left center;animation:szwait linear forwards;z-index:2}
@keyframes szwait{from{transform:scaleX(0)}to{transform:scaleX(1)}}
/* Printavo: files that didn't copy, history backup */
.pvk-group{display:flex;flex-direction:column;gap:6px;padding:10px 12px;border:1px solid var(--line);border-radius:var(--r-sm,8px)}
.pvk-group summary{cursor:pointer;font-size:12.5px}
.pvk-list{list-style:none;margin:6px 0 0;padding:0;max-height:320px;overflow:auto;font-size:12.5px}
.pvk-list li{display:grid;grid-template-columns:64px minmax(0,1fr) auto auto;gap:10px;align-items:center;padding:4px 0;border-bottom:1px solid var(--line)}
.pvk-list li:last-child{border-bottom:0}
.pvk-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pvk-backup{display:flex;flex-direction:column;gap:6px;padding:10px 12px;border:1px solid var(--line);border-radius:var(--r-sm,8px)}
.pvk-backup.old{opacity:.8}
.pvk-links{display:flex;flex-wrap:wrap;gap:6px}
.pvk-links .btn small{margin-left:4px}
.pvk-st{font-size:12px;font-weight:600;padding:2px 8px;border-radius:999px;background:var(--surface-2)}
.pvk-st.ready{background:color-mix(in srgb,#2E9D5B 16%,transparent);color:#2E9D5B}
.pvk-st.failed{background:color-mix(in srgb,#D14343 16%,transparent);color:#D14343}
@media (max-width:640px){.pvk-list li{grid-template-columns:56px minmax(0,1fr);}.pvk-list li > :nth-child(3),.pvk-list li > :nth-child(4){grid-column:2}}
.ok-note{padding:8px 12px;border-radius:var(--r-sm,8px);background:color-mix(in srgb,#2E9D5B 12%,transparent);color:var(--ink);font-size:13px}
/* Print films (Separation Studio): the roll layout and the film PC setup */
.pf-lay{display:flex;gap:12px;align-items:flex-start}
.pf-roll{flex:none;border-radius:4px}
.pf-film{fill:var(--surface-2,#F4F5F7);stroke:var(--line);stroke-width:4}
.pf-box{fill:var(--surface);stroke:var(--ink-2);stroke-width:5}
.pf-box.bad{stroke:#C0392B;fill:#FDECEA}
.pf-n{fill:var(--ink-3);font-weight:800;text-anchor:middle;dominant-baseline:central}
.pf-txt{display:flex;flex-direction:column;gap:3px;font-size:12.5px;min-width:0}
.pf-folder{font-size:12px}
.sep-ask{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:8px 12px;margin:6px 0;border:1px solid var(--accent);border-radius:8px;background:var(--accent-soft);font-size:13px}
.sep-ask>span:not(.sep-ask-sw){flex:1 1 260px}
.sep-ask-sw{width:18px;height:18px;border-radius:4px;border:1px solid var(--line);flex:none}
.sep-ask-sw+.sep-ask-sw{margin-left:-12px}
.sep-films-wrap{position:absolute;inset:0;display:flex;flex-direction:column;background:#fff;z-index:2}
.sep-films-zoom{display:flex;align-items:center;gap:8px;padding:8px 12px;border-bottom:1px solid var(--line);font-size:12.5px;flex:none}
.sep-films-zoom input[type=range]{flex:0 1 220px}
.sep-films{display:grid;gap:12px;padding:12px;align-content:start;overflow:auto;flex:1;min-height:0}
.sep-film{all:unset;box-sizing:border-box;display:flex;flex-direction:column;gap:6px;padding:8px;border:1px solid var(--line);border-radius:8px;background:#fff;cursor:pointer}
.sep-film:hover,.sep-film:focus-visible{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.sep-film canvas{width:100%;height:auto;display:block;image-rendering:auto}
.sep-film-l{font-size:12.5px;color:var(--ink-2);display:flex;gap:6px;align-items:baseline;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sep-stage .sep-canvases.gone{display:none}
.pf-nest{display:flex;align-items:center;gap:8px;margin:8px 0 0;font-size:12.5px;cursor:pointer}
.pf-nest input{width:16px;height:16px;flex:none}
.pf-again{display:flex;flex-direction:column;gap:4px;margin:8px 0 2px;font-size:12.5px}
.pf-again ol{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;border:1px solid var(--line);border-radius:6px}
.pf-again li{display:flex;align-items:center;gap:8px;padding:4px 8px}
.pf-again li+li{border-top:1px solid var(--line)}
.pf-again-n{flex:none;width:18px;height:18px;border-radius:50%;background:var(--surface-2,#F4F5F7);display:grid;place-items:center;font-size:11px;font-weight:700}
.pf-again-ink{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pf-setup ol{margin:6px 0;padding-left:18px;display:flex;flex-direction:column;gap:6px;font-size:12.5px;line-height:1.4}
.pf-setup code{font-size:11.5px}
/* Mockup Creator: style search in the setup, Export PDF panel */
/* every box in the setup row the same height, bottoms lined up; the style's brand line hangs under its box
   without pushing it up */
.mk-setup{padding-bottom:26px}
.mk-setup select,.mk-setup input,.mk-setup .mk-add{height:36px;box-sizing:border-box}
.mk-setup .mk-add{margin-bottom:0}
.mk-style{position:relative;min-width:170px}
.mk-style .style-pick input{width:100%}
.mk-style-n{position:absolute;left:2px;top:100%;margin-top:3px;font-size:11.5px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:260px}
.mk-color{min-width:150px}
.mk-pdf{display:flex;flex-direction:column;gap:10px;padding:12px 14px;margin-bottom:14px;max-width:640px}
.mk-pdf-h{display:flex;gap:10px;align-items:baseline;flex-wrap:wrap}
.mk-pdf-note{margin:0;font-size:12.5px}
.mk-pdf-desc textarea{width:100%;resize:vertical;font:inherit}
/* Separation Studio: fades (gradients) between inks */
.sep-fades{display:flex;flex-direction:column;gap:6px;margin:-4px 0 10px}
.sep-fade{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-size:12.5px;padding:7px 10px;border:1px solid var(--line);border-radius:9px;background:var(--surface)}
.sep-fade.warn{background:#FFF7E6;border-color:#F3D08A;color:#6B4700}
.sep-fade-bar{width:90px;height:14px;border-radius:7px;border:1px solid var(--line);flex:none}
.sep-fade > span:nth-child(2){flex:1;min-width:200px}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .sep-fade.warn{background:#3A2C0C;border-color:#6B5215;color:#F3C969}}
:root[data-theme="dark"] .sep-fade.warn{background:#3A2C0C;border-color:#6B5215;color:#F3C969}
/* Separation Studio: drag one ink onto another to combine them */
.sep-chip[draggable="true"]{cursor:grab}
.sep-chip.dragging{opacity:.45}
.sep-chip.drop{outline:3px solid var(--accent,#0EA5E9);outline-offset:2px;transform:scale(1.04)}
.sep-chip-split{position:absolute;top:4px;left:4px;font-size:10px;font-weight:700;padding:1px 6px;border-radius:9px;border:0;background:rgba(0,0,0,.6);color:#fff;cursor:pointer}
.mk-plan{font-size:12.5px;line-height:1.4;padding:7px 9px;border-radius:8px;background:var(--surface-2);margin:6px 0}
.mk-plan.sim{background:#FFF7E6;color:#6B4700}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .mk-plan.sim{background:#3A2C0C;color:#F3C969}}
:root[data-theme="dark"] .mk-plan.sim{background:#3A2C0C;color:#F3C969}
.mk-pdf-opts{display:flex;gap:6px 18px;flex-wrap:wrap}
/* Separation Studio: a tab per print location of the order (front, back, sleeve) */
.sep-locs{display:flex;gap:6px;flex-wrap:wrap;margin:-4px 0 12px}
.sep-loc{display:flex;flex-direction:column;gap:1px;padding:7px 14px;border:1px solid var(--line);border-radius:10px;background:var(--surface);text-decoration:none;color:var(--ink);min-width:120px}
.sep-loc small{font-size:11px;color:var(--ink-3)}
.sep-loc:hover{border-color:var(--accent,#0EA5E9)}
.sep-loc.on{border-color:var(--accent,#0EA5E9);box-shadow:inset 0 -3px 0 var(--accent,#0EA5E9)}

/* roles: crew (production, receiving, shipping) see sales items grayed out, and no money anywhere */
.nav a.nav-off{opacity:.38;cursor:not-allowed}
.nav a.nav-off:hover{background:none;color:var(--side-ink)}
html[data-nomoney] .money-only{display:none!important}
/* owner: "View as" someone else: a small tab on the Sign out line */
.side-user-r{display:flex;align-items:center;gap:10px}
.side-viewas{all:unset;box-sizing:border-box;cursor:pointer;font-size:11px;font-weight:600;color:var(--side-ink);border:1px solid rgba(255,255,255,.18);border-radius:999px;padding:1px 8px;width:96px!important;max-width:96px;flex:none;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.side-viewas:hover{color:#fff;border-color:rgba(255,255,255,.4)}
.side-viewas.on{background:#f0c75e;color:#3d2c00;border-color:#f0c75e}
.side-viewas option,.side-viewas optgroup{color:#111;background:#fff}
.viewas-bar{display:flex;align-items:center;gap:10px;margin:0 0 14px;padding:8px 12px;border-radius:8px;background:#fff4d6;border:1px solid #f0c75e;color:#5c4200;font-size:13.5px}
/* Separation Studio: Make Separations Better (the coach) */
.sep-coach{border-color:#b9a6e6;background:linear-gradient(180deg,rgba(161,82,201,.07),transparent 60%)}
.sep-coach h3::before{content:"\2726  ";color:#A152C9}
.sc-thread{display:flex;flex-direction:column;gap:10px;max-height:340px;overflow:auto;margin:6px 0 8px;padding-right:2px}
.sc-turn{display:flex;flex-direction:column;gap:5px}
.sc-me{align-self:flex-end;max-width:92%;background:var(--accent,#0E9BD8);color:#fff;border-radius:10px 10px 2px 10px;padding:6px 9px;font-size:13px;white-space:pre-wrap}
.sc-ai{align-self:flex-start;max-width:96%;background:var(--panel-2,#f3f5f9);border:1px solid var(--line,#e2e6ee);border-radius:10px 10px 10px 2px;padding:7px 9px;font-size:13px;line-height:1.4;display:flex;flex-direction:column;gap:6px}
.sc-ch ul{margin:0 0 6px;padding-left:16px;font-size:12.5px}
.sc-ch li small{color:var(--ink-3,#7c8799)}
.sc-done{font-size:12px;color:var(--ok,#2E9D5B);font-weight:600}
.sc-lesson{font-size:12px;background:rgba(161,82,201,.1);border-radius:6px;padding:5px 7px}
.sc-in{display:flex;gap:6px;align-items:flex-end}
.sc-in textarea{flex:1;min-height:44px;resize:vertical;font-size:13px}
.sc-in .mic.sc-mic{position:static;transform:none;flex:none;width:34px;height:34px;border:1px solid var(--line);background:var(--surface)}
.sc-in .mic.sc-mic svg{width:18px;height:18px}
.sc-in .mic.sc-mic.on{border-color:var(--fbs-salmon);background:var(--fbs-salmon)}
.sc-lessons-t{font-size:12px;margin-top:6px}
.sc-lessons{list-style:none;margin:6px 0 0;padding:0;display:flex;flex-direction:column;gap:6px;font-size:12.5px}
.sc-lessons li{display:flex;gap:6px;align-items:baseline}
.sc-lessons li>span{flex:1}
.db-sep-tbl{width:100%;table-layout:auto}
.db-sep-tbl td,.db-sep-tbl th{padding:8px 8px}
.db-sep-tbl td:last-child{white-space:nowrap}
.db-sep-tbl td.bad{color:var(--danger);font-weight:600}
html[data-nomoney] .stats{grid-template-columns:repeat(2,minmax(0,1fr))}
/* press layout: the roller (a dead screen that rolls the print flat) and a head left empty for the print to cool */
.pl{--pl-roll:#6B7A90}
.pl-st.roller rect{fill:color-mix(in srgb,var(--pl-roll) 22%,var(--surface));stroke:var(--pl-roll);stroke-width:2}
.pl-st.roller .pl-badge{fill:var(--pl-roll)}
.pl-tag.r{fill:var(--pl-roll)}
.pl-st.cool rect{fill:color-mix(in srgb,#2F86D6 8%,var(--surface));stroke:#2F86D6;stroke-width:1.5;stroke-dasharray:3 3}
.pl-opt.roller i,.pl-key i.roller{border-color:#6B7A90;background:color-mix(in srgb,#6B7A90 22%,var(--surface))}
.pl-opt.cool i,.pl-key i.cool{border-color:#2F86D6;border-style:dashed}
/* Separation Studio: press setup (which screen on which head) */
.sep-pressup h3 small{font-weight:600;text-transform:none;letter-spacing:0;margin-left:6px}
.sep-pressup .sep-row{display:flex;gap:6px;align-items:center}
.sep-pressup .sep-row select{flex:1;min-width:0}
.ps-chips{display:flex;flex-wrap:wrap;gap:5px;margin:6px 0}
.ps-chip{all:unset;box-sizing:border-box;cursor:pointer;display:inline-flex;align-items:center;gap:6px;padding:4px 8px;border:1px solid var(--line);border-radius:999px;font-size:12px;font-weight:600;background:var(--surface);max-width:100%}
.ps-chip i{width:12px;height:12px;border-radius:3px;border:1px solid color-mix(in srgb,var(--ink) 30%,transparent);flex:none}
.ps-chip span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ps-chip small{color:var(--ink-3);font-weight:600}
.ps-chip:hover{border-color:var(--ink-3)}
.ps-chip.on{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent) inset;background:color-mix(in srgb,var(--accent) 8%,var(--surface))}
.ps-chip.off small{color:var(--danger)}
.ps-pick{max-width:none;margin:4px 0 8px}
.ps-pick select{font-size:12.5px}
.ps-moves{font-size:12.5px;background:color-mix(in srgb,#E8792B 10%,var(--surface));border:1px solid color-mix(in srgb,#E8792B 40%,var(--surface));border-radius:8px;padding:6px 9px;margin:6px 0}
.ps-moves ul{margin:3px 0 0;padding-left:16px}
.ps-heads{list-style:none;margin:8px 0 4px;padding:0;display:grid;grid-template-columns:1fr;gap:2px;font-size:12.5px}
.ps-heads li{display:flex;align-items:center;gap:5px;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ps-heads li b{width:18px;text-align:right;color:var(--ink-3);flex:none}
.ps-heads li i{width:10px;height:10px;border-radius:2px;border:1px solid color-mix(in srgb,var(--ink) 30%,transparent);flex:none}
.ps-heads li.flash{color:#C25E14;font-weight:700}
.ps-heads li.roller{color:#55657B;font-weight:700}
.ps-heads li.cool{color:#2F86D6}
.ps-heads li.down{color:var(--danger)}
.ps-acts{display:flex;flex-wrap:wrap;gap:4px 14px;font-size:12.5px;margin-top:4px}
.pd-sheet{max-width:640px}
.pd-b{padding:12px 16px 16px;display:flex;flex-direction:column;gap:10px}
.pd-b select{max-width:320px}

/* left menu: tighter to the top (Oct 5) */
.side{padding-top:10px;gap:8px}
.brand.brand-logo{padding:2px 10px 4px;gap:5px}
.nav-g{margin-top:6px}
.nav a{padding-top:7px;padding-bottom:7px}
.sep-marks{display:flex;flex-direction:column;gap:2px;margin-top:4px}.sep-marks>span{font-size:12.5px;font-weight:700}
/* Separation Studio, fit to the window (Oct 5): save in the header, location + studio tabs on one line, the two side
   panes tabbed and each scrolling on its own, the proof sized to the space left (no page scrolling on a laptop) */
.sep .page-head{margin-bottom:8px}
.sep-topbar{display:flex;flex-wrap:wrap;align-items:center;gap:8px 14px;margin-bottom:10px}
.sep-topbar .sep-locs{margin:0}
.sep-topbar .sep-tabs{margin:0}
.sep-grid{grid-template-columns:260px minmax(0,1fr) 320px;gap:12px;--sep-h:calc(100vh - 206px);align-items:stretch}
.sep-grid>.sep-side{height:var(--sep-h);min-height:420px;display:flex;flex-direction:column;gap:8px}
.sep-ptabs{display:flex;width:100%;flex:none}
.sep-ptabs button{flex:1;padding-left:4px;padding-right:4px;white-space:nowrap}
.sep-pane{flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;display:flex;flex-direction:column;gap:12px;scrollbar-width:thin;padding-bottom:4px}
.sep-grid>.sep-main{height:var(--sep-h);min-height:420px}
.sep-main .sep-stage{flex:1;min-height:200px;position:relative}
/* the whole art, always: the canvases sit in a box the stage's size and shrink to fit it */
.sep-main .sep-canvases{position:absolute;inset:10px;display:block;max-width:none}
.sep-main .sep-canvases canvas{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);max-width:100%;max-height:100%;width:auto;height:auto}
.sep-main .sep-canvases .sep-split{position:absolute;left:0;right:0;bottom:4px;width:100%}
.sep-stage{padding:10px}
.sep-chip-sw{height:34px!important}
@media (max-width:1250px){.sep-grid{grid-template-columns:250px minmax(0,1fr)}.sep-grid>.sep-side:last-child{height:auto;grid-column:1/-1}.sep-grid>.sep-side:last-child .sep-pane{overflow:visible}}
@media (max-width:760px){.sep-grid>.sep-side,.sep-grid>.sep-main{height:auto}.sep-pane{overflow:visible}}
.ps-why{font-size:12.5px;background:color-mix(in srgb,var(--accent) 6%,var(--surface));border:1px solid color-mix(in srgb,var(--accent) 25%,var(--surface));border-radius:8px;padding:6px 9px;margin:6px 0}
.ps-why summary{font-weight:700;cursor:pointer}
.ps-why ul{margin:4px 0 0;padding-left:16px;display:flex;flex-direction:column;gap:3px}
/* press setup: one row per head, a dropdown each; drag a color onto another head to trade places */
.ps-rows{list-style:none;margin:6px 0;padding:0;display:flex;flex-direction:column;gap:3px}
.ps-row{display:grid;grid-template-columns:12px 22px 14px minmax(0,1fr) auto;align-items:center;gap:6px;padding:2px 6px 2px 2px;border:1px solid transparent;border-radius:7px;font-size:12.5px}
.ps-row.screen{cursor:grab}
.ps-row.screen:active{cursor:grabbing}
.ps-row.sel{background:color-mix(in srgb,var(--accent) 8%,var(--surface));border-color:color-mix(in srgb,var(--accent) 40%,var(--surface))}
.ps-row.drop{border-color:var(--accent);border-style:dashed;background:color-mix(in srgb,var(--accent) 10%,var(--surface))}
.ps-row.dragging{opacity:.45}
.ps-grip{color:var(--ink-3);font-size:11px;letter-spacing:-2px;user-select:none}
.ps-no{text-align:right;color:var(--ink-3);font-variant-numeric:tabular-nums}
.ps-sw{width:12px;height:12px;border-radius:3px;border:1px dashed var(--line)}
.ps-row.screen .ps-sw{border:1px solid color-mix(in srgb,var(--ink) 30%,transparent)}
.ps-row select{font-size:12.5px;padding:3px 6px;min-width:0;width:100%}
.ps-row.flash select{color:#C25E14;font-weight:700}
.ps-row.roller select{color:#55657B;font-weight:700}
.ps-row.cool select{color:#2F86D6}
.ps-row.free select{color:var(--ink-3)}
.ps-row.screen select{font-weight:600}
.ps-down{color:var(--danger);font-weight:600}
.ps-mesh{color:var(--ink-3);font-size:11px}
.ps-off{font-size:12.5px;display:flex;flex-wrap:wrap;gap:5px;align-items:center;margin:4px 0}
.ps-off .ps-chip{cursor:grab}
.pl-st.drop rect{stroke:var(--accent)!important;stroke-width:3.5!important;stroke-dasharray:4 3}
/* Coach & Learning tab: the coach beside learning from Separo */
.sep-learn{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;align-items:start}
.sep-learn .sep-coach .sc-thread{max-height:calc(100vh - 380px)}
.sep-learn-out .sep-outside{display:flex;flex-direction:column;gap:12px}
@media (max-width:1000px){.sep-learn{grid-template-columns:minmax(0,1fr)}}
/* shirt swatch: empty (dashed, crossed) when no shirt is picked; tap it for any color */
.sep-shirt-sw{position:relative;width:38px;height:32px;flex:none;border-radius:6px;border:1px solid var(--line);cursor:pointer;overflow:hidden}
.sep-shirt-sw input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%;height:100%}
.sep-shirt-sw.none{border-style:dashed;background:linear-gradient(to top right,transparent calc(50% - 1px),var(--ink-3) 50%,transparent calc(50% + 1px)) var(--surface)}
/* print films: the button up top */
.pf-head{display:flex;align-items:center;justify-content:space-between;gap:8px}
.pf-head .btn{padding-top:6px;padding-bottom:6px}
/* Settings → User Access: a card per person, like Printavo's user settings */
.ua-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(340px,1fr));gap:14px;align-items:start}
.ua-card{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:14px 16px;display:flex;flex-direction:column;gap:10px}
.ua-head{display:flex;align-items:center;gap:10px;padding-bottom:10px;border-bottom:1px solid var(--line)}
.ua-av{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;color:#fff;font-weight:700;font-size:15px;flex:none}
.ua-who{display:flex;flex-direction:column;min-width:0;flex:1}
.ua-who b{color:var(--accent);font-size:15px}
.ua-who small{color:var(--ink-3);font-size:11.5px;overflow:hidden;text-overflow:ellipsis}
.ua-head select{font-size:12.5px;padding:4px 6px;width:auto!important;flex:none;max-width:130px}
.ua-note{font-size:12.5px;color:var(--ink-3)}
.ua-group{display:flex;flex-direction:column;gap:3px}
.ua-gh{font-size:10.5px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3);margin:2px 0}
.ua-perm{display:flex;gap:8px;align-items:flex-start;font-size:13px;line-height:1.35;cursor:pointer}
.ua-perm input{margin-top:2px}
.ua-perm.changed span{font-weight:600}
.ua-perm.changed span::after{content:" \2022";color:var(--accent)}
.ua-foot{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding-top:6px;border-top:1px solid var(--line)}
/* ink chip: "Shirt color" (knock it out: the shirt shows there) */
.sep-chip-ft{display:flex;border-top:1px solid var(--line-2)}
.sep-chip-ft .sep-chip-shirt{flex:1;border-top:0}
.sep-chip-ft .sep-chip-shirt+.sep-chip-shirt{border-left:1px solid var(--line-2)}
.sep-chip-shirt.off{opacity:.45;cursor:default}
.sep-chip-shirt{display:flex;align-items:center;justify-content:center;gap:4px;font-size:10.5px;font-weight:600;color:var(--ink-3);padding:3px 4px 5px;border-top:1px solid var(--line-2);cursor:pointer;white-space:nowrap}
.sep-chip-shirt input{margin:0;width:12px;height:12px}
.sep-chip-shirt.on{color:var(--accent)}
/* press setup: the colors, each picking its head; a question when the head is taken */
.ps-colors{list-style:none;margin:6px 0;padding:0;display:flex;flex-direction:column;gap:4px}
.ps-color{border:1px solid var(--line);border-radius:8px;padding:5px 7px;background:var(--surface);cursor:grab}
.ps-color.dragging{opacity:.45}
.ps-color.asking{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent) inset}
.ps-color-r{display:grid;grid-template-columns:14px minmax(0,1fr) auto 118px;gap:6px;align-items:center}
.ps-ud{display:flex;gap:0}
.ps-ud .btn{padding:2px 5px;min-width:0}
.ps-cname{display:flex;flex-direction:column;min-width:0}
.ps-cname b{font-size:12.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ps-cname small{font-size:10.5px;color:var(--ink-3)}
/* the press setup card (components/PressSetupCard.tsx; Oct 21 redesign): the press and its stations side by side, every head one even row */
.sep-pressup{container-type:inline-size}
.ps-top{display:flex;flex-wrap:wrap;gap:14px 18px;align-items:flex-start;margin:8px 0 4px}
.ps-top .sep-press{flex:0 0 auto}
.ps-side{flex:1 1 240px;min-width:0;display:flex;flex-direction:column;gap:7px}
.ps-lbl{font-size:11.5px;color:var(--ink-3)}
.ps-strip{display:grid;gap:5px}
.ps-tile{all:unset;box-sizing:border-box;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:1px;padding:5px 2px;border:1px solid var(--line);border-radius:7px;background:var(--surface);font-size:10.5px;color:var(--ink-3);min-width:0}
.ps-tile b{font-size:12px;color:var(--ink)}
.ps-tile span{display:inline-flex;align-items:center;gap:3px;max-width:100%;overflow:hidden;white-space:nowrap}
.ps-tile:hover{border-color:var(--ink-3)}
.ps-tile.sel{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent) inset}
.ps-tile.t-flash{background:color-mix(in srgb,#E8792B 16%,var(--surface));border-color:color-mix(in srgb,#E8792B 55%,var(--line));color:#8a4512}
.ps-tile.t-cool{border-style:dashed;border-color:#2F86D6;color:#1d5e98}
.ps-tile.t-roller{background:color-mix(in srgb,#6B7A90 14%,var(--surface));border-color:#6B7A90;color:#3f4a5a}
.ps-tile.t-down{background:var(--danger-soft);border-color:var(--danger);color:var(--danger);cursor:not-allowed}
.ps-dot{width:8px;height:8px;border-radius:50%;border:1px solid color-mix(in srgb,var(--ink) 25%,transparent);flex:none}
.ps-pick{display:flex;flex-wrap:wrap;gap:5px;align-items:center;font-size:12px;color:var(--ink-2)}
.ps-chip{all:unset;cursor:pointer;padding:3px 9px;border:1px solid var(--line);border-radius:999px;font-size:12px;background:var(--surface)}
.ps-chip.on{border-color:var(--accent);color:var(--accent);font-weight:700}
.ps-chip.c-flash.on{border-color:#E8792B;color:#8a4512;background:color-mix(in srgb,#E8792B 14%,var(--surface))}
.ps-chip.c-cool.on{border-style:dashed}
.ps-sum{font-size:12px;color:var(--ink-2)}
/* the head list (its own class: the phone's .ps-heads li rules made these rows flex and squeezed the names, Oct 21) */
.ps-hrows{list-style:none;margin:8px 0 4px;padding:0;display:flex;flex-direction:column;gap:3px}
.jv-cp-step .ps-hrows select,.jv-cp-step .ps-hrows input{font-size:12px;font-weight:500}
.ps-head{display:grid;grid-template-columns:22px 12px minmax(0,1fr) 62px 50px minmax(92px,132px);gap:7px;align-items:center;height:36px;box-sizing:border-box;border:1px solid var(--line);border-radius:8px;padding:0 6px 0 4px;background:var(--surface);cursor:grab}
.ps-head.k-empty,.ps-head.k-down{cursor:default}
.ps-head.k-empty .ps-hl,.ps-head.k-cool .ps-hl{color:var(--ink-3)}
.ps-head.k-down{opacity:.6}
.ps-head.k-down .ps-hl{color:var(--danger)}
.ps-head.k-flash{background:color-mix(in srgb,#E8792B 7%,var(--surface));border-color:color-mix(in srgb,#E8792B 45%,var(--line))}
.ps-head.k-cool{border-style:dashed}
.ps-head.k-roller{background:color-mix(in srgb,#6B7A90 7%,var(--surface))}
.ps-head.sel{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent) inset}
.ps-head.dragging{opacity:.4}
.ps-head.drop{border-color:var(--accent);border-style:dashed;background:color-mix(in srgb,var(--accent) 8%,var(--surface))}
.ps-hn{font-weight:800;font-size:12px;color:var(--ink-3);text-align:right;font-variant-numeric:tabular-nums}
.ps-head .ps-sw{width:12px;height:12px;border-radius:3px;border:1px solid color-mix(in srgb,var(--ink) 30%,transparent)}
.ps-st{display:block;width:12px;height:12px;border-radius:3px;border:1px dashed var(--line);box-sizing:border-box}
.ps-st.k-flash{border:1.5px solid #E8792B;background:color-mix(in srgb,#E8792B 25%,var(--surface))}
.ps-st.k-roller{border:1.5px solid #6B7A90;background:color-mix(in srgb,#6B7A90 25%,var(--surface))}
.ps-st.k-cool{border:1.5px dashed #2F86D6}
.ps-st.k-down{border:1.5px solid var(--danger);background:color-mix(in srgb,var(--danger) 12%,var(--surface))}
.ps-hl{font-size:12.5px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.ps-hl small{font-weight:500;color:var(--ink-3)}
.ps-hm .ps-mesh{width:100%;box-sizing:border-box;font-size:11px;padding:2px 5px;height:24px}
.ps-head .ps-ud{display:flex;justify-content:center}
.ps-head .ps-ud .btn{padding:1px 5px;min-width:0;height:24px}
.ps-chg{font-size:12px;padding:2px 5px;height:26px;width:100%;min-width:0;color:var(--ink-2)}
.ps-off{display:flex;flex-wrap:wrap;gap:6px;align-items:center;font-size:12.5px;margin:4px 0;padding:6px 8px;border:1px dashed var(--danger);border-radius:8px}
.ps-offc{display:inline-flex;align-items:center;gap:5px;padding:3px 8px;border:1px solid var(--line);border-radius:999px;background:var(--surface);cursor:grab}
/* a narrow column (Separations): no mesh column, a smaller Change menu */
@container (max-width:460px){.ps-head{grid-template-columns:20px 12px minmax(0,1fr) 44px 74px;gap:5px}.ps-hm{display:none}.ps-chg{font-size:11px}}
.sep-pressup .sep-row{flex-wrap:wrap}
.sep-pressup .sep-row .chip{white-space:nowrap}
.jv-cp-step .sep-pressup{border:0;padding:0;box-shadow:none;background:none}
.ps-color select{font-size:12px;padding:3px 5px;width:100%}
.ps-ask{margin-top:6px;padding:7px 8px;border-radius:7px;background:color-mix(in srgb,var(--accent) 8%,var(--surface));font-size:12.5px;display:flex;flex-direction:column;gap:6px;cursor:default}
.ps-ask-b{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.ps-ask-b select{width:auto;font-size:12px;padding:3px 5px}
.ps-headmenu{display:flex;flex-wrap:wrap;align-items:center;gap:6px;padding:6px 8px;border:1px solid var(--accent);border-radius:8px;font-size:12.5px;margin:4px 0}
.ps-headmenu .pl-opt{padding:4px 8px;font-size:12px}
.sep-meshsug{font-size:10.5px;color:var(--accent);margin-left:4px;cursor:help}
.sep-plates .sep-lpi{width:66px!important}

/* vector art: remove its background layer */
.sep-bgask{display:flex;gap:12px;align-items:flex-start}
.sep-bgask-sw{flex:0 0 auto;width:38px;height:38px;border-radius:8px;border:1px solid var(--line);box-shadow:inset 0 0 0 3px rgba(255,255,255,.4)}
.sep-bgask-sw.sm{display:inline-block;width:14px;height:14px;border-radius:4px;vertical-align:-2px;box-shadow:none}

/* Screens list: the meta line wraps (mesh, LPI, "suggests 195" never run over the boxes) */
.sep-plates .sep-meta{white-space:normal;line-height:22px}
.sep-plates .sep-meta select,.sep-plates .sep-meta .sep-base{vertical-align:middle}
.sep-meshsug{display:inline-block;white-space:nowrap;margin-left:6px;vertical-align:middle;line-height:1.2}
/* right column: no scroll inside the page's scroll; it runs as long as it needs */
@media (min-width:1251px){
  .sep-grid>.sep-side:last-child{height:auto;min-height:0}
  .sep-grid>.sep-side:last-child .sep-pane{flex:none;overflow:visible}
}
/* the underbase chip in the inks bar */
.sep-chip-ub .sep-chip-sw{box-shadow:inset 0 -1px 0 var(--line-2)}
.sep-chip-ub .sep-chip-m{cursor:default}
.sep-chip-ub.off{opacity:.65}
.sep-nw{white-space:nowrap}

/* customer picker */
.cpk{position:relative;min-width:200px}
.cpk input{width:100%}
.cpk.sm input{height:26px;font-size:12.5px;padding:2px 8px;min-width:180px}
.cpk-list{position:absolute;z-index:40;top:calc(100% + 4px);left:0;right:0;min-width:240px;background:var(--surface);border:1px solid var(--line);border-radius:10px;box-shadow:0 10px 30px rgba(0,0,0,.15);padding:4px;display:flex;flex-direction:column}
.cpk-list button{all:unset;cursor:pointer;display:flex;flex-direction:column;padding:6px 8px;border-radius:7px;font-size:13px}
.cpk-list button:hover,.cpk-list button:focus-visible{background:var(--surface-2)}
.cpk-list button span{font-size:11.5px}
.cpk-none{padding:8px;font-size:12.5px}
.cpk-chip{display:inline-flex;align-items:center;gap:4px;padding:2px 4px 2px 10px;border-radius:999px;background:var(--surface-2);border:1px solid var(--line-2);font-size:13px;font-weight:600;color:var(--ink);text-transform:none;letter-spacing:0}
.cpk-chip.sm{font-size:12px}
.cpk-chip .cpk-x.cpk-x{all:unset;cursor:pointer;width:18px;height:18px;border-radius:50%;display:grid;place-items:center;color:var(--ink-3);font-size:14px;line-height:1}
.cpk-chip .cpk-x.cpk-x:hover{background:var(--line-2);color:var(--ink)}
.sep-eyebrow{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.sep-cust{display:inline-flex;align-items:center;gap:6px;text-transform:none;letter-spacing:0}
.sep-cust-l{font-size:12px;text-transform:none;letter-spacing:0}
/* separations list: archive per row */
.sep-qr{display:flex;align-items:center;gap:6px;margin-left:auto}
.sep-qa{opacity:.55}
.sep-qi:hover .sep-qa,.sep-qa:focus-visible{opacity:1}
.csep .dc-img{display:grid;place-items:center}
.csep .dc-img img{max-width:100%;max-height:100%;object-fit:contain}
/* customer: production files (staff only) */
.pf .aa-sec-h{flex-wrap:wrap}
.pf-staff{font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.05em;color:#B42318;background:color-mix(in srgb,#B42318 10%,transparent);border:1px solid color-mix(in srgb,#B42318 30%,transparent);padding:2px 8px;border-radius:999px}
.pf-h{display:flex;align-items:center;gap:10px;margin:14px 0 8px;flex-wrap:wrap}
.pf-h h4{margin:0;font-size:14px}
.pf-h .faint{font-size:12.5px}
.pf-drop{display:flex;align-items:center;justify-content:center;padding:12px;border:1.5px dashed var(--line);border-radius:10px;cursor:pointer;font-size:13px;color:var(--ink-3)}
.pf-drop.over,.pf-drop:hover{border-color:var(--accent);color:var(--accent)}
.pf-files{list-style:none;margin:8px 0 0;padding:0;display:flex;flex-direction:column;gap:4px}
.pf-file{display:grid;grid-template-columns:auto minmax(0,1fr) auto auto;gap:10px;align-items:center;padding:6px 8px;border:1px solid var(--line-2);border-radius:8px}
.pf-kind{font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:var(--ink-3);background:var(--surface-2);padding:2px 6px;border-radius:5px}
.pf-name{text-align:left;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pf-meta{font-size:12px;white-space:nowrap}
/* separation name: click to rename */
.sep-name{all:unset;cursor:text;border-radius:6px;padding:0 4px;margin-left:-4px}
.sep-name:hover{background:var(--surface-2)}
.sep-name-ed{font-size:.55em;margin-left:8px;color:var(--ink-3);opacity:0;vertical-align:middle}
.sep-name:hover .sep-name-ed,.sep-name:focus-visible .sep-name-ed{opacity:1}
.sep-rename{font:inherit;font-size:inherit;font-weight:inherit;padding:0 6px;border:1px solid var(--accent);border-radius:8px;min-width:280px;max-width:100%;background:var(--surface);color:var(--ink)}

/* ---------- Check-In (Goods & Receiving) ---------- */
.ck-week-l{font-size:14px;min-width:170px;text-align:center}
.ck-chips{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:4px 0 14px}
.ck-chip{all:unset;cursor:pointer;display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:999px;border:1px solid var(--line);background:var(--surface);font-size:13px;font-weight:600;color:var(--ink-2,var(--ink))}
.ck-chip i{width:8px;height:8px;border-radius:50%;background:var(--sc,#888)}
.ck-chip b{font-variant-numeric:tabular-nums;color:var(--ink-3)}
.ck-chip.on{border-color:var(--sc,var(--accent));box-shadow:inset 0 0 0 1px var(--sc,var(--accent));background:color-mix(in srgb,var(--sc,var(--accent)) 8%,var(--surface))}
.ck-q{min-width:220px}
.ck-sec{margin:0 0 18px}
.ck-sec h2{font-size:15px;margin:0 0 8px;display:flex;gap:8px;align-items:baseline}
.ck-sec h2 .faint{font-size:12.5px;font-weight:500}
.ck-ready{padding:12px;border-radius:14px;background:color-mix(in srgb,#1E9E5A 7%,var(--surface));border:1px solid color-mix(in srgb,#1E9E5A 30%,transparent)}
