.jf-notes{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.jf-notes li{display:grid;grid-template-columns:auto 1fr auto auto;gap:10px;align-items:baseline;padding:8px 0;border-top:1px solid var(--line-2);font-size:13.5px}
.jf-notes small{color:var(--ink-3);white-space:nowrap}
.jf-tag{font-size:11px;font-weight:800;padding:2px 8px;border-radius:999px;background:var(--accent-soft);color:var(--accent,var(--fbs-blue));white-space:nowrap}
.jf-body{white-space:pre-wrap}
.jf-big{display:flex;flex-direction:column;align-items:center;gap:10px;max-width:min(1100px,96vw)}
.jf-big img{max-width:100%;max-height:82vh;object-fit:contain;border-radius:10px;background:#000}
@media (max-width:760px){.jf-notes li{grid-template-columns:1fr}}

/* Request Separations (calendar job panel, order page) behind the art check */
.srq{display:flex;flex-direction:column;gap:10px;font-size:13.5px}
.srq-ok{color:#1F7A47;font-weight:700}
.srq-block{background:#FFF7E6;border:1px solid #F2C46D;border-radius:10px;padding:10px 12px;display:flex;flex-direction:column;gap:6px;align-items:flex-start}
.srq-block>b{color:#8A5A00}
.srq-block ul{margin:0;padding-left:18px;display:flex;flex-direction:column;gap:2px}
.srq-ask{display:flex;flex-direction:column;gap:6px;width:100%}
.srq-ask label{display:flex;flex-direction:column;gap:4px;font-weight:600}
.srq-ask textarea{font:inherit;padding:8px;border:1px solid var(--line);border-radius:8px;resize:vertical;background:#fff}
.srq-l{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.srq-l li{display:flex;align-items:center;gap:8px;padding:7px 0;border-top:1px solid var(--line-2)}
.srq-l li:first-child{border-top:0}
.srq-what{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}
.srq-what small{color:var(--ink-3);font-size:12px}
.srq-what .srq-prob{color:#B4401B}
.srq-msg.ok{color:#1F7A47;font-weight:600}
.srq-go{align-self:flex-start}
.ms-seps{border:1px solid var(--line);border-radius:12px;padding:10px 12px;display:flex;flex-direction:column;gap:8px;background:var(--panel, #fff)}
.ms-seps-h{display:flex;flex-direction:column;gap:1px}
.srq .btn:disabled{opacity:.45;cursor:not-allowed}

/* Ink Room: Rio formulas + mixing calculator */
.ink-wrap{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(320px,1fr);gap:16px;align-items:start}
@media (max-width:900px){.ink-wrap{grid-template-columns:1fr}.ink-calc{order:-1}}
.ink-calc{position:sticky;top:12px}
.ink-q{width:100%;font:inherit;font-size:16px;padding:10px 12px;border:1px solid var(--line);border-radius:10px;background:var(--surface)}
.ink-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:8px}
.ink-tile{display:flex;flex-direction:column;align-items:stretch;gap:3px;padding:6px;border:1px solid var(--line);border-radius:10px;background:var(--surface);cursor:pointer;text-align:left;font:inherit}
.ink-tile i{display:block;height:44px;border-radius:6px;border:1px solid rgba(0,0,0,.08)}
.ink-tile b{font-size:13px}
.ink-tile small{font-size:11px;color:var(--ink-3)}
.ink-tile.has small{color:#1F7A47;font-weight:600}
.ink-tile.on{outline:2px solid var(--fbs-blue, #0A8FC0);outline-offset:1px}
.ink-head{display:flex;gap:12px;align-items:center}
.ink-head i{width:64px;height:64px;border-radius:10px;border:1px solid rgba(0,0,0,.1);flex:none}
.ink-head h2{margin:0;font-size:24px}
.ink-none{display:flex;flex-direction:column;gap:4px;background:#FFF7E6;border:1px solid #F2C46D;border-radius:10px;padding:10px 12px;font-size:13.5px}
.ink-amt{display:flex;gap:8px;align-items:flex-end}
.ink-amt label{display:flex;flex-direction:column;gap:4px;font-weight:600;font-size:13px}
.ink-amt input{width:120px;font:inherit;font-size:22px;font-weight:700;padding:6px 10px;border:1px solid var(--line);border-radius:10px;background:var(--surface)}
.ink-amt select{font:inherit;font-size:15px;padding:9px 10px;border:1px solid var(--line);border-radius:10px;background:var(--surface)}
.ink-tbl{width:100%;border-collapse:collapse;font-size:14px}
.ink-tbl th{font-size:12px;color:var(--ink-3);text-align:left;font-weight:600;padding:6px 4px;border-bottom:1px solid var(--line)}
.ink-tbl td{padding:9px 4px;border-bottom:1px solid var(--line-2);vertical-align:middle}
.ink-tbl td small{display:block;color:var(--ink-3);font-size:12px}
.ink-tbl .r{text-align:right}
.ink-tbl .ink-g{font-size:20px;font-weight:800;font-variant-numeric:tabular-nums}
.ink-tbl tfoot td{border-bottom:0;font-weight:700}
.ink-tile.stock small{color:var(--ink-2)}
.ink-tile:disabled{opacity:.5;cursor:default}
.ink-instock{color:#0A6E8F !important;font-weight:700}
.ink-stock{display:flex;gap:10px;align-items:center;background:#EAF6FB;border:1px solid #9CCFE3;border-radius:10px;padding:10px 12px;font-size:13.5px}
.ink-stock i{width:34px;height:34px;border-radius:8px;flex:none;border:1px solid rgba(0,0,0,.1)}
.ink-stock span{display:flex;flex-direction:column;gap:2px}
.ink-group{display:flex;flex-direction:column;gap:6px}
.ink-group h3{margin:4px 0 0;font-size:14px;font-weight:700}
.ink-group h3 .faint{font-weight:500;margin-left:4px}
.ink-sub{margin:4px 0 0;font-size:15px}
.ink-stock.as-btn{width:100%;text-align:left;font:inherit;cursor:pointer;color:inherit}
.ink-stock.as-btn:hover{border-color:#0A8FC0}
.ink-form label{display:flex;flex-direction:column;gap:4px;font-weight:600;font-size:13px}
.ink-form input:not([type=color]),.ink-form textarea{font:inherit;font-weight:400;font-size:15px;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--surface);min-width:0}
.ink-form-2{display:grid;grid-template-columns:1fr 1fr;gap:10px}
@media (max-width:480px){.ink-form-2{grid-template-columns:1fr}}
.ink-colorpick{width:48px;height:38px;padding:2px;border:1px solid var(--line);border-radius:8px;background:var(--surface);cursor:pointer}
.ink-pmsnote{margin-top:-6px}
.ink-pmsnote.ok{color:#1F7A47}
.ink-tile.pick{opacity:.55}
.ink-tile.pick.in{opacity:1;border-color:#1F7A47;box-shadow:inset 0 0 0 1px #1F7A47}
.ink-tile.pick i{position:relative}
.ink-check{position:absolute;top:4px;right:4px;width:20px;height:20px;border-radius:50%;background:#fff;border:1px solid var(--line);display:grid;place-items:center;font-size:13px;font-weight:800;color:#1F7A47}
.ink-tile.pick.in small{color:#1F7A47;font-weight:600}
.ink-form label.ink-check-row{flex-direction:row;align-items:center;gap:8px;font-weight:500}
.ink-mixsys{margin-top:10px;padding:14px;border-radius:12px;background:#F2F6FA;border:1px dashed #8FB3CC}
.ink-mixsys h3{font-size:15px}
.ink-mixsys-sub{font-size:12.5px;color:var(--ink-3);margin:-2px 0 4px}
.ink-mixsys .ink-tile{background:#fff}
.ink-form select{font:inherit;font-weight:400;font-size:15px;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--surface)}
/* Ink Room inventory */
.inv-tbl{width:100%;border-collapse:collapse;font-size:14px}
.inv-tbl th{font-size:12px;color:var(--ink-3);text-align:left;font-weight:600;padding:6px 8px;border-bottom:1px solid var(--line)}
.inv-tbl td{padding:9px 8px;border-bottom:1px solid var(--line-2);vertical-align:top}
.inv-tbl .r{text-align:right}
.inv-head td{background:var(--surface-2,#F4F5F7);font-weight:700;font-size:12.5px;color:var(--ink-2);padding:6px 8px}
.inv-row{cursor:pointer}
.inv-row:hover td{background:#F7FAFC}
.inv-row.on td{background:#EEF5FA}
.inv-row.short td:first-child{box-shadow:inset 3px 0 0 var(--danger,#c0392b)}
.inv-sub{display:block;font-size:11.5px}
.inv-warn{color:var(--danger,#c0392b)}
.inv-detail td{background:#FAFBFC;padding:10px 12px 12px}
.inv-use{display:grid;grid-template-columns:110px 1fr auto;gap:10px;padding:6px 0;border-bottom:1px dashed var(--line-2);font-size:13px;align-items:start}
.inv-use small{display:block;font-size:11.5px}
.inv-use.done{opacity:.6}
.inv-day{font-weight:600;color:var(--ink-2)}
.inv-adj input{width:90px;font:inherit;padding:5px 8px;border:1px solid var(--line);border-radius:8px}
.inv-adj select{font:inherit;padding:5px 6px;border:1px solid var(--line);border-radius:8px}
.inv-alerts{display:flex;flex-direction:column;gap:6px}
.inv-alert{display:flex;gap:10px;align-items:flex-start;text-align:left;font:inherit;color:inherit;background:#FDF0EE;border:1px solid #F0B8AE;border-radius:10px;padding:9px 12px;cursor:pointer;font-size:13.5px}
.inv-alert i{width:8px;height:8px;border-radius:50%;margin-top:6px;flex:none}
.inv-alert span{display:flex;flex-direction:column;gap:2px}
.inv-order{display:flex;flex-direction:column;gap:3px;background:#EAF6FB;border:1px solid #9CCFE3;border-radius:10px;padding:9px 12px;font-size:13.5px}
.inv-sec h4{margin:4px 0 8px;font-size:14px}
.inv-count{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:6px 14px}
.inv-count-row{display:grid;grid-template-columns:1fr 80px 64px;gap:6px;align-items:center;padding:4px 0;border-bottom:1px solid var(--line-2)}
.inv-count-row span{display:flex;flex-direction:column;font-size:13.5px}
.inv-count-row small{font-size:11.5px}
.inv-count-row input{font:inherit;font-size:16px;padding:6px 8px;border:1px solid var(--line);border-radius:8px;width:100%;box-sizing:border-box;text-align:right}
.inv-count-row select{font:inherit;padding:6px 4px;border:1px solid var(--line);border-radius:8px}
.inv-set{display:grid;grid-template-columns:1fr 120px;gap:12px;align-items:center;padding:6px 0;border-bottom:1px solid var(--line-2)}
.inv-set span{display:flex;flex-direction:column;gap:2px;font-size:13.5px}
.inv-set small{font-size:12px}
.inv-set input{font:inherit;padding:6px 8px;border:1px solid var(--line);border-radius:8px;text-align:right}
@media (max-width:640px){.inv-use{grid-template-columns:1fr auto}.inv-day{grid-column:1/-1}.inv-tbl th:nth-child(4),.inv-tbl td:nth-child(4){display:none}}
/* Inbox */
.ibx-list{display:flex;flex-direction:column;border-top:1px solid var(--line)}
.ibx-row{border-bottom:1px solid var(--line)}
.ibx-row.on{background:#FAFBFC}
.ibx-head{display:grid;grid-template-columns:14px minmax(140px,220px) 1fr auto;gap:12px;align-items:start;width:100%;text-align:left;font:inherit;color:inherit;background:none;border:0;padding:11px 6px;cursor:pointer}
.ibx-head:hover{background:#F7FAFC}
.ibx-dot{width:9px;height:9px;border-radius:50%;margin-top:6px;background:var(--line)}
.ibx-dot.due{background:#E8A33D}.ibx-dot.late{background:var(--danger,#c0392b)}.ibx-dot.ok{background:#1F7A47}
.ibx-who{display:flex;flex-wrap:wrap;gap:4px;align-items:center;font-size:14px}
.ibx-who .tag{font-size:10.5px}
.ibx-sub{display:flex;flex-direction:column;gap:2px;font-size:14px;min-width:0}
.ibx-sub b{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ibx-sub small{color:var(--ink-3);font-size:12.5px}
.ibx-when{display:flex;gap:6px;align-items:center;font-size:12.5px;white-space:nowrap}
.ibx-detail{padding:4px 12px 14px 32px;display:flex;flex-direction:column;gap:10px}
.ibx-body{white-space:pre-wrap;font:inherit;font-size:13.5px;background:#fff;border:1px solid var(--line);border-radius:10px;padding:10px 12px;max-height:340px;overflow:auto;margin:0}
.ibx-html{display:flex;flex-direction:column;align-items:flex-start;gap:4px}.ibx-html iframe,.ibx-sig iframe{width:100%;border:1px solid var(--line);border-radius:10px;background:#fff;display:block}
.ibx-thread{display:flex;flex-direction:column;gap:6px}
.ibx-t{font-size:12.5px;border-left:3px solid var(--line);padding:4px 10px}
.ibx-t.out{border-left-color:#0A8FC0}
.ibx-t div{white-space:pre-wrap;color:var(--ink-2);margin-top:2px}
.ibx-reply{display:flex;flex-direction:column;gap:6px}
.ibx-reply input,.ibx-reply textarea,.ibx-in,.ibx-acts select{font:inherit;font-size:14px;padding:7px 10px;border:1px solid var(--line);border-radius:8px;background:var(--surface)}
.ibx-reply textarea{resize:vertical}
.ibx-opts{display:flex;flex-wrap:wrap;gap:6px;align-items:center}.ibx-opts .chip{max-width:100%;white-space:normal;text-align:left}
.ibx-tell{display:flex;gap:6px}.ibx-tell input{flex:1;min-width:0}
.ibx-in{width:170px}
.ibx-find{position:relative}
.ibx-hits{position:absolute;top:100%;left:0;z-index:5;background:#fff;border:1px solid var(--line);border-radius:8px;box-shadow:0 6px 18px rgba(0,0,0,.12);display:flex;flex-direction:column;min-width:220px}
.ibx-hits button{font:inherit;text-align:left;background:none;border:0;padding:7px 10px;cursor:pointer}
.ibx-hits button:hover{background:#F2F6FA}
@media (max-width:760px){.ibx-head{grid-template-columns:14px 1fr}.ibx-sub,.ibx-when{grid-column:2}.ibx-detail{padding-left:12px}}
.ibx-connect{margin-bottom:12px}
.ibx-form{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:10px}
.ibx-form label{display:flex;flex-direction:column;gap:4px;font-size:13px;font-weight:600}
.ibx-form input,.ibx-form select{font:inherit;font-weight:400;font-size:14px;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--surface)}
.ibx-boxes{font-size:12.5px;margin-bottom:10px;display:flex;gap:8px;flex-wrap:wrap}
.ibx-boxes span.ok{color:#1F7A47}.ibx-boxes span.bad{color:var(--danger,#c0392b)}.ibx-boxes span.off{opacity:.6}
.ibx-whose{display:inline-flex;gap:4px;margin-left:8px}
.db-click{cursor:pointer}.db-click:hover{background:var(--accent-soft)}
/* Inbox: two panes like Outlook (list left, email + answer right) */
.ibx-split{display:grid;grid-template-columns:minmax(290px,380px) minmax(0,1fr);gap:12px;height:calc(100vh - 168px);min-height:540px}
.ibx-pane{background:var(--surface);border:1px solid var(--line);border-radius:12px;overflow:hidden;display:flex;flex-direction:column;min-height:0}
.ibx-left-h{padding:10px 10px 8px;border-bottom:1px solid var(--line);display:flex;flex-direction:column;gap:8px}
.ibx-tabs{display:flex;gap:2px;background:var(--bg,#f1f3f6);border-radius:9px;padding:3px}
.ibx-tabs button{flex:1 1 auto;white-space:nowrap;border:0;background:none;padding:6px 8px;border-radius:7px;font:inherit;font-size:13px;font-weight:600;color:var(--ink-2);cursor:pointer;display:flex;gap:6px;justify-content:center;align-items:center}
.ibx-tabs button span{font-size:11.5px;font-weight:700;background:var(--line);color:var(--ink-2);border-radius:99px;padding:0 7px;line-height:18px}
.ibx-tabs button.on{background:var(--surface);color:var(--accent);box-shadow:0 1px 2px rgba(0,0,0,.08)}
.ibx-tabs button.on span{background:var(--accent);color:#fff}
.ibx-left-tools{display:flex;gap:6px;align-items:center}
.ibx-left-tools input{flex:1;min-width:0;font:inherit;font-size:13px;padding:6px 9px;border:1px solid var(--line);border-radius:8px;background:var(--surface)}
.ibx-seg{display:inline-flex;border:1px solid var(--line);border-radius:8px;overflow:hidden}
.ibx-seg button{border:0;background:none;font:inherit;font-size:12px;font-weight:600;padding:5px 9px;color:var(--ink-2);cursor:pointer}
.ibx-seg button.on{background:var(--accent-soft);color:var(--accent)}
.ibx-items{overflow-y:auto;flex:1;min-height:0}
.ibx-none{padding:18px 14px}
.ibx-item{display:flex;flex-direction:column;gap:2px;width:100%;text-align:left;border:0;border-bottom:1px solid var(--line);border-left:3px solid transparent;background:none;padding:9px 12px 9px 10px;font:inherit;color:inherit;cursor:pointer}
.ibx-item:hover{background:var(--bg,#f6f7f9)}
.ibx-item.on{background:var(--accent-soft);border-left-color:var(--accent)}
.ibx-item:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
.ibx-item-top{display:flex;align-items:center;gap:7px;min-width:0}
.ibx-item-who{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px}
.ibx-item.needs .ibx-item-who{font-weight:800}
.ibx-item-when{font-size:12px;color:var(--ink-3);white-space:nowrap}
.ibx-item-when.late{color:var(--danger);font-weight:700}
.ibx-item-subj{font-size:13px;font-weight:600;color:var(--ink-2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding-left:15px}
.ibx-item-sum{font-size:12.5px;color:var(--ink-3);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;padding-left:15px}
.ibx-item-tags{display:flex;gap:5px;flex-wrap:wrap;align-items:center;font-size:11.5px;padding-left:15px}
.ibx-item-tags:empty{display:none}
.ibx-right{overflow-y:auto}
.ibx-empty{margin:auto;display:flex;flex-direction:column;gap:4px;align-items:center;text-align:center;padding:40px}
.ibx-read{display:flex;flex-direction:column}
.ibx-read-h{padding:14px 18px 12px;border-bottom:1px solid var(--line);display:flex;flex-direction:column;gap:6px;position:sticky;top:0;background:var(--surface);z-index:2}
.ibx-read-h h2{margin:0;font-size:18px;line-height:1.25}
.ibx-read-from{font-size:13px}
.ibx-read-sum{font-size:13px;color:var(--ink-2);background:var(--bg,#f6f7f9);border-radius:8px;padding:6px 9px}
.ibx-read-tools{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.ibx-read-tools select{font:inherit;font-size:13px;padding:5px 8px;border:1px solid var(--line);border-radius:8px;background:var(--surface);max-width:240px}
.ibx-read-tools .spacer{flex:1}
.ibx-back{display:none;align-self:flex-start}
.ibx-lead{display:flex;gap:6px;flex-wrap:wrap;align-items:center;font-size:13px;background:#fff7e6;border:1px solid #f3d9a4;border-radius:9px;padding:8px 10px}
.ibx-answer{padding:14px 18px;display:flex;flex-direction:column;gap:8px;border-bottom:1px solid var(--line);background:linear-gradient(var(--accent-soft),transparent 120px)}
.ibx-answer-h{display:flex;align-items:center;gap:10px}
.ibx-answer-h b{font-size:14px}
.ibx-answer .ibx-opts{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:6px}
.ibx-opt{display:flex;flex-direction:column;gap:2px;text-align:left;border:1px solid var(--line);background:var(--surface);border-radius:9px;padding:7px 10px;font:inherit;cursor:pointer;color:inherit}
.ibx-opt b{font-size:13px}
.ibx-opt span{font-size:12px;color:var(--ink-3);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.ibx-opt:hover{border-color:var(--accent)}
.ibx-opt.on{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-soft);background:var(--surface)}
.ibx-opt.on b{color:var(--accent)}
.ibx-answer input,.ibx-answer textarea{font:inherit;font-size:14px;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--surface)}
.ibx-answer textarea{resize:vertical;min-height:150px;line-height:1.45}
.ibx-subj{font-weight:600}
.ibx-send{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:12.5px}
.ibx-msg{padding:14px 18px;display:flex;flex-direction:column;gap:8px}
.ibx-msg-h{font-size:13px}
.ibx-right .ibx-thread{padding:0 18px 18px;display:flex;flex-direction:column;gap:6px}
@media (max-width:1180px){
  .ibx-split{grid-template-columns:1fr;height:auto;min-height:0}
  .ibx-left .ibx-items{max-height:none}
  .ibx-split .ibx-right{display:none}
  .ibx-split.picked .ibx-left{display:none}
  .ibx-split.picked .ibx-right{display:flex}
  .ibx-back{display:inline-flex}
  .ibx-read-h{position:static}
}
/* urgent replies */
.ibx-tabs button span.hot{background:var(--danger)!important;color:#fff!important}
.ibx-urgent{background:var(--danger);color:#fff;border-color:var(--danger);text-transform:none;letter-spacing:0;font-family:inherit;font-weight:700;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ibx-item.urgent{border-left-color:var(--danger)}
.ibx-item.urgent.on{border-left-color:var(--danger)}
.ibx-read-urgent{font-size:13px;color:var(--danger);background:color-mix(in srgb,var(--danger) 9%,transparent);border:1px solid color-mix(in srgb,var(--danger) 30%,transparent);border-radius:8px;padding:6px 9px}
.db-urgent{background:color-mix(in srgb,var(--danger) 4%,var(--surface))}
.db-urgent .db-row{border-left:3px solid var(--danger);padding-left:10px}
.db-late{color:var(--danger);font-weight:700;font-size:12.5px}
.db-urgent-tag{font-size:11px;font-weight:800;color:#fff;background:var(--danger);border-radius:5px;padding:1px 6px}
/* left menu, Oct 6: closer together so the whole menu fits without shrinking (logo, hello, search, groups) */
@media (min-width: 821px){
  .side{padding-top:10px;padding-bottom:10px;gap:7px}
  .brand.brand-logo{padding:2px 10px 6px;gap:4px}
  .brand.brand-logo img{max-height:48px;width:auto}
  .side-hello{font-size:14px}
  .side-search input{padding-top:5px;padding-bottom:5px}
  .nav{gap:1px}
  .nav a{padding:clamp(3px,.5vh,6px) 10px}
  .nav-g{margin-top:clamp(1px,.3vh,4px);gap:1px}
  .nav-h{padding-top:clamp(4px,.55vh,7px);padding-bottom:2px;margin-top:2px}
}
/* suggested answers: every card the same shape (two-line title, two-line preview) so the row lines up */
.ibx-answer .ibx-opts{grid-template-columns:repeat(auto-fit,minmax(190px,1fr));align-items:stretch}
.ibx-opt{justify-content:flex-start}
.ibx-opt b{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.3;min-height:2.6em}
.ibx-opt span{line-height:1.35;min-height:2.7em}
/* Ink Room: when a PMS color was last mixed */
.ink-hist{display:flex;flex-direction:column;gap:4px;border-top:1px solid var(--line);margin-top:6px;padding-top:8px;font-size:13px}
.ink-hist-h{display:flex;align-items:center;justify-content:space-between;gap:8px}
.ink-hist ul{list-style:none;margin:2px 0 0;padding:0}
.ink-hist li{display:flex;justify-content:space-between;gap:8px;padding:3px 0;border-bottom:1px solid var(--line-2,#eef0f3)}
.ink-hist-old{color:#B54708;font-weight:700}
/* Inbox → Create order (components/EmailOrderPanel.tsx) */
.eo{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:12px 14px;display:flex;flex-direction:column;gap:10px;margin:8px 0}
.eo-h{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.eo-h b{font-size:16px}
.eo-conf{font-size:12px;font-weight:600;padding:2px 8px;border-radius:999px;background:var(--surface-2);color:var(--ink-2)}
.eo-conf.high{background:#E3F4EA;color:#1F7A47}.eo-conf.low{background:#FDEBD8;color:#B54708}
.eo-reading{margin:0;font-size:13.5px;color:var(--ink-2)}
.eo-tell{display:flex;flex-direction:column;gap:6px;border:1px solid var(--line);border-radius:10px;padding:10px 12px;background:var(--surface-2)}
.eo-tell.ask{border-color:var(--accent);background:var(--accent-soft)}
.eo-tell label{font-size:13.5px;font-weight:600}
.eo-tell textarea{width:100%;min-width:0;font:inherit;font-size:13.5px;resize:vertical}
.eo-tell select{max-width:100%;min-width:0}
.eo-tell-line{display:inline-block;margin-left:8px;font-weight:400;color:var(--ink-2);font-size:12.5px}
.eo-chips{display:flex;flex-wrap:wrap;gap:6px}
.eo-chip{border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:3px 10px;font:inherit;font-size:12.5px;cursor:pointer;color:var(--ink)}
.eo-chip:hover{border-color:var(--accent)}
.eo-found{font-size:13px;border-left:3px solid var(--accent);padding:4px 10px;background:var(--surface-2);border-radius:0 8px 8px 0;overflow-wrap:anywhere}
.eo-sum{margin:0;font-size:14px}
.eo-files{display:flex;flex-wrap:wrap;gap:10px}
.eo-file{display:flex;flex-direction:column;gap:3px;width:132px;font-size:12px}
.eo-file img,.eo-doc{width:132px;height:96px;object-fit:contain;border:1px solid var(--line-2);border-radius:8px;background:#fff}
.eo-doc{display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--ink-3);text-decoration:none;font-size:14px}
.eo-fname{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.eo-file select,.eo-file small{font-size:12px}.eo-file small{color:var(--ink-3)}
.eo-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px}
.eo label{display:flex;flex-direction:column;gap:3px;font-size:12px;color:var(--ink-3);font-weight:600}
.eo input,.eo select,.eo textarea{font:inherit;font-size:13.5px;color:var(--ink);padding:6px 8px;border:1px solid var(--line);border-radius:7px;background:var(--surface);min-width:0}
.eo .eo-check{flex-direction:row;align-items:center;gap:6px;color:var(--ink);font-weight:500;font-size:13.5px}
.eo-goods{display:flex;flex-wrap:wrap;gap:8px 12px;align-items:flex-end;padding:8px 10px;border-radius:9px;background:var(--surface-2)}
.eo-goods .grow{flex:1;min-width:200px}
.eo-note{margin:0;font-size:12.5px}
.eo-group{border-top:1px solid var(--line-2);padding-top:10px;display:flex;flex-direction:column;gap:6px}
.eo-gh{display:flex;gap:8px;align-items:center}.eo-gname{font-weight:700;flex:1;max-width:320px}
.eo-lines{display:flex;flex-direction:column;gap:8px}
.eo-line{display:flex;flex-direction:column;gap:5px;padding:8px;border:1px solid var(--line-2);border-radius:9px}
.eo-lf{display:flex;gap:6px;flex-wrap:wrap}.eo-lf input{width:110px}.eo-lf .grow{flex:1;min-width:160px}
.eo-sizes{display:flex;flex-wrap:wrap;gap:6px;align-items:flex-end}
.eo .eo-sz{width:56px;text-align:center;gap:2px}.eo-sz input{text-align:center;width:100%;font-weight:700}
.eo-qty{margin-left:auto;font-size:13px}
.eo-sub{font-size:12px;font-weight:700;color:var(--ink-3);display:flex;gap:8px;align-items:center}
.eo-print{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.eo-print > input{width:150px}.eo-print .eo-short{width:80px}
.eo .eo-n{flex-direction:row;align-items:center;gap:4px}.eo-n input{width:44px;text-align:center}
.eo-art{width:46px;height:46px;object-fit:contain;border:1px solid var(--line-2);border-radius:7px;background:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:10px;color:var(--ink-3);text-align:center}
.eo-art.on{background:var(--accent-soft);color:var(--ink);font-weight:600}
.eo-mocks{display:flex;flex-wrap:wrap;gap:8px}
.eo .eo-mock{flex-direction:row;align-items:center;gap:6px;padding:4px 8px 4px 4px;border:1.5px solid var(--line);border-radius:9px;font-weight:500;color:var(--ink);font-size:12.5px}
.eo-mock img{width:54px;height:54px;object-fit:contain;background:#fff;border-radius:6px}
.eo .eo-mock.on{border-color:var(--accent);background:var(--accent-soft)}
.eo-fin{display:flex;flex-wrap:wrap;gap:6px 14px;align-items:center}
.eo-link{border:0;background:none;color:var(--accent);font:inherit;font-weight:600;font-size:13px;cursor:pointer;padding:2px 0;align-self:flex-start}
.eo-x{border:0;background:none;color:var(--ink-3);font-size:18px;line-height:1;cursor:pointer;padding:2px 6px}
.eo-x:hover{color:var(--danger,#c0392b)}
.eo-notes textarea{resize:vertical}
.eo-q ul{margin:4px 0;padding-left:18px;font-size:13.5px}.eo-q li{margin:2px 0}
.eo-foot{display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap;border-top:1px solid var(--line-2);padding-top:10px}
.eo-foot b{font-size:15px}
/* contract (wholesale) extras on a group / imprint */
.ct-extra{gap:14px;flex-wrap:wrap;font-size:13px;align-items:center;margin-top:4px}
.ct-extra label{display:inline-flex;gap:6px;align-items:center}
.ct-extra input[type=number]{width:82px}
/* Settings → Wholesale, laid out like the contract sheet */
.ws{display:flex;flex-direction:column;gap:18px}
.ws-load{gap:10px;align-items:center;flex-wrap:wrap}.ws-load .faint{font-size:12.5px}
.ws-sec{display:flex;flex-direction:column;gap:10px;border-top:1px solid var(--line);padding-top:14px}
.ws-sec h3{margin:0;font-size:16px}
.ws-fees{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px 14px}
.ws-fees .field small,.ws .field small{font-size:11.5px}
.ws-notes{font-size:12.5px;white-space:pre-wrap}
/* group editor: screens / inks / digitizing (contract jobs), small, beside the group total; the order's finishing panel */
.sbx{display:flex;flex-direction:column;gap:8px;font-size:12.5px;max-width:520px;margin-bottom:10px}
.sbx-h{display:flex;align-items:center;gap:12px;font-size:11px;font-weight:600;letter-spacing:.02em;color:var(--muted);margin-bottom:2px}
.sbx-h label.check{font-weight:400;font-size:12.5px;color:var(--text,inherit);letter-spacing:0}
.sbx-r{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:2px 0}
.sbx-r label.check{display:inline-flex;gap:5px;align-items:center}
.sbx-r .linkbtn{margin-left:4px}
.sbx-r b.num{margin-left:auto;font-weight:600;min-width:58px;text-align:right}
.sbx-r b.num.sbx-off{color:var(--muted);text-decoration:line-through;font-weight:400}
.sbx-end{min-width:150px;color:var(--muted)}
.sbx-end:has(input:checked){color:inherit}
.sbx-ub.auto label{opacity:.5}
.sbx-ub.auto label:hover{opacity:.85}
.sbx-ovr{display:inline-flex;align-items:center;gap:2px;margin-left:6px;font-size:11px;padding:0 2px 0 6px;border-radius:9px;background:var(--surface-2);color:var(--muted)}
.sbx-ovr button{border:0;background:none;color:inherit;cursor:pointer;font-size:13px;line-height:1;padding:0 3px}
.sbx-num{width:48px;padding:2px 5px;font-size:12.5px}
.sbx-loc{min-width:84px;font-weight:500}
.fin-panel{margin-bottom:14px}
.fin-panel .panel-h{flex-wrap:wrap}
.fin-panel label.check{display:inline-flex;gap:6px;align-items:center}
/* Mockup Creator: the customer's own mockup, to match */
.mk-cust .panel-b{display:flex;flex-direction:column;gap:8px}
.mk-cust-row{display:flex;gap:8px;flex-wrap:wrap}
.mk-cust-th{border:1px solid var(--line);border-radius:6px;padding:0;background:#fff;cursor:zoom-in;width:120px;height:120px;overflow:hidden}
.mk-cust-th img{width:100%;height:100%;object-fit:contain;display:block}
.mk-cust-th.big{width:100%;height:auto;cursor:zoom-out}
.mk-cust-th.big img{height:auto}
/* Inbox → Create order: the summary to approve */
.eo-rev-dl{display:grid;grid-template-columns:max-content 1fr;gap:6px 14px;margin:8px 0 4px;font-size:13.5px}
.eo-rev-dl dt{color:var(--muted);font-size:12.5px;padding-top:1px}
.eo-rev-dl dd{margin:0}
.eo-rev-dl ul{margin:0;padding-left:18px}
.eo-rev-print{display:flex;gap:8px;align-items:center;margin-bottom:4px}
.eo-rev-print img{width:40px;height:40px;object-fit:contain;border:1px solid var(--line);border-radius:5px;background:#fff}
.eo-rev-files{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:6px;font-size:12.5px}
.eo-rev-files span{display:inline-flex;gap:6px;align-items:center}
.eo-rev-files img{width:48px;height:48px;object-fit:contain;border:1px solid var(--line);border-radius:5px;background:#fff}
.eo-rev-files small{flex-basis:100%;color:var(--muted)}
.back-btn{background:none;border:0;padding:0;cursor:pointer;font-family:inherit;font-weight:600}
.eo-quick{margin-top:4px;font-size:12.5px}
.rp-files{margin:6px 0;padding-left:18px;columns:2;font-size:13px}
/* Mockup Creator on a phone: a handle a finger can grab, a header that wraps, the shirt full width */
@media (pointer:coarse){
  .mk-handle{width:26px;height:26px;right:-13px;bottom:-13px;border-radius:50%;border-width:3px;box-shadow:0 1px 4px rgba(0,0,0,.3)}
  .mk-art.sel{outline-width:2px}
}
@media (max-width:700px){
  .mk-head{flex-direction:column;align-items:stretch;gap:8px}
  .mk-head > .row{flex-wrap:wrap;gap:6px}
  .mk-head > .row .btn{flex:1 1 calc(50% - 6px);justify-content:center}
  .mk-head > .row .save-state{flex:1 1 100%;order:9}
  .mk-head h1{font-size:20px}
  .mk.mk-stack .mk-views{max-width:100%}
  .mk-setup{padding:10px;gap:8px 10px}
  .mk-setup .mk-f{flex:1 1 100%}
  .mk-closeups{grid-template-columns:minmax(0,1fr)}
}
/* Inbox → Create order: when we can print it */
.eo-when{display:flex;flex-direction:column;gap:6px;margin:8px 0;padding:8px 10px;border:1px solid var(--line);border-radius:8px;font-size:13px}
.eo-when-h{display:flex;gap:10px;align-items:baseline;flex-wrap:wrap}
.eo-when-opts{display:flex;gap:8px;flex-wrap:wrap}
.eo-when-o{display:flex;flex-direction:column;gap:1px;padding:5px 10px;border-radius:7px;background:var(--surface-2);min-width:118px}
.eo-when-o small{color:var(--muted);font-size:11.5px}
.eo-when-o em{font-style:normal;font-size:11.5px}
.eo-when-o.ok em{color:var(--ok,#2e9d5b)}
.eo-when-o.miss em{color:var(--danger)}
/* Mockup Creator on a phone: size check per print */
.mk-sizer{align-items:stretch;text-align:center;gap:12px}
.mk-sizer h2{font-size:22px}
.mk-sizer-art{max-height:120px;max-width:70%;align-self:center;object-fit:contain;background:#fff;border-radius:8px;padding:6px}
.mk-sizer-now{font-size:15px}
.mk-sizer-now b{font-size:34px;margin-right:4px}
.mk-sizer-now span{display:block;color:var(--muted);font-size:13px}
.mk-sizer-b{display:flex;gap:10px}
.mk-sizer-b .btn{flex:1 1 0;padding:12px;font-size:16px;justify-content:center}
.mk-sizer-pick{display:flex;flex-direction:column;gap:6px;font-size:13px;color:var(--muted)}
.mk-sizer-pick select{font-size:20px;padding:10px;text-align:center}
.mk-cust-size{font-size:13px;font-weight:600;color:var(--warn-ink,#8a5a00);background:var(--warn-bg,#fff4d6);border-radius:6px;padding:6px 8px}
.cs-tag{display:block;margin-top:3px;border:0;background:none;padding:0;font:inherit;font-size:11.5px;color:var(--muted);cursor:pointer;text-align:left}
.cs-tag:hover{color:var(--ink)}
.cs-tag.on{color:var(--warn-ink,#8a5a00);font-weight:600}
.mk-capnote{font-size:11.5px;color:var(--muted);line-height:1.35}
/* Mockup Creator: show the same print on each size ordered; the one picked is the mockup */
.mk-sizes{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:10px;font-size:13px}
.mk-sizes .chip{min-width:46px;justify-content:center;font-weight:700}
.mk-sizes-n{font-size:12px;flex:1 1 220px}
.sep-art-note{margin:8px 0;padding:8px 10px;border-radius:8px;background:var(--warn-bg,#fff4d6);color:var(--warn-ink,#8a5a00);font-size:13px}

/* Report an issue (shop menu) and the Support page (owner) */
.nav-support{all:unset;box-sizing:border-box;display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:6px;color:var(--side-ink);font-weight:500;cursor:pointer;width:100%}
.nav-support:hover{background:var(--side-hover);color:var(--side-ink-strong)}
.nav-support:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.nav-support svg{width:18px;height:18px;flex:none;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.sup-back{position:fixed;inset:0;background:rgba(15,20,30,.55);display:grid;place-items:center;z-index:1000;padding:16px}
.sup-box{background:var(--surface,#fff);color:var(--ink,#1c2230);border-radius:12px;padding:16px;width:min(640px,100%);max-height:calc(100vh - 32px);overflow:auto;display:flex;flex-direction:column;gap:10px;box-shadow:0 12px 40px rgba(0,0,0,.25)}
.sup-box h3{margin:0}
.sup-shot{width:100%;max-height:320px;object-fit:contain;border:1px solid var(--line);border-radius:8px;background:#f4f5f7}
.sup-noshot{padding:14px;border:1px dashed var(--line);border-radius:8px;font-size:13px}
.sup-list{display:flex;flex-direction:column;gap:12px;margin-top:12px}
.sup-card{display:grid;grid-template-columns:220px 1fr;gap:14px;padding:12px;border:1px solid var(--line);border-radius:10px;background:var(--surface)}
.sup-card.st-fixed,.sup-card.st-wont{opacity:.65}
.sup-thumb{all:unset;cursor:zoom-in;display:block;border:1px solid var(--line);border-radius:6px;overflow:hidden;background:#f4f5f7;align-self:start}
.sup-thumb img{display:block;width:100%;height:auto}
.sup-thumb.none{cursor:default;padding:24px 8px;text-align:center;font-size:12px}
.sup-body{display:flex;flex-direction:column;gap:8px;min-width:0}
.sup-meta{font-size:12.5px;color:var(--ink-2)}
.sup-msg{margin:0;white-space:pre-wrap;font-size:14px}
.sup-notes{width:100%;font-size:13px;resize:vertical}
.sup-big{max-width:96vw;max-height:92vh;border-radius:6px;box-shadow:0 12px 40px rgba(0,0,0,.4)}
@media (max-width:700px){.sup-card{grid-template-columns:1fr}}
/* moving customers off Printavo: the move checklist and the warnings */
.mv{background:var(--surface);border-radius:14px;max-width:620px;width:100%;max-height:92vh;overflow:auto;padding:18px 20px;display:flex;flex-direction:column;gap:12px;box-shadow:0 20px 50px rgba(0,0,0,.25)}
.mv-h{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.mv-h h2{margin:2px 0 0;font-size:20px}
.mv-pv{font-size:13px;background:var(--surface-2);border-radius:8px;padding:8px 10px}
.mv-steps{display:flex;gap:4px;flex-wrap:wrap;list-style:none;margin:0;padding:0}
.mv-steps button{border:1px solid var(--line);background:none;border-radius:999px;padding:4px 10px;font:inherit;font-size:12.5px;cursor:pointer;color:var(--ink-2)}
.mv-steps li.on button{border-color:var(--accent);color:var(--ink);font-weight:600}
.mv-steps li.done button{color:var(--ok,#2e9d5b)}
.mv-b{min-height:120px}
.mv-f{display:flex;gap:8px;align-items:center}
.mv-choice{display:grid;gap:8px}
.mv-opt{display:flex;flex-direction:column;gap:2px;border:1px solid var(--line);border-radius:10px;padding:10px 12px;cursor:pointer}
.mv-opt.on{border-color:var(--accent)}
.mv-opt input{display:none}
.mv-opt span{font-size:13px;color:var(--muted)}
.mv-warn{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:10px 0;padding:12px 14px;border-radius:10px;background:var(--warn-bg,#fff4d6);color:var(--warn-ink,#8a5a00);font-size:14px}
.mv-warn > div{flex:1 1 300px}
.mv-strip{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:8px 0 12px;padding:9px 12px;border-radius:9px;background:var(--warn-bg,#fff4d6);color:var(--warn-ink,#8a5a00);font-size:13.5px}
.mv-strip > span{flex:1 1 300px}
.mv-strip.on{background:var(--surface-2);color:var(--ink-2)}
/* Send to Printavo (40,000-series orders during the move) */
.pvs-strip{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin:10px 0;padding:10px 14px;border-radius:10px;background:var(--surface-2);border:1px solid var(--line);font-size:13.5px}
.pvs-ok{font-size:15px}
.pvs-who{font-size:14px}
.pvc{margin:0 0 12px;padding:10px 14px;border:1px solid var(--line);border-radius:10px;background:var(--surface);font-size:13.5px;display:grid;gap:8px}
.pvc-list,.pvc-info{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.pvc-list li{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:6px 8px;border-radius:8px;background:var(--surface-2)}
.pvc-art{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;padding:8px 10px;border-radius:8px;background:var(--surface-2);border:1px solid #d9a400}
/* Printavo Sync page */
.pvsync{display:grid;gap:14px}
.pvsync .page-head{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;flex-wrap:wrap}
.pvsync h1{margin:0}
.pvsync-list{display:grid;gap:10px}
.pvsync-card{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:12px 14px;display:grid;gap:8px}
.pvsync-h{display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap}
.pvsync-num{font-family:var(--mono,ui-monospace,monospace);font-weight:700}
.pvsync-empty{padding:24px;border:1px dashed var(--line);border-radius:12px;text-align:center;color:var(--ink-2)}
.pvc-what{display:inline-block;font-size:11.5px;font-weight:600;padding:1px 7px;border-radius:999px;background:var(--surface);border:1px solid var(--line);margin-right:4px}
/* the customer's film folder (Dropbox) */
.ff{font-size:13.5px;padding:8px 0;display:grid;gap:6px}
.ff-list{list-style:none;margin:0;padding:0;display:grid;gap:3px;max-height:220px;overflow:auto}
/* reorder prints not confirmed yet (size / ink read off an old mockup): grayed until production confirms */
.unconf{opacity:.55;filter:grayscale(1)}
.unconf:focus-within{opacity:1;filter:none}
.imp-unconf td{background:var(--surface-2);font-size:12.5px;padding:6px 10px!important}
.imp-unconf td{border-left:3px solid #d9a400}
.imp-unconf td>span{margin-right:10px}
.wo-unconf{font-size:9pt;font-weight:800;color:#b00;margin-top:2px}

/* narrow windows (Oct 8): the left menu takes ~220px, so the two-column pages drop to one column sooner, long words
   and emails wrap instead of running over the next column, and the page itself never scrolls sideways */
@media (max-width:1280px){ .ed-grid{grid-template-columns:minmax(0,1fr)} .ed-aside{position:static} }
.app{overflow-x:clip}
.main{overflow-wrap:break-word}
/* break long words only when they must: "anywhere" let table columns shrink to one letter wide in a half-screen window
   (Oct 21, Nick: the Orders and Customers lists); phones keep it */
.main a[href^="mailto:"],.main td,.main dd{overflow-wrap:break-word}
@media (max-width:760px){ .main a[href^="mailto:"],.main td,.main dd{overflow-wrap:anywhere} }
.pv-dates{min-width:0}
.pv-tbl th,.pv-tbl td{word-break:normal}

/* Order chat (components/OrderAssist.tsx OrderChat) */
.oc-list{display:flex;flex-direction:column;gap:8px;max-height:420px;overflow-y:auto;padding-right:2px}
.oc-msg{display:flex;flex-direction:column;gap:6px;padding:8px 10px;border-radius:10px;font-size:13.5px;max-width:92%;overflow-wrap:anywhere}
.oc-msg.staff{align-self:flex-end;background:var(--accent-soft)}
.oc-msg.ai{align-self:flex-start;background:var(--surface-2)}
.oc-text{white-space:pre-wrap}
.oc-form{display:flex;gap:6px;align-items:flex-end}
.oc-form textarea{flex:1;min-width:0;font:inherit;font-size:13.5px;resize:vertical}
.oc-acts{display:flex;flex-wrap:wrap;gap:6px}
.ibx-chat{margin:8px 0}

/* Inbox when an email is open: a slim list, the email, and on the right the AI chat over your response */
.ibx-split.reading{grid-template-columns:190px minmax(0,1fr)}
.ibx-split.reading.nolist{grid-template-columns:minmax(0,1fr)}
.ibx-split.reading.nolist .ibx-left{display:none}
.ibx-split.reading .ibx-left .ibx-item{padding:7px 10px}
.ibx-split.reading .ibx-item-sum,.ibx-split.reading .ibx-item-tags,.ibx-split.reading .ibx-left-tools .ibx-seg{display:none}
.ibx-split.reading .ibx-item-subj{padding-left:15px;font-size:12.5px}
.ibx-split.reading .ibx-tabs button{font-size:12px;padding:5px 4px}
.ibx-split.reading .ibx-right{overflow:hidden;background:none;border:0;border-radius:0}
.ibx-work{display:grid;grid-template-columns:minmax(0,.72fr) minmax(0,1.45fr);grid-template-rows:minmax(0,.85fr) minmax(0,1.15fr);gap:12px;height:100%;min-height:0}
.ibx-col{overflow-y:auto;min-height:0;min-width:0;display:flex;flex-direction:column;background:var(--surface);border:1px solid var(--line);border-radius:12px}
.ibx-col-mail{grid-column:1;grid-row:1 / 3}
.ibx-col-ai{grid-column:2;grid-row:1;background:var(--surface-2)}
.ibx-col-resp{grid-column:2;grid-row:2}
.ibx-col-mail .ibx-read-h{padding:12px 14px 10px}
.ibx-col-mail .ibx-read-h h2{font-size:16px}
.ibx-col-mail .ibx-msg{padding:12px 14px}
.ibx-col-mail .ibx-thread{padding:0 14px 14px}
/* the chat, compact: small type, no heavy bubbles, the last few messages, one-line input that grows */
.ibx-col-ai .ibx-chat{display:flex;flex-direction:column;gap:6px;padding:8px 10px;min-height:100%}
.ibx-col-ai .ibx-chat h3{margin:0;font-size:13px}
.ibx-col-ai .oc-list{max-height:none;flex:1;gap:5px;overflow-y:auto}
.ibx-col-ai .oc-msg{font-size:13px;padding:5px 9px;border-radius:9px;gap:4px;max-width:94%}
.ibx-col-ai .oc-msg.ai{background:var(--surface);border:1px solid var(--line)}
.ibx-col-ai .oc-msg .eo-found{font-size:12px;padding:2px 8px}
.ibx-col-ai .oc-acts{gap:4px}
.btn.xs{font-size:12px;padding:2px 8px;min-height:0;line-height:1.5}
.oc-more{align-self:center;border:0;background:none;color:var(--accent);font:inherit;font-size:12px;font-weight:600;cursor:pointer;padding:0}
.oc-starters .eo-chip{font-size:12px;padding:2px 9px}
.ibx-col-ai .oc-form{position:sticky;bottom:0;background:var(--surface-2);padding-top:4px;align-items:flex-end}
.ibx-col-ai .oc-form textarea{resize:none;overflow-y:auto;min-height:32px;padding:6px 9px}
.ibx-col-resp .ibx-answer{border-bottom:0;padding:10px 14px;background:none}
.ibx-col-resp .eo{margin:8px 12px}
.ibx-resp-tabs{display:flex;gap:4px;padding:8px 12px 6px;border-bottom:1px solid var(--line);position:sticky;top:0;background:var(--surface);z-index:2}
.ibx-resp-tabs button{border:0;background:none;font:inherit;font-size:13px;font-weight:600;padding:4px 12px;border-radius:8px;cursor:pointer;color:var(--ink-2)}
.ibx-resp-tabs button.on{background:var(--accent-soft);color:var(--accent)}
.ibx-made{margin:8px 12px 0;font-size:13px;background:var(--ok-soft);border-radius:8px;padding:6px 10px}
.oc-event{align-self:center;font-size:12px;color:var(--ink-2);background:var(--surface);border:1px dashed var(--line);border-radius:999px;padding:2px 12px;text-align:center}
.ibx-work-tabs{display:none}
.ibx-listbtn{display:inline-flex}
/* narrower screens: the list folds away first, then one pane at a time with tabs */
@media (max-width:1180px){
  .ibx-split.reading{grid-template-columns:minmax(0,1fr)}
  .ibx-split.reading .ibx-right{height:calc(100vh - 150px);min-height:480px}
  .ibx-work{grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr);gap:0}
  .ibx-work-tabs{display:flex;gap:2px;padding:6px;border:1px solid var(--line);border-radius:12px 12px 0 0;background:var(--surface)}
  .ibx-work-tabs button{flex:1;border:0;background:none;font:inherit;font-size:13.5px;font-weight:600;padding:7px;border-radius:8px;cursor:pointer;color:var(--ink-2)}
  .ibx-work-tabs button.on{background:var(--accent-soft);color:var(--accent)}
  .ibx-col{display:none;grid-column:1;grid-row:2;border-radius:0 0 12px 12px;border-top:0}
  .ibx-work[data-pane="mail"] .ibx-col-mail,.ibx-work[data-pane="ai"] .ibx-col-ai,.ibx-work[data-pane="resp"] .ibx-col-resp{display:flex}
  .ibx-listbtn{display:none}
}

/* the chats' microphone: beside Send */
.oc-form .mic.oc-mic{position:static;transform:none;flex:none;width:32px;height:32px;border:1px solid var(--line);background:var(--surface)}
.oc-form .mic.oc-mic svg{width:17px;height:17px}
.oc-form .mic.oc-mic.on{border-color:var(--fbs-salmon);background:var(--fbs-salmon)}

/* Order goods (app/shop/order-goods) */
.og{display:flex;flex-direction:column;gap:14px;max-width:1100px}
.og-chip{display:inline-flex;align-items:center;gap:6px;background:var(--accent-soft);border-radius:999px;padding:3px 6px 3px 12px;font-size:13px;max-width:100%;overflow-wrap:anywhere}
.og-chip button{border:0;background:none;cursor:pointer;color:var(--ink-3);font-size:12px;padding:2px 6px}
.og-find{position:relative;display:inline-flex;flex-direction:column;min-width:0}
.og-find input{min-width:0}
.og-hits{position:absolute;top:100%;left:0;z-index:6;background:var(--surface);border:1px solid var(--line);border-radius:8px;box-shadow:0 6px 18px rgba(0,0,0,.12);display:flex;flex-direction:column;min-width:240px;max-height:340px;overflow-y:auto}
.og-hits.wide{min-width:min(520px,90vw)}
.og-hits button{display:flex;gap:10px;align-items:center;text-align:left;border:0;border-bottom:1px solid var(--line-2);background:none;padding:7px 10px;font:inherit;font-size:13px;cursor:pointer;color:inherit}
.og-hits button:hover{background:var(--surface-2)}
.og-hits img{width:36px;height:36px;object-fit:contain;flex:none}
.og-add{display:flex;gap:8px;align-items:flex-start}
.og-add .og-find .sx{width:100%}
.og-pick{border:1px solid var(--line);border-radius:10px;padding:10px 12px;display:flex;flex-direction:column;gap:10px;background:var(--surface-2)}
.og-pick select{width:auto;max-width:100%}
.og-sizes{display:flex;flex-wrap:wrap;gap:8px}
.og-sizes label{display:flex;flex-direction:column;gap:2px;align-items:center;width:84px;font-size:12px;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:6px}
.og-sizes label.out{opacity:.55}
.og-sizes input{width:64px;text-align:center}
.og-color{display:inline-flex;align-items:center;gap:6px}
.og-color select{max-width:200px}
.og-color.check select{border-color:var(--warn);background:var(--warn-soft)}
.og-check{font-size:11px;font-weight:700;color:var(--warn)}
.og-ss{color:inherit;text-decoration:none;border-bottom:1px dotted var(--ink-3)}
.og-ss:hover{color:var(--accent);border-bottom-color:var(--accent)}
.og-wh{display:inline-block;font-size:12px;padding:1px 8px;border-radius:999px;background:var(--ok-soft);margin:1px 4px 1px 0;white-space:nowrap}
.og-wh.away{background:var(--warn-soft);color:var(--warn);font-weight:700}

/* ---------- Inbox, reworked Oct 9: list · email (answer docked at the bottom) · Assistant ---------- */
.ibx2-head{align-items:flex-end}
.ibx2-status{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.ibx2-box{display:inline-flex;align-items:center;gap:6px;font-size:12.5px;color:var(--ink-3)}
.ibx2-box i{width:8px;height:8px;border-radius:50%;background:#1F7A47}
.ibx2-box.bad{color:var(--danger)}.ibx2-box.bad i{background:var(--danger)}
.ibx2-toast{position:fixed;bottom:18px;left:50%;transform:translateX(-50%);z-index:50;background:var(--ink,#1d2433);color:#fff;font-size:13.5px;padding:9px 16px;border-radius:10px;box-shadow:0 8px 24px rgba(0,0,0,.18);max-width:min(560px,92vw)}
.ibx2{display:grid;grid-template-columns:var(--ibx-list,300px) minmax(0,1fr);gap:12px;height:calc(100vh - 150px);min-height:520px;position:relative}
.ibx2.nolist{grid-template-columns:minmax(0,1fr)}.ibx2.nolist .ibx2-list{display:none}
.ibx2-list,.ibx2-mail,.ibx2-ai,.ibx2-empty{background:var(--surface);border:1px solid var(--line);border-radius:12px;min-height:0;min-width:0;overflow:hidden;display:flex;flex-direction:column}
.ibx2-empty{align-items:center;justify-content:center;gap:4px;text-align:center;padding:40px;color:var(--ink-3)}.ibx2-empty b{color:var(--ink)}
/* the list */
.ibx2-list-h{padding:10px 10px 8px;display:flex;flex-direction:column;gap:8px;border-bottom:1px solid var(--line)}
.ibx2-tabs{display:flex;gap:2px;background:var(--bg,#f1f3f6);border-radius:9px;padding:3px}
.ibx2-tabs button{flex:1;border:0;background:none;padding:5px 6px;border-radius:7px;font:inherit;font-size:13px;font-weight:600;color:var(--ink-2);cursor:pointer;white-space:nowrap}
.ibx2-tabs button span{font-size:11.5px;font-weight:700;color:var(--ink-3);margin-left:2px}
.ibx2-tabs button span.hot{color:var(--danger)}
.ibx2-tabs button.on{background:var(--surface);color:var(--accent);box-shadow:0 1px 2px rgba(0,0,0,.08)}
.ibx2-find{display:flex;gap:6px}
.ibx2-find input,.ibx2-find select{font:inherit;font-size:13px;padding:5px 8px;border:1px solid var(--line);border-radius:8px;background:var(--surface);min-width:0}
.ibx2-find input{flex:1;width:auto}.ibx2-find select{flex:none;width:auto}
.ibx2-items{flex:1;overflow-y:auto;min-height:0}
.ibx2-none{padding:18px 14px;color:var(--ink-3);font-size:13.5px}
.ibx2-item{display:flex;flex-direction:column;gap:2px;width:100%;text-align:left;border:0;border-bottom:1px solid var(--line);border-left:3px solid transparent;background:none;padding:9px 12px 9px 11px;font:inherit;color:inherit;cursor:pointer}
.ibx2-item:hover{background:var(--bg,#f6f7f9)}
.ibx2-item.on{background:var(--accent-soft);border-left-color:var(--accent)}
.ibx2-item.urgent{border-left-color:var(--danger)}
.ibx2-item:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
.ibx2-item-1{display:flex;align-items:baseline;gap:6px;min-width:0}
.ibx2-item-1 b{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px;font-weight:600}
.ibx2-item.needs .ibx2-item-1 b{font-weight:800}
.ibx2-item-1 em{font-style:normal;font-size:11px;font-weight:700;color:var(--danger)}
.ibx2-item-1 time{font-size:12px;color:var(--ink-3);white-space:nowrap}
.ibx2-item-1 time.late{color:var(--danger);font-weight:700}
.ibx2-item-2{font-size:12.5px;color:var(--ink-2);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.35}
.ibx2-item-3{display:flex;gap:8px;font-size:11.5px;color:var(--ink-3)}
/* the email + the Assistant */
.ibx2-work{display:grid;grid-template-columns:minmax(0,1fr) var(--ibx-ai,330px);gap:12px;min-height:0;min-width:0;position:relative}
.ibx2-sw{display:none}
.ibx2-mh{padding:12px 16px 10px;border-bottom:1px solid var(--line);display:flex;flex-direction:column;gap:6px;flex:none}
.ibx2-mh-1{display:flex;align-items:center;gap:8px;min-width:0;font-size:13.5px}
.ibx2-listbtn{border:1px solid var(--line);background:var(--surface);border-radius:7px;width:26px;height:26px;cursor:pointer;color:var(--ink-2);font:inherit;font-size:13px;flex:none}
.ibx2-who{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ibx2-who span{color:var(--ink-3)}
.ibx2-when{font-size:12.5px;color:var(--ink-3);white-space:nowrap}
.ibx2-mh h2{margin:0;font-size:17px;line-height:1.3}
.ibx2-sum{display:none;font-size:13px;color:var(--ink-2)}
@media (max-width:1080px){.ibx2-sum{display:block}}
.ibx2-meta{display:flex;flex-wrap:wrap;gap:6px;align-items:center;font-size:12px}
.ibx2-chip{border:1px solid var(--line);border-radius:999px;padding:1px 9px;color:var(--ink-2);text-decoration:none;font-weight:600}
.ibx2-chip.link:hover{border-color:var(--accent);color:var(--accent)}
.ibx2-chip.ok{border-color:transparent;background:var(--ok-soft,#E3F4EA);color:#1F7A47}
.ibx2-urgent{background:var(--danger);color:#fff;border-radius:999px;padding:1px 9px;font-weight:700}
.ibx2-acts{display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-top:2px}
.ibx2-file{font:inherit;font-size:13px;padding:4px 8px;border:1px solid var(--line);border-radius:8px;background:var(--surface);width:auto;max-width:132px}
.ibx2-more{position:relative}
.ibx2-more summary{list-style:none;cursor:pointer}.ibx2-more summary::-webkit-details-marker{display:none}
.ibx2-menu{position:absolute;right:0;top:calc(100% + 4px);z-index:6;background:var(--surface);border:1px solid var(--line);border-radius:10px;box-shadow:0 8px 24px rgba(0,0,0,.12);display:flex;flex-direction:column;min-width:240px;padding:4px}
.ibx2-menu a,.ibx2-menu button{font:inherit;font-size:13.5px;text-align:left;background:none;border:0;padding:8px 10px;border-radius:7px;cursor:pointer;color:var(--ink);text-decoration:none}
.ibx2-menu a:hover,.ibx2-menu button:hover{background:var(--bg,#f2f5f8)}
.ibx2-made{font-size:13px;background:var(--ok-soft,#E3F4EA);border-radius:8px;padding:6px 10px}
.ibx2-read{flex:1;overflow-y:auto;min-height:0;padding:12px 16px 16px;display:flex;flex-direction:column;gap:10px}
.ibx2-order{flex:1;overflow-y:auto;min-height:0}
.ibx2-order .eo{margin:10px 12px}
.ibx2-new{display:flex;gap:6px;flex-wrap:wrap;align-items:center;font-size:13px;background:#fff7e6;border:1px solid #f3d9a4;border-radius:9px;padding:7px 10px}
.ibx2-new input{font:inherit;font-size:13px;padding:4px 8px;border:1px solid var(--line);border-radius:7px;width:200px}
.ibx2-pick{position:relative;display:inline-flex;gap:6px}
.ibx2-files{display:flex;gap:6px;flex-wrap:wrap}
.ibx2-files button{font:inherit;font-size:12.5px;border:1px solid var(--line);background:var(--surface);border-radius:8px;padding:4px 9px;cursor:pointer}
.ibx2-files button:hover{border-color:var(--accent)}
.ibx2-thread summary{cursor:pointer;font-size:13px;font-weight:600;color:var(--ink-2);padding:4px 0}
.ibx2-thread[open]{display:flex;flex-direction:column;gap:6px}
/* the answer, docked at the bottom */
.ibx2-compose{flex:none;border-top:1px solid var(--line);background:var(--surface-2,#f7f8fa);padding:8px 12px 10px;display:flex;flex-direction:column;gap:6px;max-height:62%;overflow-y:auto}
.ibx2-sugs{display:flex;gap:6px;overflow-x:auto;padding-bottom:2px;scrollbar-width:thin}
.ibx2-sug{flex:none;font:inherit;font-size:12.5px;font-weight:600;border:1px solid var(--line);background:var(--surface);border-radius:999px;padding:3px 11px;cursor:pointer;color:var(--ink-2);max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ibx2-sug:hover,.ibx2-sug.on{border-color:var(--accent);color:var(--accent)}
.ibx2-sug.on{background:var(--accent-soft)}
.ibx2-sug.ghost{border-style:dashed}
.ibx2-thinking{font-size:12.5px;color:var(--ink-3);padding:3px 0}
.ibx2-replybar{font:inherit;font-size:14px;text-align:left;border:1px solid var(--line);background:var(--surface);border-radius:9px;padding:9px 12px;color:var(--ink-3);cursor:text}
.ibx2-replybar:hover{border-color:var(--accent)}
.ibx2-to{display:flex;gap:8px;align-items:center;font-size:12.5px;color:var(--ink-3)}
.ibx2-to span{white-space:nowrap}
.ibx2-to input{flex:1;min-width:0;font:inherit;font-size:13.5px;font-weight:600;padding:5px 9px;border:1px solid var(--line);border-radius:8px;background:var(--surface)}
.ibx2-compose textarea{font:inherit;font-size:14px;line-height:1.45;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--surface);resize:vertical;min-height:120px}
.ibx2-tell{display:flex;gap:6px}
.ibx2-tell input{flex:1;min-width:0;font:inherit;font-size:13px;padding:5px 9px;border:1px solid var(--line);border-radius:8px;background:var(--surface)}
.ibx2-send{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:12px}
.ibx2-send .spacer{flex:1}
/* the Assistant */
.ibx2-ai{background:var(--surface-2,#f7f8fa)}
.ibx2-ai .ibx-chat{flex:1;min-height:0;display:flex;flex-direction:column;gap:8px;padding:12px;margin:0}
.ibx2-ai .ibx-chat h3{margin:0;font-size:13.5px}
.oc-summary{font-size:13px;line-height:1.4;background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:8px 10px;color:var(--ink-2)}
.ibx2-ai .oc-list{flex:1;max-height:none;min-height:0;overflow-y:auto;gap:6px}
.ibx2-ai .oc-msg{font-size:13px;padding:6px 10px;border-radius:10px;max-width:96%}
.ibx2-ai .oc-msg.ai{background:var(--surface);border:1px solid var(--line)}
.ibx2-ai .oc-acts{gap:4px}
.ibx2-ai .oc-starters{display:flex;flex-direction:column;align-items:flex-start;gap:5px}
.ibx2-ai .oc-form{margin-top:auto;background:var(--surface-2,#f7f8fa);align-items:flex-end}
.ibx2-ai .oc-form textarea{resize:none;overflow-y:auto;min-height:34px;padding:7px 9px}
/* narrower screens: the Assistant slims, then shares the column with the email (switch at the top) */

@media (max-width:1080px){
  .ibx2-work{grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr);gap:8px}
  .ibx2-sw{display:flex;gap:4px;background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:4px}
