  .ibx2-ai .ibx-chat{min-height:60vh}
  .ibx2-ai .oc-form{position:sticky;bottom:0;padding:6px 0 8px}
  /* the header: one line for who (the time under it), the subject, the summary, small chips */
  .ibx2-mh{padding:10px 12px;gap:5px}
  .ibx2-mh-1{flex-wrap:wrap;row-gap:0}
  .ibx2-who{flex-basis:100%;font-size:14px}
  .ibx2-when{font-size:12px}
