  .ibx2-urgent{border-radius:7px;font-size:12.5px;padding:4px 9px;flex-basis:100%;background:color-mix(in srgb,var(--danger) 10%,var(--surface));color:var(--danger);border:1px solid color-mix(in srgb,var(--danger) 30%,transparent)}
  /* the buttons: Reply and Create order side by side, File under across, then No reply and More */
  .ibx2-acts{display:grid;grid-template-columns:1fr 1fr;gap:6px}
  .ibx2-acts > .btn,.ibx2-acts > details > summary{width:100%;justify-content:center;text-align:center}
  .ibx2-acts .ibx2-file{grid-column:1 / -1;max-width:none;width:100%;padding:6px 8px}
  .ibx2-more .ibx2-menu{right:0;left:auto;min-width:220px}
  /* the email at its full length; the answer follows it */
  .ibx2-read{overflow:visible;padding:10px 12px 12px}
  .ibx2-read .ibx-html iframe{max-width:100%}
  .ibx2-compose{max-height:none;overflow:visible;border-radius:0 0 10px 10px;padding:10px 12px 0}
  .ibx2-to{flex-direction:column;align-items:stretch;gap:4px}
