  .ibx2-tell button{flex:none}
  .ibx2-send{position:sticky;bottom:0;z-index:4;background:var(--surface-2,#f7f8fa);margin:0 -12px;padding:8px 12px calc(8px + env(safe-area-inset-bottom));border-top:1px solid var(--line)}
  .ibx2-send .faint,.ibx2-send .spacer{display:none}
  .ibx2-send .btn.primary{flex:1;justify-content:center}
  .ibx2-replybar{margin-bottom:10px}
  .ibx2-order{overflow:visible}
  .ibx2-order .eo{margin:8px}
}

/* dashboard: one "Needs a reply" list (urgent first), one line per customer (Oct 9) */
