.db-reply .db-one em{font-style:normal;font-weight:700;color:var(--danger)}
.db-reply.hot{border-left:3px solid var(--danger);padding-left:10px;background:color-mix(in srgb,var(--danger) 4%,transparent)}
.db-reply.db-click{cursor:pointer}
