.mk-canva-ask{display:flex;flex-direction:column;gap:6px;font-size:13px;border-top:1px solid var(--line);padding-top:8px}
.mk-more-or{font-size:12px;color:var(--ink-3);margin:2px 0 6px}
.il-canva{display:flex;align-items:center;justify-content:center;gap:8px;margin-top:10px;flex-wrap:wrap}

/* "Check the shirt colors" before an order is made (Oct 10) */
.cc-back{position:fixed;inset:0;z-index:80;background:rgba(15,20,30,.4);display:flex;align-items:center;justify-content:center;padding:16px}
.cc{background:var(--surface);border-radius:12px;box-shadow:0 18px 50px rgba(0,0,0,.25);width:min(560px,100%);max-height:90vh;overflow:auto;padding:16px 18px;display:flex;flex-direction:column;gap:10px}
