.cc-foot{display:flex;gap:8px;justify-content:flex-end;margin-top:4px}

/* ---------- Inbox Assistant as a text-message conversation (Oct 10) ---------- */
.tx{flex:1;min-height:0;display:flex;flex-direction:column;background:var(--surface)}
.tx-h{display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid var(--line);font-size:14px}
.tx-av{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(135deg,#0E9BD8,#F26660 60%,#FCB122);color:#fff;font-size:13px}
.tx-list{flex:1;min-height:0;overflow-y:auto;padding:10px 10px 6px;display:flex;flex-direction:column;gap:3px}
.tx-item{display:flex;flex-direction:column;gap:3px}
.tx-time{align-self:center;font-size:11px;color:var(--ink-3);margin:8px 0 4px}
.tx-row{display:flex;flex-direction:column;gap:4px;max-width:86%}
.tx-row.staff{align-self:flex-end;align-items:flex-end}
.tx-row.ai{align-self:flex-start;align-items:flex-start}
.tx-b{font-size:14px;line-height:1.35;padding:7px 12px;border-radius:18px;white-space:pre-wrap;overflow-wrap:anywhere}
.tx-b.staff{background:#0A84FF;color:#fff;border-bottom-right-radius:5px}
.tx-b.ai{background:#E9E9EB;color:#111;border-bottom-left-radius:5px}
.tx-b a{color:inherit;text-decoration:underline}
