/* Workbench cards (mockups, quotes) in the email Assistant (Oct 22) */
.tx-card{margin:6px 0 2px;max-width:100%}
.tx-card .wb-card{margin:0}
.tx-status{display:block;margin:4px 0 0 4px;font-size:12px;color:var(--ink-3)}
.tx-acts{display:flex;flex-direction:row;flex-wrap:wrap;gap:5px;margin:2px 0 4px;align-self:flex-start}
.tx-acts button{width:auto;white-space:nowrap}
.tx-acts button{font:inherit;font-size:12.5px;font-weight:600;border:1px solid #0A84FF;color:#0A84FF;background:var(--surface);border-radius:999px;padding:3px 11px;cursor:pointer}
.tx-acts button.first{background:#0A84FF;color:#fff}
.tx-acts button:disabled{opacity:.5;cursor:default}
.tx-event{align-self:center;font-size:11.5px;color:var(--ink-3);margin:6px 0;text-align:center}
.tx-typing{display:inline-flex;gap:4px;padding:10px 12px}
.tx-typing i{width:7px;height:7px;border-radius:50%;background:#8e8e93;animation:txdot 1.2s infinite}
.tx-typing i:nth-child(2){animation-delay:.2s}.tx-typing i:nth-child(3){animation-delay:.4s}
@keyframes txdot{0%,60%,100%{opacity:.35;transform:translateY(0)}30%{opacity:1;transform:translateY(-3px)}}
@media (prefers-reduced-motion:reduce){.tx-typing i{animation:none}}
.tx-starters{display:flex;gap:6px;overflow-x:auto;padding:4px 10px;scrollbar-width:none}
