.tx-field textarea{flex:1;min-width:0;border:0;outline:0;resize:none;font:inherit;font-size:14px;line-height:1.35;padding:5px 0;background:transparent;max-height:110px;min-height:0;height:29px;box-shadow:none}
.tx-field .tx-mic{right:3px;top:auto;bottom:3px;transform:none}
