/* draggable borders between panes (Oct 10) */
.ibx2-sv{position:absolute;top:0;bottom:0;width:8px;cursor:col-resize;z-index:6;touch-action:none}
.ibx2-sv::after{content:"";position:absolute;top:0;bottom:0;left:3px;width:2px;border-radius:2px;background:transparent;transition:background .15s}
.ibx2-sv:hover::after,.ibx2-sv:focus-visible::after{background:var(--accent)}
.ibx2-sv:focus-visible{outline:none}
.ibx2.nolist .ibx2-sv-list{display:none}
.ibx2-sh{flex:none;height:8px;margin-top:-4px;cursor:row-resize;position:relative;z-index:3;touch-action:none}
.ibx2-sh::after{content:"";position:absolute;left:0;right:0;top:3px;height:2px;background:transparent;transition:background .15s}
.ibx2-sh:hover::after,.ibx2-sh:focus-visible::after{background:var(--accent)}
.ibx2-compose.sized{max-height:none}
.ibx2-compose.sized textarea{flex:1;min-height:80px}
body.ibx2-dragx{cursor:col-resize;user-select:none}body.ibx2-dragy{cursor:row-resize;user-select:none}
body.ibx2-dragx iframe,body.ibx2-dragy iframe{pointer-events:none}
