@media (max-width:1180px){ .ibx2.mf{grid-template-columns:var(--ibx-list,300px) minmax(0,1fr)} .ibx2.mf .mf-rail{display:none} .mf-pick{display:block} .ibx2.mf .ibx2-sv-list{display:none} }
@media (max-width:760px){ .ibx2.mf{grid-template-columns:1fr} .mf-msg{max-width:100%} }
@media (max-width:1180px){ .ibx2.mf.nolist{grid-template-columns:minmax(0,1fr)} }

/* the left menu folded to icons (ShopNav "mini"): compact, a label pops up beside the icon you point at, and the
   arrow at the top opens the full menu (and folds it again). Desktop only; phones keep their own menu. */
.side-edge,.side-tip{display:none}
@media (min-width:821px){
  /* the right edge of the menu is the open / fold switch: a thin line with a small arrow that lights up */
  .side-edge{display:block;position:absolute;top:0;right:0;bottom:0;width:12px;padding:0;border:0;background:transparent;cursor:pointer;z-index:4}
  .side-edge::before{content:"";position:absolute;top:0;bottom:0;right:0;width:2px;background:rgba(255,255,255,.07);transition:background .15s,width .15s}
  .side-edge:hover::before,.side-edge:focus-visible::before{width:3px;background:var(--accent)}
  .side-edge-k{position:absolute;top:50%;right:-1px;transform:translateY(-50%);width:16px;height:44px;border-radius:8px 0 0 8px;background:rgba(255,255,255,.1);display:flex;align-items:center;justify-content:center;color:var(--side-ink);transition:background .15s,color .15s}
  .side-edge-k svg{width:13px;height:13px;fill:none;stroke:currentColor;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
  .side-edge:hover .side-edge-k,.side-edge:focus-visible .side-edge-k{background:var(--accent);color:#fff}
  .side-edge:focus-visible{outline:none}
  .app:has(.side.mini){grid-template-columns:64px minmax(0,1fr)}
  .side.mini{padding:12px 8px;overflow-x:hidden}
  .side.mini :is(.lbl-t,.lbl-s,.nav-h,.side-hello,.side-search,.nav-mine,.side-user,.nav-add-sc,.nav-add-btns,.brand span){display:none!important}
  .side.mini .nav-g{display:flex!important;flex-direction:column;margin-top:6px!important;padding-top:6px;border-top:1px solid rgba(255,255,255,.08)}
  .side.mini .nav a{justify-content:center;padding:8px 0!important;position:relative}
  .side.mini .nav a svg{width:19px;height:19px}
  .side.mini .nav .badge{position:absolute;top:1px;right:4px;margin:0;font-size:9.5px;padding:0 4px}
  .side.mini .brand.brand-logo{padding:0;justify-content:center}
  .side.mini .brand.brand-logo img{width:40px!important}
  .side-tip{display:block;position:fixed;z-index:10000;transform:translateY(-50%);background:#0b1220;color:#fff;font-size:12.5px;font-weight:600;padding:5px 10px;border-radius:7px;white-space:nowrap;pointer-events:none;box-shadow:0 6px 18px rgba(0,0,0,.25)}
  .side-tip::before{content:"";position:absolute;left:-5px;top:50%;transform:translateY(-50%);border:5px solid transparent;border-right-color:#0b1220;border-left:0}
}
/* Email: the folders across the top, one bar like the Customers / To-dos / Events tabs (the chosen one lit) */
.mf-bar{display:flex;align-items:center;gap:2px;background:var(--bg,#f1f3f6);border:1px solid var(--line-2);border-radius:9px;padding:3px;margin:-4px 0 10px;overflow-x:auto;scrollbar-width:none}
.mf-bar::-webkit-scrollbar{display:none}
.mf-chip{display:inline-flex;align-items:center;justify-content:center;gap:6px;flex:1 1 auto;border:0;background:none;border-radius:7px;padding:5px 10px;font:inherit;font-size:13px;font-weight:600;color:var(--ink-2);cursor:pointer;white-space:nowrap;list-style:none}
.mf-chip::-webkit-details-marker{display:none}
.mf-chip b{font-size:11px;font-weight:700;color:var(--accent)}
.mf-chip:hover{background:color-mix(in srgb,var(--surface) 60%,transparent)}
.mf-chip.on,.mf-dd.on>.mf-chip{background:var(--ink);color:var(--surface);box-shadow:0 1px 2px rgba(0,0,0,.12)}
.mf-chip.on b,.mf-dd.on>.mf-chip b{color:#fff;background:var(--accent);border-radius:8px;padding:0 6px}
.mf-dd{position:relative;flex:1 1 auto;display:flex}
.mf-dd>.mf-chip{flex:1}
.mf-ddm{position:fixed;z-index:70;margin-top:0;min-width:220px;max-height:60vh;overflow-y:auto;background:var(--surface);border:1px solid var(--line);border-radius:10px;box-shadow:0 12px 32px rgba(20,29,43,.18);padding:6px;display:flex;flex-direction:column}
.mf-ddm button{display:flex;align-items:center;gap:8px;border:0;background:none;text-align:left;font:inherit;font-size:13.5px;padding:7px 12px;border-radius:7px;cursor:pointer;color:var(--ink)}
.mf-ddm button:hover{background:var(--surface-2)}
.mf-ddm button.on{color:var(--accent);font-weight:700}
.mf-ddm button b{margin-left:auto;font-size:11px;color:var(--accent)}
/* right-click an email (components/MailContextMenu.tsx, Oct 20) */
.cxm-wrap{display:contents}
.cxm{position:fixed;z-index:90;min-width:216px;max-width:min(320px,calc(100vw - 16px));max-height:calc(100vh - 16px);overflow-y:auto;background:var(--surface);border:1px solid var(--line);border-radius:10px;box-shadow:0 12px 32px rgba(20,29,43,.2);padding:5px;display:flex;flex-direction:column;font-size:13.5px}
.cxm-i{display:flex;align-items:center;gap:9px;border:0;background:none;text-align:left;font:inherit;padding:6px 10px;border-radius:7px;cursor:pointer;color:var(--ink);white-space:nowrap}
.cxm-i:hover:not(:disabled),.cxm-i:focus-visible,.cxm-i.on{background:var(--surface-2);outline:none}
.cxm-i:disabled{color:var(--ink-3);cursor:default}
.cxm-i.danger{color:var(--danger)}
.cxm-ic{width:16px;height:16px;flex:none;display:inline-flex;align-items:center;justify-content:center}
.cxm-ic svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.cxm-l{flex:1;overflow:hidden;text-overflow:ellipsis}
.cxm-h{color:var(--ink-3);font-size:11.5px;margin-left:10px}
.cxm-more{width:14px;height:14px;fill:none;stroke:var(--ink-3);stroke-width:2}
.cxm-sep{height:1px;background:var(--line);margin:4px 6px}
.mf-load{padding:6px 10px;font-size:13px}

/* the left menu: hidden to icons until you point at it (QuickBooks style); the pin keeps it open (ShopNav).
   Folded or open, every row stays exactly where it is (one column, same spacing; words are only hidden), so the
   thing under the pointer when it slides out is the thing you click. */
.side-pin{display:none}
@media (min-width:821px){
  .side-pin{display:inline-flex;position:absolute;top:10px;right:8px;z-index:3;width:26px;height:26px;align-items:center;justify-content:center;border:0;border-radius:7px;background:transparent;color:var(--side-ink);cursor:pointer;opacity:.55}
  .side-pin svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linejoin:round;transform:rotate(35deg);transition:transform .15s}
  .side-pin.on svg{transform:none;fill:currentColor}
  .side-pin:hover,.side-pin.on{opacity:1;background:rgba(255,255,255,.08)}
  .app:has(.side.auto){grid-template-columns:64px minmax(0,1fr)}
  .side.auto{width:64px;z-index:60;overflow-x:hidden;transition:width .16s ease .12s,box-shadow .16s ease .12s}
  .side.auto:hover,.side.auto:has(:focus-visible){width:232px;box-shadow:10px 0 34px rgba(5,10,20,.35)}
  /* one column always, in both states */
  .side.auto .nav-g{display:flex!important;flex-direction:column}
  .side.auto .nav a{white-space:nowrap}
  .side.auto .nav a .lbl-t{display:inline!important}
  .side.auto .nav a .lbl-s{display:none!important}
  .side.auto .nav a svg{flex:none}
  /* folded: the words are there but invisible (they keep their space) */
  .side.auto:not(:hover):not(:has(:focus-visible)) :is(.lbl-t,.nav-h,.side-hello,.side-search,.nav-mine,.side-user,.nav-add-sc,.nav-add-btns,.brand span){visibility:hidden}
  .side.auto:not(:hover):not(:has(:focus-visible)) .side-pin{visibility:hidden}
  .side.auto:not(:hover):not(:has(:focus-visible)) .nav .badge{position:absolute;top:1px;left:30px;margin:0;font-size:9.5px;padding:0 4px}
  .side.auto .nav a{position:relative}
}
@media (min-width:821px) and (prefers-reduced-motion:reduce){ .side.auto{transition:none} }


/* ───────── the top of an open email (components/MailFolders.tsx MailHead + Toolbar) ───────── */
.eh{flex:none;border-bottom:1px solid var(--line)}
.eh-bar{display:flex;align-items:center;gap:8px;padding:8px 10px;background:var(--bg);border-bottom:1px solid var(--line-2);min-width:0}
.eh-list,.eh-back{flex:none;width:32px;height:34px;border:1px solid var(--line);background:var(--surface);border-radius:8px;cursor:pointer;color:var(--ink-2);font:inherit;font-size:13px;display:inline-flex;align-items:center;justify-content:center}
.eh-back{display:none}
.eh-back svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.eh-b{padding:14px 18px 12px;display:flex;flex-direction:column;gap:10px}
.eh-subj{margin:0;font-family:var(--display);font-size:20px;line-height:1.25;letter-spacing:-.005em;color:var(--ink)}
.eh-from{display:flex;align-items:flex-start;gap:10px;min-width:0}
.eh-av{flex:none;width:36px;height:36px;border-radius:50%;background:var(--accent-soft);color:var(--accent);display:inline-flex;align-items:center;justify-content:center;font-weight:800;font-size:13px}
.eh-who{flex:1;min-width:0;font-size:14px;line-height:1.35}
.eh-who b{color:var(--ink)}
.eh-addr{color:var(--ink-3);font-size:12.5px;margin-left:8px}
.eh-to{border:0;background:none;padding:0;font:inherit;font-size:12.5px;color:var(--ink-3);cursor:pointer}
.eh-to:hover{color:var(--accent)}
.eh-full{margin-top:4px;font-size:12.5px;color:var(--ink-2);display:flex;flex-direction:column;gap:2px;word-break:break-word}
.eh-full span{display:inline-block;width:28px;color:var(--ink-3);font-weight:700}
.eh-date{flex:none;font-size:12.5px;color:var(--ink-3);white-space:nowrap;padding-top:2px}
.eh-meta{display:flex;flex-wrap:wrap;align-items:center;gap:6px 8px}
.eh-sum{flex-basis:100%;font-size:13.5px;color:var(--ink-2);background:color-mix(in srgb,var(--accent) 6%,var(--surface));border-left:3px solid var(--accent);border-radius:6px;padding:7px 10px}
.eh-tag{font-size:11.5px;font-weight:700;border-radius:999px;padding:2px 9px;background:var(--surface-2);color:var(--ink-2);text-decoration:none}
.eh-tag.todo{background:color-mix(in srgb,var(--fbs-blue,#0E9BD8) 14%,var(--surface));color:var(--fbs-blue,#0E9BD8)}
.eh-tag.event{background:color-mix(in srgb,var(--fbs-orange,#FCB122) 20%,var(--surface));color:#9A6A00}
.eh-tag.hot{background:var(--danger-soft);color:var(--danger)}
.eh-tag.ok{background:var(--ok-soft);color:var(--ok)}
.eh-tag.link:hover{text-decoration:underline}
.eh-err{margin:8px 18px 0}
/* the toolbar: groups of big buttons, icon + word */
.tb{display:flex;align-items:center;gap:6px;flex:1;min-width:0;flex-wrap:wrap;container-type:inline-size}
.tb-g{display:flex;align-items:center;gap:2px;padding:2px;background:var(--surface);border:1px solid var(--line);border-radius:10px}
.tb-b{display:inline-flex;align-items:center;gap:6px;height:32px;padding:0 11px;border:0;border-radius:8px;background:transparent;font:inherit;font-size:13.5px;font-weight:600;color:var(--ink);cursor:pointer;white-space:nowrap;list-style:none}
.tb-b::-webkit-details-marker{display:none}
.tb-b svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round;flex:none}
.tb-b:hover:not(:disabled){background:var(--surface-2)}
.tb-b:focus-visible{outline:2px solid var(--accent);outline-offset:1px}
.tb-b:disabled{opacity:.45;cursor:default}
.tb-b.primary{background:var(--accent);color:#fff}
.tb-b.primary:hover:not(:disabled){background:var(--accent-hover)}
.tb-b.strong{color:var(--ink)}
.tb-b.strong svg{color:var(--accent)}
.tb-b.danger{color:var(--danger)}
.tb-b.danger:hover:not(:disabled){background:var(--danger-soft)}
.tb-caret{font-size:10px;color:var(--ink-3);margin-left:-2px}
.tb-m{position:relative}
.tb-menu{position:absolute;top:calc(100% + 6px);left:0;z-index:40;min-width:220px;max-height:360px;overflow-y:auto;background:var(--surface);border:1px solid var(--line);border-radius:10px;box-shadow:0 14px 34px rgba(20,29,43,.2);padding:6px;display:flex;flex-direction:column}
.tb-menu button,.tb-menu a{display:block;border:0;background:none;text-align:left;font:inherit;font-size:13.5px;padding:7px 12px;border-radius:7px;cursor:pointer;color:var(--ink);text-decoration:none;white-space:nowrap}
.tb-menu button:hover,.tb-menu a:hover{background:var(--surface-2)}
.tb-menu button.on{color:var(--accent);font-weight:700}
.tb .mf-hint{margin-left:4px}
@container (max-width:620px){ .tb-b:not(.primary) .tb-l{display:none} .tb-b{padding:0 9px} }
.mf-msg-a.tb{margin-top:10px}
@media (max-width:760px){ .eh-back{display:inline-flex} .eh-list{display:none} .eh-bar{position:sticky;top:0;z-index:5} .eh-b{padding:12px 12px 10px} .eh-subj{font-size:18px} }
/* Email → Inbox summary: a greeting, the numbers, then each group as its own colored card */
.ibx2-item.ibx2-brief{background:linear-gradient(90deg,color-mix(in srgb,var(--accent) 8%,var(--surface)),var(--surface));border-left-color:var(--accent)}
.br .eh-bar{flex:none}
.br-k{font-weight:700;font-size:14px;color:var(--accent)}
.br-at{font-size:12px}
.br-b{padding:0 0 30px!important;background:var(--bg)}
.br-hero{padding:26px 28px 22px;background:radial-gradient(120% 140% at 0% 0%,color-mix(in srgb,#0E9BD8 16%,var(--surface)) 0%,var(--surface) 55%),var(--surface);border-bottom:1px solid var(--line-2)}
.br-date{font-size:12.5px;font-weight:700;color:var(--accent);letter-spacing:.02em}
.br-hi{font-family:var(--display);font-size:clamp(24px,2.6vw,32px);line-height:1.1;margin:6px 0 10px;letter-spacing:-.01em;color:var(--ink)}
.br-head{font-size:15.5px;line-height:1.55;color:var(--ink-2);margin:0;max-width:68ch}
.br-wait{display:flex;align-items:center;gap:10px;color:var(--ink-3)}
.br-dots{display:inline-flex;gap:5px}
.br-dots i{width:7px;height:7px;border-radius:50%;background:var(--accent);animation:brd 1s infinite ease-in-out}
.br-dots i:nth-child(2){animation-delay:.15s}.br-dots i:nth-child(3){animation-delay:.3s}
@keyframes brd{0%,80%,100%{opacity:.25;transform:translateY(0)}40%{opacity:1;transform:translateY(-3px)}}
.br-tiles{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;padding:18px 28px 6px}
.br-tile{--t:var(--ink-3);display:flex;flex-direction:column;align-items:flex-start;gap:2px;border:1px solid var(--line);border-left:4px solid var(--t);border-radius:12px;background:var(--surface);padding:10px 12px;font:inherit;text-align:left;cursor:pointer;color:var(--ink);transition:transform .12s,box-shadow .12s}
.br-tile:hover:not(:disabled){transform:translateY(-1px);box-shadow:0 6px 16px rgba(20,29,43,.08)}
.br-tile:disabled{cursor:default}
.br-tile b{font-family:var(--display);font-size:26px;line-height:1;color:var(--t)}
.br-tile span{font-size:12px;color:var(--ink-2);font-weight:600}
.br-tile.br-tone-hot,.br-card.br-tone-hot{--t:#E5484D}.br-tile.br-tone-ord,.br-card.br-tone-ord{--t:#0E9BD8}.br-tile.br-tone-todo,.br-card.br-tone-todo{--t:#7C5CE0}.br-tile.br-tone-cal,.br-card.br-tone-cal{--t:#D99A00}.br-tile.br-tone-fyi,.br-card.br-tone-fyi{--t:#7A8599}
.br-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px;padding:14px 28px 0;align-items:start}
.br-card{--t:#7A8599;background:var(--surface);border:1px solid var(--line);border-radius:14px;overflow:hidden;box-shadow:0 1px 3px rgba(20,29,43,.05);animation:brin .35s ease both;animation-delay:calc(var(--i,0) * 70ms)}
@keyframes brin{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
.br-card h3{display:flex;align-items:center;gap:9px;margin:0;padding:12px 14px;font-size:14px;font-weight:800;color:var(--ink);background:color-mix(in srgb,var(--t) 8%,var(--surface));border-bottom:1px solid color-mix(in srgb,var(--t) 18%,var(--line))}
.br-mark{width:24px;height:24px;border-radius:7px;background:var(--t);color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:12.5px;font-weight:800}
.br-n{margin-left:auto;font-size:12px;font-weight:700;color:var(--t)}
.br-card ul{list-style:none;margin:0;padding:4px 0}
.br-card li button,.br-row{display:flex;align-items:center;gap:11px;width:100%;border:0;background:none;text-align:left;font:inherit;padding:9px 14px;color:var(--ink)}
.br-card li button{cursor:pointer}
.br-card li button:hover{background:color-mix(in srgb,var(--t) 7%,var(--surface))}
.br-card li button:focus-visible{outline:2px solid var(--t);outline-offset:-2px}
.br-av{flex:none;width:30px;height:30px;border-radius:50%;background:color-mix(in srgb,var(--t) 14%,var(--surface));color:var(--t);display:inline-flex;align-items:center;justify-content:center;font-size:11.5px;font-weight:800}
.br-tx{flex:1;min-width:0;font-size:13.5px;line-height:1.4}
.br-go{flex:none;font-size:20px;color:var(--ink-3);transition:transform .12s,color .12s}
.br-card li button:hover .br-go{transform:translateX(2px);color:var(--t)}
@media (prefers-reduced-motion:reduce){.br-card{animation:none}.br-dots i{animation:none}.br-tile{transition:none}}
@media (max-width:1100px){.br-tiles{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media (max-width:760px){.br-hero{padding:18px 14px 16px}.br-tiles{padding:14px 12px 4px;grid-template-columns:repeat(2,minmax(0,1fr))}.br-grid{padding:12px 12px 0;grid-template-columns:1fr}}
/* the Inbox brief button: first in the list, always there, its own look */
.ibx2-briefbtn{flex:none;display:flex;align-items:center;gap:12px;margin:0 8px 8px;padding:12px 14px;border:0;border-radius:12px;cursor:pointer;text-align:left;font:inherit;color:#fff;
  background:linear-gradient(120deg,#0E9BD8 0%,#3A7BD5 55%,#6A5AE0 100%);box-shadow:0 4px 14px color-mix(in srgb,#0E9BD8 35%,transparent);transition:transform .12s,box-shadow .12s}
.ibx2-briefbtn:hover{transform:translateY(-1px);box-shadow:0 6px 18px color-mix(in srgb,#0E9BD8 45%,transparent)}
.ibx2-briefbtn:focus-visible{outline:3px solid var(--fbs-orange,#FCB122);outline-offset:2px}
.ibx2-briefbtn.on{box-shadow:0 0 0 3px var(--surface),0 0 0 5px #0E9BD8,0 6px 18px color-mix(in srgb,#0E9BD8 40%,transparent)}
.ibx2-briefic{flex:none;width:34px;height:34px;border-radius:10px;background:rgba(255,255,255,.18);display:inline-flex;align-items:center;justify-content:center;font-size:18px}
.ibx2-brieft{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}
.ibx2-brieft b{font-size:15px;letter-spacing:.01em}
.ibx2-brieft span{font-size:12.5px;opacity:.9;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ibx2-briefgo{flex:none;font-size:22px;line-height:1;opacity:.85}
@media (prefers-reduced-motion:reduce){.ibx2-briefbtn{transition:none}.ibx2-briefbtn:hover{transform:none}}
.mf-older-s{display:flex;flex-direction:column;align-items:center;gap:6px;padding:12px;font-size:12.5px;text-align:center}

/* Email → Inbox summary, third version: one column to read, "Start here" first (components/InboxView.tsx BriefPane) */
.sm2 .eh-bar{flex:none}
.sm2-k{font-weight:700;font-size:14px;color:var(--accent)}
