.eh-pn,.pbar{display:none}
.sw{position:relative;overflow:hidden;max-height:240px}
.sw-row{position:relative;z-index:1;background:var(--surface);transition:transform .22s cubic-bezier(.2,.8,.2,1);touch-action:pan-y}
.sw-acts{position:absolute;top:0;right:0;bottom:0;display:flex;overflow:hidden}
.sw-acts button{flex:1 1 0;min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;border:0;color:#fff;font:inherit;font-size:11.5px;font-weight:700;cursor:pointer;overflow:hidden;white-space:nowrap;transition:flex-grow .18s}
.sw-acts svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round;flex:none}
.sw-later{background:#7C5CE0}
