.sw-acts.full .sw-later,.sw-acts.full .sw-bh{flex-grow:0;padding:0}
.sw-acts.full .sw-arch{flex-grow:1}
.sw.gone{max-height:0;transition:max-height .22s ease .14s}
.tx-back{display:none}
