@media (max-width:760px){.as-card{flex-direction:column;align-items:stretch;bottom:calc(76px + env(safe-area-inset-bottom))}.as-b .btn{flex:1;justify-content:center;height:42px;font-size:15px}}
/* after sending: the follow-ups the reply promises (a to-do or event on My Day) */
.as-card{flex-direction:column;align-items:stretch;gap:10px}
.as-fl{display:flex;flex-direction:column;gap:6px}
.as-q{font-size:12.5px;font-weight:700;color:var(--ink-3)}
.as-f{display:flex;align-items:center;gap:8px;font-size:13.5px}
.as-k{flex:none;font-size:11px;font-weight:800;border-radius:999px;padding:2px 8px;background:color-mix(in srgb,#7C5CE0 14%,var(--surface));color:#6847c9}
.as-k.event{background:color-mix(in srgb,#D99A00 16%,var(--surface));color:#9a6c00}
.as-ft{flex:1;min-width:0}
.as-done{font-size:12.5px;color:var(--danger);flex:none}
.as-done.ok{color:#1f8a4c;font-weight:700}
.as-b{align-items:center;justify-content:flex-end}
.as-b .as-q{margin-right:auto}
@media (max-width:760px){.as-b{flex-direction:row}.as-f{flex-wrap:wrap}}
/* Cheer mode (components/Cheer.tsx): fireworks in the shop's colors and a kind note when you finish something */
.ch-fx{position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:3500}
.ch-note{position:fixed;left:50%;top:calc(16% + env(safe-area-inset-top));transform:translate(-50%,-10px) scale(.92);opacity:0;z-index:3600;width:min(360px,calc(100vw - 32px));text-align:center;border-radius:22px;padding:18px 18px 16px;box-shadow:0 22px 60px rgba(20,29,43,.28);border:2px solid transparent;background-image:linear-gradient(var(--surface),var(--surface)),conic-gradient(from 0deg,#0E9BD8,#7C5CE0,#F26660,#FCB122,#0E9BD8);background-origin:border-box;background-clip:padding-box,border-box;transition:opacity .25s,transform .35s cubic-bezier(.2,1.4,.4,1);pointer-events:none}
.ch-note.show{opacity:1;transform:translate(-50%,0) scale(1)}
.ch-big{font-family:var(--display);font-weight:800;font-size:24px;line-height:1.15;letter-spacing:-.01em;text-wrap:balance;margin:0 0 6px;color:var(--ink)}
.ch-small{font-size:14px;color:var(--ink-2);margin:0}
.ch-n{display:inline-block;margin-top:10px;font-size:12.5px;font-weight:700;color:#6847c9;background:color-mix(in srgb,#7C5CE0 12%,var(--surface));border-radius:999px;padding:3px 10px}
@media (prefers-reduced-motion:reduce){.ch-note{transition:opacity .2s}}
.md-head{display:flex;align-items:flex-start;gap:12px;flex-wrap:wrap}
.md-head>div:first-child{flex:1;min-width:0}
.md-cheer{display:inline-flex;align-items:center;gap:6px;font-size:13px;font-weight:600;color:var(--ink-2);border:1px solid var(--line);border-radius:999px;padding:6px 12px;background:var(--surface);cursor:pointer;user-select:none}
.md-cheer input{position:absolute;opacity:0;pointer-events:none}
.md-cheer.on{border-color:transparent;color:#fff;background:linear-gradient(135deg,#F26660,#7C5CE0)}
.md-cheer:has(input:focus-visible){outline:2px solid var(--accent);outline-offset:2px}
/* an email that mentions a piece count: Order goods right on it (lib/pieces.ts) */
.eh-tag.goods{background:color-mix(in srgb,#1F9D57 14%,var(--surface));color:#17783f;font-weight:700;text-decoration:none}
.eh-tag.goods:hover{background:color-mix(in srgb,#1F9D57 22%,var(--surface))}
.db-goods{margin-right:4px}
/* the sender, beside their name: their company */
.eh-org{color:var(--ink-2);font-size:13px;margin-left:6px}
.eh-org::before{content:"· ";color:var(--ink-3)}
/* phones: the sender in three clean lines: name · company / address / to … and the date (Oct 12, Nick: "looks jumbled") */
@media (max-width:760px){
  .eh-from{display:grid;grid-template-columns:36px minmax(0,1fr);column-gap:10px;row-gap:2px;align-items:start}
  .eh-av{grid-row:1 / span 2}
  .eh-n{display:flex;flex-wrap:wrap;align-items:baseline;column-gap:6px;row-gap:0}
  .eh-n b{font-size:15px}
  .eh-org{margin-left:0}
  .eh-addr{flex-basis:100%;margin-left:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .eh-date{grid-column:2;padding-top:0}
}
/* phones: nothing may make the page wider than the screen (Oct 12, Nick: "emails not showing on one page"). A grid
   column of 1fr grows to fit its widest content (a wide email, an image, a long file name) and pulled the whole page
   (and the fixed bottom bar) past the right edge; minmax(0,1fr) keeps it to the screen */
@media (max-width:820px){
  html,body{max-width:100%;overflow-x:clip}
  .app{grid-template-columns:minmax(0,1fr)}
  /* (no max-width here: 100vw plus the page's side padding was wider than the screen and clipped the right edge) */
  .main{min-width:0;max-width:none;box-sizing:border-box}
  .ibx2-head,.ibx2-tabs,.mf-bar,.ibx2-find,.ibx2-list-h{min-width:0;max-width:100%}
  .ibx2-tabs{overflow-x:auto;scrollbar-width:none}
  .ibx2-tabs::-webkit-scrollbar{display:none}
}
@media (max-width:760px){
  .ibx2{grid-template-columns:minmax(0,1fr)}
  .ibx2-list,.ibx2-work,.ibx2-mail,.ibx2-read,.ibx2-compose,.eh,.eh-b{min-width:0;max-width:100%}
  .ibx2-read img,.ibx2-read table{max-width:100%;height:auto}
  .ibx2-files{flex-wrap:wrap}
  .ibx2-files>*{max-width:100%;white-space:normal;overflow-wrap:anywhere;text-align:left}
  .ibx2-read pre,.ibx2-read .lm-text{white-space:pre-wrap;overflow-wrap:anywhere}
}
/* phones: Create order / reorder right on the email (the toolbar that has it on a computer is the bottom bar there) */
.eh-tag.make{display:none}
@media (max-width:760px) and (pointer:coarse){
  .eh-tag.make{display:inline-flex;align-items:center;border:0;cursor:pointer;font:inherit;font-weight:700;background:var(--accent);color:#fff}
  .eh-tag.make:disabled{opacity:.5}
}
.eh-tag.order{background:var(--accent);color:#fff;font-weight:700;text-decoration:none}
/* phones: an iPhone zooms the whole page in when you tap into a box with text under 16px, and stays zoomed (Oct 12:
   Amanda searched "Edu" and the page sat zoomed in, the right edge and the menu button off screen). Every box 16px+ */
@media (max-width:820px) and (pointer:coarse){
  input:not([type=checkbox]):not([type=radio]):not([type=range]):not([type=color]),select,textarea{font-size:16px!important}
}
.eop{max-width:980px}
.eop .page-head h1{margin-top:4px}

/* Email as conversations (Oct 12): one row per conversation, its emails listed under it when it's open */
.ibx2-cvn{flex:none;min-width:18px;height:18px;padding:0 5px;border-radius:9px;background:var(--line);color:var(--ink-2);font-size:11px;font-weight:700;line-height:18px;text-align:center}
.ibx2-cv.open .ibx2-cvn{background:var(--accent);color:#fff}
.ibx2-cvl{display:flex;flex-direction:column;border-bottom:1px solid var(--line);background:color-mix(in srgb,var(--accent) 4%,var(--surface))}
.ibx2-cvi{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:1px 8px;width:100%;text-align:left;border:0;border-left:3px solid transparent;background:none;padding:6px 12px 6px 26px;font:inherit;color:inherit;cursor:pointer;position:relative}
.ibx2-cvi::before{content:"";position:absolute;left:15px;top:0;bottom:0;border-left:1.5px solid var(--line)}
.ibx2-cvi:hover{background:var(--bg,#f6f7f9)}
.ibx2-cvi.on{background:var(--accent-soft);border-left-color:var(--accent)}
.ibx2-cvi b{font-size:12.5px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ibx2-cvi.ol-unread b{color:var(--accent)}
.ibx2-cvi time{font-size:11.5px;color:var(--ink-3);white-space:nowrap}
.ibx2-cvi span{grid-column:1/-1;font-size:12px;color:var(--ink-3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ibx2-cvi:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
/* the conversation at the top of the open email: phones (no list beside it), or with the list hidden */
.cv-strip{display:flex;flex-direction:column;border:1px solid var(--line);border-radius:10px;overflow:hidden;margin:0 0 12px;background:var(--surface)}
.cv-h{font-size:12px;font-weight:700;color:var(--ink-2);padding:7px 12px;background:var(--bg,#f6f7f9);border-bottom:1px solid var(--line)}
.cv-i{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:1px 8px;text-align:left;border:0;border-bottom:1px solid var(--line);background:none;padding:8px 12px;font:inherit;color:inherit;cursor:pointer}
.cv-i:last-child{border-bottom:0}
.cv-i.on{background:var(--accent-soft);box-shadow:inset 3px 0 0 var(--accent);cursor:default}
.cv-i b{font-size:13px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cv-i.ol-unread b{color:var(--accent)}
.cv-i time{font-size:11.5px;color:var(--ink-3);white-space:nowrap}
.cv-i span{grid-column:1/-1;font-size:12px;color:var(--ink-3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.cv-i.on span{color:var(--accent);font-weight:600}
.ibx2:not(.nolist) .cv-strip{display:none}
@media (max-width:760px) and (pointer:coarse){.ibx2:not(.nolist) .cv-strip{display:flex}.cv-i{padding:10px 12px}}
.ibx-t.newer{border-left-color:var(--accent)}
.ibx-newer{margin-left:6px;font-size:10.5px;font-weight:700;color:var(--accent);background:var(--accent-soft);border-radius:6px;padding:1px 6px}

/* Alerts & Away (Oct 12) */
.al{display:flex;flex-direction:column;gap:14px;max-width:760px}
.al-card{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 18px;display:flex;flex-direction:column;gap:10px;min-width:0}
.al-card h2{font-size:16px;margin:0}
.al-card p{margin:0;font-size:14px;line-height:1.45;color:var(--ink-2)}
.al-row{display:flex;align-items:center;gap:14px;justify-content:space-between}
.al-t{display:flex;flex-direction:column;gap:6px;min-width:0}
.al-away{border-width:2px}
.al-away.on{border-color:var(--accent);background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 10%,var(--surface)),var(--surface) 60%)}
.al-sw{flex:none;display:inline-flex;align-items:center;gap:8px;border:0;background:none;padding:4px;cursor:pointer;font:inherit;color:var(--ink-2)}
.al-sw .al-knob{width:50px;height:30px;border-radius:15px;background:var(--line);position:relative;transition:background .2s}
.al-sw .al-knob::after{content:"";position:absolute;top:3px;left:3px;width:24px;height:24px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(20,29,43,.3);transition:transform .2s}
.al-sw.on .al-knob{background:var(--accent)}
.al-sw.on .al-knob::after{transform:translateX(20px)}
.al-sw .al-swl{font-size:13px;font-weight:700;min-width:24px}
.al-sw:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:18px}
.al-sw:disabled{opacity:.6;cursor:default}
@media (prefers-reduced-motion:reduce){.al-sw .al-knob,.al-sw .al-knob::after{transition:none}}
.al-warn{font-size:13px;font-weight:600;color:var(--warn)}
.al-note{font-size:13px;color:var(--ink-2);background:var(--bg,#f6f7f9);border-radius:10px;padding:8px 12px}
.al-ok{color:var(--ok,#2BB673)!important;font-weight:600}
.al-steps ol{margin:4px 0 6px;padding-left:20px;font-size:14px;line-height:1.6}
.al-devs{display:flex;flex-direction:column;gap:6px;border-top:1px solid var(--line);padding-top:10px}
.al-sub{font-size:12px}
.al-dev{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:13px}
.al-dev em{font-style:normal;color:var(--accent)}
.al-list{margin:0;padding-left:18px;font-size:13.5px;line-height:1.6;color:var(--ink-2)}
.al-hist{display:flex;flex-direction:column}
.al-h{display:grid;grid-template-columns:auto minmax(0,1fr);gap:2px 10px;padding:10px 0;border-top:1px solid var(--line);color:inherit;text-decoration:none}
.al-h:first-child{border-top:0}
.al-hk{grid-row:span 2;align-self:start;font-size:11px;font-weight:700;border-radius:6px;padding:2px 7px;background:var(--accent-soft);color:var(--accent)}
.al-h.job .al-hk{background:color-mix(in srgb,#FCB122 20%,var(--surface));color:#9A6A00}
.al-hb{display:flex;flex-direction:column;gap:2px;min-width:0}
.al-hb b{font-size:14px}
.al-hb span{font-size:13px;color:var(--ink-2)}
.al-h time{grid-column:2;font-size:12px;color:var(--ink-3)}
@media (max-width:760px){.al-row{align-items:flex-start}.al-card{padding:14px}}
@media (max-width:760px) and (pointer:coarse){.al-row:has(.btn){flex-direction:column;align-items:stretch}}

/* Needs you today (dashboard, Oct 12) */
.nt{background:var(--surface);border:1.5px solid color-mix(in srgb,var(--danger) 45%,var(--line));border-radius:14px;padding:14px 16px;margin:4px 0 16px;display:flex;flex-direction:column;gap:8px}
.nt-h{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap}
.nt-h h2{font-size:16px;margin:0}
.nt-n{font-size:12px;font-weight:700;color:#fff;background:var(--danger);border-radius:9px;padding:1px 7px}
.nt-note{font-size:12px}
.nt-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.nt-list li{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:10px;align-items:start;padding:10px 0;border-top:1px solid var(--line)}
.nt-list li:first-child{border-top:0}
.nt-k{font-size:11px;font-weight:700;border-radius:6px;padding:2px 7px;background:color-mix(in srgb,#FCB122 22%,var(--surface));color:#8A5F00;white-space:nowrap;margin-top:2px}
.nt-list li.late .nt-k{background:color-mix(in srgb,var(--danger) 15%,var(--surface));color:var(--danger)}
.nt-b{display:flex;flex-direction:column;gap:2px;min-width:0}
.nt-b b{font-size:14px}
.nt-b span{font-size:13px;color:var(--ink-2);line-height:1.4}
.nt-b em{font-style:normal;font-size:11.5px;color:var(--ink-3)}
.nt-calm{font-size:13px;color:var(--ink-2);margin:2px 0 14px;display:flex;gap:6px;align-items:center}
.nt-calm span{color:var(--ok,#2BB673);font-weight:700}
@media (max-width:760px){.nt-list li{grid-template-columns:minmax(0,1fr) auto}.nt-k{grid-column:1/-1;justify-self:start}}

/* Cc on replies (Oct 12) */
.cc-add{align-self:flex-start;border:0;background:none;padding:2px 0;font:inherit;font-size:12.5px;font-weight:600;color:var(--accent);cursor:pointer}
.cc{display:flex;flex-wrap:wrap;align-items:center;gap:6px;padding:4px 0;border-bottom:1px solid var(--line);min-width:0}
.cc-l{font-size:12.5px;color:var(--ink-3);font-weight:600}
.cc-chip{display:inline-flex;align-items:center;gap:4px;background:var(--accent-soft);color:var(--accent);border-radius:12px;padding:2px 4px 2px 9px;font-size:12.5px;font-weight:600}
.cc-chip button{border:0;background:none;color:inherit;font-size:15px;line-height:1;padding:0 4px;cursor:pointer;border-radius:8px}
.cc-chip button:hover{background:color-mix(in srgb,var(--accent) 15%,transparent)}
.cc-in{position:relative;flex:1;min-width:120px}
.cc-in input{width:100%;border:0;outline:0;background:none;font:inherit;font-size:13px;padding:3px 0;color:inherit}
.cc-sugg{position:absolute;left:0;top:100%;z-index:20;min-width:240px;background:var(--surface);border:1px solid var(--line);border-radius:10px;box-shadow:0 6px 20px rgba(20,29,43,.14);display:flex;flex-direction:column;padding:4px}
.cc-sugg button{text-align:left;border:0;background:none;padding:6px 8px;border-radius:7px;font:inherit;font-size:12.5px;color:var(--ink-2);cursor:pointer}
.cc-sugg button:hover{background:var(--bg,#f6f7f9)}
.cc-sugg b{color:var(--ink);margin-right:4px}
@media (max-width:760px) and (pointer:coarse){.cc-in input{font-size:16px}}

/* AI Workbench (Oct 13): chats on the left, the conversation with its cards, and the message box at the bottom */
.wb-head{margin-bottom:12px}
.wb{display:grid;grid-template-columns:230px minmax(0,1fr);gap:16px;height:calc(100dvh - 150px);min-height:520px}
.wb-side{display:flex;flex-direction:column;gap:10px;min-height:0}
.wb-new{width:100%;justify-content:center}
.wb-chats{display:flex;flex-direction:column;gap:2px;overflow-y:auto;min-height:0;padding-right:2px}
.wb-none{color:var(--ink-3);font-size:13px;margin:6px 4px}
.wb-chat{display:flex;flex-direction:column;align-items:flex-start;gap:1px;text-align:left;border:0;background:none;padding:8px 10px;border-radius:8px;cursor:pointer;color:var(--ink-2);min-width:0}
.wb-chat:hover{background:var(--surface-2)}
.wb-chat.on{background:var(--accent-soft);color:var(--ink)}
.wb-chat-t{font-size:13.5px;font-weight:500;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.wb-chat-d{font-size:11.5px;color:var(--ink-3)}
.wb-main{position:relative;display:flex;flex-direction:column;min-height:0;background:var(--surface);border:1px solid var(--line);border-radius:14px;overflow:hidden}
.wb-listbtn{display:none}
.wb-scroll{flex:1;overflow-y:auto;padding:22px clamp(14px,3vw,34px) 12px;display:flex;flex-direction:column;gap:16px}
.wb-hello{max-width:640px;margin:auto 0;padding:10px 0 20px}
.wb-hello h2{font-family:var(--display);font-size:26px;line-height:1.15;margin:0 0 8px}
.wb-hello p{color:var(--ink-2);margin:0 0 16px;font-size:14.5px;line-height:1.55;max-width:62ch}
.wb-starters{display:flex;flex-wrap:wrap;gap:8px}
.wb-starters button{border:1px solid var(--line);background:var(--surface-2);border-radius:999px;padding:7px 13px;font-size:13px;cursor:pointer;color:var(--ink);text-align:left}
.wb-starters button:hover{border-color:var(--accent);background:var(--accent-soft)}
.wb-msg{display:flex;flex-direction:column;gap:10px;max-width:min(760px,100%)}
.wb-msg.me{align-self:flex-end;align-items:flex-end}
.wb-msg.me .wb-text{background:var(--accent);color:var(--accent-ink);border-radius:16px 16px 4px 16px;padding:9px 14px}
.wb-msg.ai .wb-text{color:var(--ink);line-height:1.55}
.wb-msg.err .wb-text{color:var(--danger)}
.wb-text{white-space:pre-wrap;font-size:14.5px;overflow-wrap:anywhere}
.wb-mfiles{display:flex;flex-wrap:wrap;gap:6px;justify-content:flex-end}
.wb-mpic{display:block;width:84px;height:84px;border-radius:10px;overflow:hidden;border:1px solid var(--line);background:#fff}
.wb-mpic img{width:100%;height:100%;object-fit:contain}
.wb-mdoc{display:inline-flex;align-items:center;padding:7px 11px;border-radius:10px;border:1px solid var(--line);background:var(--surface-2);font-size:13px;color:var(--ink);text-decoration:none;max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.wb-status{display:flex;align-items:center;gap:8px;color:var(--ink-3);font-size:13.5px}
.wb-dots{display:inline-flex;gap:3px}
.wb-dots i{width:6px;height:6px;border-radius:50%;background:var(--accent);animation:wbdot 1.1s infinite ease-in-out}
.wb-dots i:nth-child(2){animation-delay:.15s}.wb-dots i:nth-child(3){animation-delay:.3s}
@keyframes wbdot{0%,80%,100%{opacity:.25;transform:translateY(0)}40%{opacity:1;transform:translateY(-3px)}}
@media (prefers-reduced-motion: reduce){.wb-dots i{animation:none;opacity:.7}}
.wb-err{color:var(--danger);background:var(--danger-soft);border-radius:8px;padding:8px 12px;font-size:13.5px}
.wb-card{border:1px solid var(--line);border-radius:12px;background:var(--bg);padding:12px 14px;display:flex;flex-direction:column;gap:10px;width:100%;min-width:0}
.wb-card-h{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap}
.wb-card-h > div{display:flex;flex-direction:column;gap:1px;min-width:0}
.wb-card-h b{font-size:15px}
.wb-card-h span{font-size:12.5px;color:var(--ink-3)}
.wb-note{margin:0;font-size:13px;color:var(--ink-2)}
.wb-mocks{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}
.wb-mock{margin:0;display:flex;flex-direction:column;gap:4px;min-width:0}
.wb-mock-img{display:block;border:1px solid var(--line);border-radius:10px;overflow:hidden;background:#fff;padding:0;cursor:zoom-in;aspect-ratio:4/5}
.wb-mock-img img{width:100%;height:100%;object-fit:cover;display:block}
.wb-mock-wait{aspect-ratio:4/5;border:1px dashed var(--line);border-radius:10px;display:grid;place-items:center;font-size:12.5px;color:var(--ink-3);background:var(--surface)}
.wb-mock figcaption{display:flex;justify-content:space-between;gap:6px;font-size:12.5px;color:var(--ink-2)}
.wb-mock figcaption a{font-size:12px}
