.pga-tiers{display:flex;flex-direction:column;gap:6px;border:1px solid var(--line);border-radius:10px;padding:10px 12px;background:var(--surface);font-size:13.5px}
.pga-tiers>div{display:flex;flex-wrap:wrap;gap:6px 14px;align-items:baseline}
