/* program: a recommended price for a quantity they've never had (Oct 14) */
.prg-sug{display:flex;flex-direction:column;gap:8px;margin-top:8px}
.prg-sug-c{border:1px solid var(--accent);background:var(--accent-soft);border-radius:12px;padding:10px 12px;display:flex;flex-direction:column;gap:6px}
