.ibx2-fwd textarea{width:100%;resize:vertical}
.ibx2-fwd-a{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
/* toolbar section headers (Oct 14, Nick: Email · Move · Spam · Actions) */
/* the header sits inside its section, left of the buttons */
.tb-sec{min-width:0}
.tb-sec-l{font-size:11px;font-weight:600;color:var(--ink-3);letter-spacing:.02em;padding:0 8px 0 6px;margin-right:2px;border-right:1px solid var(--line);align-self:stretch;display:flex;align-items:center;white-space:nowrap}
/* two lines, never three: each line stays on one line and its buttons drop their words when it runs out of room */
