.tb-row>*{flex:none}
@container (max-width:1000px){ .tb-row.r2 .tb-sec[aria-label="Messages"] .tb-b .tb-l{display:none} }
@container (max-width:780px){ .tb-row .tb-b:not(.primary) .tb-l{display:none} .tb-row .tb-b{padding:0 9px} }
@container (max-width:520px){ .tb-row .tb-sec-l{display:none} .tb-row .tb-b.primary .tb-l{display:none} }
.tb-ask{display:flex;flex-wrap:wrap;align-items:center;gap:6px;padding:2px 6px;font-size:13px;color:var(--ink)}
.tb-ask .btn.danger{background:var(--danger);border-color:var(--danger);color:#fff}
.pv2-mails{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}
.pv2-mails li{border:1px solid var(--line);border-radius:10px;padding:8px 12px;background:var(--surface);font-size:14px}
