  .eh-av{width:36px;height:36px;font-size:13px;grid-row:auto}
  .eh-who{grid-column:2;grid-row:1;font-size:14px;line-height:1.3}
  .eh-n{display:flex;flex-wrap:nowrap;align-items:baseline;column-gap:6px;min-width:0;overflow:hidden;white-space:nowrap}
  .eh-n b{font-size:14.5px}
  .eh-org{margin-left:0;font-size:14px;color:var(--ink-2)}
  .eh-addr{margin-left:2px;font-size:12.5px;color:var(--ink-3);overflow:hidden;text-overflow:ellipsis}
  .eh-to{font-size:12.5px;color:var(--ink-3)}
  .eh-date{grid-column:3;grid-row:1;align-self:start;padding-top:2px;font-size:12.5px;color:var(--ink-3)}
  /* the AI card */
  .eh .eh-ai{order:2;flex-wrap:wrap;align-items:center;column-gap:6px;row-gap:6px;margin:14px 24px 0;padding:10px 12px;border:0;border-radius:12px;
    background:color-mix(in srgb,var(--ai-c) 5%,var(--surface));box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--ai-c) 14%,transparent)}
  .eh .eh-ai::before{display:none}
  .eh .eh-ai-l{flex:0 0 100%;flex-direction:row;gap:6px;min-width:0;padding:0;font-size:11.5px}
  .eh .eh-ai-l::after{content:"summary";margin-left:-2px}
  .eh .eh-ai-orb{width:16px;height:16px;border-radius:5px;font-size:9px}
  .eh .eh-ai-b{display:contents}
  .eh .eh-ai-b .eh-sum{flex:0 0 100%;font-size:13.5px;line-height:1.45;font-weight:400;color:var(--ink-2)}
  .eh .eh-ai-tags{gap:5px}
  .eh .eh-ai-tags .eh-tag{font-size:11.5px;padding:2px 9px}
  .eh .eh-hist{font-size:12.5px;padding:0 4px}
  .eh .eh-ai-btn,.eh .eh-ai-btn.on{margin-left:auto;height:30px;padding:0 10px;gap:5px;border:0;border-radius:8px;background:var(--surface);
    box-shadow:inset 0 0 0 1px var(--line);color:var(--accent);font-size:12.5px;font-weight:600;filter:none}
  .eh .eh-ai-btn:hover:not(:disabled){background:var(--surface-2);filter:none}
  .eh .eh-ai-btn.on{background:var(--accent-soft);box-shadow:inset 0 0 0 1.5px var(--accent)}
  .eh .eh-ai-btn svg{width:15px;height:15px}
  /* the email */
  .ibx2-read{padding:12px 24px 18px}
  .ibx2-orig-h{display:none}
  .ibx-html>.btn{display:none}
  .ibx2-read .ibx-html iframe{border:0;border-radius:0}
  .ibx-q{display:block;align-self:flex-start;border:0;background:none;padding:4px 0;font:inherit;font-size:13px;font-weight:600;color:var(--accent);cursor:pointer}
  .ibx-q:hover{text-decoration:underline}
  /* the conversation, folded to one line */
  .cv-strip{border:0;border-radius:0;margin:0;background:none;overflow:visible}
  .cv-strip:not(.pop)>:not(.cv-sum){display:none!important}
  .cv-sum{display:flex;align-items:baseline;gap:5px;width:100%;border:0;border-top:1px solid var(--line-2);border-bottom:1px solid var(--line-2);background:none;padding:9px 0;font:inherit;font-size:13px;color:var(--ink-2);text-align:left;cursor:pointer}
  .cv-sum b{color:var(--ink);font-weight:600}
  .cv-sum span{margin-left:auto;color:var(--accent);font-size:12.5px;font-weight:600}
  .cv-sum:hover span{text-decoration:underline}
  .cv-strip.pop .cv-sum{border-bottom:0}
  .cv-strip.pop{border-bottom:1px solid var(--line-2);margin-bottom:4px}
  .cv-strip.pop .cv-h{display:none}
  .cv-i{grid-template-columns:auto minmax(0,1fr) auto;align-items:baseline;gap:0 8px;padding:7px 0;border-bottom:0;border-top:1px solid var(--line-2)}
  .cv-i:hover:not(.on){background:color-mix(in srgb,var(--surface-2) 60%,transparent)}
  .cv-i.on{background:none;box-shadow:none}
  .cv-i b{font-size:13px}
  .cv-i span{grid-column:2;grid-row:1;font-size:12.5px}
  .cv-i time{grid-column:3;grid-row:1;font-size:11.5px}
  .cv-more{border-top:1px solid var(--line-2);background:none;padding:8px 0}
}
/* Customer details: Delete the whole customer, small, at the very bottom, with a confirm (Oct 15, Nick) */
.cu-del{display:flex;align-items:center;flex-wrap:wrap;gap:8px 12px;margin:22px 0 6px;padding-top:14px;border-top:1px solid var(--line-2);font-size:12.5px}
.cu-del-b{color:var(--danger);font-size:12.5px}
.cu-del-b:disabled{color:var(--ink-3)}
.cu-del-ask{display:flex;align-items:center;flex-wrap:wrap;gap:8px 14px;padding:10px 12px;border-radius:10px;background:var(--danger-soft);font-size:13.5px;color:var(--ink)}
.cu-del-ask .btn.danger{background:var(--danger);border-color:var(--danger);color:#fff}
/* a 40,000 job run from Printavo: its status, Printavo's words, not changeable here (Oct 15, Nick) */
.status-select.pv-st{display:inline-flex;align-items:center;gap:7px;height:36px;padding:0 12px;border:1px solid color-mix(in srgb,var(--sc) 40%,var(--line));border-radius:8px;font-size:13.5px;white-space:nowrap;cursor:default}
.status-select.pv-st small{font-size:10.5px;font-weight:700;color:var(--ink-3);background:var(--surface);border-radius:4px;padding:1px 5px}
/* Production notes & files in the order page's narrow side column (Oct 15, Nick: "text overlapping and buttons
   outside the box"): Download / Remove wrap under a file instead of running into the next; the note row stacks */
.prod-facts{flex-wrap:wrap;gap:2px 10px;min-width:0}
.prod-compact .prod-facts{flex-direction:column;gap:1px;font-size:11.5px}
.prod-compact .prod-facts .linkish{font-size:11.5px;text-align:left}
.prod-compact .jf-add{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
.prod-compact .jf-add input[type=text]{grid-column:1/-1;order:-1;min-width:0}
.prod-compact .jf-add select{grid-column:1/-1;min-width:0;width:100%}
.prod-compact .jf-add .btn{justify-content:center;min-width:0;white-space:nowrap;padding-left:8px;padding-right:8px}

/* ───────── The order page in tabs (Oct 15, Nick: "too much information on one page… tabs at the top and reimagine
   the organization"): header · Printavo bar · summary strip · Order / Art & production / Messages / Payments / Activity ───────── */
.ot-sum{display:flex;align-items:stretch;background:var(--surface);border:1px solid var(--line);border-radius:14px;margin:0 0 12px;overflow:hidden}
.ot-sum>div{flex:1 1 0;padding:10px 16px;border-left:1px solid var(--line-2);min-width:0}
.ot-sum>div:first-child{border-left:0;flex:1.6 1 0}
.ot-sum span{display:block;font-size:11.5px;font-weight:600;color:var(--ink-3)}
.ot-sum b{display:block;font-size:15px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--ink)}
.ot-sum b.ok,.ot-sum small.ok{color:var(--ok)}
.ot-sum b.hot{color:var(--danger)}
.ot-sum small{display:block;font-size:12px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ot-sum small.due{color:var(--warn);font-weight:600}
.ot-nav{position:sticky;top:0;z-index:20;margin:0 0 16px}
.ot-panes>[hidden]{display:none!important}
.ot-one{display:flex;flex-direction:column;gap:14px;max-width:900px}
/* More ▾ */
.ot-more{position:relative}
.ot-more>summary{list-style:none;cursor:pointer}
.ot-more>summary::-webkit-details-marker{display:none}
.ot-menu{position:absolute;right:0;top:calc(100% + 4px);z-index:40;min-width:180px;display:flex;flex-direction:column;padding:4px;background:var(--surface);border:1px solid var(--line);border-radius:10px;box-shadow:0 12px 30px rgba(20,29,43,.16)}
.ot-menu a,.ot-menu button{display:block;width:100%;text-align:left;border:0;background:none;font:inherit;font-size:13.5px;color:var(--ink);padding:8px 10px;border-radius:7px;text-decoration:none;cursor:pointer}
.ot-menu a:hover,.ot-menu button:hover{background:var(--surface-2)}
.ot-menu .danger{color:var(--danger);border-top:1px solid var(--line-2);border-radius:0 0 7px 7px;margin-top:2px}
.ot-menu .danger.armed{background:var(--danger);color:#fff}
/* the Printavo bar and its check, one block */
.pvx-box{margin:10px 0 12px}
.pvx-box>.pvs-strip{margin:0}
.pvx-box>.pvs-strip:not(:last-child){border-radius:10px 10px 0 0;border-bottom:0}
.pvx-box>.pvc{margin:0;border-radius:0 0 10px 10px;background:var(--surface-2);padding-top:4px}
.pvx-box:empty{display:none}
@media (max-width:900px){
  .ot-sum{flex-wrap:wrap}
