/* Orders list: bulk delete, Nick only (Oct 15) */
.bulk-bar{display:flex;align-items:center;flex-wrap:wrap;gap:8px 14px;margin:0 0 10px;padding:8px 12px;border:1px solid color-mix(in srgb,var(--danger) 30%,var(--line));border-radius:10px;background:color-mix(in srgb,var(--danger) 5%,var(--surface));position:sticky;top:0;z-index:15}
.bulk-bar .spacer{flex:1}
.bulk-bar .btn.danger.armed{background:var(--danger);border-color:var(--danger);color:#fff}
