.imp-card-h{display:flex;align-items:center;gap:8px;padding:8px 10px 8px 14px;background:var(--surface-2);border-bottom:1px solid var(--line-2);font-size:13px}
.imp-card-h>b{font-size:14px}
.imp-card-h>span:not(.spacer):not(.imp-each){color:var(--ink-2)}
.imp-card-h .spacer{flex:1}
.imp-each{font-size:12.5px;color:var(--ink-3)}
.imp-each b{font-size:15px;color:var(--ink);margin-right:2px}
.imp-grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1.2fr) 74px minmax(0,1.8fr);grid-template-areas:"me lo co in" "si dr no no";gap:10px 12px;padding:12px 14px 6px}
.imp-grid>div{display:flex;flex-direction:column;gap:3px;min-width:0}
