.imp-art{padding:8px 14px 12px;border-top:1px dashed var(--line-2);margin-top:8px}
@media (max-width:1100px){ .imp-grid{grid-template-columns:minmax(0,1fr) minmax(0,1fr) 70px;grid-template-areas:"me lo co" "in in in" "si dr dr" "no no no"} }
