@media (max-width:760px){ .pr{grid-template-columns:90px minmax(0,1fr)} .pr-logo{width:90px;height:90px} }

/* the print close-up popup (like the Mockup Creator's) and the shirt color behind each small logo (Oct 15, Nick) */
.pr-logo{border-color:color-mix(in srgb,var(--ink) 12%,transparent)}
.pr-cu{background:#fff;border-radius:16px;padding:16px 18px 14px;box-shadow:0 24px 60px rgba(0,0,0,.3);cursor:default;max-width:92vw;max-height:92vh;overflow:auto;display:flex;flex-direction:column;gap:10px}
.pr-cu-f{display:flex;align-items:center;gap:10px;font-size:12.5px}
.pr-cu-f .btn{margin-left:auto}
/* the zoomed logo on the shirt's color (Oct 15, Nick: "liked the way I had it… just the shirt color in the background") */
.pr-zoom img{padding:24px;box-sizing:border-box}
/* the zoomed logo's ink colors (Oct 15, Nick) */
.pr-zoom-inks{display:flex;flex-wrap:wrap;gap:6px 16px;font-size:13.5px;font-weight:600;color:var(--ink)}
.pr-zoom-inks span{display:inline-flex;align-items:center;gap:7px}
.pr-zoom-inks i{width:18px;height:18px;border-radius:4px;border:1px solid rgba(0,0,0,.18);flex:none}

/* ───────── The order page, one look (Oct 15, Nick: "a lot of different fonts and CSS styles now… make it look unified") ─────────
   Two fonts only: Archivo for titles (the page title, panel titles, a group's sections), Public Sans for everything
   else, numbers included (tabular, no typewriter font). One label style for every field and column: small, grey,
   sentence case. One title style for panels and a group's sections. */
.ord{font-family:var(--body)}
.ord .mono,.ord .num,.ord .pb-r b,.ord .ordno{font-family:var(--body);font-variant-numeric:tabular-nums}
.ord .eyebrow{font-family:var(--body);font-size:12px;letter-spacing:0;text-transform:none;color:var(--ink-3)}
.ord h1 .mono{font-family:var(--display);font-weight:600;color:var(--ink-3)}
/* labels: fields, table columns, sizes, summary strip, prints, fees */
.ord .field label,.ord .lbl:not(.gsec),.ord .gl-head,.ord .fee-head,.ord .lbl2,.ord .imp-l,.ord .pf dt,.ord .ot-sum span,
.ord .sz-h,.ord .gl-sizes .h,.ord .sbx-h:not(.gsec),.ord .comm-sum span{font-family:var(--body);font-size:12px;font-weight:600;letter-spacing:0;text-transform:none;color:var(--ink-3)}
/* titles: panels, the group's name, and its sections (Garments, Imprints, Screens, Finishing) look the same */
.ord .panel-h h2,.ord .lbl.gsec,.ord .sbx-h.gsec,.ord .line-h input.grp-name{font-family:var(--display);font-stretch:85%;font-weight:700;font-size:16px;letter-spacing:.005em;text-transform:none;color:var(--ink)}
.ord .lbl.gsec,.ord .sbx-h.gsec{position:relative;display:block;padding-left:12px;margin-bottom:2px}
.ord .lbl.gsec::before,.ord .sbx-h.gsec::before{content:"";position:absolute;left:0;top:.18em;bottom:.18em;width:4px;height:auto;border-radius:2px;background:linear-gradient(180deg,var(--fbs-blue) 0%,var(--fbs-salmon) 52%,var(--fbs-orange) 100%)}
.ord .line-h input.grp-name{font-size:17px}
/* "Customer supplied goods": a quiet tag on the group, not a shouting banner */
.ord .cs-banner{font-family:var(--body);font-size:12.5px;font-weight:700;letter-spacing:0;text-transform:none;text-align:left;color:var(--accent);background:color-mix(in srgb,var(--accent) 6%,var(--surface));padding:7px 16px}
/* the tabs and summary strip in the same voice */
.ord .ot-nav .aa-tab{font-size:13.5px;letter-spacing:0;text-transform:none;font-weight:700}
.ord .ot-sum b{font-family:var(--body);font-weight:700}
/* money: the same weight and size wherever it's a total */
.ord .pb-r.pb-t b,.ord .totals .tr.big span:last-child,.ord .grp-total b{font-family:var(--body);font-stretch:100%;font-weight:800}
.ord .pr-top>b,.ord .pr-each b{font-family:var(--body)}

/* ───────── The order page, calmer (Oct 15, Nick: "all the different shading, accent colors… too much going on… sizes
   filled in weird with blue… customer supplied goods and order check don't fit together"). White panels, one hairline
   color, grey only for quiet text, the blue only for what you click; no tinted bands or boxes inside panels. ───────── */
.ord .line-h{background:var(--surface)}
.ord .cs-banner{background:none;border-bottom:0;color:var(--ink-3);font-weight:600;font-size:12.5px;padding:0 16px 2px;margin-top:-4px}
.ord .cs-banner::before{content:"";display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--ink-3);margin-right:7px;vertical-align:1px}
.ord .lbl.gsec,.ord .sbx-h.gsec{padding-left:0}
.ord .lbl.gsec::before,.ord .sbx-h.gsec::before{display:none}
/* sizes: a filled size is just a bold number, no blue box */
.ord .sizes input.has,.ord .szc input.sz.has,.ord .pv-grid input.sz.has{background:var(--surface);border-color:var(--line);color:var(--ink);font-weight:700}
/* the customer, the price box, the Printavo bar: white with a hairline, not grey fills */
.ord .cust-row{background:var(--surface);border:1px solid var(--line-2)}
.ord .cust-row .cust-card{border:0}
.ord .price-box{background:var(--surface);border:1px solid var(--line-2)}
.ord .pvx-box>.pvs-strip,.ord .pvx-box>.pvc,.ord .pvs-strip{background:var(--surface)}
.ord .pvx-box>.pvc{border-top:1px solid var(--line-2)}
/* tabs: the current one underlined, not a blue block */
.ord .ot-nav{padding:0 8px;gap:0}
.ord .ot-nav .aa-tab{border-radius:0;padding:12px 10px;color:var(--ink-3)}
.ord .ot-nav .aa-tab:hover{background:none;color:var(--ink)}
.ord .ot-nav .aa-tab.on{background:none;color:var(--ink);box-shadow:inset 0 -2.5px 0 var(--accent)}
.ord .ot-nav .aa-n{background:var(--surface-2);color:var(--ink-3)}
/* the side panels speak the same way: Customer supplied goods without its own colored card, Order check without the
   dashed blue box */
.ord .ed-aside .gb{display:block}
.ord .ed-aside .gc{border:0;border-radius:0;padding:0;gap:10px;background:none}
.ord .ed-aside .gc-h .gc-no,.ord .ed-aside .gc-h .gc-t>b,.ord .ed-aside .gc-sub{display:none}
.ord .ed-aside .gc-st{background:none;padding:0;color:var(--ok);font-weight:700;font-size:13.5px}
.ord .ed-aside .gc-steps li span{background:var(--line-2)}
.ord .ed-aside .gc-steps li.done span,.ord .ed-aside .gc-steps li.now span{background:var(--ink-3)}
.ord .ed-aside .gc-steps li.now span{background:var(--accent)}
.ord .ai-box{border:1px solid var(--line-2);background:var(--surface);border-radius:10px}
.ord .ai-box h3{font-size:13.5px}
.ord .eo-chip{background:var(--surface);border-color:var(--line)}
/* prints: the logo tile keeps the shirt color (the one color that means something), everything else stays plain */
.ord .imp-mock .mk-big{border-color:var(--line-2)}
/* (Oct 15, Nick) the customer's details plain on the panel (no box); "Customer supplied goods" big across the middle of
   the group again; titles with a short horizontal rainbow under them instead of the little bar on the left */
.ord .cust-row{background:none;border:0;padding:4px 0 0}
.ord .cs-banner{display:block;text-align:center;font-family:var(--display);font-stretch:85%;font-size:16px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);background:color-mix(in srgb,var(--accent) 5%,var(--surface));border-top:1px solid var(--line-2);border-bottom:1px solid var(--line-2);padding:9px 16px;margin:0}
.ord .cs-banner::before{display:none}
.ord .panel-h h2,.ord .lbl.gsec,.ord .sbx-h.gsec{position:relative;padding-left:0;padding-bottom:7px}
.ord .panel-h h2::before{display:none}
.ord .panel-h h2::after,.ord .lbl.gsec::after,.ord .sbx-h.gsec::after{content:"";position:absolute;left:0;bottom:0;width:28px;height:3px;border-radius:2px;background:linear-gradient(90deg,var(--fbs-blue) 0%,var(--fbs-salmon) 52%,var(--fbs-orange) 100%)}
.ord .lbl.gsec,.ord .sbx-h.gsec{margin-bottom:6px}
/* titles: the rainbow under them like the page headers' (Oct 15, Nick: "more like this" — the Email page's) */
.ord .lbl.gsec,.ord .sbx-h.gsec{width:fit-content}
.ord .panel-h h2,.ord .lbl.gsec,.ord .sbx-h.gsec{padding-bottom:9px}
.ord .panel-h h2::after,.ord .lbl.gsec::after,.ord .sbx-h.gsec::after{width:calc(100% + 36px);min-width:72px;height:4px;border-radius:4px;background:var(--fbs-fade)}
.ord .ed-head h1::after{content:"";display:block;height:4px;border-radius:4px;margin-top:10px;width:calc(100% + 60px);min-width:140px;max-width:100%;background:var(--fbs-fade)}
.ord .ed-head .ed-title{min-width:0}
/* every rainbow underline sits close under its words, like the logo's (Oct 15, Nick: "make it closer… more like our logo") */
.page-head h1::after,.portal .p-main h1::after,.md-head h1::after,.ord .ed-head h1::after{margin-top:3px}
.ord .panel-h h2,.ord .lbl.gsec,.ord .sbx-h.gsec{padding-bottom:5px}
.portal .aa-sec-h h3{padding-bottom:5px}
/* the order title: the job first, then "– Order #40003"; its rainbow runs the whole title and a bit past (Oct 15, Nick) */
.ord .ed-head h1 .ot-no{font-weight:600;color:var(--ink-3);font-size:.82em}
.ord .ed-head h1::after{max-width:none;width:calc(100% + 60px)}
/* sub-sections (Garments, Imprints, Screens, Finishing, Fees & adjustments, Customer notes): bold titles, no rainbow */
.ord .lbl.gsec::after,.ord .sbx-h.gsec::after,.ord .fin-panel .panel-h h2::after,.ord .fees-notes .panel-h h2::after{display:none}
.ord .lbl.gsec,.ord .sbx-h.gsec,.ord .fin-panel .panel-h h2,.ord .fees-notes .panel-h h2{padding-bottom:0}
/* Customer supplied goods on the order page, reworked (Oct 15, Nick: "this box looks messy"): the status first, big and
   on the left; the progress; where it's coming from; the buttons in an even grid; no "View order" (you're on it) */
.ord .ed-aside .gc{gap:12px}
.ord .ed-aside .gc-h{display:flex;align-items:center;gap:8px}
.ord .ed-aside .gc-t{display:none}
.ord .ed-aside .gc-st{display:inline-flex;align-items:center;gap:8px;font-size:15px;font-weight:700;color:var(--gc,var(--ok))}
.ord .ed-aside .gc-st::before{content:"";width:9px;height:9px;border-radius:50%;background:currentColor;flex:none}
.ord .ed-aside .gc-steps{gap:3px}
.ord .ed-aside .gc-steps li{font-size:11px;gap:4px}
.ord .ed-aside .gc-steps li span{height:4px}
.ord .ed-aside .gc-from{font-size:13px;color:var(--ink-2);padding:8px 0 0;border-top:1px solid var(--line-2)}
.ord .ed-aside .gc-acts{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.ord .ed-aside .gc-acts .btn{width:100%;justify-content:center;margin:0}
.ord .ed-aside .gc-acts .btn:nth-last-of-type(1){grid-column:1/-1}
.ord .ed-aside .gc-acts .spacer{display:none}
.ord .ed-aside .gc-acts .gc-link{grid-column:1/-1;justify-self:start;font-size:12.5px}
.ord .ed-aside .gc-acts .gc-link:last-of-type{display:none}

/* ───────── Order check's "Ask about this order", like iPhone Messages (Oct 15, Nick) ─────────
   your messages in blue bubbles on the right, the AI's in grey on the left, suggestions as reply pills, a rounded
   message box with the mic and a round blue ↑ send inside it, three dots while the AI types */
.oc.ai-box{border:0;background:none;padding:0;gap:10px}
.oc h3{font-family:var(--body);font-size:12.5px;font-weight:600;color:var(--ink-3);text-align:center;margin:2px 0 0}
.oc .oc-list{gap:4px;max-height:460px;padding:2px 2px 4px}
.oc .oc-msg{position:relative;max-width:82%;padding:8px 13px;border-radius:19px;font-size:14px;line-height:1.35;gap:6px}
.oc .oc-msg.staff{align-self:flex-end;background:#0A84FF;color:#fff;border-bottom-right-radius:6px}
.oc .oc-msg.staff a{color:#fff;text-decoration:underline}
.oc .oc-msg.ai{align-self:flex-start;background:#E9E9EB;color:#111;border-bottom-left-radius:6px}
.oc .oc-msg.ai .muted,.oc .oc-msg.ai .faint{color:#555}
.oc .oc-msg + .oc-msg.staff:not(:has(+ .oc-msg.staff)),.oc .oc-msg.ai + .oc-msg.staff{margin-top:6px}
.oc .oc-msg.staff + .oc-msg.ai{margin-top:6px}
.oc .oc-msg .btn.sm{background:#fff;border-color:transparent;color:#0A84FF;font-weight:700;border-radius:999px}
.oc .eo-chips{display:flex;flex-direction:column;align-items:flex-end;gap:6px}
.oc .eo-chip{background:none;border:1.5px solid #0A84FF;color:#0A84FF;border-radius:999px;padding:6px 12px;font-size:13px;font-weight:600;text-align:right}
.oc .eo-chip:hover:not(:disabled){background:#0A84FF;color:#fff}
.oc-typing{align-self:flex-start;display:inline-flex;gap:4px;align-items:center;background:#E9E9EB;border-radius:19px;border-bottom-left-radius:6px;padding:11px 13px}
.oc-typing i{width:7px;height:7px;border-radius:50%;background:#8E8E93;animation:oc-dot 1.2s infinite ease-in-out}
.oc-typing i:nth-child(2){animation-delay:.15s}.oc-typing i:nth-child(3){animation-delay:.3s}
@keyframes oc-dot{0%,60%,100%{opacity:.35;transform:translateY(0)}30%{opacity:1;transform:translateY(-3px)}}
@media (prefers-reduced-motion:reduce){.oc-typing i{animation:none;opacity:.6}}
.oc .oc-form{display:flex;align-items:flex-end;gap:6px;border:1px solid #C7C7CC;border-radius:20px;padding:4px 4px 4px 12px;background:var(--surface)}
.oc .oc-form:focus-within{border-color:#0A84FF}
.oc .oc-form textarea{border:0;box-shadow:none;outline:none;resize:none;padding:6px 0;min-height:22px;max-height:140px;font-size:14px;line-height:1.35;background:none;field-sizing:content}
.oc .oc-form .mic.oc-mic{width:30px;height:30px;border:0;background:none;color:#8E8E93}
.oc .oc-form .mic.oc-mic.on{background:var(--fbs-salmon);color:#fff;border-radius:50%}
.oc-send{flex:none;width:30px;height:30px;border-radius:50%;border:0;background:#0A84FF;color:#fff;display:grid;place-items:center;cursor:pointer;padding:0}
.oc-send svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
.oc-send:disabled{background:#C7C7CC;cursor:default}
.oc .eo-chip{width:auto;max-width:88%;font-weight:500;text-align:left;line-height:1.3}
/* a print's screens on its own line in the print; the group's money in one line under the prints (Oct 15, Nick: "a big
   waste of vertical… incorporate the screens into the imprint lines, move the total up") */
.pr-scr{display:flex;flex-wrap:wrap;align-items:center;gap:4px 14px;font-size:13px;color:var(--ink-2);margin-top:2px}
.pr-scr-l{font-size:12px;font-weight:600;color:var(--ink-3)}
.pr-scr .check{font-size:13px;gap:5px}
.pr-scr .sbx-ub{display:inline-flex;align-items:center;gap:6px}
.imp-scr{padding:0 14px 10px}
.grp-sum{display:flex;flex-wrap:wrap;justify-content:flex-end;align-items:baseline;gap:4px 18px;padding:10px 0 2px;font-size:13px;color:var(--ink-3)}
.grp-sum b{color:var(--ink-2);font-weight:600;margin-left:3px}
.grp-sum-t{color:var(--ink);font-weight:600}
.grp-sum-t b{font-size:18px;font-weight:800;color:var(--ink);margin-left:6px}
/* the screens line: read, with a pencil to change underbase / remake (Oct 15, Nick) */
.pr-scr-v{display:inline-flex;align-items:center;gap:6px}
.pr-scr-tag{font-size:11.5px;font-weight:600;color:var(--ink-2);background:var(--surface-2);border-radius:999px;padding:1px 8px}
.pr-scr-ed{display:inline-grid;place-items:center;min-width:24px;height:24px;border:0;border-radius:6px;background:none;color:var(--ink-3);cursor:pointer;padding:0 4px;font:inherit;font-size:12.5px;font-weight:600}
.pr-scr-ed:hover{background:var(--surface-2);color:var(--accent)}
.pr-scr-ed.on{color:var(--accent)}
.pr-scr-ed svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.pr-scr-opts{display:inline-flex;flex-wrap:wrap;align-items:center;gap:4px 14px;padding:3px 10px;border-radius:8px;background:var(--surface-2)}
/* Order check: where the job stands in a few big bullets (Oct 15, Nick) */
.os-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:9px}
.os{display:flex;align-items:flex-start;gap:10px}
.os i{flex:none;width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font-style:normal;font-size:13px;font-weight:800;margin-top:1px}
.os.ok i{background:color-mix(in srgb,var(--ok) 14%,var(--surface));color:var(--ok)}
.os.wait i{background:color-mix(in srgb,var(--warn) 16%,var(--surface));color:var(--warn);font-size:18px;line-height:0}
.os.bad i{background:var(--danger-soft);color:var(--danger)}
.os.info i{background:var(--surface-2);color:var(--ink-3)}
.os span{display:flex;flex-direction:column;min-width:0}
.os b{font-size:14.5px;font-weight:700;color:var(--ink);line-height:1.3}
.os.info b{color:var(--ink-2);font-weight:600}
.os small{font-size:12px;color:var(--ink-3)}
.os-checks{margin-top:12px;padding-top:10px;border-top:1px solid var(--line-2)}
/* a group, tighter (Oct 15, Nick: "a lot of wasted space… especially vertically… more compressed") */
.ord .line-b{padding:12px 14px;gap:10px}
.ord .line-h{padding:7px 14px}
.ord .cs-banner{padding:5px 16px;font-size:14px}
.ord .gl-row.grp-total{border-top:1px solid var(--line-2);padding-top:6px;align-items:center}
.ord .gl-row.grp-total>.gl-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;overflow:visible;white-space:normal}
.ord .gl-adds{display:flex;gap:6px;flex-wrap:wrap}
.ord .imp-sec{padding-top:10px;gap:6px}
.ord .imp-wrap{grid-template-columns:150px minmax(0,1fr);gap:14px}
.ord .mk-big img{max-height:170px}
.ord .imp-mock{gap:5px}
.ord .imp-mock .btn{height:28px}
.ord .mk-when{font-size:11.5px}
.ord .pr{grid-template-columns:96px minmax(0,1fr);gap:14px;padding:10px 0}
.ord .pr-logo{width:96px;height:96px}
.ord .pr-main{gap:2px}
.ord .pr-notes{font-size:12px;line-height:1.4}
.ord .grp-sum{padding:6px 0 0}
/* (Oct 15, Nick) the mockup a bit bigger again; Customer and Job details tighter */
.ord .imp-wrap{grid-template-columns:185px minmax(0,1fr)}
.ord .mk-big img{max-height:215px}
.ord .top2 .panel-h{padding:9px 14px}
.ord .top2 .panel-b{padding:10px 14px 12px;gap:8px}
.ord .top2 .field{gap:3px}
.ord .top2 input:not([type=checkbox]),.ord .top2 select{height:34px;padding-top:4px;padding-bottom:4px}
.ord .jd-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px 12px;align-items:start}
.ord .jd-grid .check{font-size:12px!important;margin-top:2px!important}
@media (max-width:1100px){ .ord .jd-grid{grid-template-columns:repeat(2,minmax(0,1fr))} }
.ord .cust-row{padding:2px 0 0;gap:10px}
.ord .cust-card{gap:1px;font-size:12.5px;line-height:1.35}
.ord .cust-card .cc-co{font-size:14px}
.ord .cust-card .cc-extra{margin-top:3px;padding-top:3px}
.ord .pt-box .chip{padding:3px 10px;font-size:12px;min-height:0}
/* the Printavo box as a side panel on the Order tab (Oct 15, Nick) */
.pv-panel .panel-b{display:flex;flex-direction:column;gap:10px;padding:10px 14px 12px}
.pv-panel .pvs-strip{display:flex;flex-direction:column;align-items:stretch;gap:8px;margin:0;padding:0;border:0;background:none;font-size:13px;color:var(--ink-2)}
.pv-panel .pvs-strip>span:first-child{line-height:1.4}
.pv-panel .pvs-strip>span.row{display:grid!important;grid-template-columns:1fr 1fr;gap:6px!important}
.pv-panel .pvs-strip .btn{width:100%;justify-content:center}
.pv-panel .pvc{margin:0;padding:10px 0 0;border:0;border-top:1px solid var(--line-2);border-radius:0;background:none;font-size:13px}
.pv-panel .pvc>.row{flex-direction:column;align-items:stretch!important;gap:6px!important}
.pv-panel .pvc>.row>span.row{display:flex;flex-direction:column;align-items:stretch!important;gap:6px!important}
.pv-panel .pvc>.row .btn{width:100%;justify-content:center}
.pv-panel .pvc-list li{flex-direction:column;align-items:stretch}
/* Customer and Job details always the same height (Oct 15, Nick) */
.ord .top2{align-items:stretch}
.ord .top2>.panel{display:flex;flex-direction:column}
.ord .top2>.panel>.panel-b{flex:1}
/* the summary strip in the rainbow theme; the current tab stands out (Oct 15, Nick) */
.ord .ot-sum{position:relative;border:0;box-shadow:0 1px 3px rgba(20,29,43,.08),0 0 0 1px var(--line-2);padding-top:4px}
.ord .ot-sum::before{content:"";position:absolute;left:0;right:0;top:0;height:4px;background:var(--fbs-fade)}
.ord .ot-sum>div{border-left:0;position:relative}
.ord .ot-sum>div+div::before{content:"";position:absolute;left:0;top:12px;bottom:12px;width:1px;background:var(--line-2)}
.ord .ot-sum>div:nth-child(5n+1) span{color:var(--fbs-blue)}
.ord .ot-sum>div:nth-child(5n+2) span{color:color-mix(in srgb,var(--fbs-salmon) 85%,#000)}
.ord .ot-sum>div:nth-child(5n+3) span{color:color-mix(in srgb,var(--fbs-orange) 70%,#000)}
.ord .ot-sum>div:nth-child(5n+4) span{color:var(--fbs-blue)}
