.ph-st b{color:var(--ink)}
.ph-login{font-size:12px}
.ph-note{white-space:pre-line;background:var(--surface-2);border-radius:8px;padding:7px 10px;margin-top:3px}
.ph-own{display:flex;align-items:center;gap:8px;margin-top:4px;flex-wrap:wrap}
.ph-own span{font-size:12px;color:var(--ink-3)}
.ph-own img{width:64px;height:64px;object-fit:contain;border:1px solid var(--line);border-radius:8px;background:#fff}
.ph-acts{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:6px}
.ph-q{font-size:12.5px;color:var(--ink-2)}

/* ---------- the customer's dashboard (Oct 15, Nick): assistant + message center, needs you, jobs on a timeline ---------- */
.pdx{display:flex;flex-direction:column;gap:18px}
.pdx-hello{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap}
.pdx-h1{margin:0;font-family:var(--display);font-stretch:85%;font-weight:800;font-size:30px;line-height:1.1;display:inline-block;position:relative;padding-bottom:6px}
.pdx-h1::after{content:"";position:absolute;left:0;bottom:-2px;height:4px;border-radius:4px;width:calc(100% + 60px);background:var(--fbs-fade)}
.pdx-sub{color:var(--ink-3);margin-top:10px;font-size:14px}
.pdx-acts{display:flex;gap:8px;flex-wrap:wrap}
.pdx-card{background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 18px}
.pdx-h{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:12px}
.pdx-h h2{margin:0;font-family:var(--display);font-stretch:85%;font-weight:700;font-size:16px;position:relative;padding-bottom:5px;width:fit-content}
.pdx-h h2::after{content:"";position:absolute;left:0;bottom:0;height:4px;border-radius:4px;width:calc(100% + 36px);min-width:72px;background:var(--fbs-fade)}
.pdx-h .faint{font-size:12.5px}
.pdx-none{color:var(--ink-3);font-size:13.5px;padding:6px 0}
.pdx-top{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);gap:18px;align-items:stretch}
.pdx-asst .pa-bare{padding:0;background:none;border:0;box-shadow:none}
.pdx-asst .pa-in{border:1.5px solid var(--fbs-blue);border-radius:12px;box-shadow:0 0 0 4px color-mix(in srgb,var(--fbs-blue) 9%,transparent)}
.pdx-asst .pa-in input{font-size:15px}
.pdx-asst .pa-ideas{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px;overflow:visible}
.pdx-asst .pa-ideas button,.pdx-asst .pa-person{font-size:12.5px;border:1px solid var(--line);border-radius:999px;padding:5px 11px;background:var(--surface);color:var(--ink-2);flex:0 1 auto;max-width:none;white-space:nowrap;overflow:visible}
.pdx-asst .pa-person{color:#0a7fb3;border-color:#cfe6f3;font-weight:700;text-decoration:none}
.pdx-asst .pa-talk{max-height:300px}
.pdx-badge{background:var(--fbs-salmon);color:#fff;border-radius:999px;padding:2px 9px;font-size:12px;font-weight:700}
.pdx-th{display:grid;grid-template-columns:44px minmax(0,1fr) auto;gap:10px;align-items:center;padding:9px 0;border-top:1px solid var(--line-2,var(--line));text-decoration:none;color:inherit}
.pdx-th:first-of-type{border-top:0;padding-top:0}
.pdx-ti{width:44px;height:44px;border-radius:10px;background:var(--surface-2);display:grid;place-items:center;font-size:10.5px;font-family:var(--mono);color:var(--ink-2)}
.pdx-ti.g{background:#141D2B;color:#fff;font-family:var(--body);font-weight:800}
.pdx-tt{display:flex;flex-direction:column;min-width:0}
.pdx-tt b{font-size:13.5px}
.pdx-tt small{font-size:12.5px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pdx-tw{font-size:11.5px;color:var(--ink-3)}
.pdx-th.new .pdx-ti{box-shadow:0 0 0 2px var(--fbs-salmon)}
.pdx-th.new small{color:var(--ink-2);font-weight:600}
.pdx-note{margin-top:10px;font-size:12.5px;color:var(--ink-2);background:var(--surface-2);border-radius:10px;padding:9px 11px;line-height:1.4}
.pdx-mc{display:flex;gap:8px;margin-top:10px}
.pdx-mc .btn{flex:1;justify-content:center;text-align:center}
.pdx-needs{display:flex;flex-direction:column;gap:10px}
.pdx-need{display:grid;grid-template-columns:96px minmax(0,1fr) auto;gap:16px;align-items:center;border:1.5px solid #f4c46b;background:#fffaf0;border-radius:12px;padding:10px 14px}
.pdx-need img,.pdx-need-ic{width:96px;height:86px;object-fit:contain;background:#fff;border-radius:10px;border:1px solid var(--line-2,var(--line));display:grid;place-items:center;font-size:28px;color:#a76a00}
.pdx-need .k{font-size:12px;font-weight:700;color:#a76a00;text-transform:uppercase;letter-spacing:.05em}
.pdx-need .t{font-size:15px;margin-top:3px;color:var(--ink)}
.pdx-job{display:grid;grid-template-columns:170px minmax(0,1fr) auto;gap:20px;padding:16px 0;border-top:1px solid var(--line-2,var(--line))}
.pdx-h + .pdx-job,.pdx-h + .pdx-none + .pdx-job{border-top:0;padding-top:4px}
.pdx-pic{position:relative;display:block;width:170px;height:170px;border:1px solid var(--line-2,var(--line));border-radius:14px;background:#fafbfc;overflow:hidden}
.pdx-pic img{position:absolute;inset:6px;width:calc(100% - 12px);height:calc(100% - 12px);object-fit:contain}
.pdx-nopic{position:absolute;inset:0;display:grid;place-items:center;font-family:var(--mono);color:var(--ink-3)}
.pdx-job.quiet{grid-template-columns:110px minmax(0,1fr) auto;align-items:center}
.pdx-job.quiet .pdx-pic{width:110px;height:110px}
.pdx-due{position:absolute;left:8px;top:8px;background:#141D2B;color:#fff;border-radius:8px;padding:4px 8px;font-size:10px;line-height:1.25;text-transform:uppercase;letter-spacing:.04em;display:flex;flex-direction:column}
.pdx-due b{font-size:12.5px;letter-spacing:0}
.pdx-due.done{background:var(--ok)}
.pdx-jt{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap}
.pdx-jt .n{font-family:var(--mono);font-size:12px;color:var(--ink-3)}
.pdx-jt .t{font-family:var(--display);font-stretch:85%;font-weight:800;font-size:22px;color:var(--ink);text-decoration:none}
.pdx-pill{border-radius:999px;padding:2px 10px;font-size:12px;font-weight:700}
.pdx-pill.wait{background:#fff1d6;color:#8a5a00}.pdx-pill.ok{background:#e3f4ea;color:var(--ok)}.pdx-pill.info{background:#e6f4fb;color:#0a6f9c}
.pdx-js{color:var(--ink-2);margin-top:4px;font-size:13.5px}
.pdx-tl{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));margin-top:16px;position:relative}
.pdx-tl::before,.pdx-tl::after{content:"";position:absolute;left:8.33%;top:17px;height:4px;border-radius:4px}
.pdx-tl::before{right:8.33%;background:#e6e9ee}
.pdx-tl::after{width:calc((100% - 16.66%) * var(--fill) / 100);background:var(--fbs-fade);z-index:0}
.pdx-tl.small{max-width:420px;margin-top:10px}
.pdx-tl.small::before,.pdx-tl.small::after{top:12px}
.pdx-st{display:flex;flex-direction:column;align-items:center;text-align:center;gap:2px;position:relative;z-index:1;min-width:0}
.pdx-st i{font-style:normal;width:38px;height:38px;border-radius:50%;display:grid;place-items:center;background:var(--surface);border:2px solid var(--line);font-size:15px;color:var(--ink-3)}
.pdx-tl.small .pdx-st i{width:28px;height:28px;font-size:12px}
.pdx-st b{font-size:12.5px;margin-top:4px}
.pdx-st small{font-size:11.5px;color:var(--ink-3)}
.pdx-st.done i{background:var(--ok);border-color:var(--ok);color:#fff;font-weight:800}
.pdx-st.cur i{background:#fff6e5;border:3px solid var(--fbs-orange);color:#a76a00;box-shadow:0 0 0 5px color-mix(in srgb,var(--fbs-orange) 22%,transparent)}
.pdx-st.cur b{color:#a76a00}
.pdx-now{margin-top:14px;background:var(--surface-2);border-radius:10px;padding:9px 12px;color:var(--ink-2);font-size:13.5px}
.pdx-now b{color:var(--ink)}
.pdx-go{font-weight:700;color:#0a7fb3;margin-left:4px}
.pdx-jmsg{display:block;margin-top:8px;font-size:13px;color:var(--ink-2);text-decoration:none}
.pdx-jmsg span{color:#0a7fb3;font-weight:700;margin-left:4px}
.pdx-jr{align-self:center}
.pdx-done{font-size:12.5px;color:var(--ok)}
.pdx-bottom{display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:18px;align-items:start}
.pdx-again{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.pdx-ag{border:1px solid var(--line-2,var(--line));border-radius:12px;padding:10px;display:flex;flex-direction:column;gap:5px;min-width:0}
.pdx-ag-pic{position:relative;display:block;height:120px;background:#fafbfc;border-radius:8px;overflow:hidden}
.pdx-ag-pic img{position:absolute;inset:4px;width:calc(100% - 8px);height:calc(100% - 8px);object-fit:contain}
.pdx-ag-pic span{position:absolute;inset:0;display:grid;place-items:center;font-family:var(--mono);color:var(--ink-3)}
.pdx-ag b{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pdx-ag small{color:var(--ink-3);font-size:12px}
.pdx-ag .btn{align-self:flex-start}
.pdx-art{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px}
.pdx-art a{position:relative;aspect-ratio:1;border:1px solid var(--line-2,var(--line));border-radius:10px;background:#fff;overflow:hidden;display:grid;place-items:center;text-decoration:none}
.pdx-art img{position:absolute;inset:8%;width:84%;height:84%;object-fit:contain}
.pdx-art a.add{border-style:dashed;color:#0a7fb3;font-weight:700;font-size:12px;text-align:center;background:#fafcfe}
.pdx-kv{display:flex;justify-content:space-between;gap:10px;padding:8px 0;border-top:1px solid var(--line-2,var(--line));font-size:13.5px}
.pdx-kv:nth-child(2){border-top:0}
.pdx-kv span{color:var(--ink-2)}
.pdx-kv b{text-align:right}
.pdx-kv b.ok{color:var(--ok)}.pdx-kv b.bad{color:var(--danger)}
@media (max-width:900px){
  .pdx-top,.pdx-bottom{grid-template-columns:minmax(0,1fr)}
  .pdx-job,.pdx-job.quiet{grid-template-columns:96px minmax(0,1fr)}
  .pdx-pic,.pdx-job.quiet .pdx-pic{width:96px;height:96px}
  .pdx-due{font-size:8.5px;padding:3px 5px}.pdx-due b{font-size:10.5px}
  .pdx-tl{grid-column:1 / -1}
  .pdx-jb{display:contents}
  .pdx-jt,.pdx-js{grid-column:2}
  .pdx-now,.pdx-jmsg,.pdx-tl{grid-column:1 / -1}
  .pdx-jr{grid-column:1 / -1;justify-self:start}
  .pdx-st b{font-size:11px}.pdx-st small{font-size:10.5px}
  .pdx-st i{width:30px;height:30px;font-size:13px}
  .pdx-tl::before,.pdx-tl::after{top:13px}
  .pdx-need{grid-template-columns:64px minmax(0,1fr)}
  .pdx-need img,.pdx-need-ic{width:64px;height:60px}
  .pdx-need .btn{grid-column:1 / -1}
  .pdx-again{grid-template-columns:repeat(2,minmax(0,1fr))}
  .pdx-art{grid-template-columns:repeat(4,minmax(0,1fr))}
  .pdx-jt .t{font-size:18px}
}

.p-main > .pdx-hello{margin-bottom:16px}
/* portal Orders: Quotes then Orders under one search line */
.aa-sec-h.aa-sec-pad{padding:16px 4px 6px;display:flex;align-items:baseline;gap:10px}
.aa-oldq{margin-left:auto;font-size:12.5px;color:var(--ink-2);font-weight:400}
.aa-none-q{padding:8px 4px 4px;font-size:13px}

/* portal Payments on a phone: the AI payment helper (and pay box) comes before the payment history (Oct 15, Nick) */
@media (max-width:900px){
  .aa-home.aa-paylay{display:flex!important;flex-direction:column;gap:14px}
  .aa-paylay > .aa-home-main{display:contents}
  .aa-paylay > .aa-payside{order:2}
  .aa-paylay .aa-ph-card{order:3}
}
/* the little rainbow under section titles runs a bit past the words, like everywhere else (Oct 15, Nick) */
.portal .aa-sec-h h3{width:fit-content}
.portal .aa-sec-h h3::after{width:calc(100% + 36px);min-width:72px;height:4px;border-radius:4px}

/* customer supplied goods in the portal: full-width cards in the portal's style (Oct 15, Nick) */
.portal .gb{display:flex;flex-direction:column;gap:14px}
.portal .gc{border:1px solid var(--line);border-radius:14px;padding:16px 18px;gap:12px;position:relative;overflow:hidden}
.portal .gc::before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--gc)}
.portal .gc-t b{font-family:var(--display);font-stretch:85%;font-weight:800;font-size:22px;line-height:1.15}
.portal .gc-no{font-family:var(--mono);font-size:12px;color:var(--ink-3)}
.portal .gc-sub{font-size:13.5px;color:var(--ink-2);margin-top:2px}
.portal .gc-st{font-size:12.5px}
.portal .gc-steps{gap:8px;margin-top:2px}
.portal .gc-steps li{font-size:12.5px;gap:7px}
.portal .gc-steps li span{height:7px}
.portal .gc-steps li.done span{background:var(--ok)}
.portal .gc-steps li.now span{background:var(--fbs-fade)}
.portal .gc-help{font-size:14px;background:var(--surface-2);border-radius:10px;padding:9px 12px}
.portal .gc-from{font-size:13.5px}
.portal .gc-acts{border-top:1px solid var(--line-2,var(--line));padding-top:12px}

/* account order tables (customer page and portal): the order name gets real room, long Printavo statuses wrap
   instead of squeezing it to a letter per line, the Archived tag stays on one line (Oct 15, Nick) */
.aa-tbl td.m{min-width:190px}
.aa-tbl td.m .aa-t{word-break:normal;overflow-wrap:break-word}
.aa-tbl .aa-arch{white-space:nowrap;display:inline-block;margin-left:6px;vertical-align:1px}
.aa-tbl .aa-pill{white-space:normal;max-width:210px;display:inline-block;line-height:1.3}
.aa-tbl td.dt{white-space:nowrap}
/* …and the words never break letter by letter; beside the attention panel the table drops Paid (Total − Balance) and
   tightens so everything fits without scrolling */
.aa-tbl td,.aa-tbl th{word-break:normal;overflow-wrap:normal}
.aa-tbl .aa-pill{min-width:120px;overflow-wrap:break-word}
.aa-home-main .aa-tbl{min-width:0}
.aa-home-main .aa-tbl .paid{display:none}
.aa-home-main .aa-tbl td,.aa-home-main .aa-tbl th{padding:10px 8px}
.aa-home-main .aa-tbl td.m{min-width:160px}

/* Your jobs: Screen printing / Embroidery tabs, and one row per job when there are many (Oct 15, Nick) */
.pdx-count{font-family:var(--body);font-stretch:100%;font-weight:600;font-size:12.5px;color:var(--ink-3);margin-left:10px}
.pdx-ktabs{display:flex;gap:6px;flex-wrap:wrap;margin:-2px 0 12px}
.pdx-ktabs button{font:inherit;font-size:13px;font-weight:700;border:1px solid var(--line);background:var(--surface);color:var(--ink-2);border-radius:999px;padding:6px 12px;display:inline-flex;align-items:center;gap:6px;cursor:pointer}
.pdx-ktabs button span{background:var(--surface-2);color:var(--ink-3);border-radius:999px;padding:0 7px;font-size:11.5px}
.pdx-ktabs button.on{background:color-mix(in srgb,var(--fbs-blue) 10%,var(--surface));border-color:var(--fbs-blue);color:#0a6f9c}
.pdx-ktabs button.on span{background:var(--fbs-blue);color:#fff}
.pdx-rows{display:flex;flex-direction:column}
.pdx-row{display:grid;grid-template-columns:56px minmax(0,1fr) 230px 92px 150px;gap:14px;align-items:center;padding:10px 4px;border-top:1px solid var(--line-2,var(--line));text-decoration:none;color:inherit}
.pdx-row:first-child{border-top:0}
.pdx-row:hover{background:var(--surface-2)}
.pdx-rpic{position:relative;width:56px;height:56px;border:1px solid var(--line-2,var(--line));border-radius:10px;background:#fafbfc;overflow:hidden;display:grid;place-items:center;font-family:var(--mono);font-size:10px;color:var(--ink-3)}
.pdx-rpic img{position:absolute;inset:3px;width:calc(100% - 6px);height:calc(100% - 6px);object-fit:contain}
.pdx-rt{display:flex;flex-direction:column;min-width:0}
.pdx-rt small{font-family:var(--mono);font-size:11px;color:var(--ink-3)}
.pdx-rt b{font-size:14.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pdx-rt em{font-style:normal;font-size:12px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pdx-rtl{display:flex;align-items:center;gap:3px;flex-wrap:wrap}
.pdx-rtl i{font-style:normal;width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font-size:10px;border:1.5px solid var(--line);background:var(--surface);color:var(--ink-3)}
.pdx-rtl i.done{background:var(--ok);border-color:var(--ok);color:#fff;font-weight:800}
.pdx-rtl i.cur{border:2px solid var(--fbs-orange);background:#fff6e5;color:#a76a00;box-shadow:0 0 0 3px color-mix(in srgb,var(--fbs-orange) 20%,transparent)}
.pdx-rtl small{flex-basis:100%;font-size:11.5px;color:var(--ink-2);font-weight:600;margin-top:2px}
.pdx-rdue{display:flex;flex-direction:column;font-size:12.5px}
.pdx-rdue small{font-size:10.5px;text-transform:uppercase;letter-spacing:.04em;color:var(--ink-3)}
.pdx-row .pdx-pill{justify-self:end;text-align:center}
.pdx-more{margin-top:8px;align-self:center;font:inherit;font-weight:700;font-size:13px;color:#0a7fb3;background:none;border:1px solid var(--line);border-radius:999px;padding:6px 14px;cursor:pointer}
@media (max-width:900px){
  .pdx-row{grid-template-columns:48px minmax(0,1fr) auto;row-gap:6px}
  .pdx-rpic{width:48px;height:48px}
  .pdx-rtl{grid-column:2 / -1}
  .pdx-rdue{display:none}
  .pdx-row .pdx-pill{grid-row:1;grid-column:3}
}
.aa-paidup{background:#e9f6ef;border:1px solid #bfe3cd;border-radius:12px;padding:12px 14px;color:var(--ink-2)}
.aa-paidup b{color:var(--ok);margin-right:4px}
.aa-more-row{display:flex;justify-content:center;padding:10px}
/* old Printavo order page: the date labels (Created, Invoice date, Production due…) stay whole words, not a letter per line (Oct 15, Nick) */
.pv-info .pv-dates dt{white-space:nowrap;overflow-wrap:normal}
/* …and the long values (a PO like "RUSH AOC A73269_IPEA Tee") wrap inside the dates column instead of running out of the box */
.pv-info .pv-dates dd{white-space:normal;overflow-wrap:anywhere}
@media (min-width:900px){ .pv-info{grid-template-columns:repeat(3,minmax(0,1fr)) minmax(240px,1.35fr)} }
.aa-pvnote{margin:10px 16px 6px;background:#fff6e5;border:1px solid #f4d9a6;color:#6b4a00;border-radius:10px;padding:9px 12px;font-size:13px;line-height:1.4}
.aa-pvnote b{color:#4d3500}

/* dashboard Payments box (Oct 15, Nick: payments get their own box, not a "Needs you" item) */
.pdx-bottom{grid-template-columns:minmax(0,1fr)}
.pdx-pay-row{display:flex;align-items:stretch;gap:14px;flex-wrap:wrap}
.pdx-pay-big{display:flex;flex-direction:column;justify-content:center;min-width:180px;padding:12px 16px;border-radius:12px;background:var(--surface-2)}
.pdx-pay-big small{font-size:11.5px;text-transform:uppercase;letter-spacing:.05em;color:var(--ink-3);font-weight:700}
.pdx-pay-big b{font-family:var(--display);font-stretch:85%;font-weight:800;font-size:30px;line-height:1.1}
.pdx-pay-big.owe b{color:var(--danger)}
.pdx-pay-big.ok{background:#e9f6ef}.pdx-pay-big.ok b{color:var(--ok)}
.pdx-pay-big span{font-size:12.5px;color:var(--ok);font-weight:700}
.pdx-pay-parts{display:flex;gap:10px;flex-wrap:wrap}
.pdx-pay-parts > div{display:flex;flex-direction:column;justify-content:center;padding:10px 14px;border:1px solid var(--line-2,var(--line));border-radius:12px;min-width:150px}
.pdx-pay-parts span{font-size:12px;color:var(--ink-3);font-weight:700}
.pdx-pay-parts b{font-size:18px}
.pdx-pay-parts small{font-size:11.5px;color:var(--ink-3)}
.pdx-pay-parts .late{border-color:#f3c3c0;background:#fdf1f0}.pdx-pay-parts .late b{color:var(--danger)}
.pdx-pay-meta{display:flex;flex-direction:column;justify-content:center;gap:6px;font-size:13px;min-width:200px;flex:1}
.pdx-pay-meta div{display:flex;justify-content:space-between;gap:10px}
.pdx-pay-meta span{color:var(--ink-3)}
.pdx-pay-acts{display:flex;flex-direction:column;justify-content:center;gap:8px}
.pdx-pay-acts .btn{justify-content:center;text-align:center}
@media (max-width:900px){ .pdx-pay-big,.pdx-pay-parts > div{flex:1} .pdx-pay-acts{flex-direction:row;width:100%} .pdx-pay-acts .btn{flex:1} }

/* Your jobs, one useful row per job (Oct 15, Nick: "if they're waiting to approve a proof, it should say click here to
   approve proof… if it ships, tracking… flesh out the little symbols"): labeled steps with real icons, a line that says
   what's happening, and the one thing they can do next */
.pdx-st i svg{width:18px;height:18px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.pdx-tl.small .pdx-st i svg{width:14px;height:14px}
.pjf{display:flex;justify-content:space-between;gap:8px 12px;flex-wrap:wrap;margin:-2px 0 6px}
.pjf .pdx-ktabs{margin:0}
.pdx-ktabs button.need{border-color:#f4c46b;background:#fff7e8;color:#8a5a00}
.pdx-ktabs button.need span{background:#f0a500;color:#fff}
.pdx-ktabs button.need.on{box-shadow:0 0 0 2px #f4c46b}
.pjr-list{display:flex;flex-direction:column}
.pjr{display:grid;grid-template-columns:64px minmax(0,1.2fr) minmax(0,1.6fr) 220px;gap:16px;align-items:center;padding:14px 4px;border-top:1px solid var(--line-2,var(--line))}
.pjr:first-child{border-top:0}
.pjr-pic{position:relative;width:64px;height:64px;border:1px solid var(--line-2,var(--line));border-radius:10px;background:#fafbfc;overflow:hidden;display:grid;place-items:center;font-family:var(--mono);font-size:10px;color:var(--ink-3);text-decoration:none}
.pjr-pic img{position:absolute;inset:3px;width:calc(100% - 6px);height:calc(100% - 6px);object-fit:contain}
.pjr-t{display:flex;flex-direction:column;min-width:0;text-decoration:none;color:inherit}
.pjr-t small{font-family:var(--mono);font-size:11px;color:var(--ink-3)}
.pjr-t b{font-size:15px;line-height:1.2;margin-top:1px;overflow:hidden;text-overflow:ellipsis;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
.pjr-t em{font-style:normal;font-size:12.5px;color:var(--ink-3);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pjr-t:hover b{color:#0a7fb3}
.pjs{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));position:relative}
.pjs::before,.pjs::after{content:"";position:absolute;left:8.33%;top:13px;height:3px;border-radius:3px}
.pjs::before{right:8.33%;background:#e6e9ee}
.pjs::after{width:calc((100% - 16.66%) * var(--fill) / 100);background:var(--fbs-fade)}
.pjs-st{display:flex;flex-direction:column;align-items:center;gap:3px;position:relative;z-index:1;min-width:0}
.pjs-st i{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:var(--surface);border:2px solid #cfd5de;color:#8a93a3}
.pjs-st i svg{width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.pjs-st b{font-size:10.5px;font-weight:600;color:var(--ink-3);white-space:nowrap;max-width:100%;overflow:hidden;text-overflow:ellipsis}
.pjs-st.done i{background:var(--ok);border-color:var(--ok);color:#fff}
.pjs-st.done b{color:var(--ink-2)}
.pjs-st.cur i{background:#fff6e5;border:2.5px solid var(--fbs-orange);color:#a76a00;box-shadow:0 0 0 4px color-mix(in srgb,var(--fbs-orange) 22%,transparent)}
.pjs-st.cur b{color:#a76a00;font-weight:800}
.pjr-now{font-size:12.5px;color:var(--ink-2);margin-top:7px;text-align:center}
.pjr-now b{color:var(--ink)}
.pjr-act{display:flex;flex-direction:column;gap:5px;align-items:stretch;min-width:0}
.pjr-btn{font-weight:700;border-radius:9px;padding:8px 12px;white-space:normal;text-align:center;line-height:1.2}
.pjr-btn.need{background:#f0a500;border-color:#f0a500;color:#fff}
.pjr-btn.need:hover{background:#d99500;border-color:#d99500}
.pjr-btn.go{background:var(--fbs-blue);border-color:var(--fbs-blue);color:#fff}
.pjr-btn.ok{background:var(--ok);border-color:var(--ok);color:#fff}
.pjr-sub{font-size:12px;color:var(--ink-3);text-align:center;overflow-wrap:anywhere}
.pjr-owe{font-size:12px;text-align:center;color:#b3261e;font-weight:700;text-decoration:none}
.pjr-msg{font-size:12px;text-align:center;color:#0a7fb3;font-weight:700;text-decoration:none}
.pjr-owe:hover,.pjr-msg:hover{text-decoration:underline}
@media (max-width:1100px){ .pjr{grid-template-columns:56px minmax(0,1fr) 200px} .pjr-mid{grid-column:2 / -1;grid-row:2} .pjr-pic{width:56px;height:56px} }
@media (max-width:640px){
  .pjr{grid-template-columns:52px minmax(0,1fr);gap:10px 12px}
  .pjr-pic{width:52px;height:52px}
  .pjr-mid{grid-column:1 / -1;grid-row:auto}
  .pjr-act{grid-column:1 / -1}
  .pjs-st b{font-size:9.5px}
  .pjf{flex-direction:column}
}

/* Time Clock → Settings: the ZKTeco face clock (Oct 16) */
