/* a logo on shirt colors: the portfolio views (Oct 16, Nick) */
.lv{position:relative;display:inline-block;border-radius:8px;overflow:hidden;flex:none;border:1px solid rgba(0,0,0,.08)}
.lv-art{position:absolute;inset:12%;-webkit-mask-size:contain;mask-size:contain;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat;-webkit-mask-position:center;mask-position:center}
