/* Apple Messages look (Oct 16, Nick) */
.im{--im-blue:#0a84ff;--im-gray:#e9e9eb;--im-bg:#fff;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","Helvetica Neue",system-ui,sans-serif;background:var(--im-bg);border:1px solid #e5e5ea;border-radius:16px;display:flex;flex-direction:column;max-height:78vh;position:sticky;top:12px;min-width:0;overflow:hidden;box-shadow:0 1px 3px rgba(0,0,0,.06)}
.im-h{display:flex;align-items:center;gap:10px;padding:10px 14px;background:rgba(246,246,248,.92);border-bottom:1px solid #e5e5ea}
.im-av{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(180deg,#a4a9b6,#868b97);color:#fff;font-size:14px;flex:none}
.im-who{display:flex;flex-direction:column;line-height:1.2;min-width:0}
.im-who b{font-size:13.5px;font-weight:600}
.im-who small{font-size:11.5px;color:#8e8e93;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.im-done{margin-left:auto;border:0;background:none;color:var(--im-blue);font-size:14px;font-weight:600;cursor:pointer;padding:4px}
.im-msgs{flex:1;overflow:auto;padding:12px 14px 14px;display:flex;flex-direction:column;gap:2px;min-height:220px}
.im-grp{display:flex;flex-direction:column;gap:3px}
.im-time{align-self:center;font-size:11px;color:#8e8e93;margin:10px 0 4px;font-weight:500}
.im-row{display:flex;align-items:flex-end;gap:6px;margin-top:3px}
.im-row.me{justify-content:flex-end}
.im-row.them{justify-content:flex-start;flex-wrap:wrap}
.im-b{position:relative;max-width:78%;padding:7px 12px;border-radius:18px;font-size:14px;line-height:1.35;white-space:pre-wrap;overflow-wrap:anywhere}
.im-b.me{background:var(--im-blue);color:#fff;margin-right:6px}
.im-b.them{background:var(--im-gray);color:#000;margin-left:6px}
.im-b.me::before,.im-b.them::before{content:"";position:absolute;bottom:0;height:18px;width:20px}
.im-b.me::before{right:-7px;background:var(--im-blue);border-bottom-left-radius:16px 14px}
.im-b.them::before{left:-7px;background:var(--im-gray);border-bottom-right-radius:16px 14px}
.im-b.me::after,.im-b.them::after{content:"";position:absolute;bottom:0;height:18px;width:26px;background:var(--im-bg)}
.im-b.me::after{right:-26px;border-bottom-left-radius:10px}
.im-b.them::after{left:-26px;border-bottom-right-radius:10px}
.im-by{font-size:10.5px;color:#8e8e93;text-align:right;margin:1px 12px 0 0}
.im-file{display:flex;gap:6px;align-items:center;max-width:78%;background:#f2f2f7;border:1px solid #e5e5ea;border-radius:14px;padding:8px 12px;font-size:13px;margin-right:6px}
.im-file span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.im-card{max-width:92%;margin-left:6px;background:#fff;border:1px solid #e5e5ea;border-radius:16px;overflow:hidden;font-size:13px;box-shadow:0 1px 2px rgba(0,0,0,.05)}
.im-card.dismissed{opacity:.6}
.im-card-h{padding:8px 12px;font-weight:600;font-size:12.5px;background:#f6f6f8;border-bottom:1px solid #ececf0}
.im-card.applied .im-card-h{color:#248a3d}
.im-line{display:flex;gap:6px;align-items:baseline;padding:4px 12px;border-bottom:1px solid #f2f2f5}
.im-line .op{width:12px;font-weight:700;flex:none;text-align:center}
.im-line .op.add{color:#248a3d}.im-line .op.chg{color:#c27c0e}.im-line .op.del{color:#d70015}
.im-line .what{color:#8e8e93;width:78px;flex:none;font-size:12px}
.im-line .txt{min-width:0}
.im-line .dot{display:inline-block;width:11px;height:11px;border-radius:3px;border:1px solid rgba(0,0,0,.18);margin-right:5px;vertical-align:-1px}
.im-acts{display:flex}
.im-acts button{flex:1;border:0;background:none;padding:10px;font-size:14px;cursor:pointer}
.im-apply{color:var(--im-blue);font-weight:600;border-right:1px solid #ececf0 !important}
.im-later{color:#8e8e93}
.im-acts button:hover{background:#f6f6f8}
.im-card-f{padding:7px 12px;font-size:11.5px;color:#8e8e93}
.im-b.typing{display:inline-flex;gap:4px;padding:11px 13px}
.im-b.typing i{width:7px;height:7px;border-radius:50%;background:#8e8e93;animation:im-dot 1.2s infinite ease-in-out}
.im-b.typing i:nth-child(2){animation-delay:.15s}.im-b.typing i:nth-child(3){animation-delay:.3s}
@keyframes im-dot{0%,60%,100%{opacity:.35;transform:translateY(0)}30%{opacity:1;transform:translateY(-2px)}}
@media (prefers-reduced-motion:reduce){.im-b.typing i{animation:none}}
.im-note{font-size:11px;color:#8e8e93;margin-left:6px}
.im-err{margin:0 14px 6px;font-size:12.5px;color:#d70015}
.im-staged{display:flex;flex-wrap:wrap;gap:6px;padding:6px 14px 0;font-size:12px}
.im-staged span{display:inline-flex;gap:4px;align-items:center;background:#f2f2f7;border-radius:10px;padding:3px 4px 3px 8px}
.im-staged button{border:0;background:none;cursor:pointer;color:#8e8e93}
.im-in{display:flex;gap:8px;align-items:flex-end;padding:8px 12px 10px;border-top:1px solid #f0f0f3}
.im-plus{width:32px;height:32px;border-radius:50%;background:#e9e9eb;color:#6c6c70;display:grid;place-items:center;font-size:20px;line-height:1;cursor:pointer;flex:none}
.im-field{flex:1;min-width:0;display:flex;align-items:flex-end;border:1px solid #d1d1d6;border-radius:18px;padding:3px 3px 3px 12px;background:#fff}
