.sg-pic{width:44px;height:44px;border-radius:6px;background:var(--surface-2);display:grid;place-items:center;overflow:hidden;flex:none;text-decoration:none;color:var(--ink-3);font-size:10px;font-weight:700;border:1px solid var(--line)}
