/* portal: the program price grid, read only (Oct 17) */
.prc{display:grid;grid-template-columns:minmax(0,auto) minmax(240px,1fr);gap:18px 28px;align-items:start;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px 18px;margin:0 0 16px}
