.prc-side{display:flex;flex-direction:column;gap:12px}
.prc-blk{border:1px solid var(--line);border-radius:12px;padding:12px 14px}
.prc-blk h4{margin:0 0 8px;font-size:12px;font-weight:700;color:var(--ink-3);text-transform:none}
