.prc-tabs{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 10px}.prc-tabs .chip.on{background:var(--accent);border-color:var(--accent);color:#fff}
.pga-match label{font-size:12px}
.rc-xp{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--ink-2);border:1px solid var(--line);border-radius:8px;padding:3px 6px 3px 9px}
