/* one at a time (Oct 23): the made ones ticked with their number, the next one picked out */
.osp-plan li.made b{color:var(--ink-3);font-weight:600}
.osp-plan li.next b{color:var(--accent)}
.osp-made{color:var(--ok);font-weight:700;white-space:nowrap;text-decoration:none}
.osp-made:hover{text-decoration:underline}
.osp-plan-acts{display:flex;flex-wrap:wrap;gap:8px}
.orv-nextq{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}
.osp-sugg{width:100%;margin-bottom:12px}
.eo-parts{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 8px}
.eo-parts .chip.done{border-color:var(--ok);color:var(--ok)}
.osp-ready{border-color:var(--ok)!important;box-shadow:inset 0 0 0 1px var(--ok)!important}
.osp-ready b{color:var(--ok)}
/* Create order: what the AI remembers about the customer (Oct 20) */
.eo-remember{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--ink-2);margin:4px 0}
.eo-mem{margin:6px 0;font-size:12.5px}
.eo-mem summary{cursor:pointer;color:var(--ink-2);font-weight:600}
.eo-mem ul{margin:6px 0 0;padding-left:18px;display:flex;flex-direction:column;gap:4px}
.eo-mem li span.faint{margin:0 8px;font-size:11.5px}
/* Create order: a wholesale reorder offers the reprint screen fee (Oct 20) */
.eo-fee{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:6px 0 8px;padding:10px 12px;border-radius:10px;border:1px solid #E8C468;background:#FFF8E5;font-size:13px}
.eo-fee span{flex:1 1 300px}
/* After sending: Archive counts down 5 seconds and archives by itself (Oct 20) */
.as-arch{position:relative;overflow:hidden;min-width:118px}
.as-arch.counting{background:color-mix(in srgb,var(--brand,#1F6FD1) 45%,#fff);border-color:var(--brand,#1F6FD1)}
.as-arch.counting::before{content:"";position:absolute;inset:0 auto 0 0;width:var(--as-left,100%);background:var(--brand,#1F6FD1);transition:width .1s linear;z-index:0}
.as-arch-t{position:relative;z-index:1}
.as-arch.counting{color:#fff}
/* Create order in one go (Oct 20) */
.qo{width:min(580px,100%)}
.qo-steps{list-style:none;margin:6px 0 12px;padding:0;display:flex;flex-direction:column;gap:6px;font-size:13.5px}
.qo-steps li{display:flex;align-items:center;gap:8px;color:var(--ink-3)}
.qo-steps li i{width:18px;height:18px;border-radius:50%;display:inline-grid;place-items:center;font-style:normal;font-size:11px;font-weight:700;flex:none}
.qo-steps li.done{color:var(--ink-2)}
.qo-steps li.done i{background:var(--ok);color:#fff}
.qo-steps li.error i{background:var(--danger);color:#fff}
.qo-steps li.doing{color:var(--ink);font-weight:600}
.qo-steps li.doing i{border:2px solid var(--brand,#1F6FD1);border-right-color:transparent;animation:qo-spin .8s linear infinite}
@keyframes qo-spin{to{transform:rotate(360deg)}}
@media (prefers-reduced-motion:reduce){.qo-steps li.doing i{animation:none}}
.qo-made{border:1px solid var(--line);border-radius:12px;padding:10px 12px;margin:8px 0;display:flex;flex-direction:column;gap:6px}
.qo-made-h{display:flex;flex-wrap:wrap;align-items:baseline;gap:8px;font-size:14px}
.qo-made-h b{font-size:16px}
.qo-did{margin:0;padding-left:18px;font-size:12.5px;color:var(--ink-2);display:flex;flex-direction:column;gap:2px}
.qo-ask{font-size:12.5px}
.qo-ask summary{cursor:pointer;color:var(--ink-2)}
.qo-ask ul{margin:4px 0 0;padding-left:18px}
.qo-made .btn{align-self:flex-start}
.osp-review{font-size:12.5px}
.qo-steps li{align-items:flex-start}
.qo-steps li span{display:flex;flex-direction:column;gap:2px}
.qo-note{font-weight:400;font-style:italic;color:var(--ink-3);font-size:12.5px}
/* Create order: help with the art when it couldn't be brought in (Oct 20) */
.qo-help{display:flex;flex-direction:column;gap:6px;margin:8px 0;padding:10px 12px;border:1px solid #E8C468;background:#FFF8E5;border-radius:12px;font-size:13px}
.qo-help-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:8px;margin:4px 0}
.qo-help-it{display:flex;flex-direction:column;gap:4px;padding:6px;border:1px solid var(--line);border-radius:10px;background:var(--surface);cursor:pointer;font:inherit;color:inherit;text-align:left}
.qo-help-it img{width:100%;aspect-ratio:1;object-fit:contain;background:#fff;border-radius:6px}
.qo-help-it span{font-size:11.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.qo-help-it:hover{border-color:var(--brand,#1F6FD1)}
.qo-help-wait{grid-column:1/-1;font-size:12px}
.qo-help-acts{display:flex;flex-wrap:wrap;gap:8px}
/* Printavo Art Resolution Center (Oct 20) */
.arc-h{display:flex;flex-wrap:wrap;align-items:baseline;gap:8px}
.arc-h b{font-size:15px}
.arc-it{position:relative;cursor:default}
.arc-f{position:absolute;top:8px;left:8px;background:rgba(15,23,42,.75);color:#fff;font-size:10.5px;font-weight:700;padding:1px 6px;border-radius:999px}
.arc-use{display:flex;gap:4px;flex-wrap:wrap}
.arc-use .btn{padding:2px 8px;font-size:11.5px}
.arc-chat{display:flex;flex-direction:column;gap:6px;max-height:220px;overflow:auto;padding:4px 0}
.arc-m{display:flex;flex-direction:column;gap:4px;max-width:90%;padding:6px 10px;border-radius:10px;font-size:13px}
.arc-m.ai{background:var(--surface);border:1px solid var(--line);align-self:flex-start}
.arc-m.staff{background:var(--brand,#1F6FD1);color:#fff;align-self:flex-end}
.arc-acts{display:flex;flex-wrap:wrap;gap:6px}
.arc-films{display:flex;flex-direction:column;gap:6px}
.arc-say{display:flex;gap:6px}
.arc-say input{flex:1;min-width:0;padding:6px 9px;border:1px solid var(--line);border-radius:8px;font:inherit}
.arc-why{margin:0;padding-left:18px;font-size:12.5px;color:#8A5A00}
.qo-open{font-size:13px;font-weight:600;align-self:flex-start}
.qo-foot{align-items:center}
.arc-sec{display:flex;flex-direction:column;gap:4px}
.arc-sec>b{font-size:13px}
.arc-noimg{width:100%;aspect-ratio:1;display:grid;place-items:center;background:#f4f5f7;border-radius:6px;font-size:12px}
.arc-it small{font-size:10.5px;line-height:1.25;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.arc-conf{display:flex;gap:10px;align-items:flex-start}
.arc-conf img,.arc-conf .arc-noimg{width:120px;height:120px;object-fit:contain;flex:none;background:#fff;border-radius:8px;border:1px solid var(--line)}
.arc-conf-f{display:flex;flex-direction:column;gap:6px;font-size:13px}
.arc-conf-f label{display:flex;flex-direction:column;gap:2px;font-weight:600}
.arc-conf-f select,.arc-conf-f input{font:inherit;font-weight:400;padding:5px 8px;border:1px solid var(--line);border-radius:8px}
.arc-in{display:flex;align-items:center;gap:4px;font-weight:400}
.arc-in input{width:90px}
/* Create order: asking about the art, redone (Oct 20: one gallery, one pick, one button) */
.qo.wide{width:min(760px,100%)}
.ap{display:flex;flex-direction:column;gap:10px;margin:6px 0 2px}
.ap-q{margin:0;font-size:17px;line-height:1.3}
.ap-why{margin:-4px 0 0;font-size:13px;color:var(--ink-2)}
.ap-ai{display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 10px;font-size:13px;padding:8px 10px;border-radius:10px;background:var(--bg-2,#f4f6fa)}
.ap-ai-i{color:var(--brand,#1F6FD1);font-weight:700}
.ap-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(132px,1fr));gap:10px;max-height:min(46vh,420px);overflow:auto;padding:2px}
.ap-it{display:flex;flex-direction:column;gap:4px;padding:0;border:2px solid transparent;border-radius:12px;background:none;cursor:pointer;font:inherit;color:inherit;text-align:left}
.ap-it:disabled{cursor:default;opacity:.6}
.ap-it:hover:not(:disabled) .ap-pic{border-color:var(--ink-3)}
.ap-it.on{border-color:var(--brand,#1F6FD1)}
.ap-it.on .ap-pic{border-color:transparent}
.ap-pic{display:grid;place-items:center;aspect-ratio:1;border:1px solid var(--line);border-radius:10px;overflow:hidden;background:#fff;font-size:12px}
.ap-pic img{max-width:92%;max-height:92%;object-fit:contain}
.ap-pic.big{width:180px;flex:none}
.ap-tag{font-size:11.5px;color:var(--ink-3);padding:0 4px 4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ap-wait{grid-column:1/-1;font-size:12.5px;color:var(--ink-3)}
.ap-link{background:none;border:0;padding:0;color:var(--brand,#1F6FD1);font:inherit;font-size:13px;cursor:pointer;text-decoration:underline;text-underline-offset:2px}
.ap-link:disabled{color:var(--ink-3)}
.ap-films{display:flex;flex-wrap:wrap;gap:6px 12px;font-size:13px}
.ap-ask{display:flex;gap:6px}
.ap-ask input{flex:1;min-width:0;padding:7px 10px;border:1px solid var(--line);border-radius:8px;font:inherit;font-size:13px}
.ap-foot{display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding-top:8px;border-top:1px solid var(--line)}
.ap-more{display:flex;flex-wrap:wrap;gap:4px 14px;flex:1 1 280px}
.ap-bg{display:flex;align-items:center;gap:6px;font-size:13px}
.ap-conf{display:flex;gap:14px;align-items:flex-start}
.ap-conf-f{display:flex;flex-direction:column;gap:10px;min-width:0}
.ap-chips{display:flex;flex-wrap:wrap;gap:6px}
.ap-other{font:inherit;font-size:13px;padding:4px 8px;border:1px solid var(--line);border-radius:999px;background:var(--surface)}
.ap-w{display:flex;flex-wrap:wrap;align-items:center;gap:6px;font-size:13px}
.ap-w input{width:80px;padding:5px 8px;border:1px solid var(--line);border-radius:8px;font:inherit}
@media (max-width:560px){.ap-conf{flex-direction:column}.ap-pic.big{width:100%}}
/* Email search suggestions sit in the list, above the matching emails, instead of covering them (Oct 20, Nick) */
.ibx2-find{flex-wrap:wrap}
.ibx2-find .msug{position:static;flex:1 0 100%;order:9;margin:6px 0 4px;box-shadow:none;max-height:min(34vh,300px)}
/* Create order window: Cancel (nothing saved) and the "what are these?" Resolution Center (Oct 20) */
.qo{position:relative}
.qo-x{position:absolute;top:10px;right:12px;width:30px;height:30px;border:0;border-radius:8px;background:none;color:var(--ink-3);font-size:22px;line-height:1;cursor:pointer}
.qo-x:hover{background:var(--bg-2,#f4f6fa);color:var(--ink)}
.ap-cancel{color:#b42318}
.arc{display:flex;flex-direction:column;gap:12px}
.arc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:14px;max-height:min(56vh,560px);overflow:auto;padding:2px}
.arc-grid.sm{grid-template-columns:repeat(auto-fill,minmax(160px,1fr));max-height:min(40vh,380px)}
.arc-card{display:flex;flex-direction:column;gap:6px;padding:8px;border:2px solid var(--line);border-radius:12px;min-width:0}
.arc-card.set{border-color:var(--ink-3);opacity:.8}
.arc-card.art{border-color:var(--brand,#1F6FD1);opacity:1}
.arc-pic{display:grid;place-items:center;aspect-ratio:1;border-radius:8px;overflow:hidden;background:#fff;font-size:12px;border:1px solid var(--line)}
.arc-pic.clear{background:#fff}
.arc-pic img{max-width:94%;max-height:94%;object-fit:contain}
.arc-name{font-size:12px;color:var(--ink-2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.arc-chips{display:flex;flex-wrap:wrap;gap:5px}
.arc-chips .chip{font-size:12px;padding:3px 9px}
.arc-bg{display:flex;align-items:center;gap:6px;font-size:12.5px}
.arc-else{border-top:1px solid var(--line);padding-top:8px;display:flex;flex-direction:column;gap:8px}
.arc-else summary{cursor:pointer;font-size:13px;color:var(--brand,#1F6FD1)}
.arc-else[open]{display:flex}
.arc-else[open]>*+*{margin-top:8px}
.arc-tools{display:flex;flex-wrap:wrap;align-items:center;gap:6px 14px;font-size:13px}
.qo.wide{width:min(960px,100%)}
.qo>h3{padding-right:34px}
.arc-chips .chip.on{background:var(--brand,#1F6FD1);border-color:var(--brand,#1F6FD1);color:#fff}
/* inbox search: suggestions open from a small down arrow, never by themselves (Oct 20) */
.sug-tg{flex:none;display:grid;place-items:center;width:28px;height:28px;border:0;border-radius:7px;background:none;color:var(--ink-3);cursor:pointer;padding:0}
.sug-tg svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round;transition:transform .15s}
.sug-tg:hover{background:var(--surface-2);color:var(--ink)}
.sug-tg.on{color:var(--accent)}
.sug-tg.on svg{transform:rotate(180deg)}
.arc-hint{font-size:12px;color:var(--ink-3);font-style:italic}
.arc-hint.ok{font-style:normal;color:var(--ok,#16794c)}
.arc-place{display:flex;flex-wrap:wrap;align-items:center;gap:6px;font-size:12.5px}
.arc-place select{flex:1 1 120px;min-width:0;font:inherit;font-size:12.5px;padding:4px 6px;border:1px solid var(--line);border-radius:7px;background:var(--surface)}
.arc-place input{width:58px;font:inherit;font-size:12.5px;padding:4px 6px;border:1px solid var(--line);border-radius:7px}
/* the old job's files one at a time: 1 of N (Oct 20) */
.arc-step{display:flex;flex-direction:column;gap:10px}
.arc-nav{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.arc-nav>b{font-size:14px;min-width:52px;text-align:center}
.arc-arrow{width:34px;height:34px;border:1px solid var(--line);border-radius:9px;background:var(--surface);font-size:22px;line-height:1;cursor:pointer;color:var(--ink)}
.arc-arrow:disabled{opacity:.35;cursor:default}
.arc-dots{display:flex;flex-wrap:wrap;gap:6px;margin-left:8px}
.arc-dot{width:40px;height:40px;padding:0;border:2px solid var(--line);border-radius:8px;background:#fff;overflow:hidden;cursor:pointer;display:grid;place-items:center;font-size:12px;color:var(--ink-3)}
.arc-dot img{max-width:100%;max-height:100%;object-fit:contain}
.arc-dot.on{outline:2px solid var(--ink);outline-offset:1px}
.arc-dot.set{border-color:var(--ink-3)}
.arc-dot.art{border-color:var(--brand,#1F6FD1)}
.arc-one .arc-card{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(220px,1fr);gap:8px 16px;align-content:start;border-width:2px}
.arc-one .arc-card>.arc-pic{grid-row:1/span 6;aspect-ratio:auto;height:min(46vh,420px)}
.arc-one .arc-card>*:not(.arc-pic){grid-column:2}
.arc-one .arc-chips .chip{font-size:13px;padding:5px 11px}
@media (max-width:640px){.arc-one .arc-card{grid-template-columns:1fr}.arc-one .arc-card>*:not(.arc-pic){grid-column:1}.arc-one .arc-card>.arc-pic{grid-row:auto;height:min(40vh,320px)}}
.arc-job{font-size:13px;font-weight:500;margin-left:6px;white-space:nowrap}
.arc-split{font-size:12px;justify-self:start;text-align:left}
/* what a production file is (Oct 20) */
.prod-kind{font:inherit;font-size:11.5px;max-width:100%;padding:2px 4px;border:1px dashed var(--line);border-radius:6px;background:var(--surface);color:var(--ink-3)}
.prod-kind.set{border-style:solid;border-color:color-mix(in srgb,var(--accent) 40%,var(--line));color:var(--accent);font-weight:600}
div.prod-kind{border:0;padding:0}
.prod-type{font-size:11px}
.arc-kind{display:flex;align-items:center;gap:6px;font-size:12.5px}
.arc-kind select{flex:1;min-width:0;font:inherit;font-size:12.5px;padding:4px 6px;border:1px solid var(--line);border-radius:7px;background:var(--surface)}
.prod-guess{font-size:11.5px;color:var(--ink-2)}
.prod-guess .linkish.ok{color:var(--accent);font-weight:700;background:none;border:0;padding:0 0 0 4px;cursor:pointer;font-size:11.5px;text-decoration:underline}
.prod-fnote{width:100%;font:inherit;font-size:11.5px;padding:3px 5px;border:1px solid transparent;border-radius:6px;background:transparent;color:var(--ink-2)}
.prod-fnote:hover,.prod-fnote:focus{border-color:var(--line);background:var(--surface)}
.prod-fnote.ro{padding:0}
.arc-note{font:inherit;font-size:12.5px;padding:5px 8px;border:1px solid var(--line);border-radius:7px;min-width:0}
/* several orders from one email, one at a time (Oct 20) */
.qo-part{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px;margin:-4px 34px 12px 0;padding:8px 12px;border-radius:10px;background:var(--accent-soft)}
.qo-part-n{font-size:12px;font-weight:700;color:var(--accent);text-transform:none}
.qo-part b{font-size:14px}
.qo-part-dots{display:flex;gap:5px;margin-left:auto}
.qo-part-dots i{width:9px;height:9px;border-radius:50%;background:var(--line)}
.qo-part-dots i.on{background:var(--accent)}
.qo-part-dots i.done{background:var(--ok,#16794c)}
.qo-pause{display:flex;flex-direction:column;gap:10px}
.qo-pause h3{margin:0}
.qo-pause-n{font-size:12.5px;margin:0}
.arc-ub{display:flex;flex-direction:column;gap:8px;padding:10px 12px;border:1px solid var(--line);border-radius:10px;background:var(--bg-2,#f6f8fb)}
.arc-ub-r{display:flex;flex-wrap:wrap;align-items:center;gap:6px 12px;font-size:13px}
/* the answers stay put when more show up (Oct 20, Nick: "why does this button change positions when you click it?"):
   the picture spans every row, the rows hug their content, and the spare height goes to a last empty row */
.arc-one .arc-card{grid-template-rows:repeat(12,min-content) 1fr;grid-auto-rows:min-content}
.arc-one .arc-card>.arc-pic{grid-row:1/-1}
@media (max-width:640px){.arc-one .arc-card{grid-template-rows:none}.arc-one .arc-card>.arc-pic{grid-row:auto}}
/* Mockup Creator: Combine colors, and a reorder's inks waiting for production (Oct 20) */
.mk-colors-h{display:flex;align-items:center;justify-content:space-between;gap:8px}
.mk-comb-r{cursor:pointer}
.mk-comb-r input{margin:0 4px 0 0}
.mk-comb-r.on{background:color-mix(in srgb,var(--accent) 8%,transparent);border-radius:8px}
.mk-comb-how{display:flex;flex-direction:column;gap:6px;padding:8px 0;border-top:1px solid var(--line);margin-top:6px;font-size:13px}
.mk-comb-ink{display:flex;flex-wrap:wrap;align-items:center;gap:6px}
.mk-comb-ink select{font:inherit;font-size:12.5px;padding:3px 6px;border:1px solid var(--line);border-radius:7px}
.mk-comb-ink input{width:52px;font:inherit;font-size:12.5px;padding:2px 4px;border:1px solid var(--line);border-radius:6px}
.mk-comb-n{margin:0;font-size:12px}
.mk-plan.mk-wait{background:color-mix(in srgb,#f5a524 14%,var(--surface));border-color:color-mix(in srgb,#f5a524 40%,var(--line))}
.arc-ub-h{font-size:13.5px}
.arc-ub-l{min-width:150px}
.arc-ub-r input[type=number]{width:58px;font:inherit;font-size:13px;padding:3px 6px;border:1px solid var(--line);border-radius:7px}
.arc-ub-w{display:flex;align-items:center;gap:6px;font-size:13px;margin-left:auto}
.arc-mode{border-top:1px solid var(--line);padding-top:8px}
.arc-mode .check{font-size:13px}
/* a visual-only reorder print (Oct 20) */
.pr-stamp{display:inline-block;width:fit-content;margin:2px 0;padding:2px 10px;border:2px solid #b7791f;border-radius:6px;color:#975a16;font-size:11.5px;font-weight:800;letter-spacing:.02em;text-transform:uppercase;transform:rotate(-1deg);background:color-mix(in srgb,#f5a524 10%,transparent)}
.pr-specs.pr-grey{color:var(--ink-3)}
/* Resolution Center step 2: how it printed, one row per print spot (Oct 20) */
.arc-det-h,.arc-det-r{display:grid;grid-template-columns:minmax(130px,170px) minmax(0,1fr) minmax(170px,230px);gap:8px 14px;align-items:center}
.arc-det-h{font-size:11.5px;font-weight:700;color:var(--ink-3);text-transform:uppercase;letter-spacing:.03em}
.arc-det-r{padding:6px 0;border-top:1px solid var(--line);font-size:13px}
