/* Art & production tidied (Oct 21): proof versions in a row, mockup saves grouped */
.ph-row{display:flex!important;flex-direction:column;gap:8px}
.ph-row .ph-body{order:1}
.ph-row .ph-pics{order:2;display:flex;flex-direction:row;flex-wrap:wrap;gap:6px}
.ph-row .ph-pic{width:72px;height:72px}
.mkh-grp{padding:10px 0;border-bottom:1px solid var(--line-2,var(--line));display:flex;flex-direction:column;gap:6px}
