.mkh-grp:first-child .mkh-th{width:54px;height:54px}
.mkh-th img{max-width:100%;max-height:100%;object-fit:contain}
.mkh-grp-s{color:var(--ink-2);font-size:12px}
.mkh-more{margin-top:8px;font-size:13px}
.prod-thumb img.prod-page{background:#fff;object-fit:contain}
.prod-sheet{display:grid;grid-template-columns:repeat(3,18px);grid-auto-rows:10px;gap:2px;position:relative;padding-bottom:16px}
.prod-sheet i{background:#e7f3ea;border:1px solid #9cc7a6;border-radius:1px}
.prod-sheet b{position:absolute;left:0;right:0;bottom:0;text-align:center;font-size:11px;color:#1e7a3a}
/* a print's inks as chips (Oct 21, Nick: "the colors just seem to run on and on") */
.pr-scr-l{min-width:54px}
.pr-inkl{align-items:flex-start}
.pr-inkl > .pr-scr-l{padding-top:3px}
.pr-inkl > .pr-scr-v{flex-wrap:wrap;gap:6px 10px;flex:1 1 300px;min-width:0}
.ink-chips{display:inline-flex;flex-wrap:wrap;gap:4px 5px}
.ink-chip{display:inline-flex;align-items:center;gap:5px;padding:2px 9px 2px 4px;border-radius:999px;background:var(--surface-2);font-size:12px;font-weight:600;color:var(--ink);white-space:nowrap;line-height:1.5}
.ink-chip i{width:13px;height:13px;border-radius:50%;box-shadow:inset 0 0 0 1px rgba(0,0,0,.18);flex:none}
.ink-chip.pms{box-shadow:inset 0 0 0 1px var(--line)}
.pr-pms{font-size:12.5px;color:var(--ink-2);white-space:nowrap}
.imp-scr + .imp-scr{margin-top:-6px}
/* the group's mockups are buttons that open big (Oct 21, Nick) */
button.mk-big{padding:0;cursor:zoom-in;width:100%;font:inherit}
.imp-mock .mk-more button{display:block;aspect-ratio:1;border:1px solid var(--line);border-radius:8px;overflow:hidden;background:#fff;line-height:0;padding:0;cursor:zoom-in}
