.aa-shop .aa-tbl{font-size:inherit}
.aa-shop .aa-tbl thead th{background:var(--surface);color:var(--ink-3);font-size:11px;letter-spacing:.08em;text-transform:uppercase;font-weight:600;padding:10px 14px;white-space:nowrap}
.aa-shop .aa-tbl td{padding:11px 14px}
.aa-shop .aa-tbl tbody tr:hover{background:transparent}
.aa-shop .aa-tbl tbody tr:hover td{background:var(--surface-2)}
.aa-shop .aa-tbl td a{font-weight:600}
.aa-shop .aa-tbl td.num a,.aa-shop .aa-tbl td .num{font-family:var(--mono);font-size:13px}
.aa-shop .aa-aging{gap:1px;background:var(--line);border:1px solid var(--line);border-radius:var(--r);overflow:hidden}
.aa-shop .aa-age{border:0;border-radius:0;padding:14px 16px;gap:4px}
.aa-shop .aa-age b{font-family:var(--display);font-stretch:85%;font-weight:700;font-size:24px;line-height:1.1;font-variant-numeric:tabular-nums}
.aa-shop .aa-age span{font-weight:500;font-size:12px;color:var(--ink-2)}
.aa-shop .aa-age.late,.aa-shop .aa-age.bad{background:var(--surface)}
.aa-shop .aa-age.late b{color:var(--warn)}
.aa-shop .aa-age.bad b{color:var(--danger)}

/* ===== One look across the shop (Oct 21, Nick: "unify everything… I meant the top of this page [the order page]…
   I liked these toolbars"): the order page's top is the kit. Tab bars and filter chips are its tab bar (white bar, the
   picked tab tinted blue with a blue underline, counts in little pills); number cards are its summary card (the color
   fade on top, colored labels over each number). Scoped to the shop (main.main): the customer portal is untouched. */
main.main :is(.chips, .mk-hit-seg, .aa-sub, .set-tabs, .ibx2-tabs, .rv-seg, .md-seg, .jt-chips){display:flex;flex-wrap:wrap;gap:0;background:var(--surface);border:0;box-shadow:0 1px 3px rgba(20,29,43,.08),0 0 0 1px var(--line-2);border-radius:14px;padding:0;overflow:hidden;margin-bottom:0}
main.main :is(.aa-shopnav .chips, .aa-sub, .set-tabs){width:100%}
main.main :is(.chips, .mk-hit-seg, .ibx2-tabs, .jt-chips){width:fit-content;max-width:100%}
main.main .aa-sub,main.main .set-tabs{margin-bottom:14px}
main.main :is(:is(:is(.chips, .mk-hit-seg) > :is(.chip, button)), .aa-sub > button, .set-tabs a, .ibx2-tabs > button, .rv-seg > button, .md-seg > button, .jt-chips > button){all:unset;box-sizing:border-box;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px;flex:0 0 auto;padding:8px 14px;font-family:var(--body);font-size:13.5px;font-weight:700;color:var(--ink-3);white-space:nowrap;text-decoration:none;border-radius:0}
main.main :is(.aa-shopnav .chips .chip, .aa-sub > button, .set-tabs a){flex:1 0 auto;padding:12px 14px}
main.main :is(:is(:is(.chips, .mk-hit-seg) > :is(.chip, button)), .aa-sub > button, .set-tabs a, .ibx2-tabs > button, .rv-seg > button, .md-seg > button, .jt-chips > button):hover{color:var(--ink);background:transparent}
main.main :is(:is(:is(.chips, .mk-hit-seg) > :is(.chip, button)).on, .aa-sub > button.on, .set-tabs a.on, .ibx2-tabs > button.on, .rv-seg > button.on, .md-seg > button.on, .jt-chips > button.on){color:var(--ink);background:color-mix(in srgb,var(--fbs-blue) 10%,var(--surface));box-shadow:inset 0 -4px 0 var(--fbs-blue);font-weight:800}
main.main :is(.chip .chip-n, .aa-sub > button :is(span, small), .ibx2-tabs > button span, .rv-seg > button :is(span, small), .jt-chips > button small){font-size:11px;font-weight:700;min-width:20px;text-align:center;padding:1px 6px;border-radius:10px;background:var(--surface-2);color:var(--ink-3);margin:0}
main.main :is(.chip.on .chip-n, .aa-sub > button.on :is(span, small), .ibx2-tabs > button.on span, .rv-seg > button.on :is(span, small), .jt-chips > button.on small){background:var(--fbs-blue);color:#fff}
main.main .md-seg input[type=date]{border:0;background:var(--surface);padding:0 10px}
main.main .toolbar{gap:10px}
/* number cards → the summary card */
main.main :is(.stats, .sc-kpis, .rv-kpis, .db-kpis, .aa-shop .aa-aging){position:relative;display:flex;flex-wrap:wrap;gap:0;background:var(--surface);border:0;box-shadow:0 1px 3px rgba(20,29,43,.08),0 0 0 1px var(--line-2);border-radius:14px;overflow:hidden;padding-top:4px}
main.main :is(.stats, .sc-kpis, .rv-kpis, .db-kpis, .aa-shop .aa-aging)::before{content:"";position:absolute;left:0;right:0;top:0;height:4px;background:var(--fbs-fade)}
main.main :is(.stats, .sc-kpis, .rv-kpis, .db-kpis, .aa-shop .aa-aging) > :is(a, button, div){all:unset;box-sizing:border-box;flex:1 1 0;min-width:130px;display:flex;flex-direction:column;align-items:flex-start;gap:2px;padding:10px 16px;text-align:left;position:relative;background:var(--surface);color:var(--ink);text-decoration:none}
main.main :is(.stats, .sc-kpis, .rv-kpis, .db-kpis, .aa-shop .aa-aging) > :is(a, button){cursor:pointer}
main.main :is(.stats, .sc-kpis, .rv-kpis, .db-kpis, .aa-shop .aa-aging) > :is(a, button):hover{background:var(--surface-2)}
main.main :is(.stats, .sc-kpis, .rv-kpis, .db-kpis, .aa-shop .aa-aging) > :is(a, button):disabled{cursor:default;background:var(--surface)}
main.main :is(.stats, .sc-kpis, .rv-kpis, .db-kpis, .aa-shop .aa-aging) > * + *::before{content:"";position:absolute;left:0;top:12px;bottom:12px;width:1px;height:auto;background:var(--line-2);right:auto}
main.main :is(.stats, .sc-kpis, .rv-kpis, .db-kpis, .aa-shop .aa-aging) > * > :is(span:not(.v), .k){order:-1;font-family:var(--body);font-size:11.5px;font-weight:700;color:var(--fbs-blue);text-transform:none;letter-spacing:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
main.main :is(.stats, .sc-kpis, .rv-kpis, .db-kpis, .aa-shop .aa-aging) > :nth-child(5n+2) > :is(span:not(.v), .k){color:color-mix(in srgb,var(--fbs-salmon) 85%,#000)}
main.main :is(.stats, .sc-kpis, .rv-kpis, .db-kpis, .aa-shop .aa-aging) > :nth-child(5n+3) > :is(span:not(.v), .k){color:color-mix(in srgb,var(--fbs-orange) 70%,#000)}
main.main :is(.stats, .sc-kpis, .rv-kpis, .db-kpis, .aa-shop .aa-aging) > :nth-child(5n+5) > :is(span:not(.v), .k){color:color-mix(in srgb,var(--fbs-salmon) 85%,#000)}
main.main :is(.stats, .sc-kpis, .rv-kpis, .db-kpis, .aa-shop .aa-aging) :is(b, .v){font-family:var(--body);font-stretch:normal;font-weight:700;font-size:17px;line-height:1.25;color:var(--ink);font-variant-numeric:tabular-nums;white-space:nowrap}
main.main :is(.stats, .sc-kpis, .rv-kpis, .db-kpis, .aa-shop .aa-aging) small{font-size:12px;color:var(--ink-3)}
main.main .stat .v.alert,main.main :is(.rv-kpis .bad, .sc-kpi.bad, .aa-age.bad) b,main.main .db-kpis .bad b small{color:var(--danger)}
main.main :is(.rv-kpis .warn, .sc-kpi.warn, .aa-age.late) b{color:var(--warn)}
main.main .rv-kpis .ok b{color:var(--ok)}
main.main :is(.rv-kpis .info, .db-kpis .hot) b{color:var(--fbs-blue)}
main.main :is(.sc-kpis, .rv-kpis) > button.on{background:color-mix(in srgb,var(--fbs-blue) 10%,var(--surface));box-shadow:inset 0 -4px 0 var(--fbs-blue)}
main.main .stats{margin-bottom:12px}
/* tables → the Orders list */
main.main :is(.rv-tbl, .aa-tbl){font-size:inherit}
main.main :is(.rv-tbl, .aa-tbl) th{background:var(--surface);color:var(--ink-3);font-size:11px;letter-spacing:.08em;text-transform:uppercase;font-weight:600;padding:10px 14px;border-bottom:1px solid var(--line);white-space:nowrap}
main.main :is(.rv-tbl, .aa-tbl) td{padding:10px 14px;border-bottom:1px solid var(--line-2)}
main.main :is(.rv-tbl, .aa-tbl) tbody tr:last-child td{border-bottom:0}
main.main .aa-tbl tbody tr:hover{background:transparent}
main.main .aa-tbl tbody tr:hover td{background:var(--surface-2)}
main.main .aa-tbl td a{font-weight:600}
main.main .aa-card.aa-tblcard{border-radius:var(--r);padding:0}
/* page titles that aren't in a .page-head still get its color bar */
main.main .jv-h h1::after{content:"";display:block;background:var(--fbs-fade);height:5px;border-radius:4px;width:calc(100% + 60px);min-width:140px;max-width:100%;margin-top:6px}
main.main .db-kpis > a:first-child::before{display:none}
main.main .stat small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
.ctx-tb{padding:10px 16px 0;margin:0}
main.main .jt-chips{margin:0 16px 8px;width:fit-content}
main.main .jt-chips > button small{font-size:11px;font-weight:700;padding:1px 6px;border-radius:10px;background:var(--surface-2);color:var(--ink-3)}
main.main .jt-chips > button.on small{background:var(--fbs-blue);color:#fff}

/* the secondary toolbar (Oct 21, Nick approved): fits its tabs, bold labels, the picked one tinted blue with the blue
   underline, every count in a bubble (blue on the picked tab); the inbox's red "needs a reply" count stays red */
main.main .ibx2-tabs > button{flex:0 0 auto;padding:9px 15px}
main.main .ibx2-tabs > button span.hot{background:var(--danger);color:#fff}
main.main :is(:is(:is(.chips, .mk-hit-seg) > :is(.chip, button)), .ibx2-tabs > button, .jt-chips > button){gap:7px}
main.main nav.aa-shopnav .chips{width:100%}
/* one type in lists (Oct 21, Nick: "we got like 5 different fonts here… spilling over onto other lines… the invoice
   number aren't the same as the numbers under all the other ones"): every list in the page's font, numbers with even
   digits, numbers / money / dates never break across lines, the Quote / Inv tag on the number's line, every status the
   same pill (Printavo's history statuses too) */
main.main :is(.tbl, .rv-tbl, .aa-tbl){font-family:var(--body)}
main.main :is(.ordno, .tag, .aa-tbl .num, .rv-tbl .num, .aa-tbl td.num a){font-family:var(--body);font-variant-numeric:tabular-nums}
main.main .ordno{font-weight:700;font-size:14px;color:var(--ink)}
main.main .tag{font-size:10px;font-weight:700;letter-spacing:.05em;padding:2px 6px;vertical-align:1px}
main.main :is(.tbl, .rv-tbl, .aa-tbl) td{font-variant-numeric:tabular-nums}
main.main :is(.tbl, .rv-tbl, .aa-tbl) :is(td.r, th.r, td.dt, td:first-child){white-space:nowrap}
main.main .due{white-space:nowrap}
main.main .pill,main.main .pv-dot{display:inline-flex;align-items:center;gap:6px;padding:3px 9px 3px 8px;border-radius:99px;font-family:var(--body);font-size:12px;font-weight:600;line-height:1.35;white-space:nowrap;color:color-mix(in srgb,var(--sc) 72%,#000);background:color-mix(in srgb,var(--sc) 14%,transparent)}
main.main .pv-dot::before,main.main .pill::before{content:"";flex:none;width:7px;height:7px;border-radius:50%;background:var(--sc)}
main.main .aa-arch{font-family:var(--body)}
/* the type and color system (Oct 21, Nick: "a standard font, then a sub font, a standard color, a bold color… unify
   the whole look"): titles (page h1 and panel h2) in the title font (--display); everything else in the one body font
   (--body), no typewriter text except real code. Text is --ink; sub text (second lines, notes, labels) --ink-3; bold
   is --ink at 700; links and the picked tab --accent / --fbs-blue. */
/* the sidebar too (Oct 21, Nick: "don't forget about the left toolbar"); the title font only on the page's h1 and panel titles
   (an email's subject or the inbox summary's heading are body text) */
.app :where(*):not(main.main h1, main.main h1 *, .panel-h h2, .panel-h h2 *, code, pre, kbd, samp, svg, svg *, [style*="font-family"], [style*="font-family"] *, [data-font], [data-font] *){font-family:var(--body) !important}
main.main :is(.sub, .faint, .muted, small){color:var(--ink-3)}
main.main :is(b, strong){color:inherit}
/* Email's folder bar is a section bar like the order page's (Oct 21, Nick: "all the toolbars on email look off") */
html body main.main.main:has(.ibx2) .mf-bar{background:var(--surface)!important;border:0!important;box-shadow:0 1px 3px rgba(20,29,43,.08),0 0 0 1px var(--line-2)!important;border-radius:14px!important;padding:0!important;gap:0!important;align-items:stretch}
html body main.main.main:has(.ibx2) .mf-bar .mf-chip{border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;padding:12px 14px!important;font-size:13.5px!important;font-weight:700!important;color:var(--ink-3)!important;display:inline-flex;align-items:center;gap:6px;flex:1 0 auto;justify-content:center;min-height:0!important}
html body main.main.main:has(.ibx2) .mf-bar .mf-chip:hover{color:var(--ink)!important}
html body main.main.main:has(.ibx2) .mf-bar .mf-chip.on,html body main.main.main:has(.ibx2) .mf-bar .mf-dd.on>.mf-chip{color:var(--ink)!important;background:color-mix(in srgb,var(--fbs-blue) 10%,var(--surface))!important;box-shadow:inset 0 -4px 0 var(--fbs-blue)!important;font-weight:800!important;border-bottom:0!important}
html body main.main.main:has(.ibx2) .mf-bar .mf-chip b{font-size:11px;font-weight:700;min-width:20px;text-align:center;padding:1px 6px;border-radius:10px;background:var(--surface-2);color:var(--ink-3)}
html body main.main.main:has(.ibx2) .mf-bar .mf-chip.on b,html body main.main.main:has(.ibx2) .mf-bar .mf-dd.on>.mf-chip b{background:var(--fbs-blue);color:#fff}
html body main.main.main:has(.ibx2) .mf-bar .mf-dd{display:flex;flex:1 0 auto}
html body main.main.main:has(.ibx2) .mf-bar .mf-dd > .mf-chip{width:100%}
/* the inbox list's filter tabs fit its narrow column: one row, smaller */
main.main .ibx2-tabs{width:100%;flex-wrap:nowrap}
main.main .ibx2-tabs > button{flex:1 1 auto;padding:8px 6px;font-size:12.5px;gap:4px;min-width:0}
main.main .ibx2-tabs > button span{min-width:16px;padding:0 5px;font-size:10.5px}
/* the inbox list's filter tabs: the secondary toolbar's look across the top of the list */
html body main.main.main:has(.ibx2) .ibx2-list .ibx2-tabs{background:var(--surface)!important;border-radius:0!important;padding:0!important;gap:0!important;border-bottom:1px solid var(--line-2);box-shadow:none!important;flex-wrap:nowrap!important}
html body main.main.main:has(.ibx2) .ibx2-list .ibx2-tabs button{padding:10px 4px!important;font-size:12.5px!important;font-weight:700!important;color:var(--ink-3)!important;border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;flex:1 1 auto;gap:4px;margin:0}
html body main.main.main:has(.ibx2) .ibx2-list .ibx2-tabs button.on{color:var(--ink)!important;font-weight:800!important;background:color-mix(in srgb,var(--fbs-blue) 10%,var(--surface))!important;box-shadow:inset 0 -4px 0 var(--fbs-blue)!important}
html body main.main.main:has(.ibx2) .ibx2-list .ibx2-tabs button span{font-size:10.5px!important;font-weight:700;min-width:16px;padding:0 5px;border-radius:10px;background:var(--surface-2);color:var(--ink-3);margin:0!important}
html body main.main.main:has(.ibx2) .ibx2-list .ibx2-tabs button.on span{background:var(--fbs-blue);color:#fff}
html body main.main.main:has(.ibx2) .ibx2-list .ibx2-tabs button span.hot{background:var(--danger);color:#fff}
/* Email's reading-pane buttons (Reply · Forward · Archive · News · Move · Black Hole · Create order…): each group a white
   bar like the toolbars, icon and label on one line, bold gray labels that darken and tint on hover; Reply the one blue
   button (Oct 21, Nick: "the buttons look weird too") */
html body main.main.main:has(.ibx2) .eh-bar .tb-row{gap:8px!important}
html body main.main.main:has(.ibx2) .eh-bar .tb-row .tb-g{flex:0 0 auto!important;display:flex!important;flex-wrap:nowrap!important;gap:0!important;padding:0!important;background:var(--surface)!important;border:0!important;border-left:0!important;border-radius:14px!important;box-shadow:0 1px 3px rgba(20,29,43,.08),0 0 0 1px var(--line-2)!important;overflow:hidden}
html body main.main.main:has(.ibx2) .eh-bar .tb-row .tb-g>.tb-b,html body main.main.main:has(.ibx2) .eh-bar .tb-row .tb-g>.tb-m{flex:0 0 auto!important;min-width:0}
html body main.main.main:has(.ibx2) .eh-bar .tb-row .tb-b{flex-direction:row!important;height:38px!important;min-height:0!important;padding:0 12px!important;gap:6px!important;border-radius:0!important;font-size:13px!important;font-weight:700!important;line-height:1!important;white-space:nowrap!important;color:var(--ink-3)!important;background:transparent!important;box-shadow:none!important}
html body main.main.main:has(.ibx2) .eh-bar .tb-row .tb-b svg{width:16px!important;height:16px!important;color:inherit!important}
html body main.main.main:has(.ibx2) .eh-bar .tb-row .tb-b:hover:not(:disabled){color:var(--ink)!important;background:color-mix(in srgb,var(--fbs-blue) 10%,var(--surface))!important}
html body main.main.main:has(.ibx2) .eh-bar .tb-row .tb-b.danger{color:var(--danger)!important}
html body main.main.main:has(.ibx2) .eh-bar .tb-row .tb-b.primary{color:#fff!important;background:var(--accent)!important}
html body main.main.main:has(.ibx2) .eh-bar .tb-row .tb-b.ai{color:#fff!important;background:var(--ai-grad)!important}
html body main.main.main:has(.ibx2) .eh-bar .tb-row .tb-sec-l{display:none!important}
/* page-top buttons are all the same button (no bare text buttons next to boxed ones) */
main.main :is(.page-head, .ibx2-head) .btn.ghost{background:var(--surface);border-color:var(--line);color:var(--ink)}
main.main :is(.page-head, .ibx2-head) .btn.ghost:hover{border-color:var(--accent);color:var(--accent)}
/* search boxes: short words that fit, and if a box is ever too narrow the text ends with "…" instead of being cut
   (Oct 21, Nick: "I hate how it cuts off… it's messy") */
.app input{text-overflow:ellipsis}
.app input::placeholder{text-overflow:ellipsis;opacity:1;color:var(--ink-3)}
/* search (Oct 21, Nick: "much more informative") */
.sx-ai{display:flex;flex-wrap:wrap;gap:4px 10px;align-items:baseline;background:var(--surface);border-radius:14px;box-shadow:0 1px 3px rgba(20,29,43,.08),0 0 0 1px var(--line-2);padding:10px 14px;margin:0 0 14px;font-size:13.5px;line-height:1.5}
.sx-ai > b{color:var(--fbs-blue)}
.sx-ai-refs{display:flex;flex-wrap:wrap;gap:6px;flex-basis:100%}
.sx-ai-refs a{font-size:12px;font-weight:600;color:var(--accent);background:var(--accent-soft);border-radius:99px;padding:2px 9px;text-decoration:none}
.sx-cust{margin:0 0 16px}
.sx-cust-h{display:flex;align-items:center;gap:12px;margin:0 0 8px}
.sx-cust-t{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.sx-cust-t b{font-size:17px;color:var(--ink)}
.sx-cust-t a{text-decoration:none}
.sx-cust-t .faint{font-size:13px}
.sx-sec{margin:0 0 18px}
.sx-sec h3{font-size:14px;font-weight:700;margin:0 0 8px;display:flex;gap:8px;align-items:baseline}
.sx-sec h3 .faint{font-size:12.5px;font-weight:500}
.sx-job{display:flex;align-items:center;gap:10px}
.sx-th{flex:none;width:34px;height:34px;border-radius:6px;background:var(--surface-2);overflow:hidden;display:grid;place-items:center}
.sx-th img{width:100%;height:100%;object-fit:contain}
.sx-art{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}
.sx-art-i{display:flex;flex-direction:column;gap:4px;background:var(--surface);border-radius:12px;box-shadow:0 0 0 1px var(--line-2);padding:8px;text-decoration:none;color:var(--ink)}
.sx-art-i:hover{box-shadow:0 0 0 1px var(--accent)}
.sx-art-p{height:100px;border-radius:8px;background:#fff;border:1px solid var(--line-2);display:grid;place-items:center;overflow:hidden}
.sx-art-p img{max-width:100%;max-height:100%;object-fit:contain}
.sx-art-i b{font-size:12.5px}
.sx-msg{white-space:normal!important;max-width:640px;color:var(--ink-2)}

/* ===== Phones, after the one-look changes (Oct 21, Nick: "look at what we did to the mobile phone… it looks really
   funky now") ===== */
@media (max-width:760px){
  /* a garment: style and brand, the description, then each color with its sizes, then qty / each / total */
  .ord .gl-list .gl{display:flex;flex-direction:column;gap:8px}
  .ord .gl-list .gl .gl-sty{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:6px;max-width:none;width:100%}
  .ord .gl-list .gl .gl-sty > *{grid-area:auto!important;min-width:0}
  .ord .gl-list .gl .gl-sty .a-de{grid-column:1 / -1!important}
  .ord .gl-list .gl > .gl-row.gl-r2{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;grid-template-areas:"co co co x" "sz sz sz sz" "cs qt ea to"!important;gap:8px;align-items:end}
  .ord .gl-list.ws .gl > .gl-row.gl-r2{grid-template-areas:"co co co x" "sz sz sz sz" "qt ea to to"!important}
  .ord .gl-list .gl > .gl-row.gl-r2 > *{padding-top:0!important}
  .ord .gl-list .gl > .gl-row.gl-r2 .a-sz .szrow{margin:0}
  .ord .gl-list .gl.same{padding-top:6px}
  /* tab bars and toolbars on a phone: one row you can swipe, never two or three rows (Oct 21, Nick: "these 3 or 4 line
     toolbars everywhere") */
