/* the line description: plain text under the line, from the style column; a box only while typing (Oct 22, Nick: "it
   looks bad") */
html body .ord .line-b .gl > .gl-note textarea{box-sizing:border-box;width:calc(100% + 8px);margin-left:-8px;field-sizing:content;min-height:0;resize:none;font:13px/1.4 var(--body);color:var(--ink-2);padding:3px 7px;border:1px solid transparent;border-radius:var(--r);background:transparent;box-shadow:none;outline:0;overflow:hidden}
html body .ord .line-b .gl > .gl-note textarea:hover{border-color:var(--line)}
html body .ord .line-b .gl > .gl-note textarea:focus{border-color:var(--accent);background:var(--surface)}
/* the version under the logo for everyone but the owner (Oct 22) */
/* the version above Sign out for everyone (Oct 22): floats over the bar's top edge, so the bar keeps its height */
.side-user{position:relative}
.nav-ver-all{position:absolute;right:8px;bottom:100%;margin-bottom:2px;line-height:1;pointer-events:auto}
.nav-ver-all .ver-tag{font-size:11px;color:var(--side-ink,#9aa3b2);opacity:1;display:inline-block;white-space:nowrap}
.side.mini .nav-ver-all{display:none}
/* ---- Separation studio by job (Oct 22, Nick: "it should just be the jobs… front, back… this whole left side looks
   terrible… remove the scrolling and make it expand out") ---- */
.sep-locs2{gap:8px;flex-wrap:wrap}
.sep-locs2 .sep-loc{flex-direction:row;align-items:center;gap:10px;padding:6px 12px 6px 6px;min-width:150px;position:relative}
.sep-loc-pic{width:46px;height:46px;flex:none;border-radius:8px;background:var(--surface-2);border:1px solid var(--line);overflow:hidden;display:grid;place-items:center}
.sep-loc-pic img{width:86%;height:86%;object-fit:contain}
.sep-loc-t{display:flex;flex-direction:column;gap:1px;min-width:0}
.sep-loc-t b{font-size:14px;font-weight:700;color:var(--ink);white-space:nowrap}
.sep-loc-t small{font-size:12px;color:var(--ink-3);white-space:nowrap}
.sep-loc-g{font-weight:500}
.sep-loc-ed{border:0;background:none;color:var(--ink-3);cursor:pointer;padding:2px 4px;font-size:13px;align-self:flex-start}
.sep-loc-ed:hover{color:var(--accent)}
.sep-rename.sm{font-size:13px;width:130px}
.sep-topbar .sep-tabs{margin-left:auto}
/* the left cards: all of them, stacked, the column grows instead of scrolling */
.sep-grid{align-items:start}
.sep-grid>.sep-side:first-child{height:auto;min-height:0}
@media (min-width:1251px){.sep-grid{grid-template-columns:290px minmax(0,1fr) 320px}}
.sep-pane-all{flex:none;overflow:visible;min-height:0}
.sep-mocks button{display:flex;flex-direction:column;gap:3px;color:var(--ink-3);font-size:11.5px;min-width:0;border:0;background:none;padding:0;cursor:zoom-in;text-align:left}
.sep-mocks button:hover img{border-color:var(--accent)}
/* the inks and the proof's views on one line */
.sep-vbar.full{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;margin:10px 0 6px}
main.main .sep-vbar.full>.rv-seg{width:auto!important}
.sep-inkbar .sep-count{align-self:center}
.sep-inkbar>.btn.sm{align-self:center}
@media (max-width:760px){main.main .sep-vbar.full>.rv-seg{width:100%!important}main.main .sep-vbar.full>.rv-seg>button{flex:1 1 0!important}}
/* the settings: one line each, the rest behind the chevron (Oct 22, Nick) */
.sep-set{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:2px 12px}
.sep-sr{padding:8px 0;border-top:1px solid var(--line-2,var(--line))}
.sep-sr:first-child{border-top:0}
.sep-sr-h{display:grid;grid-template-columns:64px minmax(0,1fr) 22px;align-items:center;gap:8px;min-height:30px}
.sep-sr-l{font-size:12.5px;font-weight:700;color:var(--ink);white-space:nowrap}
.sep-sr-m{display:flex;align-items:center;gap:6px;min-width:0}
.sep-sr-m>select{flex:1;min-width:0}
.sep-sr-m .sep-row{flex:1;min-width:0}
.sep-sr-m .sep-row select{flex:1;min-width:0}
.sep-sr-m .sep-shirt-sw{width:30px;height:28px}
main.main .sep-sr-m>.rv-seg{flex:1 1 auto!important;min-width:0;display:flex!important;flex-wrap:nowrap!important;width:auto!important;border-radius:10px;overflow:hidden!important}
main.main .sep-sr-m>.rv-seg>button{flex:1 1 0!important;min-width:0;padding:6px 4px!important;font-size:12.5px!important;justify-content:center;overflow:hidden;text-overflow:ellipsis}
.sep-sr-m>select{min-width:84px}
.sep-sr-m>.btn{flex:none;white-space:nowrap}
.sep-sr-num{display:flex;align-items:center;gap:5px;font-size:12.5px;color:var(--ink-3);white-space:nowrap}
.sep-sr-num input{width:62px}
.sep-sr-sum{font-size:12px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.sep-sr-num+.sep-sr-sum{margin-left:auto}
.sep-sr-more{border:0;background:none;color:var(--ink-3);width:22px;height:22px;padding:0;display:grid;place-items:center;border-radius:6px;cursor:pointer}
.sep-sr-more:hover{color:var(--accent);background:var(--surface-2)}
.sep-sr-more.none{cursor:default;background:none}
.sep-sr.open .sep-sr-more svg{transform:rotate(180deg)}
.sep-sr-b{display:flex;flex-direction:column;gap:8px;padding:8px 0 2px}
.sep-sr>.sep-help,.sep-sr>.sep-tip,.sep-sr>.sep-multi2{margin-top:6px}
.sep-multi2{font-size:12px;color:var(--ink-3);line-height:1.45}
/* the mockups on the job line, between the print tabs and Separations / Coach */
.sep-mockstrip{display:flex;gap:6px;align-items:center;margin:0 auto;padding:5px 6px 5px 12px;background:var(--surface);border:1px solid var(--line);border-radius:10px}
.sep-mockstrip-l{display:flex;flex-direction:column;line-height:1.25;margin-right:6px;white-space:nowrap}
.sep-mockstrip-l b{font-size:13px;font-weight:700;color:var(--ink)}
.sep-mockstrip-l small{font-size:12px;color:var(--ink-3)}
.sep-mockstrip>button{width:46px;height:46px;padding:0;border:1px solid var(--line);border-radius:8px;background:var(--surface-2);cursor:zoom-in;overflow:hidden;flex:none}
.sep-mockstrip>button:hover{border-color:var(--accent)}
.sep-mockstrip img{width:100%;height:100%;object-fit:cover;display:block}
.sep-mockstrip+.sep-tabs{margin-left:0}
/* half screen: the settings stay beside the proof, screens and films under them */
@media (max-width:1250px){
  .sep-grid{grid-template-columns:250px minmax(0,1fr)}
  .sep-grid>.sep-side:last-child{grid-column:1/-1}
}
/* phone: the proof first, then the settings */
@media (max-width:760px){
  .sep-grid{grid-template-columns:minmax(0,1fr)}
  .sep-grid>.sep-main{order:1}
  .sep-grid>.sep-side:first-child{order:2}
  .sep-grid>.sep-side:last-child{order:3}
  .sep-mockstrip{margin:0}
}
/* the zoomed picture's close button */
.pz-in{position:relative;width:auto;max-width:min(920px,100%)}
.pz-in .mkz-pic{overflow:hidden;padding:16px 56px}
.pz-in .mkz-pic img{width:auto;height:auto;max-width:100%;max-height:calc(100vh - 150px);object-fit:contain}
.pz-x{position:absolute;top:10px;right:10px;z-index:2;width:36px;height:36px;border-radius:50%;border:1px solid var(--line);background:var(--surface);color:var(--ink);font-size:16px;line-height:1;cursor:pointer;display:grid;place-items:center}
.pz-x:hover{border-color:var(--accent);color:var(--accent)}
.pz-cap{font-weight:700;color:var(--ink)}
/* the Separations list by job: a picture per print, its spot under it */
.sep-qj{grid-template-columns:auto minmax(0,1fr) auto}
.sep-qps{display:flex;gap:8px}
.sep-qp{display:flex;flex-direction:column;align-items:center;gap:3px;width:84px}
.sep-qp .sep-qt{width:84px;height:84px}
.sep-qsame{display:inline-flex;align-items:center;gap:4px;align-self:flex-start;margin-top:3px;font-size:12px;font-weight:600;color:var(--accent);background:var(--accent-soft);border-radius:6px;padding:1px 7px;white-space:nowrap}
.sep-qsame i{width:9px;height:9px;border-radius:50%;box-shadow:0 0 0 1px var(--line)}
.sep-qp small{font-size:11.5px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}
.sep-qp .sep-qt{position:relative;border:1px solid var(--line)}
.sep-qp .sep-qt img{max-width:86%;max-height:86%}
.sep-qdots{position:absolute;right:3px;bottom:3px;display:flex;gap:2px}
.sep-qdots i{width:9px;height:9px;border-radius:50%;border:1.5px solid #fff;box-shadow:0 0 0 1px rgba(0,0,0,.18)}
@media (max-width:640px){.sep-qj{grid-template-columns:minmax(0,1fr) auto}.sep-qj .sep-qps{grid-column:1/-1;flex-wrap:wrap}}
/* separations: the order's mockups, so the film room sees what the print is for (Oct 22) */
.sep-mocks{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:8px}
.sep-mocks a{display:flex;flex-direction:column;gap:3px;text-decoration:none;color:var(--ink-3);font-size:11.5px;min-width:0}
.sep-mocks img{width:100%;aspect-ratio:1;object-fit:contain;background:var(--surface-2);border:1px solid var(--line);border-radius:var(--r)}
.sep-mocks span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
/* a customer's mockup sheet, to confirm (Oct 22): the art cut off it on a checkerboard (its background is gone), the specs read off it */
.ap-specs{margin:6px 0 2px;padding-left:18px;font-size:13px;color:var(--ink)}
.ap-specs li{margin:2px 0}
.ap-sw{display:inline-block;width:11px;height:11px;border-radius:3px;vertical-align:-1px;box-shadow:0 0 0 1px var(--line)}
.ap-pic.ap-check{background:repeating-conic-gradient(#e9edf2 0 25%,#fff 0 50%) 0 0/16px 16px}
/* where each file comes from: the email, or the old Printavo job (Oct 22) */
.ap-src{margin:10px 0 4px;font-family:var(--body);font-size:13px;font-weight:700;color:var(--ink)}
.ap-src .faint{font-weight:400;font-size:12px}
.ap-sent-old .ap-sent-i{max-width:120px}
/* the cut-out art on a dark checkerboard: light inks (cream, white) show */
.ap-pic.ap-check{background:repeating-conic-gradient(#3a3f47 0 25%,#2c3036 0 50%) 0 0/16px 16px}
/* hold to see a customer mockup without its stamp (Oct 22) */
.pv-zoom-bar .pv-peek{all:unset;cursor:pointer;user-select:none;-webkit-user-select:none;touch-action:none;font-weight:700;font-size:13px;color:#fff;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.4);border-radius:8px;padding:6px 12px}
.pv-zoom-bar .pv-peek.on{background:var(--accent);border-color:var(--accent)}

/* ClickUp Jobs (app/shop/clickup, Oct 22): the job being processed, as a panel over the list */
.cu-head-acts{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.cu-checked{margin:-6px 0 12px;font-size:12.5px}
.cu-job{margin-bottom:16px}
.cu-job .panel-h{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap}
.cu-title{font-size:14px;font-weight:700;color:var(--ink)}
.cu-line{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-top:4px;font-size:14px;color:var(--ink)}
.cu-tags{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}
.cu-tag{display:inline-block;font-size:12px;padding:2px 8px;border-radius:999px;background:var(--surface-2);color:var(--ink-2);white-space:nowrap}
.cu-notes{margin:12px 0 0;white-space:pre-wrap;font-size:14px;color:var(--ink);max-height:240px;overflow:auto}
.cu-sec{margin-top:14px}
.cu-k{font-size:12px;color:var(--ink-3);margin-bottom:4px}
.cu-files,.cu-comments{margin:0;padding-left:18px;font-size:14px}
.cu-files li,.cu-comments li{margin:2px 0}
.cu-comments li>div{white-space:pre-wrap;color:var(--ink)}
.cu-cust{display:flex;flex-direction:column;gap:4px;padding:10px 12px;border-radius:var(--r);background:var(--accent-soft)}
.cu-cust select{margin-left:6px;max-width:100%}
.cu-ask{margin-top:16px;padding-top:12px;border-top:1px solid var(--line);display:flex;flex-direction:column;gap:8px}
.cu-acts{display:flex;gap:8px;flex-wrap:wrap}
.cu-done{margin-top:16px;padding:10px 12px;border-radius:var(--r);background:var(--accent-soft);display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:14px}
.cu-bad{color:var(--danger)}
.cu-nw{white-space:nowrap}
tr.cu-off td{color:var(--ink-3)}
.cu-known{display:flex;gap:16px;flex-wrap:wrap;margin-top:10px;font-size:14px;color:var(--ink)}
.cu-job .mf-tray{margin:0}
/* ClickUp Jobs: the customer band on the left of its jobs (Oct 22, Nick: "something on the left that shows the grouping") */
.tbl tr.cu-gstart > td{border-top:1px solid var(--line)}
.tbl td.cu-rail{vertical-align:top;background:var(--surface-2);border-left:3px solid var(--fbs-blue);border-radius:0;min-width:150px;cursor:default}
.cu-rail-c{font-weight:700;color:var(--ink)}
.cu-rail-n{display:inline-block;margin-top:6px;font-size:12px;font-weight:700;padding:1px 8px;border-radius:999px;background:var(--accent-soft);color:var(--accent);white-space:nowrap}
/* ClickUp workspace view (Oct 22): the whole workspace, by board, like ClickUp's list */
.cu-ws-t{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;font-size:14px;color:var(--ink)}
.tbl th.cu-box-h{white-space:nowrap}
.tbl td.cu-box{text-align:center;color:var(--ok)}
.tbl tr.cu-done-row td:not(.cu-rail){color:var(--ink-3)}
/* New email (components/NewEmail.tsx, Oct 22) */
.ne-panel{margin-bottom:14px}
.ne-box{border-top:0;background:var(--surface);gap:8px}
.ne-to{position:relative}
.ne-hits{position:absolute;top:100%;left:40px;right:0;z-index:30;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:0 6px 20px rgba(20,29,43,.12);display:flex;flex-direction:column;max-height:260px;overflow:auto}
.ne-hits button{text-align:left;background:none;border:0;padding:7px 10px;font:inherit;font-size:13px;color:var(--ink);cursor:pointer}
.ne-hits button:hover,.ne-hits button:focus{background:var(--surface-2)}
.ne-files{display:flex;flex-wrap:wrap;gap:6px 12px;font-size:13px;color:var(--ink)}
.ne-file{display:inline-flex;gap:6px;align-items:baseline;padding:3px 8px;border:1px solid var(--line);border-radius:var(--r)}
/* ClickUp lists fill the window, no sideways scroll (Oct 22, Nick): fixed columns, the job name wraps */
.tbl-wrap.cu-fit{overflow-x:hidden}
.tbl.cu-tbl{table-layout:fixed;width:100%}
.tbl.cu-tbl td{overflow-wrap:anywhere}
.tbl.cu-tbl th.cu-w-rail{width:170px}
.tbl.cu-tbl th.cu-w-due{width:96px}
.tbl.cu-tbl th.cu-w-files{width:84px}
.tbl.cu-tbl th.cu-w-pv{width:130px}
.tbl.cu-tbl th.cu-w-ours{width:72px}
.tbl.cu-tbl th.cu-w-added{width:132px}
.tbl.cu-tbl th.cu-w-status{width:130px}
.tbl.cu-tbl th.cu-w-act{width:118px}
.tbl.cu-tbl th.cu-box-h{width:92px;white-space:normal;line-height:1.2}
/* a new customer (or board) starts with a blue bar and a little space (Oct 22, Nick: "they look to run together") */
.tbl.cu-tbl tbody tr.cu-gstart:not(:first-child) > td{border-top:3px solid var(--fbs-blue);padding-top:14px}
@media (max-width:1100px){.tbl.cu-tbl th.cu-w-added{width:0;padding:0;font-size:0}.tbl.cu-tbl td.cu-added{display:none}.tbl.cu-tbl th.cu-w-rail{width:140px}}
/* ClickUp priority flags (Oct 22): Urgent red, High amber, like ClickUp's */
.cu-flag{display:inline-flex;align-items:center;gap:3px;margin-left:8px;font-size:12px;font-weight:700;white-space:nowrap;vertical-align:1px}
.cu-flag svg{width:13px;height:13px;fill:currentColor;stroke:currentColor;stroke-width:1.5;stroke-linejoin:round}
.cu-flag.urgent{color:var(--danger)}
.cu-flag.high{color:var(--warn)}
/* ClickUp tables: text wraps inside its column (the shop rule keeps every row's first cell on one line, which is the
   customer band here, and the job name in the rows under it), so nothing runs into the next column (Oct 22) */
html body main.main .tbl.cu-tbl td{white-space:normal}
html body main.main .tbl.cu-tbl td.cu-nw,html body main.main .tbl.cu-tbl td.r{white-space:nowrap}
/* ClickUp tables: drag a header's right edge to resize the column (Oct 22) */
.tbl.cu-tbl th{position:relative}
.cu-rsz{position:absolute;top:0;right:-4px;width:9px;height:100%;cursor:col-resize;z-index:2}
.cu-rsz::after{content:"";position:absolute;top:25%;bottom:25%;left:4px;width:1px;background:var(--line)}
.cu-rsz:hover::after,body.cu-resizing .cu-rsz::after{background:var(--fbs-blue);width:2px}
body.cu-resizing{cursor:col-resize;user-select:none}
/* a ClickUp check box you can tick from the workspace view */
.cu-boxbtn{width:20px;height:20px;padding:0;border:1.5px solid var(--line);border-radius:5px;background:var(--surface);display:inline-flex;align-items:center;justify-content:center;cursor:pointer;vertical-align:middle}
.cu-boxbtn:hover{border-color:var(--fbs-blue)}
.cu-boxbtn.on{background:var(--fbs-blue);border-color:var(--fbs-blue)}
.cu-boxbtn svg{width:14px;height:14px;fill:none;stroke:#fff;stroke-width:2.6;stroke-linecap:round;stroke-linejoin:round}
/* ClickUp Jobs: the toolbar and column headings pinned to the top while the list scrolls (Oct 22) */
.toolbar.cu-pinned{position:sticky;top:0;z-index:16;background:var(--bg);margin:0;padding:10px 0}
.tbl-wrap.cu-fit.cu-pinhead{overflow:visible}
.tbl-wrap.cu-pinhead .tbl.cu-tbl thead th{position:sticky;top:var(--cu-th-top,0px);z-index:12;background:var(--surface);box-shadow:0 1px 0 var(--line),0 2px 6px rgba(20,29,43,.06)}
.tbl-wrap.cu-pinhead .tbl.cu-tbl thead th:first-child{border-top-left-radius:var(--r)}
.tbl-wrap.cu-pinhead .tbl.cu-tbl thead th:last-child{border-top-right-radius:var(--r)}
.cu-pin{display:inline-flex;align-items:center;gap:5px;height:34px;padding:0 12px;border:0;border-radius:14px;background:var(--surface);box-shadow:0 1px 3px rgba(20,29,43,.08),0 0 0 1px var(--line-2);font:inherit;font-size:13px;font-weight:600;color:var(--ink-2);cursor:pointer;white-space:nowrap}
.cu-pin svg{width:15px;height:15px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linejoin:round}
.cu-pin.on{color:var(--fbs-blue)}
.cu-pin.on svg{fill:currentColor}
/* ClickUp tables: borders drawn per cell (not by the table), and the band's blue edge drawn inside the cell, so a pinned
   heading covers the rows cleanly (Oct 22, Nick: "this blue line oddity to the left of the Customer" heading) */
.tbl.cu-tbl{border-collapse:separate;border-spacing:0}
.tbl.cu-tbl td.cu-rail{border-left:0;box-shadow:inset 3px 0 0 var(--fbs-blue)}
/* ClickUp Jobs: an FBS invoice that started in Printavo (Oct 22, Nick: "a little symbol" by orders from Printavo) */
.cu-pvtag{display:inline-block;margin-left:6px;font-size:11px;font-weight:700;line-height:16px;padding:0 6px;border-radius:999px;background:var(--warn-soft);color:var(--warn);vertical-align:1px;white-space:nowrap}
/* ClickUp Jobs: one FBS invoice column, each number tagged New system (portal) or Old system (Printavo) (Oct 22) */
.tbl.cu-tbl th.cu-w-inv{width:190px}
.cu-inv{display:flex;flex-direction:column;gap:3px}
.cu-inv-r{display:flex;align-items:baseline;flex-wrap:wrap;gap:0 6px}
.cu-inv-s{flex-basis:100%}
.cu-sys{display:inline-block;font-size:11px;font-weight:700;line-height:16px;padding:0 6px;border-radius:999px;white-space:nowrap}
.cu-sys.new{background:var(--accent-soft);color:var(--accent)}
.cu-sys.old{background:var(--warn-soft);color:var(--warn)}
.cu-known{align-items:baseline}
/* the pinned heading had rounded top corners; with rows scrolled under it, the customer band's blue edge showed through
   that corner and down beside it (Oct 22, Nick: "this blue line oddity"). Square corners, and the table's box clips to
   its own rounded edge (clip keeps the heading pinnable, unlike hidden) */
.tbl-wrap.cu-pinhead .tbl.cu-tbl thead th:first-child,.tbl-wrap.cu-pinhead .tbl.cu-tbl thead th:last-child{border-radius:0}
.tbl-wrap.cu-fit.cu-pinhead{overflow:clip}
/* the resize handle sits inside its own heading: hanging over the next one, the next (pinned) heading covered it and
   only a pixel could be grabbed (Oct 22, Nick: "the cursor jumps and it doesn't just move it over") */
.cu-rsz{right:0;width:10px}
.cu-rsz::after{left:auto;right:0}
/* measuring a column's natural width for double-click fit (one synchronous pass, never painted) */
.tbl.cu-tbl.cu-measure{table-layout:auto!important;width:auto!important}
.tbl.cu-tbl.cu-measure th,.tbl.cu-tbl.cu-measure td{white-space:nowrap!important;width:auto!important;min-width:0!important}
/* ClickUp Jobs: a board heading inside a customer with several boards (Cedar: Bulk Orders, then Cart Orders) (Oct 22) */
.tbl.cu-tbl tr.cu-boardrow > td:not(.cu-rail){background:var(--surface-2);font-size:12.5px;font-weight:700;color:var(--ink-2);padding-top:7px;padding-bottom:7px;text-transform:none;letter-spacing:0}
.cu-rail-b{margin-top:6px}
/* ClickUp Jobs: a Printavo job = a small Printavo-blue bubble with its P (Oct 22, Nick: "this little logo in blue, the
   Printavo blue… a little small bubble"); the icon is public/brand/printavo-p.png (Nick's file, white on transparent) */
.cu-sys.pv{--pv-blue:#1E9BD7;display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;padding:0;border-radius:50%;background:var(--pv-blue);vertical-align:-3px}
.cu-sys.pv img{width:12px;height:12px;display:block}
/* ClickUp Jobs on a phone (Oct 22, Nick: "looks really bad in iPhone mode"): its own card layout (the tables are
   data-keep, so MobileTables leaves them alone). Each customer's band becomes a header across the card, each job a
   card: name and flag, then due · files · FBS INV#, the button on the right; board headings full width. */
@media (max-width: 700px){
  .tbl-wrap.cu-fit{border-radius:var(--r)}
  .tbl.cu-tbl,.tbl.cu-tbl tbody{display:block;width:100%!important;table-layout:auto!important}
  .tbl.cu-tbl thead{display:none}
  html body main.main .tbl.cu-tbl tr{display:flex;flex-wrap:wrap;align-items:center;gap:4px 12px;padding:10px 12px;border-bottom:1px solid var(--line-2)}
  html body main.main .tbl.cu-tbl td{display:block;border:0!important;padding:0!important;width:auto!important;min-width:0!important;background:transparent;white-space:normal!important}
  html body main.main .tbl.cu-tbl tbody tr.cu-gstart:not(:first-child) > td{border-top:0!important;padding-top:0!important}
  html body main.main .tbl.cu-tbl tbody tr.cu-gstart:not(:first-child){border-top:3px solid var(--fbs-blue)}
  /* the customer (or board) band: a header strip across the top of its first card */
  html body main.main .tbl.cu-tbl td.cu-rail{flex:1 1 100%;order:-1;display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 10px;margin:-10px -12px 6px;padding:8px 12px!important;background:var(--surface-2);box-shadow:inset 3px 0 0 var(--fbs-blue)}
  .tbl.cu-tbl td.cu-rail .cu-rail-n{margin-top:0}
  .tbl.cu-tbl td.cu-rail .cu-rail-b{margin-top:0;flex-basis:100%}
  /* the job: full width first */
  html body main.main .tbl.cu-tbl tr:not(.cu-boardrow) > td:nth-child(1):not(.cu-rail),html body main.main .tbl.cu-tbl tr > td.cu-rail + td{flex:1 1 100%}
  /* board headings */
  html body main.main .tbl.cu-tbl tr.cu-boardrow{padding:6px 12px;background:var(--surface-2)}
  html body main.main .tbl.cu-tbl tr.cu-boardrow > td:not(.cu-rail){flex:1 1 100%;background:transparent}
  html body main.main .tbl.cu-tbl tr.cu-boardrow > td.cu-rail{margin:-6px -12px 6px}
  /* the small details in one line; Added hidden; the action button pushed right */
  .tbl.cu-tbl td.cu-added{display:none!important}
  html body main.main .tbl.cu-tbl td.r{margin-left:auto}
  .tbl.cu-tbl .cu-inv{flex-direction:row;flex-wrap:wrap;gap:2px 10px}
  .tbl.cu-tbl .cu-inv-s{display:none}
  /* workspace view: the ClickUp boxes say which box they are */
  html body main.main .tbl.cu-tbl td.cu-box{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:var(--ink-3)}
  html body main.main .tbl.cu-tbl td.cu-box::before{content:attr(data-box)}
  .cu-rsz{display:none}
  /* the toolbar: tabs scroll inside themselves only if they must; select and search full width */
  .toolbar.cu-pinned{padding:8px 0}
}
@media (max-width: 700px){
  /* the phone's own top bar is pinned already: here the toolbar scrolls with the page */
  .toolbar.cu-pinned{position:static}
  /* the tabs wrap onto a second line instead of running off the screen */
  html body main.main .toolbar.cu-pinned .chips{flex-wrap:wrap;width:100%;max-width:100%}
  html body main.main .toolbar.cu-pinned > select,html body main.main .toolbar.cu-pinned > :is(.si,.search-input,label){width:100%}
}
@media (max-width: 700px){
  /* the shop's tables keep a minimum width (cards then ran past the screen and hid the button): not these */
  html body main.main .tbl.cu-tbl,html body main.main .tbl.cu-tbl tbody,html body main.main .tbl.cu-tbl tr{min-width:0!important;width:100%!important;max-width:100%!important;box-sizing:border-box}
  /* the tabs wrap onto a second line (the shop's phone rule scrolls them sideways) */
  html body main.main .toolbar.cu-pinned .chips{flex-wrap:wrap!important;overflow:visible!important}
}
