.rq-pick-c small{font-size:12px;color:var(--ink-3)}
.rq-pick-img{width:100%;aspect-ratio:1;display:grid;place-items:center;background:#fff;border-radius:6px;overflow:hidden}
.rq-pick-img img{max-width:100%;max-height:100%;object-fit:contain}

