.ss-lab{text-align:center;white-space:nowrap;outline:none}
.ss-handle{position:absolute;right:-7px;bottom:-7px;width:14px;height:14px;border-radius:3px;background:#fff;border:2px solid var(--accent);cursor:nwse-resize;z-index:3}
