.ss-pick textarea{width:100%;font:inherit;font-size:14px;border:1px solid var(--line);border-radius:6px;padding:6px 8px;box-sizing:border-box}
.ss-pick input[type=text]{height:36px;border:1px solid var(--line);border-radius:6px;padding:0 10px;font:inherit;font-size:14px}
.ss-tip{margin:0;padding:10px;border:1px dashed var(--line);border-radius:var(--r);font-size:13px}
.ss-adds{display:flex;flex-wrap:wrap;gap:6px}
