.aa-payside .qp-chip{padding:2px 8px;font-size:11.5px;font-weight:600;line-height:1.5}

/* card / bank on file (Oct 24, Nick): saved ones to pick, and "Keep this on file" with its authorization */
.pp-saved{display:flex;flex-direction:column;gap:6px;margin-bottom:10px}
.pp-sv{display:flex;align-items:center;gap:10px;padding:8px 10px;border:1px solid var(--line);border-radius:6px;cursor:pointer;font-size:14px;background:var(--surface)}
.pp-sv.on{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 6%,var(--surface))}
.pp-sv small{color:var(--ink-3);font-size:12.5px}
