/* portal: their drafts, above the order lists (Oct 24, Nick) */
.aa-drafts{display:flex;align-items:center;gap:8px 14px;flex-wrap:wrap;padding:10px 14px;margin-bottom:12px;border:1px dashed var(--line);border-radius:10px;background:var(--surface);font-size:13.5px}
