.aa-draft .linkbtn.danger{color:var(--danger)}
/* a draft order (Oct 24, Nick): the bar under the title with Save / Discard */
.draft-bar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:10px 14px;margin:8px 0 4px;border:1px dashed color-mix(in srgb,var(--fbs-orange,#F7941D) 60%,var(--line));border-radius:10px;background:color-mix(in srgb,var(--fbs-orange,#F7941D) 7%,var(--surface));font-size:14px}
