.pdx-trk-t{display:flex;flex-direction:column;min-width:0;color:var(--ink);text-decoration:none}
.pdx-trk-t b{font-size:13.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pdx-trk-t small{font-size:12px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pdx-trk-h{font-size:12px;font-weight:700;padding:3px 10px;border-radius:999px;color:var(--sc);background:color-mix(in srgb,var(--sc) 14%,transparent);white-space:nowrap}
.pdx-trk .pd-link{grid-column:1 / -1;font-size:12.5px}
.pdx-track-none{margin:0;font-size:12.5px;color:var(--ink-3)}
/* the assistant's mic sits right beside Ask (Oct 24, Nick: it had floated off to the far right of the page) */
.pa-in .mic{position:static;transform:none;width:36px;height:36px;flex:none;border-radius:8px;color:var(--accent)}
.pa-in .mic:hover{background:var(--accent-soft)}
.pa-in .mic svg{width:18px;height:18px}
/* On hold: the stamp, the dashboard panel, the reason (Oct 24, Nick: "a visual that says on hold, like a stamp… see the reason why") */
.hold-stamp{display:inline-block;padding:3px 10px;border:2.5px solid var(--danger);border-radius:6px;color:var(--danger);font:800 12px/1.2 var(--display);text-transform:uppercase;letter-spacing:.08em;transform:rotate(-8deg);background:color-mix(in srgb,var(--surface) 88%,transparent);white-space:nowrap;pointer-events:none}
.hold-stamp.big{font-size:18px;padding:5px 16px;border-width:3px}
.pjr-stepsw{position:relative;display:block}
.pjr-stepsw>.hold-stamp{position:absolute;left:50%;top:40%;transform:translate(-50%,-50%) rotate(-8deg)}
.pjr-mid.held .pjs{opacity:.4;filter:grayscale(1)}
.pjr-now.hold{color:var(--ink)}
.pjr-now.hold>b{color:var(--danger)}
.hold-why{display:inline}
.hold-why summary{display:inline;cursor:pointer;color:var(--accent);font-weight:600;font-size:12.5px;list-style:none}
.hold-why summary::-webkit-details-marker{display:none}
.hold-why[open] summary{color:var(--ink-3)}
.hold-why p{margin:6px 0 0;padding:8px 10px;border-radius:8px;background:color-mix(in srgb,var(--danger) 7%,var(--surface));font-size:13px;color:var(--ink);white-space:pre-wrap}
.pdx-hold{margin-bottom:16px;border-color:color-mix(in srgb,var(--danger) 35%,var(--line))}
.pdx-hold-list{display:flex;flex-direction:column;gap:10px}
.pdx-hold-row{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:14px;align-items:start;padding:10px 12px;border:1px solid var(--line);border-radius:10px}
.pdx-hold-row>.hold-stamp{margin-top:4px}
.pdx-hold-t{display:flex;flex-direction:column;gap:2px;min-width:0}
.pdx-hold-t a{color:var(--ink);text-decoration:none}
.pdx-hold-t>span{font-size:13px;color:var(--ink-2,var(--ink))}
.pdx-hold-acts{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}
@media (max-width:700px){.pdx-hold-row{grid-template-columns:auto minmax(0,1fr)}.pdx-hold-acts{grid-column:1 / -1;justify-content:flex-start}}
.po-held .panel-b{position:relative}
.po-held .stepper{opacity:.45;filter:grayscale(1)}
.po-held .panel-b>.hold-stamp{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) rotate(-6deg);z-index:1}
.po-hold{display:flex;flex-direction:column;gap:8px}
/* the wholesale price list in the portal (Oct 24, Nick: "a nice version of the price list") */
.pl .pl-lead{margin:4px 0 16px;color:var(--ink-3);font-size:14px;max-width:760px}
.pl-sec{margin-bottom:16px}
.pl-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:var(--r)}
.pl-tbl{width:100%;border-collapse:collapse;font-size:14px;font-variant-numeric:tabular-nums}
.pl-tbl th,.pl-tbl td{padding:9px 14px;text-align:right;white-space:nowrap;border-bottom:1px solid var(--line-2,var(--line))}
.pl-tbl thead th{font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-3);font-weight:600;background:var(--surface-2)}
.pl-tbl th:first-child{text-align:left;position:sticky;left:0;background:var(--surface);font-weight:700;color:var(--ink)}
.pl-tbl thead th:first-child{background:var(--surface-2);color:var(--ink-3)}
.pl-tbl tbody tr:nth-child(even) td,.pl-tbl tbody tr:nth-child(even) th{background:color-mix(in srgb,var(--surface-2) 45%,var(--surface))}
.pl-tbl tbody tr:hover td{background:var(--accent-soft)}
.pl-tbl tbody tr:last-child th,.pl-tbl tbody tr:last-child td{border-bottom:0}
.pl-tbl td small{color:var(--ink-3);font-size:12px}
.pl-narrow{max-width:560px}
.pl-rules{margin:12px 0 0;padding-left:18px;display:flex;flex-direction:column;gap:5px;font-size:13.5px;color:var(--ink-2,var(--ink))}
.pl-two{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.pl-two .pl-sec{margin-bottom:16px}
@media (max-width:800px){.pl-two{grid-template-columns:1fr}}
.pl-dl{margin:0;display:flex;flex-direction:column}
.pl-dl>div{display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px solid var(--line-2,var(--line));font-size:14px}
.pl-dl>div:last-child{border-bottom:0}
.pl-dl dt{color:var(--ink)}
.pl-dl dd{margin:0;white-space:nowrap;font-variant-numeric:tabular-nums}
.pl-dl dd small{color:var(--ink-3);font-size:12px}
.pl-dl .tot{border-top:2px solid var(--line);border-bottom:0}
.pl-ex p{margin:0 0 6px;font-size:14px}
.pl-cols{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));column-gap:28px}
.pl-cols>div:last-child{border-bottom:1px solid var(--line-2,var(--line))}
.pl-notes{margin:0;padding-left:18px;display:flex;flex-direction:column;gap:6px;font-size:13.5px}
.pl-foot{margin:6px 0 24px;font-size:13px}
@media print{.pl .back,.pl .page-head .row,.p-head,.p-foot,header,footer,.preview-bar{display:none!important}.pl-sec{break-inside:avoid}.pl-tbl tbody tr:hover td{background:none}}
.pl-tabs{margin:0 0 14px}
@media print{.pl-tabs{display:none!important}}
/* On hold under Payments; Order tracking full width (Oct 24, Nick) */
.pdx .pdx-hold,.pdx .pdx-sent{margin-bottom:0}
.pdx-hold{border-color:var(--line)}
.pdx-hold.has{border-color:color-mix(in srgb,var(--danger) 35%,var(--line))}
.pdx-hold-n{display:inline-grid;place-items:center;min-width:22px;height:22px;padding:0 6px;border-radius:999px;background:var(--danger);color:#fff;font-size:12px;font-weight:700}
.pdx-col .pdx-hold-row{grid-template-columns:auto minmax(0,1fr);gap:10px}
.pdx-col .pdx-hold-acts{grid-column:1 / -1;justify-content:flex-start}
.pdx-col .pdx-hold-row>.hold-stamp{font-size:10px;padding:2px 7px}
.pdx-col .pdx-hold-list{max-height:320px;overflow:auto}
.pdx-track .pdx-track-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:10px}
.pl-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin:4px 0 4px}
.pl-head h2{margin:0;font-family:var(--display);font-size:20px}
@media print{.portal .aa-nav,.pl-head .row{display:none!important}}
/* the left column: the assistant, with Order tracking under it (Oct 24, Nick's mock-up) */
.pdx-left>.pdx-asst{flex:0 0 auto}
.pdx-left>.pdx-track{flex:1 1 auto}
.pdx-left .pdx-track .pdx-track-list{grid-template-columns:repeat(auto-fill,minmax(240px,1fr))}
.pdx-top>.pdx-col:not(.pdx-left)>.pdx-hold{flex:1 1 auto}
/* Orders sent to FBS, nothing waiting (Oct 24, Nick: "we're all caught up… a nice little graphic") */
.pdx-caught{display:flex;align-items:center;gap:14px;padding:6px 2px}
.pdx-caught svg{flex:0 0 auto}
.pdx-caught b{display:block;font-size:15px}
.pdx-caught span{display:block;font-size:13px;color:var(--ink-3);margin-top:2px}
/* portal: something on screen the moment a link is clicked (Oct 24) */
.p-loading{display:flex;flex-direction:column;gap:18px}
.p-sk{border-radius:14px;background:linear-gradient(90deg,var(--surface-2) 0%,var(--surface) 50%,var(--surface-2) 100%);background-size:200% 100%;animation:p-sk 1.1s ease-in-out infinite}
.p-sk-h{height:34px;width:min(320px,60%)}
.p-sk-row{display:grid;grid-template-columns:1.7fr 1fr;gap:18px}
.p-sk-card{height:180px}
.p-sk-card.wide{height:260px}
@keyframes p-sk{0%{background-position:100% 0}100%{background-position:-100% 0}}
@media (prefers-reduced-motion:reduce){.p-sk{animation:none}}
/* the customer's builder before a mockup: a small grayed outline of the prints (Oct 24, Nick) */
.mk-lock.need .mk-body{display:none}
.mk-need-sum{display:flex;flex-direction:column;gap:6px;padding:4px 0}
.mk-need-row{display:grid;grid-template-columns:70px minmax(0,1fr) 90px 70px;gap:10px;align-items:center;padding:9px 12px;border:1px dashed var(--line);border-radius:6px;background:var(--surface-2);color:var(--ink-3);font-size:13px}
.mk-need-row b{color:var(--ink-3);font-weight:600}
.mk-need-row span:nth-child(n+3){height:10px;border-radius:5px;background:var(--surface-3);color:transparent;overflow:hidden}
.mk-need-sum small{font-size:12.5px;color:var(--ink-3)}
/* order builder side cards, reworked (Oct 24, Nick: "these side panels look really bad… need to be rethought") */
.rq-card{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:14px 16px;display:flex;flex-direction:column;gap:8px}
.rq-card h3{margin:0;font-family:var(--display);font-size:15px;line-height:1.2;color:var(--ink)}
.rq-card>p{margin:-4px 0 4px;font-size:12.5px;color:var(--ink-3);line-height:1.4}
.rq-card .rq-card-busy{margin:0;font-size:12px;color:var(--accent)}
.rq-fast{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.rq-fast .rq-fast-o{flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:6px;padding:12px 8px;min-height:76px}
.rq-fast .rq-fast-o .ic{margin:0;width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:var(--accent-soft)}
.rq-fast .rq-fast-o b{font-size:13.5px}
.rq-draft{font-size:12px;font-weight:700;color:var(--ink-3);background:var(--surface-2);border:1px solid var(--line);padding:3px 10px;border-radius:999px}
.rq-missing{margin:0 0 4px;padding-left:18px;display:flex;flex-direction:column;gap:6px;font-size:14px}
/* the simple order form */
.so-row2{display:grid;grid-template-columns:minmax(0,1fr) 180px;gap:12px;align-items:start}
@media (max-width:640px){.so-row2{grid-template-columns:1fr}}
.so-seg{display:flex;flex-wrap:wrap;border:1px solid var(--line);border-radius:6px;overflow:hidden;width:max-content;max-width:100%}
.so-seg button{all:unset;cursor:pointer;height:34px;padding:0 14px;display:inline-flex;align-items:center;font:500 13.5px var(--body);color:var(--ink-2,var(--ink));border-right:1px solid var(--line);background:var(--surface)}
.so-seg button:last-child{border-right:0}
.so-seg button:hover{background:var(--surface-2)}
.so-seg button.on{background:var(--accent-soft);color:var(--accent);font-weight:700}
.so-seg button:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
.so-toggle{display:inline-flex;align-items:center;gap:10px;font-size:14px;cursor:pointer;width:max-content}
.so-toggle input{position:absolute;opacity:0;width:1px;height:1px}
.so-sw{width:36px;height:20px;border-radius:999px;background:var(--surface-3);position:relative;transition:background .15s;flex:0 0 auto}
.so-sw::after{content:"";position:absolute;top:2px;left:2px;width:16px;height:16px;border-radius:50%;background:#fff;box-shadow:0 1px 2px rgba(0,0,0,.2);transition:transform .15s}
.so-toggle input:checked+.so-sw{background:var(--accent)}
.so-toggle input:checked+.so-sw::after{transform:translateX(16px)}
.so-toggle input:focus-visible+.so-sw{outline:2px solid var(--accent);outline-offset:2px}
.so-goods{padding:12px;border:1px solid var(--line-2,var(--line));border-radius:8px;background:color-mix(in srgb,var(--surface-2) 40%,var(--surface))}
/* Mockup Creator: their own garment photos, and the close-up eyedropper (Oct 24, Nick) */
.mk-own b{display:block;font-size:14px;line-height:36px;height:36px;padding:0 10px;border:1px dashed var(--line);border-radius:6px;background:var(--surface-2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mk-own-add{all:unset;cursor:pointer;display:inline-flex;align-items:center;height:30px;padding:0 10px;border:1px dashed var(--line);border-radius:999px;font-size:12.5px;color:var(--accent)}
.mk-own-add:hover{border-color:var(--accent)}
.mk-own-dlg{width:min(560px,100%)}
.mk-own-pics{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}
.mk-own-pic{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;aspect-ratio:4/5;border:1.5px dashed var(--line);border-radius:10px;background:var(--surface-2);cursor:pointer;color:var(--accent);font-weight:600;font-size:13.5px;overflow:hidden}
.mk-own-pic:hover{border-color:var(--accent)}
.mk-own-pic.has{border-style:solid;background:#fff}
.mk-own-pic img{max-width:100%;max-height:85%;object-fit:contain}
.mk-own-pic small{font-size:11.5px;color:var(--ink-3);font-weight:400}
.mk-cu-h{position:relative}
.mk-cu-eye{display:inline-flex;align-items:center;gap:3px;margin-left:auto}
.mk-cu-eyeb{all:unset;cursor:pointer;display:inline-flex;align-items:center;gap:4px;height:22px;padding:0 6px;border:1px solid var(--line);border-radius:6px;background:var(--surface);color:var(--ink-3)}
.mk-cu-eyeb:hover{border-color:var(--accent);color:var(--accent)}
.mk-cu-eyeb .sw{width:12px;height:12px;border-radius:3px;border:1px solid rgba(0,0,0,.15)}
.mk-cu-eyer{all:unset;cursor:pointer;font-size:13px;color:var(--ink-3);padding:0 3px}
.mk-cu-eyer:hover{color:var(--accent)}
/* the same-art check (Oct 24, Nick) */
.same-art{width:min(560px,100%)}
.same-art-pics{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:6px 0 4px}
.same-art-pics figure{margin:0;display:flex;flex-direction:column;gap:6px}
.same-art-pics figure>div{aspect-ratio:4/3;border:1px solid var(--line);border-radius:10px;background:#fff;display:grid;place-items:center;overflow:hidden;padding:10px}
.same-art-pics img{max-width:100%;max-height:100%;object-fit:contain}
.same-art-pics figcaption{font-size:13px;text-align:center}
.same-art-pics small{color:var(--ink-3)}
/* Tag Print under the prints, on the right (Oct 24, Nick) */
.tagp-sec{display:flex;flex-direction:column;align-items:flex-end;margin-top:10px}
.tagp-sec.on{align-items:stretch}
.tagp-sec .tagp-cb{margin-left:0}
/* shop: charge the customer's card on file (Oct 24) */
.cof{display:flex;flex-direction:column;gap:6px;padding:10px 12px;border:1px solid var(--line);border-radius:var(--r);background:var(--surface-2)}
.cof-h{display:flex;flex-direction:column;gap:2px;font-size:13.5px}
.cof-h .faint{font-size:12px}
.cof-row{display:flex;gap:8px;flex-wrap:wrap}
.cof-row select{flex:1 1 200px;min-width:0}
.cof-row input{width:110px}
/* portal Settings: payment methods (Oct 24, Nick) */
.ps-card-t{display:flex;flex-direction:column;gap:3px;min-width:0}
.ps-card-t small{font-size:12px;color:var(--ink-3)}
.ps-card-t .ps-card-ok{color:var(--ok)}
.ps-card-ask{display:flex;flex-wrap:wrap;gap:6px;align-items:center;max-width:560px;line-height:1.4}
.apm{display:flex;flex-direction:column;gap:10px;padding:12px;border:1px solid var(--line);border-radius:var(--r);background:var(--surface)}
.apm-ok{align-items:flex-start;font-size:13px;line-height:1.45}
.apm-ok input{margin-top:3px}
/* Skip the form: Place a reorder (Oct 24, Nick) */
.rq-fast-wide{flex-direction:row!important;min-height:44px!important;margin-top:8px;gap:10px!important}
.rq-fast-wide .ic{width:28px!important;height:28px!important}
.rq-re{width:min(600px,100%);display:flex;flex-direction:column;gap:10px}
.rq-re-list{display:flex;flex-direction:column;gap:4px;max-height:300px;overflow:auto;border:1px solid var(--line);border-radius:var(--r);padding:4px}
.rq-re-row{all:unset;cursor:pointer;display:grid;grid-template-columns:72px minmax(0,1fr) auto;gap:10px;align-items:center;padding:8px 10px;border-radius:6px;font-size:14px}
.rq-re-row:hover{background:var(--surface-2)}
.rq-re-row.on{background:var(--accent-soft);box-shadow:inset 0 0 0 1px var(--accent)}
.rq-re-row .nm{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rq-re-row .faint{font-size:12px;white-space:nowrap}
.rq-re-row:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
/* the portal's tabs inside a tab (Artwork, Pricing; Oct 24, Nick) */
.portal .aa-subtabs{margin:0 0 12px}
/* Skip the form: three buttons, one size, icon then words (Oct 24, Nick) */
.rq-fast.rq-fast3{grid-template-columns:1fr;gap:8px}
.rq-fast.rq-fast3 .rq-fast-o{flex-direction:row;justify-content:flex-start;text-align:left;min-height:48px;height:48px;padding:0 14px;gap:12px}
.rq-fast.rq-fast3 .rq-fast-o .ic{width:30px;height:30px;flex:0 0 30px}
.rq-fast.rq-fast3 .rq-fast-o b{font-size:14px}
/* the reorder list: a picture, the order, View */
.rq-re-row{grid-template-columns:52px minmax(0,1fr) auto!important;outline:0}
.rq-re-pic{width:52px;height:52px;border:1px solid var(--line);border-radius:6px;background:#fff;display:grid;place-items:center;overflow:hidden;font-size:11px;color:var(--ink-3)}
.rq-re-pic img{width:100%;height:100%;object-fit:contain}
.rq-re-t{display:flex;flex-direction:column;min-width:0}
.rq-re-t .nm{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rq-re-t b{font-size:13.5px}
/* when they can pay (Oct 24, Nick) */
.prd{display:flex;flex-direction:column;gap:8px;padding:10px 12px;border:1px solid var(--line);border-radius:var(--r)}
.prd-row{display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap}
.prd-nf{height:36px;align-items:center}
.prd-sees{font-size:12.5px}
.pay-notready{display:flex;flex-direction:column;gap:3px;padding:10px 12px;border-radius:var(--r);background:var(--surface-2);font-size:13px}
.pay-notready span{color:var(--ink-3)}
.pay-nf,.pp-nf{font-size:12.5px;padding:8px 10px;border-radius:var(--r);background:color-mix(in srgb,var(--warn) 12%,var(--surface));color:var(--ink)}
.aa-nr{color:var(--ink-3)}
.aa-nf{color:var(--warn)}
.aa-notready td{color:var(--ink-3)}
/* portal dashboard clean-up (Oct 24, Nick: "it's very busy… clean it up a little bit") */
/* on hold: compact rows, no scrolling */
.pdx .pdx-col .pdx-hold-list{max-height:none;overflow:visible;gap:8px}
.pdx .pdx-col .pdx-hold-row{grid-template-columns:minmax(0,1fr);gap:6px;padding:8px 10px;border:1px solid var(--line);border-left:3px solid var(--danger);border-radius:0}
.pdx-hold-t b{display:block;font-size:13.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pdx-hold-t>span{font-size:12.5px}
.pdx-hold-tag{display:inline-block;margin-right:6px;padding:1px 6px;border-radius:4px;font-size:10.5px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;color:var(--danger);background:color-mix(in srgb,var(--danger) 10%,transparent)}
.pdx .pdx-col .pdx-hold-acts{justify-content:flex-start;gap:6px}
.pdx .pdx-col .pdx-hold-acts .btn{height:28px;padding:0 10px;font-size:12.5px}
.pdx-hold-more summary{cursor:pointer;font-size:12.5px;font-weight:600;color:var(--accent);padding:2px 0;list-style:none}
.pdx-hold-more summary::-webkit-details-marker{display:none}
.pdx-hold-more[open]>summary{margin-bottom:8px}
.pdx-hold-more>.pdx-hold-row+.pdx-hold-row{margin-top:8px}
/* order tracking: one order per line */
.pdx .pdx-left .pdx-track .pdx-track-list{grid-template-columns:minmax(0,1fr);gap:6px}
.pdx-trk{padding:7px 10px}
/* orders sent to FBS in the left column */
.pdx-left .pdx-sent{margin:0}
.pdx-left .pdx-sent-row{grid-template-columns:minmax(0,1fr) auto auto;gap:12px;padding:8px 10px}
.pdx-left .pdx-sent-st{flex-direction:row;align-items:center}
.pdx-left .pdx-sent-st small{display:none}
.pdx-left .pdx-caught svg{width:40px;height:40px}
/* payments: the aging boxes never spill */
.pdx-aging>div{padding:6px 6px}
.pdx-aging span{font-size:10.5px;overflow:hidden;text-overflow:ellipsis}
.pdx-aging b{font-size:12px;overflow:hidden;text-overflow:ellipsis}
/* your jobs: calmer rows */
.pjr{grid-template-columns:56px minmax(0,1.1fr) minmax(0,1.7fr) 200px;gap:14px;padding:12px 4px}
.pjr-pic,.pjr-picw{width:56px;height:56px}
.pjr-t b{font-size:14.5px}
.pjr-btn{border-radius:6px;padding:7px 10px;font-size:13px}
.pjr-btn.need{background:color-mix(in srgb,#f0a500 14%,var(--surface));border-color:color-mix(in srgb,#f0a500 55%,var(--line));color:#8a5a00}
.pjr-btn.need:hover{background:color-mix(in srgb,#f0a500 24%,var(--surface));border-color:#f0a500}
.pjr-btn.ok{background:color-mix(in srgb,var(--ok) 12%,var(--surface));border-color:color-mix(in srgb,var(--ok) 50%,var(--line));color:var(--ok)}
.pjs-st i{width:24px;height:24px}
.pjs::before,.pjs::after{top:11px}
.pdx-stabs{margin:0 0 6px}
/* order again, artwork and mockups: small */
.pdx-again{grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px}
.pdx-ag{flex-direction:row;align-items:center;gap:10px;padding:8px}
.pdx-ag-pic{flex:0 0 56px;width:56px;height:56px}
.pdx-ag>b{flex:1 1 auto;min-width:0;font-size:13px}
.pdx-ag>small{display:none}
.pdx-ag .btn{align-self:center}
.pdx-thumbs{display:grid;grid-template-columns:1fr 1fr;gap:20px}
@media (max-width:760px){.pdx-thumbs{grid-template-columns:1fr}}
.pdx-thumbs .pdx-art{grid-template-columns:repeat(auto-fill,64px);gap:8px}
.pdx-thumbs .pdx-art a{width:64px;height:64px;border-radius:8px}
.pdx-more-fold>summary{cursor:pointer;font-size:12.5px;font-weight:600;color:var(--accent);padding:4px 0 0;list-style:none}
.pdx-more-fold>summary::-webkit-details-marker{display:none}
.pdx-more-fold[open]>summary{margin-bottom:6px}
.pdx-more-fold>.pdx-track-list,.pdx-more-fold>.pdx-sent-list{display:flex;flex-direction:column;gap:6px}
/* fewer bubbles (Oct 24, Nick: "limit them a little bit… not so colorful… but not drab either") */
/* tracking and sent: words, colored only when it needs them */
.pdx-trk{border:0;border-top:1px solid var(--line-2,var(--line));border-radius:0;padding:7px 2px;grid-template-columns:8px minmax(0,1fr) auto}
.pdx-track-list>.pdx-trk:first-child{border-top:0}
.pdx-trk::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--line);align-self:center;grid-row:1}
.pdx-trk.t-bad::before{background:var(--danger)}.pdx-trk.t-act::before{background:var(--warn)}
.pdx-trk .pd-link{grid-column:2 / -1}
.pdx-trk-h{background:none;padding:0;font-weight:600;color:var(--ink-3)}
.pdx-trk.t-bad .pdx-trk-h{color:var(--danger)}.pdx-trk.t-act .pdx-trk-h{color:#a76a00}
.pdx-left .pdx-sent-row{border:0;border-top:1px solid var(--line-2,var(--line));border-radius:0;padding:7px 2px;grid-template-columns:minmax(0,1fr) auto}
.pdx-left .pdx-sent-list>.pdx-sent-row:first-child{border-top:0}
.pdx-left .pdx-sent-steps{display:none}
.pdx-sent-pill{background:none;padding:0;font-weight:600;color:var(--ink-3)}
.pdx-sent-row.t-act .pdx-sent-pill{color:var(--accent)}
.pdx-sent-row.t-act .pdx-sent-pill::after{content:" ›"}
/* on hold: the panel says it, the rows don't repeat it */
.pdx-hold-tag{display:none}
/* the job steps: kept, quieter */
.pjs::after{background:color-mix(in srgb,var(--fbs-blue) 55%,var(--line))}
.pjs-st.done i{background:color-mix(in srgb,var(--fbs-blue) 12%,var(--surface));border-color:color-mix(in srgb,var(--fbs-blue) 45%,var(--line));color:var(--fbs-blue)}
.pjs-st.cur i{background:var(--surface);border:2px solid var(--fbs-blue);color:var(--fbs-blue);box-shadow:none}
.pjs-st.cur b{color:var(--ink);font-weight:700}
.pjs-st b{font-weight:500}
/* the jobs toolbar runs the full width of the card, like the secondary toolbar everywhere else (Oct 24, Nick) */
/* order tracking: two columns past three (no "more") */
.pdx .pdx-left .pdx-track .pdx-track-list.two{grid-template-columns:repeat(2,minmax(0,1fr));column-gap:18px}
.pdx-track-list.two>.pdx-trk:nth-child(2){border-top:0}
.pdx-ag>b{font-variant-numeric:tabular-nums}
/* On hold fills its panel: 1 = points, 2 = what's wrong + buttons, 3+ = a line each (Oct 24, Nick) */
.pdx-top>.pdx-col:not(.pdx-left)>.pdx-hold{display:flex;flex-direction:column}
.pdx .pdx-col .pdx-hold-list{flex:1 1 auto;display:flex;flex-direction:column;gap:8px}
.pdx .pdx-col .pdx-hold-list>.pdx-hold-row{flex:1 1 0;display:flex;flex-direction:column;justify-content:center}
.pdx .pdx-col .pdx-hold-row.tight{flex-direction:row;align-items:center;justify-content:space-between;gap:10px}
.pdx-hold-row.tight .pdx-hold-t{display:flex;flex-direction:column;min-width:0;color:var(--ink);text-decoration:none}
.pdx-hold-row.tight .pdx-hold-t span{font-size:12.5px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pdx-hold-go{font-size:12.5px;font-weight:600;color:var(--accent);white-space:nowrap;text-decoration:none}
.pdx-hold-go:hover{text-decoration:underline}
.pdx-hold-pts{margin:6px 0 2px;padding-left:18px;display:flex;flex-direction:column;gap:3px;font-size:12.5px;color:var(--ink-2,var(--ink));line-height:1.4}
.pdx-hold-more>summary{font-size:12.5px}
/* needs-you buttons on the jobs: blue, quieter than on-hold red/orange (Oct 24, Nick) */
.pjr-btn.need{background:var(--accent-soft);border-color:color-mix(in srgb,var(--accent) 45%,var(--line));color:var(--accent)}
.pjr-btn.need:hover{background:color-mix(in srgb,var(--accent) 18%,var(--surface));border-color:var(--accent)}
/* aging boxes: the amount is never cut off; each box is at least as wide as its number and the row wraps when it must (Oct 24, Nick) */
.pdx-aging{display:flex;flex-wrap:wrap;gap:1px;background:var(--line)}
.pdx-aging>div{flex:1 1 auto;min-width:max-content;border-left:0;background:var(--surface)}
.pdx-aging>div.late{background:var(--danger-soft)}
.pdx-aging b{overflow:visible;text-overflow:clip;font-variant-numeric:tabular-nums}
.pdx-aging span{overflow:visible;text-overflow:clip}
/* the portal "?" help button: small, in line with Sign out (Oct 24, Nick: "way too big") */
.who .p-help{width:22px;height:22px;font-size:12px;border-color:var(--line-2,var(--line));color:var(--ink-3)}
.rq-reo{font-size:12px;text-align:center}
/* portal section headings: the note goes under the heading, like the page title's (Oct 24, Nick: "not doing the text below the header like we do everywhere else") */
.portal .aa-sec-h{flex-wrap:wrap;row-gap:4px}
.portal .aa-sec-h>h3+.faint,.portal .aa-sec-h>h3+span.faint{flex-basis:100%;order:2}
.portal .aa-sec-h>h3~.aa-oldq{order:3}
/* the jobs toolbar: the same as every other toolbar (Oct 24, Nick) */
.pdx-stabs{padding:1px}
/* order tracking: 1-3 one column, 4-6 two, 7-9 three (Oct 24, Nick: "no more than 9… 3 columns") */
.pdx .pdx-left .pdx-track .pdx-track-list.three{grid-template-columns:repeat(3,minmax(0,1fr));column-gap:14px}
.pdx-track-list.three>.pdx-trk:nth-child(-n+3){border-top:0}
.pdx-track-list.three>.pdx-trk{grid-template-columns:8px minmax(0,1fr)}
.pdx-track-list.three>.pdx-trk .pdx-trk-h{grid-column:2;font-size:11.5px}
.pdx-track-list.three>.pdx-trk::before{grid-row:1 / span 2;align-self:start;margin-top:6px}
/* star an order: the error when there are already 9 */
.ostar-w{position:relative;display:inline-flex}
.ostar-err{position:absolute;left:0;top:calc(100% + 4px);z-index:30;width:220px;padding:6px 9px;border-radius:8px;background:var(--ink);color:var(--surface);font-size:12px;font-weight:600;line-height:1.35;white-space:normal;box-shadow:0 4px 14px rgba(20,29,43,.18)}
/* the portal Orders tab: a star on each row, and the starred ones on top */
.aa-tbl col.c-star{width:36px}
.aa-tbl td.aa-starc{padding-left:10px;padding-right:0}
.aa-starred{margin:0 0 14px}
.aa-starred-g{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.aa-star-t{display:flex;align-items:center;gap:10px;padding:8px 12px;background:var(--surface);border:1px solid var(--line-2,var(--line));border-radius:10px;min-width:0}
.aa-star-n{display:flex;flex-direction:column;min-width:0;flex:1 1 auto;color:var(--ink);text-decoration:none}
.aa-star-n b{font-size:13.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aa-star-n small{font-size:12px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aa-star-n:hover b{color:var(--accent)}
@media (max-width:900px){.aa-starred-g{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:560px){.aa-starred-g{grid-template-columns:1fr}}
/* Dashboard and portal lists: calmer type (Oct 24, Nick: "way too much bold… the wrong font for the order numbers").
   Order numbers in the body font, gray, regular; one emphasis per row (the name, 600); statuses, notes and links lighter. */
.portal .onum{font-weight:500;color:var(--ink-3);margin-right:2px}
.portal :is(.pjr-t small,.pdx-rt small,.pjr-pic,.pdx-rpic,.pd-o .n,.pdx-jt .n,.pdx-nopic,.pdx-ag-pic span,.pdx-ti){font-family:var(--body)}
.portal .pjr-t small{font-size:12px}
.portal :is(.pjr-t b,.pdx-trk-t b,.pdx-sent-name b,.pdx-hold-t b,.aa-star-n b,.pdx-ag b){font-weight:600}
.portal :is(.pjr-btn,.pd-link,.pjr-owe,.pjr-msg,.pdx-go,.pdx-jmsg span,.pdx-more,.pdx-hold-go,.pdx-asst .pa-person){font-weight:600}
.portal :is(.pdx-trk-h,.pdx-sent-pill){font-weight:500}
.portal .pdx-trk.t-bad .pdx-trk-h,.portal .pdx-trk.t-act .pdx-trk-h{font-weight:600}
.portal .pjr-now b{font-weight:600}
.portal .pjs-st.cur b{font-weight:600}
.portal :is(.pdx-aging b,.pdx-stmt-meta b,.pdx-pay-parts span){font-weight:600}
.portal :is(.pdx-stmt-due small,.pdx-pay-big small){font-weight:600}
.portal :is(.pdx-stmt-due.late span,.pdx-stmt-due.ok span,.pdx-pay-big span){font-weight:500}
.portal .pdx-stmt-due b{font-weight:700}
.portal .pdx-hold-acts .btn{font-weight:600}
.portal .aa-otabs .chips>.chip{font-weight:600}
.portal .aa-otabs .chips>.chip.on{font-weight:700}
/* the portal has no code on it: every number in the body font (Oct 24, Nick) */
.portal{--mono:var(--body)}
/* the star on a job picture stays on the picture's corner (the wrapper added for the 9-limit message) */
.pjr-picw .ostar-w{position:static;display:contents}
.pjr-picw .ostar-err{top:60px;left:0}
/* portal order lists: the star sits in the # cell, and the columns give the order name more room */
.aa-noc{display:inline-flex;align-items:center;gap:8px}
.portal .aa-noc .ostar:not(.on){opacity:.45}
.portal .aa-tbl tr:hover .aa-noc .ostar{opacity:1}
@media (min-width:641px){
  .portal .aa-tbl-cols col.c-no{width:104px}
  .portal .aa-tbl-cols col.c-ty{width:92px}
  .portal .aa-tbl-cols col.c-st{width:150px}
  .portal .aa-tbl-cols col.c-dt{width:120px}
  .portal .aa-tbl-cols col.c-m{width:92px}
}
/* statement title: the color bar stays under the word, inside the sheet (Oct 24, Nick) */
.portal .st-title h1::after{width:100%;min-width:0;margin-left:auto}
/* On hold, nothing on hold: a calm check (Oct 24, Nick: "a graphic… everything is A-okay") */
.pdx-hold-ok{flex:1 1 auto;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:6px;padding:14px 10px}
.pdx-hold-ok b{font-size:15px;font-weight:600;color:var(--ink)}
.pdx-hold-ok span{font-size:12.5px;color:var(--ink-3);max-width:300px;line-height:1.45}
/* portal Goods tab: one short row per job (Oct 24, Nick: "these boxes are huge") */
.gb.dense{display:flex;flex-direction:column;gap:8px}
.gb.dense .gc{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(220px,1fr) auto;column-gap:22px;row-gap:4px;align-items:center;padding:10px 14px;border-radius:10px}
.gb.dense .gc-h{grid-column:1;grid-row:1;display:block}
.gb.dense .gc-t b{font-size:14px;font-weight:600}
.gb.dense .gc-t{flex-direction:row;flex-wrap:wrap;align-items:baseline;column-gap:6px}
.gb.dense .gc-sub{flex-basis:100%}
.gb.dense .gc-st{display:inline-block;margin-top:4px;padding:0;background:none;font-weight:600;font-size:12px}
.gb.dense .gc-steps{grid-column:2;grid-row:1}
.gb.dense .gc-steps li{font-size:10.5px;font-weight:500}
.gb.dense .gc-acts{grid-column:3;grid-row:1;flex-wrap:nowrap}
.gb.dense .gc-acts .spacer,.gb.dense .gc-acts .gc-link{display:none}
.gb.dense .gc-from{grid-column:1 / -1;grid-row:2;padding:0;font-size:12px}
.gb.dense .gc-from.need{display:none}
.gb.dense :is(.gc-ships,.gc-last,.gc-form,.gc-issue,.gc-note,.gc-help){grid-column:1 / -1}
@media (max-width:820px){.gb.dense .gc{grid-template-columns:1fr}.gb.dense :is(.gc-h,.gc-steps,.gc-acts,.gc-from){grid-column:1;grid-row:auto}.gb.dense .gc-acts{flex-wrap:wrap}}
/* portal order lists: the star at the end of the row (Oct 24, Nick: "on the right side") */
.portal .aa-tbl col.c-star{width:44px}
.portal .aa-tbl td.aa-starc{padding:0 10px 0 4px;text-align:right}
.portal .aa-tbl td.aa-starc .ostar:not(.on){opacity:.5}
.portal .aa-tbl tr:hover td.aa-starc .ostar{opacity:1}
@media (min-width:641px){.portal .aa-tbl-cols col.c-no{width:88px}}
/* an FBS-made (or ordered) mockup opened in the portal: look, or make a copy (Oct 24, Nick) */
.mk-lock-note{display:flex;flex-wrap:wrap;align-items:center;gap:6px 10px}
.mk-lock-note .btn{margin-left:auto}
/* the FBS-made mockup bar: slim, one line (Oct 24, Nick: "doesn't need to be so big… FBS mockup on one side… only editable by staff in the middle… make a copy to edit on the right") */
.mk-lockbar{display:flex;align-items:center;gap:14px;margin:0 0 12px;padding:6px 8px 6px 12px;background:var(--surface);border:1px solid color-mix(in srgb,var(--accent) 45%,var(--line));border-radius:var(--r)}
.mk-lockbar-l{display:inline-flex;align-items:center;gap:8px;white-space:nowrap}
.mk-lockbar-l b{font-size:14px;font-weight:600;color:var(--ink)}
.mk-lockbar-fbs{display:inline-block;background:var(--ink);color:var(--surface);font:700 12px/1 var(--body);letter-spacing:.02em;padding:4px 6px;border-radius:5px}
.mk-lockbar-m{flex:1;display:inline-flex;align-items:center;justify-content:center;gap:6px;font-size:13px;color:var(--ink-3);white-space:nowrap}
.mk-lockbar .btn{white-space:nowrap}
@media (max-width:640px){.mk-lockbar{flex-wrap:wrap}.mk-lockbar-m{justify-content:flex-start;flex-basis:100%;order:3}}
/* Design catalog (shop): the "Show in their portal" switch on the header line (Oct 24, Nick) */
.dc .panel-h{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap}
.dc .panel-h .spacer{flex:1}
.dc-portal{align-self:center;display:inline-flex;align-items:center;gap:6px}
.dc-portal.on{background:var(--accent-soft);border-color:color-mix(in srgb,var(--accent) 45%,var(--line));color:var(--accent)}
/* portal Artwork with a design catalog: the tab row (Design catalog · Artwork · Brand standards) with the search on it */
.portal .aa-dc-bar{margin:0 0 14px;flex-wrap:nowrap}
.portal .aa-dc-bar .aa-search{width:280px;max-width:40%}
/* "Show in their portal": the same switch on every section that can show in the portal, right end of its title line */
.portal-sw{align-self:center;display:inline-flex;align-items:center;gap:6px;margin-left:auto;white-space:nowrap}
.portal-sw.on{background:var(--accent-soft);border-color:color-mix(in srgb,var(--accent) 45%,var(--line));color:var(--accent)}
.aa-sec-h:has(> .portal-sw){align-items:center}
/* order lists: the Archived tag stays on the name's line; a long name shortens instead (Oct 24, Nick) */
.aa-tbl .aa-t.aa-t1{display:flex;align-items:center;gap:6px;min-width:0;flex-wrap:nowrap}
.aa-tbl .aa-t1 .aa-tn{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.aa-tbl .aa-t1 .aa-arch{flex:none;white-space:nowrap}
/* shop customer Artwork: smaller logo and mockup cards (the portal keeps its four across) (Oct 24, Nick: "way too big") */
.aa-shop .aa-grid6{grid-template-columns:repeat(auto-fill,minmax(165px,1fr))}
/* Brand standards header: room for "Show in their portal" beside Add / Edit / Set up with AI */
.aa-shop .aa-card:has(> .bai) > .aa-sec-h{padding-right:300px}
@media (max-width:640px){.aa-shop .aa-card:has(> .bai) > .aa-sec-h{padding-right:0}}
/* portal design catalog: "← All designs" above the card (Oct 24, Nick) */
.pdc-back{margin:0 0 8px}
.pdc-back .linkbtn{font-size:13px;font-weight:600;color:var(--accent);text-decoration:none;padding:0;border:0;background:none;cursor:pointer}
.pdc-back .linkbtn:hover{text-decoration:underline}
/* no prices (retail builder): the qty sits at the right end of the garment line (Oct 24, Nick) */
.line.np .gl .a-qt{justify-self:end;text-align:right}
/* retail builder: "× Price" placeholder, "FBS will send a quote" under it (Oct 24, Nick) */
.line.np .gl .a-ea.a-quote{display:flex!important;align-items:flex-start;justify-content:flex-end;gap:8px;white-space:nowrap}
.line.np .gl .a-quote .aq-in{display:inline-flex;flex-direction:column;align-items:flex-end;gap:4px}
.line.np .gl .a-quote .aq-ph{display:inline-block;height:30px;line-height:28px;padding:0 12px;border:1px dashed var(--line);border-radius:6px;font-size:13px;color:var(--ink-3);background:var(--surface)}
.line.np .gl .a-quote small{font-size:12px;color:var(--ink-3)}
.line.np .gl .a-qt{justify-self:end}
/* Mockup Creator: "Not in the catalog? Upload photos" at the bottom right of the garments bar (Oct 24, Nick) */
.mk-add-row{width:100%;align-self:stretch}
.mk-add-row .mk-own-up{margin-left:auto}
/* Mockup Creator: "Need help picking garments?" above "Not in the catalog?", and its pop-up (Oct 24, Nick) */
.mk-help-row{display:flex;justify-content:flex-end;margin:4px 0 -2px}
.mk-help-pick{display:inline-flex;align-items:center;gap:6px;color:var(--accent);border-color:color-mix(in srgb,var(--accent) 45%,var(--line))}
.mk-help-pick:hover{background:var(--accent-soft)}
.pg{max-width:680px;width:calc(100vw - 32px)}
.pg h3{margin:0 0 2px}
.pg-k{font-size:12px;color:var(--ink-3);margin:12px 0 6px}
.pg-uses{display:flex;flex-wrap:wrap;gap:6px}
.pg-use{font:inherit;font-size:12.5px;padding:5px 11px;border-radius:999px;border:1px solid var(--line);background:var(--surface);color:var(--ink-2,var(--ink));cursor:pointer}
.pg-use.on{background:var(--accent-soft);border-color:color-mix(in srgb,var(--accent) 45%,var(--line));color:var(--accent);font-weight:600}
.pg-kinds{margin:12px 0 10px}
.pg-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;max-height:min(52vh,460px);overflow:auto;padding:2px}
.pg-card{all:unset;box-sizing:border-box;cursor:pointer;display:flex;gap:10px;padding:10px;border:1px solid var(--line);border-radius:10px;background:var(--surface)}
.pg-card:hover{border-color:color-mix(in srgb,var(--accent) 45%,var(--line))}
.pg-card.on{border:2px solid var(--accent);padding:9px}
.pg-pic{flex:none;width:64px;height:64px;border-radius:8px;background:var(--surface-2);overflow:hidden;display:grid;place-items:center}
.pg-pic img{width:100%;height:100%;object-fit:contain}
.pg-t{display:flex;flex-direction:column;min-width:0;gap:1px}
.pg-tag{font-size:11.5px;color:var(--accent);font-weight:600}
.pg-t b{font-size:14px;font-weight:600;color:var(--ink)}
.pg-why{font-size:12.5px;color:var(--ink-2,var(--ink));line-height:1.35}
.pg-meta{font-size:12px;color:var(--ink-3)}
.pg-foot{display:flex;align-items:center;gap:10px;margin-top:14px}
.pg-foot .faint{flex:1;font-size:12.5px}
@media (max-width:560px){.pg-grid{grid-template-columns:1fr}}
.pgs-tbl input,.pgs-tbl select{width:100%;min-width:70px}
.pgs-uses{display:flex;flex-wrap:wrap;gap:4px 10px;font-size:12px;min-width:220px}
/* style search: our popular garments first, marked (Oct 24, Nick) */
.style-menu .sm-item em.sm-pop{font-style:normal;font-size:10.5px;font-weight:700;color:var(--accent);background:var(--accent-soft);border-radius:999px;padding:1px 7px;margin-left:auto;white-space:nowrap}
/* Create order: the emails question on one line, the list only when choosing, a chip once answered (Oct 24, Nick) */
.osp-mq{padding:0;overflow:hidden}
.osp-mq-line{display:flex;align-items:center;gap:8px;padding:8px 8px 8px 12px;border:1px solid color-mix(in srgb,var(--accent) 40%,var(--line));border-radius:8px;background:var(--surface)}
.osp-mq.open .osp-mq-line{border-bottom-left-radius:0;border-bottom-right-radius:0}
.osp-mq-line>svg{flex:none;color:var(--accent)}
.osp-mq-t{flex:1;min-width:0;font-size:13.5px;color:var(--ink)}
.osp-mq-t b{font-weight:600}
.osp-mq-line .btn{white-space:nowrap}
.osp-mq-x{width:26px;height:26px;padding:0;font-size:16px;color:var(--ink-3)}
.osp-mq.open ul{margin:0;padding:6px 12px;border:1px solid color-mix(in srgb,var(--accent) 40%,var(--line));border-top:0;max-height:220px;overflow:auto}
.osp-mq-done{display:flex;justify-content:flex-end;padding:6px 12px 8px;border:1px solid color-mix(in srgb,var(--accent) 40%,var(--line));border-top:0;border-radius:0 0 8px 8px}
.osp-mchip-w{margin:2px 0 8px}
.osp-mchip{all:unset;cursor:pointer;display:inline-flex;align-items:center;gap:6px;font-size:12.5px;font-weight:600;padding:5px 11px;border-radius:999px;background:var(--accent-soft);color:var(--accent)}
.osp-mchip-ch{font-weight:500;opacity:.8;margin-left:2px}
.osp-mchip-ch::before{content:"· ";}
/* Mockup Creator (staff): the print scale nudge for this garment's photos (Oct 24, Nick: P160) */
.mk-zoom{display:flex;align-items:center;gap:6px;margin:0 0 8px;font-size:12.5px}
.mk-zoom .btn.icon{width:28px;height:28px;padding:0}
.mk-zoom-v{min-width:42px;text-align:center;font-weight:600;font-size:13px}
/* reorder files: "Not here?" files are brought in with one button, then answered above (Oct 24, Nick) */
.arc-bring{display:flex;flex-direction:column;gap:6px}
.arc-bring .btn{align-self:flex-start}
select.chip.arc-spot{height:auto;min-height:30px;padding:4px 8px;font:inherit;font-size:12.5px;max-width:100%;cursor:pointer}
select.chip.arc-spot.on{border-color:var(--accent);color:var(--accent);background:var(--accent-soft)}
/* Mockup Creator (staff): Scale front / Scale back, top right of each photo (Oct 24, Nick) */
.mk-corner.tr{top:1.8cqw;bottom:auto;right:2.2cqw}
.mk-corner.tr .mk-pill.mk-zoom{cursor:default;display:inline-flex;align-items:center;gap:5px;white-space:nowrap}
.mk-pill.mk-zoom button{all:unset;cursor:pointer;width:18px;height:18px;display:inline-grid;place-items:center;border:1px solid var(--line);border-radius:5px;background:var(--surface);font-weight:700;line-height:1}
.mk-pill.mk-zoom button:hover{border-color:var(--accent);color:var(--accent)}
.mk-pill.mk-zoom b{min-width:34px;text-align:center;font-weight:600}
.mk-pill.mk-zoom .mk-zoom-r{border:0;background:none;color:var(--ink-3)}
/* Order type row (Oct 24): New order / Reorder / Reorder with changes, production confirms, what the customer sees */
.ord .pt-row.ot-row .ot-sel{height:36px;border:1px solid var(--line);border-radius:6px;padding:0 10px;font:inherit;font-size:14px;color:var(--ink);background:var(--surface)}
.ord .pt-row.ot-row .ot-conf{font-size:13px}
.ord .pt-row.ot-row .ot-prints{flex-basis:100%;display:flex;flex-wrap:wrap;align-items:center;gap:6px 14px;font-size:13px}
.ord .pt-row.ot-row .ot-prints .faint{font-size:12px}
.ord .pt-row.ot-row.ot-bare{border-top:0;margin-top:0;padding-top:0}
.ord .jd-tabs{margin:-2px 0 2px}
/* Create order: one card per order (Oct 24): the emails as one line, each order's type, past job and decoration on its card */
.osp-mline{display:flex;align-items:center;gap:6px;font-size:12.5px;color:var(--ink-3);margin:2px 0 12px}
.osp-mline .linkbtn{font-size:12.5px}
.osp-cards{display:flex;flex-direction:column;gap:8px;margin-bottom:12px}
.osp-card{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--line);border-radius:var(--r);background:var(--surface);font-size:13px}
.osp-card .faint{font-size:12px}
.osp-card.made{opacity:.75}
.osp-card.open{flex-direction:column;align-items:stretch;border:2px solid var(--accent);gap:8px}
.osp-card-t{display:flex;justify-content:space-between;align-items:baseline;gap:8px}
.osp-card-t b{font-size:14px}
.osp-card-t .faint{white-space:nowrap}
.osp-card-n{font-size:12px;margin-top:-4px}
.osp-cb{display:flex;flex-direction:column;gap:8px}
.osp-cb-f{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px;align-items:start}
.osp-cb-f .field{margin:0}
.osp-jobf{display:flex;justify-content:space-between;align-items:center;gap:8px;width:100%;height:36px;padding:0 10px;border:1px solid var(--line);border-radius:6px;background:var(--surface);font:inherit;font-size:14px;color:var(--ink);cursor:pointer;text-align:left}
.osp-jobf span:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.osp-jobf .faint{font-size:12px;color:var(--accent)}
.osp-cb-how{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.osp-cb-how > .faint{font-size:12px}
.osp-card-jobs{border-top:1px solid var(--line-2);padding-top:8px}
.osp-card-go{display:flex;justify-content:flex-end}
.osp-card-all{display:flex;justify-content:flex-start}
@media (max-width:560px){.osp-cb-f{grid-template-columns:1fr}}
.osp-card-btn{width:100%;text-align:left;font:inherit;color:inherit;cursor:pointer}
.osp-card-btn:hover{border-color:var(--accent)}
.osp-card-car{font-size:18px;color:var(--ink-3)}
.osp-card-go{gap:8px}
.osp-card-go .btn.on{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}
.osp-other{display:flex;flex-direction:column;border:1px solid var(--line);border-radius:var(--r);overflow:hidden}
.osp-other-it{display:flex;flex-direction:column;align-items:flex-start;gap:2px;padding:9px 12px;border:0;border-bottom:1px solid var(--line-2);background:var(--surface);font:inherit;font-size:13px;color:var(--ink);text-align:left;cursor:pointer}
.osp-other-it:hover{background:var(--accent-soft)}
.osp-other-it .faint{font-size:12px}
.osp-other-ai{margin:0;padding:9px 12px}
.po-steps{list-style:none;margin:8px 0;padding:0;display:flex;flex-direction:column;gap:4px;font-size:13px}
.po-steps li{color:var(--ink-3)}
.po-steps li.on{color:var(--ink);font-weight:700}
.po-made{display:flex;flex-direction:column;align-items:flex-start;gap:8px;margin:8px 0}
.po-warn{font-size:12.5px;color:var(--warn)}
/* Customer artwork (Oct 24): their mockups from other orders and their logos, brought onto a group */
.mk-cust{width:100%}
.dla.ca{max-width:760px;width:min(760px,calc(100vw - 32px))}
.ca-h{display:flex;justify-content:space-between;align-items:center}
.ca .toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:8px 0 10px}
.ca-q{height:36px;flex:1;min-width:160px;border:1px solid var(--line);border-radius:6px;padding:0 10px;font:inherit;font-size:14px}
.ca-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;max-height:46vh;overflow:auto;padding:2px}
.ca-card{display:flex;flex-direction:column;align-items:flex-start;gap:3px;padding:8px;border:1px solid var(--line);border-radius:var(--r);background:var(--surface);font:inherit;font-size:13px;color:var(--ink);text-align:left;cursor:pointer;min-width:0}
.ca-card:hover{border-color:var(--accent)}
.ca-card.on{border:2px solid var(--accent);padding:7px}
.ca-card b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%}
.ca-card .faint{font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%}
.ca-pic{display:flex;align-items:center;justify-content:center;width:100%;aspect-ratio:4/3;background:var(--surface-2);border-radius:6px;overflow:hidden}
.ca-pic img{width:100%;height:100%;object-fit:contain}
.ca-pic.logo img{padding:6px}
.ca-use{display:flex;flex-direction:column;gap:6px;border-top:1px solid var(--line-2);margin-top:10px;padding-top:10px;font-size:13px}
.ca-use .faint{font-size:12.5px}
.ca-warn{font-size:12.5px;color:var(--warn)}
.ca-acts{display:flex;justify-content:flex-end;align-items:flex-end;gap:8px;flex-wrap:wrap}
.ca-acts .field{margin:0;min-width:180px}
.rq-pick .toolbar{margin:4px 0 10px}
.rq-pick-c.on{outline:2px solid var(--accent);outline-offset:-2px}
/* Customer artwork / My files → search old orders (Oct 24) */
.ca-old{display:flex;flex-direction:column;gap:6px;border-top:1px solid var(--line-2);margin-top:12px;padding-top:10px;font-size:13px}
.ca-old > .faint{font-size:12.5px}
.ca-jobs{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:8px}
.ca-job{display:flex;gap:10px;align-items:center;padding:6px 8px;border:1px solid var(--line);border-radius:var(--r);background:var(--surface);font:inherit;font-size:13px;color:var(--ink);text-align:left;cursor:pointer;min-width:0}
.ca-job:hover{border-color:var(--accent)}
.ca-job.on{border:2px solid var(--accent);padding:5px 7px}
.ca-job .faint{font-size:12px}
.ca-job b{word-break:break-word}
.ca-jpic{width:56px;height:46px;flex-shrink:0;display:flex;align-items:center;justify-content:center;background:var(--surface-2);border-radius:6px;overflow:hidden}
.ca-jpic img{width:100%;height:100%;object-fit:contain}
.ca-jobfiles{display:flex;flex-direction:column;gap:8px}
.ca-jf-h{display:flex;justify-content:space-between;align-items:center;gap:8px}
.ca-oldjob{display:flex;flex-direction:column;gap:6px}
/* an old job's files as pictures, picked several at once, then "tell me what these are" (Oct 24) */
.ca-files{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}
.ca-file{display:flex;flex-direction:column;gap:4px;min-width:0}
.ca-file-pic{position:relative;display:flex;align-items:center;justify-content:center;aspect-ratio:1/1;border:1px solid var(--line);border-radius:var(--r);background:var(--surface-2);overflow:hidden;cursor:pointer;padding:6px;font:inherit}
.ca-file-pic:hover{border-color:var(--accent)}
.ca-file.on .ca-file-pic{border:2px solid var(--accent);padding:5px}
.ca-file-pic img{width:100%;height:100%;object-fit:contain}
.ca-file-pic .faint{font-size:12px}
.ca-tick{position:absolute;top:6px;left:6px;width:20px;height:20px;border-radius:50%;border:1.5px solid var(--line);background:var(--surface);display:flex;align-items:center;justify-content:center;font-size:12px;color:#fff}
.ca-tick.on{background:var(--accent);border-color:var(--accent)}
.ca-pdf{position:absolute;bottom:6px;right:6px;font-size:11px;font-weight:700;color:var(--ink-3);background:var(--surface);border-radius:4px;padding:0 4px}
.ca-look{font-size:12px;align-self:center}
.ca-bar{display:flex;align-items:center;gap:8px;font-size:13px;margin-top:4px}
.ca-what{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px}
.ca-what-r{display:flex;flex-direction:column;gap:6px}
.ca-wpic{display:flex;align-items:center;justify-content:center;aspect-ratio:4/3;background:var(--surface-2);border-radius:6px;overflow:hidden}
.ca-wpic img{width:100%;height:100%;object-fit:contain}
.ca-what-r select{height:36px;border:1px solid var(--line);border-radius:6px;padding:0 8px;font:inherit;font-size:14px;color:var(--ink);background:var(--surface)}
/* Mockup Creator: a color change on one garment color (Oct 24) */
.mk-cchg{display:flex;flex-direction:column;gap:6px;padding:8px 10px;border-radius:var(--r);background:color-mix(in srgb,var(--warn) 10%,var(--surface));font-size:13px;flex-basis:100%}
.mk-cchg-n{font-size:12.5px;color:var(--ink-2,var(--ink))}
.mk-cchg-r{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.mk-cchg-r i{width:14px;height:14px;border-radius:3px;border:1px solid var(--line);flex-shrink:0}
.mk-cchg-r input{height:32px;width:170px;border:1px solid var(--line);border-radius:6px;padding:0 8px;font:inherit;font-size:13px}
.mk-cchg .faint{font-size:12px}

/* ── Portal on a phone (Oct 24, Nick: "clean up the mobile view… a lot of things that spill out other lines like
   settings in the main toolbar is in its own line… a lot of hanging stuff all by itself"). Last in the file so it wins
   over the denser desktop rules above (the job rows' 4-column grid squeezed the text to a sliver on a phone). ── */
@media (max-width:640px){
  /* dashboard: the two start buttons the same size, side by side */
  .pdx-hello{gap:12px}
  .pdx-hello .pdx-sub{font-size:13px}
  .pdx-acts{display:grid!important;grid-template-columns:1fr 1fr;gap:8px;width:100%}
  .pdx-acts .pd-act{width:100%;min-width:0;min-height:56px;padding:8px 10px;gap:8px}
  .pdx-acts .pd-act small{display:none}
  .pdx-acts .pd-act b{font-size:13.5px;white-space:normal;line-height:1.2}
  /* the main tabs: 3 × 3, icon beside the word (Settings no longer alone on a row) */
  .portal .aa-nav{grid-template-columns:repeat(3,minmax(0,1fr));gap:2px;padding:5px}
  .portal .aa-tab{flex-direction:row;justify-content:flex-start;gap:7px;padding:9px 8px;font-size:12.5px;letter-spacing:0}
  .portal .aa-tab svg{width:17px;height:17px;flex:0 0 auto}
  .portal .aa-tab-end{margin-left:0!important;justify-content:flex-start!important}
  /* your jobs: picture + text, the buttons under them */
  .pjr{grid-template-columns:52px minmax(0,1fr);gap:8px 12px;padding:12px 2px}
  .pjr-pic,.pjr-picw{width:52px;height:52px}
  .pjr-mid,.pjr-act{grid-column:1 / -1}
  /* headings with a note: the note on its own line */
  .pdx-asst .pdx-h{flex-direction:column;align-items:flex-start;gap:2px}
  .pdx-h{flex-wrap:wrap;row-gap:2px}
  .pdx-h > .faint{flex-basis:100%;order:3;margin:2px 0 0}
  /* payments aging: "Not due" across the top, then 2 × 2 (no "Over 90" alone) */
  .pdx-aging{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important}
  .pdx-aging>div:first-child{grid-column:1 / -1}
  .pdx-aging>div{border-right:0!important}
  .pdx-aging span{font-size:11.5px}.pdx-aging b{font-size:14px}
  .portal .aa-aging{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:8px}
  .portal .aa-aging > .aa-age:first-child{grid-column:1 / -1}
  .portal .aa-aging > .aa-age{min-width:0;padding:10px 12px}
  /* filter chips fill the row; 5 chips go 3 + 2 (no "Completed" alone) */
  .portal .toolbar{flex-wrap:wrap;gap:8px}
  .portal .toolbar > .chips{display:flex;flex-wrap:wrap;width:100%;flex:1 1 100%}
  .portal .toolbar > .chips > .chip{flex:1 1 auto;justify-content:center;padding:8px 8px;font-size:13px;min-width:0;white-space:normal;line-height:1.2;text-align:center;gap:5px}
  .portal .toolbar > .chips > .chip .chip-n{flex:0 0 auto}
  .portal .toolbar > .chips:has(> .chip:nth-child(5)){display:grid;grid-template-columns:repeat(3,minmax(0,1fr))}
  .portal .toolbar > .chips:has(> .chip:nth-child(5):last-child){grid-template-columns:repeat(6,minmax(0,1fr))}
  .portal .toolbar > .chips:has(> .chip:nth-child(5):last-child) > .chip:nth-child(-n+3){grid-column:span 2}
  .portal .toolbar > .chips:has(> .chip:nth-child(5):last-child) > .chip:nth-child(n+4){grid-column:span 3}
  /* search and sort get their own full-width row */
  .portal .toolbar > .aa-search{flex:1 1 100%;width:100%;max-width:none;margin:0}
  .portal .toolbar > .aa-search .sx{width:100%}
  .portal .toolbar > .aa-search input{width:100%;min-width:0}
  .portal .toolbar > select,.portal .toolbar > .pdc-sort{flex:1 1 100%;width:100%;margin-left:0}
  /* design catalog: All across the top, the categories 2 × 2; designs two to a row */
  .portal .pdc .toolbar > .chips{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important}
  .portal .pdc .toolbar > .chips > .chip{grid-column:auto!important;white-space:nowrap}
  .portal .pdc .toolbar > .chips > .chip:first-child:nth-last-child(odd){grid-column:1 / -1!important}
  .portal .pdc-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:10px}
  .portal .pdc-grid .dc-card{padding:6px;min-width:0}
  .portal .pdc-grid .dc-card b,.portal .pdc-grid .dc-card strong{font-size:13px;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
  .portal .pdc-grid .dc-card small,.portal .pdc-grid .dc-card .faint{font-size:11.5px}
  /* dashboard art strips */
  .pdx-hold-ok svg,.pdx-caught svg{width:36px;height:36px}
  .pdx-art{grid-template-columns:repeat(5,minmax(0,1fr))!important;gap:6px}
  .pdx-art > :nth-child(n+6){display:none}
  .pdx-thumbs{grid-template-columns:minmax(0,1fr)!important;gap:14px}
  /* orders and payments lists as cards: number, name, star on top; status and money under */
  .portal .aa-tbl tr{gap:6px 10px;padding:12px}
  .portal .aa-tbl td{padding:0!important}
  .portal .aa-tbl td.ck{order:0;align-self:flex-start}
  .portal .aa-tbl td.num:not([data-l]){order:1;align-self:flex-start}
  .portal .aa-tbl td.m{order:2;flex:1 1 0}
  .portal .aa-tbl td.aa-starc{order:3;margin-left:auto;align-self:flex-start}
  .portal .aa-tbl tr::after{order:4}
  .portal .aa-tbl td:has(> .aa-pill),.portal .aa-tbl td:has(> .aa-kind){order:5}
  .portal .aa-tbl td[data-l="Type"]::before{display:none}
  .portal .aa-tbl .aa-pill{min-width:0!important;width:auto!important;max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .portal .aa-tbl td.paid,.portal .aa-tbl td[data-l="Paid"]{display:none}
  .portal .aa-tbl td[data-l]{order:6;font-size:12.5px}
  .portal .aa-tbl td.pay{order:7;margin-left:auto}
  /* projects: the two tabs fill the row */
  .portal .pj-bar{flex-wrap:wrap}
  .portal .pj-bar > .aa-sub{display:flex;width:100%;flex:1 1 100%}
  .portal .pj-bar > .aa-sub > button{flex:1 1 0;justify-content:center;min-width:0;white-space:nowrap;font-size:13px;padding-left:6px;padding-right:6px;gap:6px}
  /* settings → people: name, email under it, then phone and the buttons */
  .portal .ps-people tr{row-gap:2px;column-gap:8px;align-items:center}
  .portal .ps-people td{padding:0!important}
  .portal .ps-people td:nth-child(1),.portal .ps-people td:nth-child(2){flex:1 1 100%!important;min-width:0;overflow-wrap:anywhere}
  .portal .ps-people td:nth-child(2){color:var(--ink-2);font-size:13px}
  .portal .ps-people td.nw{flex:1 1 auto!important;margin-top:4px;font-size:13px}
  .portal .ps-people td.ps-acts{flex:0 0 auto!important;margin-left:auto;margin-top:4px;display:flex;gap:4px}
  /* an order: the progress as dots with only the current step named (it scrolled sideways) */
  .portal .stepper{overflow:visible;padding:2px 10px 0}
  .portal .step{min-width:0;font-size:0;gap:8px}
  .portal .step .dot{font-size:10px;flex:0 0 auto}
  .portal .step.cur{font-size:12.5px;white-space:nowrap}
  .portal .step.cur:first-child{align-items:flex-start}
  .portal .step.cur:last-child{align-items:flex-end}
  /* an order's items: each line a block, Qty / Each / Amount under it (the columns were one digit wide) */
  .portal table.items,.portal table.items tbody{display:block;width:100%}
  .portal table.items thead{display:none}
  .portal table.items tr{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));column-gap:10px;row-gap:6px;padding:12px 14px;border-bottom:1px solid var(--line)}
  .portal table.items td{display:block;padding:0!important;border:0!important;min-width:0}
  .portal table.items td:first-child{grid-column:1 / -1}
  .portal table.items td:not(:first-child){text-align:left;white-space:nowrap;font-size:13.5px}
  .portal table.items td:not(:first-child):empty{display:none}
  .portal table.items td:not(:first-child):not(:empty)::before{display:block;font-size:11px;font-weight:600;color:var(--ink-3);letter-spacing:.04em;text-transform:uppercase;margin-bottom:1px}
  .portal table.items td:nth-child(2):not(:empty)::before{content:"Qty"}
  .portal table.items td:nth-child(3):not(:empty)::before{content:"Each"}
  .portal table.items td:nth-child(4):not(:empty)::before{content:"Amount"}
  .portal table.items td:nth-child(4){grid-column:3}
  .portal table.items tr:has(> td:nth-child(2):empty){grid-template-columns:minmax(0,1fr) auto}
  .portal table.items tr:has(> td:nth-child(2):empty) > td:first-child{grid-column:1}
  .portal table.items tr:has(> td:nth-child(2):empty) > td:nth-child(4){grid-column:2;text-align:right}
  .portal table.items tr:has(> td:nth-child(2):empty) > td:nth-child(4)::before{display:none}
  /* mockup creator: the fields full width */
  .mk-portal .mk-setup .mk-f > input,.mk-portal .mk-setup .style-pick input{max-width:none;width:100%}
  .mk-portal .mk-setup .mk-style,.mk-portal .mk-setup .style-pick{flex:1 1 100%;width:100%;min-width:0}
}
/* starred designs panel: its color edge stayed on the screen's left side when the panel isn't sticky */
@media (max-width:700px){.portal .aa-attn.aa-favs{position:relative;top:auto}}
/* order again: the job's name over its number */
.pdx-ag-t{flex:1 1 auto;min-width:0;display:flex;flex-direction:column}
.pdx-ag-t b{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:13px}
.pdx-ag-t small{color:var(--ink-3);font-size:11.5px}
.pdx-ag-none{position:absolute;inset:0;display:grid;place-items:center;color:var(--ink-3)}
/* status pills in dark mode: Printavo's own colors (dark green, navy…) were unreadable on the dark page */
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .aa-pill{color:color-mix(in srgb,var(--sc) 50%,#fff);background:color-mix(in srgb,var(--sc) 28%,transparent)}}
:root[data-theme="dark"] .aa-pill{color:color-mix(in srgb,var(--sc) 50%,#fff);background:color-mix(in srgb,var(--sc) 28%,transparent)}
/* (Oct 24) the dashboard's artwork tiles were a fixed 64px in 56px columns: they ran past the panel's edge */
@media (max-width:640px){.pdx-art > *{width:auto!important;height:auto!important;aspect-ratio:1;min-width:0}}
.pdx-ag-t small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* ── Portal on a phone, second pass (Oct 24, Nick: "Orders screen is still cumbersome and secondary toolbar is bad") ── */
.aa-ocards,.aa-osel{display:none}
@media (max-width:640px){
  /* Orders: one row, a dropdown for the five views and the search beside it */
  .portal .aa-otabs:has(> .aa-osel){flex-wrap:nowrap;gap:8px;align-items:stretch}
  .portal .aa-otabs:has(> .aa-osel) > .chips,.portal .aa-otabs:has(> .aa-osel) > .spacer{display:none!important}
  .portal .aa-otabs > .aa-osel{display:block;flex:0 0 auto;width:auto;max-width:46%;height:40px;padding:0 30px 0 12px;font:inherit;font-size:14px;font-weight:700;color:var(--ink);background-color:var(--surface);border:1px solid var(--line);border-radius:10px}
  .portal .aa-otabs:has(> .aa-osel) > .aa-search{flex:1 1 0!important;width:auto!important;min-width:0;height:40px}
  .portal .aa-otabs:has(> .aa-osel) > .aa-search input{padding:0;height:100%}
  /* Orders: cards instead of the table */
  .portal .aa-tblcard:has(> .aa-ocards) > table{display:none}
  .portal .aa-tblcard:has(> .aa-ocards){overflow:hidden}
  .portal .aa-ocards{display:block;list-style:none;margin:0;padding:0}
  .aa-oc{display:flex;flex-direction:column;gap:4px;padding:12px 14px;border-top:1px solid var(--line);cursor:pointer}
  .aa-oc:first-child{border-top:0}
  .aa-oc.late{box-shadow:inset 3px 0 0 var(--danger)}
  .aa-oc-top{display:flex;align-items:center;gap:8px;min-height:28px}
  .aa-oc-n{flex:1 1 auto;min-width:0;font-size:15px;font-weight:700;color:var(--ink);text-decoration:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .aa-oc-top .aa-arch{margin-left:0;flex:0 0 auto}
  .aa-oc-top .star-btn,.aa-oc-top button{flex:0 0 auto}
  .aa-oc-sub{font-size:12.5px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
  .aa-oc-bot{display:flex;align-items:center;gap:6px;margin-top:4px;min-width:0}
  .aa-oc-bot .aa-pill{min-width:0;max-width:62%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11.5px;padding:3px 9px}
  .aa-oc-bot .aa-kind{margin:0;flex:0 0 auto}
  .aa-oc-amt{margin-left:auto;display:flex;align-items:baseline;gap:5px;white-space:nowrap;flex:0 0 auto}
  .aa-oc-amt b{font-size:15px;color:var(--ink)}
  .aa-oc-amt b.aa-due{color:var(--danger)}
  .aa-oc-amt small{font-size:11.5px;color:var(--ink-3)}
  .aa-ocards .aa-empty{padding:18px 14px}
  /* Payments: the aging boxes use the full width */
  .portal .aa-paylay .aa-aging,.portal .aa-aging{width:100%;align-self:stretch}
}
/* aging boxes in dark mode: the cream and pink boxes glared on the dark page */
@media (prefers-color-scheme:dark){
  :root:not([data-theme="light"]) .aa-age.late{background:#2A2210;border-color:#6B5215}
  :root:not([data-theme="light"]) .aa-age.late b{color:#F3C969}
  :root:not([data-theme="light"]) .aa-age.bad{background:#2B1412;border-color:#7A2A22}
  :root:not([data-theme="light"]) .aa-age.bad b{color:#F4A39B}
  :root:not([data-theme="light"]) .aa-kind.k-sent{color:#F3C969}
}
:root[data-theme="dark"] .aa-age.late{background:#2A2210;border-color:#6B5215}
:root[data-theme="dark"] .aa-age.late b{color:#F3C969}
:root[data-theme="dark"] .aa-age.bad{background:#2B1412;border-color:#7A2A22}
:root[data-theme="dark"] .aa-age.bad b{color:#F4A39B}
:root[data-theme="dark"] .aa-kind.k-sent{color:#F3C969}
/* an order's items: the group's mockup with its first garment (Oct 24, Nick: "Can't see the art") */
.po-item-pics{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 8px}
.po-item-pics img{width:72px;height:72px;object-fit:contain;border:1px solid var(--line);border-radius:8px;background:#fff}
@media (max-width:640px){
  /* the print specs stay off the garments on a phone (Nick: "don't add the imprint to garments on the mobile view") */
  .portal table.items .po-item-prints{display:none}
  .po-item-pics img{width:calc((100% - 18px) / 4);height:auto;aspect-ratio:1;max-width:96px}
  .po-mock-pics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  .po-mock-pics img{width:100%;height:auto;aspect-ratio:1}
  /* the top of an order: room under the header, the status on its own, the buttons two to a row */
  .portal .p-main > .back{display:inline-block;margin-top:6px}
  .portal .p-main > .page-head{flex-direction:column;align-items:stretch;gap:12px}
  .portal .p-main > .page-head > .row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
  .portal .p-main > .page-head > .row > .pill,.portal .p-main > .page-head > .row > :first-child{grid-column:1 / -1;justify-self:start}
  .portal .p-main > .page-head > .row > .btn,.portal .p-main > .page-head > .row > * > .btn,.portal .p-main > .page-head > .row > button{width:100%;justify-content:center;min-width:0;white-space:nowrap}
}
.po-grp-art td{padding-bottom:0!important;border-bottom:0!important}
.po-grp-art .po-item-pics{margin:0}
@media (max-width:640px){.portal table.items tr.po-grp-art{border-bottom:0;padding-bottom:0}}
/* Payments on a phone: status, balance and the Pay button on one line (the total is on the order) */
@media (max-width:640px){.portal .aa-paylay .aa-tbl td[data-l="Total"]{display:none}.portal .aa-paylay .aa-tbl td.pay{margin-left:auto}.portal .aa-paylay .aa-tbl tr{align-items:center}}

/* ── Shop order on a phone (Oct 24, Nick: "Try to make this better on the mobile phone") ── */
@media (max-width:760px){
  /* every size on one row (4XL and 5XL were left alone on a second row) */
  .ord .szrow{display:grid!important;grid-template-columns:repeat(auto-fit,minmax(0,1fr));grid-auto-flow:column;gap:3px}
  .ord .szrow > .szc{width:auto!important;min-width:0}
  .ord .szrow .sz{width:100%!important;min-width:0;height:34px!important;padding:0 1px;font-size:13px;text-align:center}
  /* the mockups two to a row, the same size; Edit mockup and Customer artwork side by side; Remove and Saved under them */
  .ord .imp-mock{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;align-items:center}
  .ord .imp-mock > .mk-big{grid-column:1 / -1;width:100%!important}
  .ord .imp-mock:has(> .mk-more > :nth-child(odd):last-child) > .mk-big{grid-column:auto}
  .ord .imp-mock > .mk-big img{width:100%;height:auto;max-height:none;object-fit:contain}
  .ord .imp-mock > .mk-more{display:contents}
  .ord .imp-mock > .mk-more > button{aspect-ratio:auto;width:100%;border-radius:12px}
  .ord .imp-mock > .mk-more > button img{width:100%;height:auto}
  .ord .imp-mock > .btn{width:100%;height:36px!important;margin:0}
  .ord .imp-mock > .btn:only-of-type{grid-column:1 / -1}
  .ord .imp-mock > .btn.mk-cust{border:1px solid var(--line)}
  .ord .imp-mock > .btn.danger{justify-self:start;width:auto;padding:0 2px;height:auto!important;font-size:12.5px}
  .ord .imp-mock > .mk-when{justify-self:end;text-align:right}
  .ord .imp-mock > .mk-none,.ord .imp-mock > .ink-warn{grid-column:1 / -1}
  /* a print's Inks and Screens: the label beside its value, the pencil at the end of the row */
  .ord .pr .pr-scr{flex-wrap:nowrap;align-items:center;gap:6px}
  .ord .pr .pr-scr > .pr-scr-l{flex:0 0 52px;margin:0}
  .ord .pr .pr-scr > .pr-scr-v{flex:1 1 0!important;min-width:0;display:flex;flex-wrap:wrap;align-items:center;gap:6px}
  .ord .pr .pr-scr-v > span:not(:first-child){padding-left:7px;padding-right:7px}
  .ord .pr .pr-scr > .pr-scr-ed{flex:0 0 auto}
}
/* the phone menu: SP / EMB / HP and ADM / SHOP show even when the desktop menu was folded to icons, big enough to tap
   (Oct 24, Nick: "On the mobile phone… I can't see the little embroidery shop or admin things") */
@media (max-width:820px){
  .side .side-drawer .prod-side{display:inline-flex!important;align-items:center;gap:4px;margin-left:auto}
  .side .side-drawer .prod-side button{font-size:12px;padding:6px 8px;border-radius:6px}
  .side .side-drawer .prod-side button.on{background:rgba(255,255,255,.08)}
}
/* the Printavo "P" in place of "Archived" on order lists (Oct 26, Nick) */
.pv-mark{margin-left:8px;flex:0 0 auto}
.aa-oc-top .pv-mark{margin-left:0}
/* a print with a color change: both close-ups side by side, the garment color over each, "Color change" under the new one (Oct 26, Nick) */
.pr:has(> .pr-tiles){grid-template-columns:auto minmax(0,1fr)}
.pr-tiles{display:flex;gap:8px;align-items:flex-start}
.pr-tw{display:flex;flex-direction:column;align-items:center;gap:3px}
.pr-tc{font-size:12px;font-weight:700;color:var(--ink);white-space:nowrap;max-width:130px;overflow:hidden;text-overflow:ellipsis}
.pr-cc{font-size:11px;font-weight:700;color:var(--fbs-salmon);background:color-mix(in srgb,var(--fbs-salmon) 14%,transparent);border-radius:999px;padding:1px 8px;white-space:nowrap}
@media (max-width:760px){.pr-tiles .pr-logo{width:80px;height:80px}.pr-tc{max-width:80px}}
/* the scale control: − and + only; the ↺ keeps its spot on the left even when hidden (Oct 26, Nick) */
.mk-pill.mk-zoom .mk-zoom-r{color:var(--accent)}
.mk-pill.mk-zoom .mk-zoom-r.off{visibility:hidden}
/* a print's inks with a color change: one ink a line, "change to" the new ink's swatch, "on" the garment color (Oct 26, Nick) */
.ink-lines{display:flex;flex-direction:column;gap:4px;align-items:flex-start}
.ink-ln{display:flex;align-items:center;flex-wrap:wrap;gap:4px 6px}
.ink-to{font-size:11.5px;font-weight:600;color:var(--fbs-salmon)}
.ink-tw{display:inline-flex;align-items:center;gap:5px}
.ink-on{font-size:11.5px;color:var(--ink-3)}
.pr-cc-line .pr-scr-v{white-space:nowrap}
/* Mockup Creator: no flat back photo at S&S or SanMar, pick one (Oct 26) */
.mk-noback{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:6;width:min(92%,380px);display:flex;flex-direction:column;gap:8px;padding:14px;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:0 10px 30px rgba(20,29,43,.14);font-size:14px;color:var(--ink)}
.mk-noback > .faint{font-size:12.5px;color:var(--ink-3)}
.mk-noback-pics{display:grid;grid-template-columns:repeat(auto-fill,minmax(90px,1fr));gap:8px}
.mk-noback-pics button{display:flex;flex-direction:column;align-items:center;gap:4px;padding:6px;border:1px solid var(--line);border-radius:6px;background:var(--surface);font:inherit;font-size:12px;color:var(--ink-2);cursor:pointer}
.mk-noback-pics button:hover{border-color:var(--accent)}
.mk-noback-pics button:disabled{opacity:.6;cursor:wait}
.mk-noback-pics img{width:100%;aspect-ratio:1;object-fit:contain;background:#fff}
.mk-noback .btn{align-self:flex-start;cursor:pointer}
.mk-noback .btn.off{opacity:.6;pointer-events:none}
.mk-noback .err{font-size:12.5px;color:var(--danger)}
/* 3D puff: what's puffed and the size check, in the embroidery panel (Oct 26) */
.puff{display:flex;flex-direction:column;gap:8px;margin-top:8px;padding-top:8px;border-top:1px dashed var(--line)}
.puff-h{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.puff-b{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:10px;align-items:start}
.puff-pic{display:flex;flex-direction:column;gap:4px}
.puff-pic canvas{width:100%;height:auto;background:var(--surface-2);border:1px solid var(--line);border-radius:6px;cursor:pointer}
.puff-pic .faint{font-size:12px;color:var(--ink-3)}
.puff-cols{display:flex;flex-direction:column;gap:6px;font-size:13px}
.puff-cols .check{gap:6px}
.puff-sw{display:inline-block;width:14px;height:14px;border-radius:4px;border:1px solid var(--line)}
.puff-ok{margin:0;font-size:12.5px;color:var(--ok)}
/* Mockup Creator: full color art, how it prints (Oct 26) */
.mk-full{display:flex;flex-direction:column;gap:6px;margin:8px 0;padding:10px 12px;border:1px solid var(--line);border-radius:var(--r);background:var(--surface-2);font-size:13px}
.mk-full.ask{border-color:var(--warn);background:var(--warn-soft)}
.mk-full .faint{font-size:12.5px;color:var(--ink-3)}
/* Gang sheet builder (Heat press, Oct 26) */
.gang{display:grid;grid-template-columns:minmax(260px,340px) minmax(0,1fr);gap:16px;align-items:start}
@media (max-width:900px){.gang{grid-template-columns:1fr}}
.gang-up{display:flex;align-items:center;gap:12px;min-height:72px;padding:10px;border:1.5px dashed var(--line);border-radius:var(--r);cursor:pointer;font-size:14px;color:var(--ink)}
.gang-up:hover{border-color:var(--accent)}
.gang-up img{width:64px;height:48px;object-fit:contain;background:repeating-conic-gradient(var(--surface-2) 0 25%,var(--surface) 0 50%) 0 0/10px 10px;border-radius:4px}
.gang-up span{display:flex;flex-direction:column;gap:2px}
.gang-up .faint{font-size:12px;color:var(--ink-3)}
.gang-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.gang-row .field input{height:36px;border-radius:6px;border:1px solid var(--line);font-size:14px;padding:0 10px;width:100%}
.gang .field > input{height:36px;border-radius:6px;border:1px solid var(--line);font-size:14px;padding:0 10px}
.gang-warn{margin:0;font-size:12.5px;color:var(--warn)}
.gang-sheet{overflow:auto;max-height:70vh;border:1px solid var(--line);border-radius:6px;padding:8px;background:var(--surface-2)}
.gang-sheet canvas{display:block;max-width:100%;height:auto;background:repeating-conic-gradient(#e9e9e9 0 25%,#fff 0 50%) 0 0/14px 14px;box-shadow:0 0 0 1px var(--line)}
.gang-stats{display:flex;flex-wrap:wrap;gap:6px 18px;margin-top:10px;font-size:13px;color:var(--ink-2)}
.gang-stats .faint{color:var(--ink-3)}
/* Gang sheet builder v2: logos with their versions (sizes / knocked-out colors), sheet, layout and cost (Oct 26) */
.gang-item{display:flex;flex-direction:column;gap:8px;padding:10px;border:1px solid var(--line);border-radius:var(--r);background:var(--surface)}
.gang-item-h{display:flex;align-items:center;gap:10px;min-width:0;font-size:14px}
.gang-item-h b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.gang-item-h input{height:36px;border:1px solid var(--line);border-radius:6px;padding:0 10px;font-size:14px}
.gang-pic{flex:none;width:56px;height:42px;display:grid;place-items:center;border-radius:4px;background:repeating-conic-gradient(var(--surface-2) 0 25%,var(--surface) 0 50%) 0 0/10px 10px;border:1px solid var(--line)}
.gang-pic img{max-width:100%;max-height:100%;object-fit:contain}
.gang-pic .faint{font-size:11px;color:var(--ink-3)}
.gang-vers{display:flex;flex-direction:column;gap:6px}
.gang-ver{display:grid;grid-template-columns:76px 56px 70px minmax(0,1fr) 30px;gap:6px;align-items:center;font-size:13px}
.gang-ver input{height:36px;border:1px solid var(--line);border-radius:6px;padding:0 8px;font-size:14px;min-width:0;width:100%}
.gang-ver-h span{font-size:11px;font-weight:600;color:var(--ink-3);text-transform:uppercase;letter-spacing:.03em}
.gang-knock{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:2px 0 4px;font-size:12.5px}
.gang-knock-row{display:flex;flex-wrap:wrap;align-items:center;gap:6px;width:100%}
.gang-knock-row .faint{font-size:12px;color:var(--ink-3)}
.gang-sw{width:26px;height:26px;border-radius:6px;border:1px solid var(--line);cursor:pointer;position:relative;padding:0}
.gang-sw.on::after{content:"";position:absolute;inset:-1px;border-radius:6px;background:linear-gradient(45deg,transparent 46%,var(--danger) 46% 54%,transparent 54%)}
.gang-sw.sm{width:14px;height:14px;border-radius:4px;display:inline-block;cursor:default}
.gang-row3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.gang-row3 .field input{height:36px;border-radius:6px;border:1px solid var(--line);font-size:14px;padding:0 10px;width:100%}
.gang-sum{margin:0}
.gang-zoom{display:flex;align-items:center;gap:6px;margin-bottom:6px;font-size:13px}
.gang-zoom .num{min-width:44px;text-align:center}
.gang-sheet.zoomed{max-height:75vh}
.gang-sheet.zoomed canvas{max-width:none}
.gang-vthumb{height:28px;max-width:80px;object-fit:contain;border:1px solid var(--line);border-radius:4px;background:repeating-conic-gradient(var(--surface-2) 0 25%,var(--surface) 0 50%) 0 0/8px 8px}
.gang-bar{margin-bottom:14px;flex-wrap:wrap}
.gang-bar select,.gang-bar input{height:36px;border:1px solid var(--line);border-radius:6px;font-size:14px;padding:0 10px;max-width:280px}
.gang-save{font-size:12.5px;color:var(--ink-3);white-space:nowrap}
.gang-job{height:36px;width:92px;border:1px solid var(--line);border-radius:6px;padding:0 8px;font-size:14px}
/* Gang sheet builder, the layout rethought (Oct 26): art on the left, the cost and the sheet filling the right */
.gang2{display:grid;grid-template-columns:minmax(320px,400px) minmax(0,1fr);gap:16px;align-items:start}
@media (max-width:980px){.gang2{grid-template-columns:1fr}}
.gang-left{display:flex;flex-direction:column;gap:12px;border-radius:var(--r);min-width:0}
.gang-left.over{outline:2px dashed var(--accent);outline-offset:4px}
.gang-card{padding:12px}
.gang-card-h{display:grid;grid-template-columns:48px minmax(0,1fr) auto 30px;gap:10px;align-items:center}
.gang-card .gang-pic{width:48px;height:48px}
.gang-card .gang-pic span{font-size:10px;color:var(--ink-3)}
.gang-card-t{display:flex;flex-direction:column;gap:2px;min-width:0}
.gang-card-t b{font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.gang-card-t .faint{font-size:12px;color:var(--ink-3)}
.gang-card-t input{height:36px;border:1px solid var(--line);border-radius:6px;padding:0 10px;font-size:14px}
.gang-vt{width:100%;border-collapse:collapse;margin-top:10px}
.gang-vt th{font-size:11px;font-weight:600;color:var(--ink-3);text-transform:uppercase;letter-spacing:.03em;text-align:left;padding:0 4px 4px}
.gang-vt td{padding:3px 4px;vertical-align:middle}
.gang-vt input{height:36px;border:1px solid var(--line);border-radius:6px;padding:0 8px;font-size:14px;width:100%;min-width:0}
.gang-wh{display:flex;align-items:center;gap:4px}
.gang-wh input{width:58px}
.gang-h{display:inline-block;width:46px;font-size:14px;color:var(--ink-2)}
.gang-q{width:58px!important}
.gang-ko{display:flex;flex-wrap:wrap;gap:4px}
.gang-dot{width:20px;height:20px;border-radius:50%;border:1px solid var(--line);padding:0;cursor:pointer;position:relative}
.gang-dot.off::after{content:"";position:absolute;inset:-2px;border-radius:50%;background:linear-gradient(45deg,transparent 44%,var(--danger) 44% 56%,transparent 56%)}
.gang-dot:hover{box-shadow:0 0 0 2px var(--accent-soft)}
.gang-add{margin-top:6px;font-size:13px}
.gang-drop{display:flex;align-items:center;justify-content:center;min-height:64px;padding:12px;border:1.5px dashed var(--line);border-radius:var(--r);color:var(--ink-3);font-size:13px;cursor:pointer;text-align:center}
.gang-drop:hover{border-color:var(--accent);color:var(--ink-2)}
.gang-drop b{color:var(--ink)} .gang-drop u{color:var(--accent);text-decoration:none}
.gang-job-row{display:flex;flex-direction:column;gap:8px;padding-bottom:10px;border-bottom:1px solid var(--line-2)}
.gang-job-top{display:grid;grid-template-columns:140px minmax(0,1fr) 30px;gap:10px;align-items:end}
.gang-job-top input,.gang-job-row textarea{height:36px;border:1px solid var(--line);border-radius:6px;padding:0 10px;font-size:14px;width:100%}
.gang-job-row textarea{height:auto;padding:8px 10px;font-family:inherit;resize:vertical}
.gang-job-found{font-size:13px;padding-bottom:9px}
.gang-job-art{flex-wrap:wrap;align-items:center;gap:6px}
.gang-job-art .faint{font-size:12px;color:var(--ink-3)}
.gang-right{display:flex;flex-direction:column;min-width:0}
.gang-tabs{margin:10px 0 8px;align-items:center}
.gang-view{overflow:auto;max-height:calc(100vh - 290px);min-height:320px;border:1px solid var(--line);border-radius:var(--r);padding:8px;background:var(--surface-2)}
.gang-view canvas{display:block;background:repeating-conic-gradient(#e9e9e9 0 25%,#fff 0 50%) 0 0/14px 14px;box-shadow:0 0 0 1px var(--line)}
.gang-empty{display:grid;place-items:center;min-height:320px;border:1.5px dashed var(--line);border-radius:var(--r);color:var(--ink-3);font-size:14px}
.gang-pop{position:relative}
.gang-pop-b{position:absolute;right:0;top:calc(100% + 6px);z-index:30;width:min(420px,90vw);padding:12px;display:flex;flex-direction:column;gap:8px;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:0 12px 32px rgba(20,29,43,.16)}
.gang-row2{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.gang-row2 .field input{height:36px;border-radius:6px;border:1px solid var(--line);font-size:14px;padding:0 10px;width:100%}
.gang-sheets{padding:10px 12px;display:flex;flex-direction:column;gap:4px}
.gang-sheets-h{display:flex;align-items:center;gap:8px;margin-bottom:2px}
.gang-sheets-h b{font-family:var(--display);font-size:15px}
.gang-sr{display:flex;align-items:baseline;gap:8px;width:100%;padding:5px 8px;border:0;border-left:3px solid transparent;background:none;font:inherit;text-align:left;cursor:pointer;border-radius:0;min-width:0}
.gang-sr:hover{background:var(--surface-2)}
.gang-sr.on{background:var(--accent-soft);border-left-color:var(--accent)}
.gang-sr-n{font-size:13.5px;font-weight:600;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;flex:1}
.gang-sr-m{font-size:12px;color:var(--ink-3);white-space:nowrap}
.gang-more{height:32px;border:1px solid var(--line);border-radius:6px;font-size:13px;padding:0 8px;color:var(--ink-2)}
.gang-sheets-cur{display:flex;align-items:center;gap:8px;margin-top:4px}
.gang-sheets-cur input{flex:1;height:36px;border:1px solid var(--line);border-radius:6px;padding:0 10px;font-size:14px;min-width:0}
.gang-sheets-cur .faint{font-size:12px;color:var(--ink-3);white-space:nowrap}
/* Gang sheet builder v3 (Oct 26): actions by the title, boxed sheets / art / order on the left */
.gang-acts{gap:8px;flex-wrap:wrap;align-items:center}
.gang-sheets{display:flex;flex-direction:column;gap:4px;padding-top:6px}
.gang-art.over{outline:2px dashed var(--accent);outline-offset:3px}
.gang-art .gang-card{padding:10px;border:1px solid var(--line-2);border-radius:var(--r);background:var(--surface)}
.gang-drop.big{min-height:120px;font-size:14px}
.gang-drop .faint{font-size:12px}
.gang-cust{display:flex;flex-direction:column;gap:8px}
.gang-cust > .faint{font-size:12.5px;color:var(--ink-3)}
.gang-cust-q{height:36px;border:1px solid var(--line);border-radius:6px;padding:0 10px;font-size:14px}
.gang-cust-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:8px;max-height:320px;overflow:auto}
.gang-cust-d{display:flex;flex-direction:column;align-items:center;gap:4px;padding:6px;border:1px solid var(--line);border-radius:6px;background:var(--surface);font:inherit;font-size:11.5px;color:var(--ink-2);cursor:pointer;min-width:0}
.gang-cust-d:hover{border-color:var(--accent)}
.gang-cust-d img{width:100%;aspect-ratio:1;object-fit:contain;background:repeating-conic-gradient(var(--surface-2) 0 25%,var(--surface) 0 50%) 0 0/8px 8px;border-radius:4px}
.gang-cust-d span:last-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%}
.gang-sum-p{overflow:hidden}
.gang-sum-p .gang-sum{margin:0}
.gang-sheet-p{margin-top:12px}
.gang-tabs{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.gang-sheet-p .gang-view{max-height:calc(100vh - 300px)}
.aa-gang{margin-top:18px}
.aa-gang .aa-sec-h{display:flex;align-items:baseline;gap:8px}
.aa-gang .aa-sec-h .faint{font-size:12px;color:var(--ink-3)}
/* gang sheet boxes: the title with the color bar under it (like the page title), its note under that, the button on the
   right (Oct 26, Nick) */
.gang-ph{align-items:flex-start}
.gang-pt{display:flex;flex-direction:column;gap:3px;min-width:0}
.gang-pt h2{padding-left:0!important;display:inline-block;align-self:flex-start}
.gang-pt h2::before{display:none!important}
.gang-pt h2::after{content:"";display:block;height:3px;border-radius:3px;margin-top:5px;width:calc(100% + 16px);min-width:44px;background:var(--fbs-fade,linear-gradient(90deg,var(--fbs-blue),var(--fbs-salmon),var(--fbs-orange)))}
.gang-pt .faint{font-size:12.5px;color:var(--ink-3);margin-top:2px}
.gang-ph .btn{margin-top:2px}
/* the space between pieces, over the sheet preview */
.gang-gap{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:0 0 10px;font-size:13px;color:var(--ink-3)}
.gang-gap label{font-size:13px;color:var(--ink-2,var(--ink-3));white-space:nowrap}
.gang-gap input[type=range]{flex:1;min-width:120px;max-width:260px;accent-color:var(--accent)}
.gang-gap b{color:var(--ink);font-weight:700;min-width:44px;white-space:nowrap}
.gang-gap .faint{white-space:nowrap;font-size:12.5px}
/* Reorder a gang sheet (components/GangReorder.tsx) */
.dla.grd{width:min(620px,100%);padding:0;display:flex;flex-direction:column}
.dla.grd > .panel-h{padding:14px 18px;border-bottom:1px solid var(--line)}
.grd-b{padding:10px 18px 14px;overflow:auto}
.grd-sec{font-size:12.5px;font-weight:700;color:var(--ink-3);margin:10px 0 2px}
.grd-card{border:1px solid var(--line);border-radius:var(--r);padding:10px 12px;margin-top:8px;background:var(--surface)}
.grd-card.off .grd-rt,.grd-card.off .grd-ed{opacity:.45;pointer-events:none}
.grd-top{display:grid;grid-template-columns:auto 40px minmax(0,1fr) auto;gap:10px;align-items:center}
.grd-th{width:40px;height:40px;border-radius:6px;background:var(--surface-2,#f4f6f9);display:flex;align-items:center;justify-content:center;overflow:hidden;font-size:12px}
.grd-th img{max-width:100%;max-height:100%;object-fit:contain}
.grd-nm{min-width:0}
.grd-nm b{display:block;font-size:14px;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.grd-tags{display:flex;flex-wrap:wrap;gap:5px;margin-top:4px}
.grd-tag{display:inline-flex;align-items:center;gap:3px;font-size:12px;color:var(--ink-3);background:var(--surface-2,#f4f6f9);border-radius:6px;padding:2px 8px;white-space:nowrap}
.grd-tag.ch{background:var(--warn-soft,#fdf3e1);color:var(--warn)}
.grd-dot{display:inline-block;width:10px;height:10px;border-radius:50%;border:1px solid var(--line)}
.grd-rt{display:flex;flex-direction:column;align-items:flex-end;gap:4px}
.grd-rt input{width:72px;height:36px;border:1px solid var(--line);border-radius:6px;padding:0 8px;font:14px var(--body);color:var(--ink);text-align:right}
.grd .linkish{background:none;border:0;padding:0;color:var(--accent);font-size:12.5px;cursor:pointer}
.grd-ed{display:flex;align-items:flex-end;gap:14px;flex-wrap:wrap;margin-top:10px;padding-top:10px;border-top:1px solid var(--line-2,var(--line))}
.grd-ed .field input{width:96px}
.grd-ed .gang-ko{height:36px;align-items:center}
.grd-ed .linkish{margin-bottom:10px}
.grd-only{flex-basis:100%;font-size:12px}
.grd-add{margin-top:12px}
.grd-pick{margin-top:12px;padding:10px 12px;border-radius:var(--r);background:var(--surface-2,#f4f6f9)}
.grd-pick select{width:100%}
.grd-pl{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}
.grd-pl .btn{display:inline-flex;align-items:center;gap:6px}
.grd-pl img{width:20px;height:20px;object-fit:contain}
.grd-f{display:flex;align-items:flex-end;gap:12px;flex-wrap:wrap;padding:12px 18px;border-top:1px solid var(--line)}
.grd-f .field input{width:120px}
.grd-f > .faint{margin-bottom:9px;white-space:nowrap}
/* phones: Sheet settings opens under the buttons, full width, not off the left edge */
@media (max-width:700px){
  .gang-acts{position:relative}
  .gang-acts .gang-pop{position:static}
  .gang-pop-b{left:0;right:0;width:auto}
  .gang-row2{grid-template-columns:1fr}
}
/* the art card's quantity: a normal field by the art, its label in blue to the left (Oct 26, Nick) */
.gang-qbox{display:flex;flex-direction:row;align-items:center;gap:8px;flex:none}
.gang-qbox span{font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--accent)}
.gang-qbox input{width:80px;height:36px;border:1px solid var(--line);border-radius:6px;background:var(--surface);font:700 14px var(--body);color:var(--ink);padding:0 10px}
.gang-qtot{flex:none;font-size:14px;font-weight:700;color:var(--accent);white-space:nowrap}
/* saved gang sheets: a row with its delete (click twice) */
.gang-sr-row{display:flex;align-items:center;gap:4px;min-width:0}
.gang-sr-row .gang-sr{flex:1}
.gang-del{flex:none;height:26px;min-width:26px;padding:0 6px;border:1px solid transparent;border-radius:6px;background:none;color:var(--ink-3);font:13px var(--body);cursor:pointer;white-space:nowrap;margin-left:4px}
.gang-del:hover{border-color:var(--line);color:var(--danger)}
.gang-del.armed{background:var(--danger);border-color:var(--danger);color:#fff;font-weight:700}
.gang-size{font-size:13px;color:var(--ink-3);white-space:nowrap}
.gang-size b{color:var(--ink);font-weight:700}
/* Gang sheets page: a card per sheet, like Artwork */
.gang-gc-img{display:grid;grid-template-columns:1fr 1fr;gap:6px;background:repeating-conic-gradient(var(--surface-2,#f4f6f9) 0 25%,var(--surface) 0 50%) 0 0/14px 14px;text-decoration:none}
.gang-gc-img:has(.gang-gc-t:only-child){grid-template-columns:1fr}
.gang-gc-t{display:flex;align-items:center;justify-content:center;min-width:0;min-height:0;overflow:hidden;font-size:12px}
.gang-gc-t img{max-width:100%;max-height:100%;object-fit:contain}
.gang-gc-n{font-weight:700;color:var(--ink);text-decoration:none;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.gang-gc-n:hover{color:var(--accent)}
.gang-gc .faint{font-size:12px;color:var(--ink-3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.gang-gc-s{font-size:12px;font-weight:700;color:var(--accent);white-space:nowrap}
.gang-gc-s.ord{color:var(--ok)}
.gang-gc-acts{display:flex;align-items:center;gap:6px;margin-top:6px}
.gang-tabs .btn.on{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}
.aa-card.aa-gang{margin-top:0}
.mk-ko{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin-top:6px}
td.num .pv-mark,.tbl td .tag + .pv-mark{margin-left:6px;vertical-align:middle}
/* Create DTF gang sheet from a screen printed order: which art */
.gang-ask-n{display:block;font-size:14px;color:var(--ink)}
.gang-ask-s{display:block;font-size:12px;color:var(--ink-3);margin-top:2px}
.gang-ask-two{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:8px}
.gang-ask-o{display:flex;flex-direction:column;gap:4px;align-items:flex-start;text-align:left;padding:8px;border:1.5px solid var(--line);border-radius:var(--r);background:var(--surface);cursor:pointer;font:inherit}
.gang-ask-o.on{border-color:var(--accent);background:var(--accent-soft)}
.gang-ask-o:disabled{opacity:.5;cursor:default}
.gang-ask-o b{font-size:13px;color:var(--ink)}
.gang-ask-o .faint{font-size:12px;color:var(--ink-3)}
.gang-ask-pic{width:100%;height:96px;display:flex;align-items:center;justify-content:center;border-radius:6px;background:repeating-conic-gradient(var(--surface-2,#f4f6f9) 0 25%,var(--surface) 0 50%) 0 0/12px 12px;overflow:hidden}
.gang-ask-pic img{max-width:100%;max-height:100%;object-fit:contain}
/* customer: other addresses besides billing and ship-to */
.cu-oa{display:flex;flex-direction:column;gap:8px;align-items:flex-start}
.cu-oa-r{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.6fr) 32px;gap:10px;align-items:start;width:100%}
.cu-oa-r .btn{margin-top:22px}
@media (max-width:640px){.cu-oa-r{grid-template-columns:minmax(0,1fr) 32px}.cu-oa-r .field:nth-child(2){grid-column:1}}
.se-steps{margin:0;padding-left:20px;display:flex;flex-direction:column;gap:6px;font-size:14px;color:var(--ink)}
.se-box{display:flex;flex-direction:column;gap:8px;border-top:1px solid var(--line);padding-top:12px;margin-top:4px}

/* Account owners page (Oct 26): money right-aligned, the owner chips in one row */
.ao-tbl td.num,.ao-tbl th.num{text-align:right}
.ao-tbl .nowrap{white-space:nowrap}
.ao-pick{flex-wrap:nowrap}
.ao-pick .chip{min-width:72px;justify-content:center}

/* Favorites, option A (Oct 26, Nick): one line per job and per thing waiting */
.fv-a .fv-top{border-bottom:0;padding-bottom:6px}
.fv-wait{font-size:12px;font-weight:700;color:var(--danger);background:color-mix(in srgb,var(--danger) 10%,var(--surface));border-radius:99px;padding:3px 10px;text-decoration:none;white-space:nowrap}
.fv-row{display:flex;align-items:center;gap:10px;padding:7px 14px;border-top:1px solid var(--line-2);font-size:14px;color:var(--ink);text-decoration:none;min-width:0}
.fv-row:hover .fv-x{color:var(--accent)}
.fv-row .ordno{font-weight:700;white-space:nowrap}
.fv-x{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fv-row .fv-ic svg{transform:none;stroke:var(--fbs-blue)}
.fv-d{font-size:12px;color:var(--ink-3);white-space:nowrap;min-width:46px;text-align:right}
.fv-d.late{color:var(--danger);font-weight:700}
.fv-pl{font-size:11.5px;font-weight:700;border-radius:99px;padding:2px 9px;white-space:nowrap;--pc:var(--ink-3);color:var(--pc);background:color-mix(in srgb,var(--pc) 12%,var(--surface))}
.fv-pl.s1,.fv-pl.s2{--pc:var(--fbs-blue)}.fv-pl.s3{--pc:var(--warn)}.fv-pl.s4{--pc:var(--ok)}
.fv-a .fv-foot{gap:0;display:block;border-top:1px solid var(--line-2)}
.fv-a .fv-q{padding:7px 14px}

/* My Day → Email summary (Oct 26, Nick picked the graphic version): three count tiles, then people, calm colors */
.md-email{--mc:var(--fbs-blue)}
.md2-side .md-email .md-scroll{max-height:440px;overflow-x:hidden}
.mds-tiles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:2px 0 8px}
.mds-tile{--tc:var(--fbs-blue);display:flex;flex-direction:column;align-items:center;gap:1px;padding:9px 4px 8px;border-radius:var(--r);text-decoration:none;color:var(--tc);background:color-mix(in srgb,var(--tc) 11%,var(--surface))}
.mds-tile.k-fresh,.mds-av.k-fresh{--tc:var(--ok)}.mds-tile.k-web,.mds-av.k-web{--tc:var(--fbs-orange)}
.mds-tile.k-web{color:color-mix(in srgb,var(--fbs-orange) 60%,var(--ink))}
.mds-tile svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.mds-tile b{font-size:20px;line-height:1.1;font-weight:700}
.mds-tile span{font-size:11.5px;font-weight:700;text-align:center;line-height:1.2}
.mds-tile.zero{opacity:.55}
.mds-h{font-size:12px;color:var(--ink-3);margin:8px 0 0;padding-top:8px;border-top:1px solid var(--line-2)}
.mds-row{display:flex;align-items:center;gap:10px;padding:6px 0;text-decoration:none;color:var(--ink);min-width:0}
.mds-row:hover .mds-n{color:var(--accent)}
.mds-av{--tc:var(--fbs-blue);width:30px;height:30px;border-radius:50%;flex:none;display:flex;align-items:center;justify-content:center;font-size:11.5px;font-weight:700;color:var(--tc);background:color-mix(in srgb,var(--tc) 13%,var(--surface))}
.mds-av.k-web{color:color-mix(in srgb,var(--fbs-orange) 60%,var(--ink))}
.mds-x{flex:1;min-width:0;display:flex;flex-direction:column;line-height:1.3}
.mds-n{font-size:13.5px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mds-t{font-size:12px;color:var(--ink-3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mds-w{font-size:12px;color:var(--ink-3);white-space:nowrap;display:flex;align-items:center;gap:5px}
.mds-rush{width:7px;height:7px;border-radius:50%;background:var(--fbs-orange)}
.mds-none{font-size:13px;color:var(--ink-3);padding:8px 2px}

/* To-dos, option A (Oct 26, Nick): just the list. One line each, the due day on the right; click one for its details */
.md-task-a{align-items:center;padding:7px 0}
.md-task-a .md-check{margin-top:0;width:18px;height:18px}
.md-task-a button.md-task-t{display:block;width:100%;border:0;background:none;padding:0;font:inherit;font-size:14px;text-align:left;cursor:pointer;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.md-task-a.open button.md-task-t{white-space:normal}
.md-task-a button.md-task-t:hover{color:var(--accent)}
.md-task-a.open{align-items:flex-start}
.md-due{flex:none;font-size:12px;color:var(--ink-3);white-space:nowrap}
.md-due.late{color:var(--danger);font-weight:700}
.md-task-a .md-more{opacity:0;padding:0 2px}
.md-task-a:hover .md-more,.md-task-a .md-more[aria-expanded="true"],.md-task-a .md-more:focus-visible{opacity:1}
.md-all{display:block;margin:6px 0 2px;font-size:12.5px}

/* Favorites, graphic (Oct 26, Nick: "more graphic based… don't use such bold colors so it's calm and neutral"): two
   cards a row, what's waiting as quiet counts, each job with a soft five-step track */
.fv-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:12px}
.fv-g{margin:0;display:flex;flex-direction:column}
.fv-g .fv-top{border-bottom:0;padding-bottom:8px}
.fv-g .fv-av{color:var(--ink-2);background:var(--surface-2)}
.fv-waits{display:flex;flex-wrap:wrap;gap:6px;padding:0 14px 10px}
.fv-wb{display:inline-flex;align-items:center;gap:5px;font-size:12.5px;color:var(--ink-2);background:var(--surface-2);border:1px solid var(--line-2);border-radius:99px;padding:3px 10px;text-decoration:none;white-space:nowrap}
.fv-wb:hover{border-color:var(--accent);color:var(--accent)}
.fv-wb .fv-ic svg{width:13px;height:13px;transform:none;stroke:currentColor}
.fv-gj{display:block;padding:9px 14px;border-top:1px solid var(--line-2);text-decoration:none;color:var(--ink)}
.fv-gj:hover .fv-x{color:var(--accent)}
.fv-gt{display:flex;align-items:baseline;gap:8px;font-size:14px;min-width:0}
.fv-gt .ordno{font-weight:700;white-space:nowrap}
.fv-gt .fv-d{margin-left:auto}
.fv-tk{display:grid;grid-template-columns:repeat(5,1fr);gap:4px;margin-top:7px}
.fv-tk i{height:5px;border-radius:3px;background:var(--line-2)}
.fv-tk i.d{background:color-mix(in srgb,var(--fbs-blue) 35%,var(--surface))}
.fv-tk i.c{background:color-mix(in srgb,var(--fbs-blue) 70%,var(--surface))}
.fv-tl{display:grid;grid-template-columns:repeat(5,1fr);gap:4px;margin-top:3px;font-size:11px;color:var(--ink-3)}
.fv-tl .c{color:var(--ink);font-weight:700}
.fv-g .fv-foot{display:flex;justify-content:space-between;margin-top:auto;border-top:1px solid var(--line-2)}
.fv-g .fv-q{font-size:13px;color:var(--ink-3)}
.fv-g .fv-d.late{color:var(--danger);font-weight:700}
/* the Email tiles and faces, calm like the rest of My Day (Oct 26, Nick: "calm and neutral") */
.mds-tile{background:var(--surface-2);border:1px solid var(--line-2);color:var(--ink)}
.mds-tile svg{color:color-mix(in srgb,var(--tc) 75%,var(--ink-3))}
.mds-tile.k-web{color:var(--ink)}
.mds-tile span{color:var(--ink-3)}
.mds-tile.zero{opacity:1}.mds-tile.zero b{color:var(--ink-3)}
.mds-av,.mds-av.k-web{color:var(--ink-2);background:var(--surface-2)}

/* Screen sharing (Oct 26): the sharer's bar, Nick's Join card, and the viewer */
.ss-pill,.ss-invite{position:fixed;right:18px;bottom:18px;z-index:1200;display:flex;align-items:center;gap:10px;background:var(--surface);border:1px solid var(--line);border-radius:12px;box-shadow:0 8px 28px rgba(20,29,43,.16);padding:10px 12px;font-size:14px;color:var(--ink);max-width:min(520px,calc(100vw - 36px))}
.ss-invite{bottom:84px}
.ss-t{flex:1;min-width:0}
.ss-live{width:9px;height:9px;border-radius:50%;background:var(--ink-3);flex:none}
.ss-live.on{background:var(--danger);box-shadow:0 0 0 4px color-mix(in srgb,var(--danger) 18%,transparent)}
.ss-av{width:32px;height:32px;border-radius:50%;flex:none;display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--ink-2);background:var(--surface-2)}
.ss-iv-b{display:flex;flex-direction:column;min-width:0;flex:1}
.ss-iv-b .faint{font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ss-view{position:fixed;inset:0;z-index:1300;background:#0d131c;display:flex;flex-direction:column}
.ss-bar{display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--surface);border-bottom:1px solid var(--line);font-size:14px;color:var(--ink)}
.ss-bar .faint{font-size:12.5px}
.ss-stage{flex:1;min-height:0;position:relative;display:flex;align-items:center;justify-content:center}
.ss-stage video{max-width:100%;max-height:100%;width:100%;height:100%;object-fit:contain;background:#0d131c}
.ss-wait{position:absolute;color:#cfd6df;font-size:15px}
@media (max-width:640px){ .ss-pill,.ss-invite{left:12px;right:12px;bottom:12px;flex-wrap:wrap} .ss-invite{bottom:76px} }

/* Sales by department (Oct 26): soft department colors, the year's split above the chart */
.dp-sp{fill:color-mix(in srgb,var(--fbs-blue) 72%,var(--surface));background:color-mix(in srgb,var(--fbs-blue) 72%,var(--surface))}
.dp-emb{fill:color-mix(in srgb,var(--fbs-salmon) 62%,var(--surface));background:color-mix(in srgb,var(--fbs-salmon) 62%,var(--surface))}
.dp-hp{fill:color-mix(in srgb,var(--fbs-orange) 66%,var(--surface));background:color-mix(in srgb,var(--fbs-orange) 66%,var(--surface))}
.dp-ot{fill:var(--line);background:var(--line)}
.dp-legend{display:flex;flex-wrap:wrap;gap:4px 14px;margin:2px 0 6px;font-size:12.5px;color:var(--ink-2)}
.dp-k{display:inline-flex;align-items:baseline;gap:5px;white-space:nowrap}
.dp-k i{width:9px;height:9px;border-radius:2px;display:inline-block;transform:translateY(1px)}
.dp-k b{color:var(--ink);font-weight:700}
.dp-k .faint{font-size:11.5px}
.dp-sw{display:inline-block;width:8px;height:8px;border-radius:2px}
.an-side-2{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.an-side-2 .an-side-k b{font-size:18px}

/* My Day, one calm look (Oct 26, Nick: "a lot of information… all look cohesive… one nice calming way to view your
   day"): every section the same white card with a thin border, a small colored dot by each title instead of thick
   colored bars, softer chart colors, a quiet Cheer mode */
.md2 .db-card{border-top:1px solid var(--line);box-shadow:0 1px 2px rgba(20,29,43,.04)}
.md2 .db-card-h h2::before,.md2 .md-col-h h2::before{content:"";display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:8px;vertical-align:2px;background:var(--c,var(--mc,var(--fbs-blue)))}
.md2 .md-col::before{display:none}
.md2 .md-col{box-shadow:0 1px 2px rgba(20,29,43,.04)}
.md2 .an-card{border-color:var(--line-2)}
.md2 .an-b1,.md2 .an-l1{--soft:color-mix(in srgb,var(--fbs-blue) 72%,var(--surface))}
.md2 .an-b1{fill:var(--soft)}
.md2 .an-l1{stroke:var(--soft)}
.md2 .an-bar span{background:color-mix(in srgb,var(--fbs-blue) 60%,var(--surface))}
.md2 .fv-card{box-shadow:0 1px 2px rgba(20,29,43,.04)}
.md-cheer.on{background:var(--surface-2);color:var(--ink);border-color:var(--line)}

/* Sales, option B (Oct 26, Nick: "rethink this layout, make it more readable"): one big chart you flip on the left,
   the four numbers, the owner split and the top customers on the right */
.an-board{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(280px,1fr);gap:20px;align-items:start}
.an-board-l,.an-board-r{min-width:0;display:flex;flex-direction:column;gap:14px}
.an-board-h{margin-bottom:0}
.an-board-h b{font-size:15px}
.an-board .an-ax{font-size:12.5px}
.an-k4{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.an-k4 .an-side-k b{font-size:22px}
.an-split{display:flex;flex-direction:column;gap:6px}
.an-split-h{display:flex;align-items:baseline;gap:8px;font-size:14px}
.an-split-h .faint{font-size:12px}
.an-split-bar{display:flex;gap:2px;height:12px;border-radius:6px;overflow:hidden;background:var(--line-2)}
.an-split-bar i{display:block;height:100%;min-width:3px}
.an-split-l{display:flex;flex-wrap:wrap;gap:4px 14px;font-size:13px;color:var(--ink-2)}
.an-split-l>span{white-space:nowrap;display:inline-flex;align-items:baseline;gap:4px}
.an-split-l i{width:9px;height:9px;border-radius:2px;display:inline-block}
.an-split-l b,.an-split-o b{color:var(--ink);font-weight:700}
.an-split-o{display:flex;justify-content:space-between;gap:10px;font-size:13.5px}
.an-split-o>span{display:flex;flex-direction:column;white-space:nowrap}
.an-split-o>span:last-child{text-align:right}
.an-split-o .faint{font-size:12px}
.an-more{font-size:12.5px;margin-top:6px;align-self:flex-start}
@media (max-width:1100px){ .an-board{grid-template-columns:minmax(0,1fr)} }

/* Report an issue → share my screen, first and spelled out (Oct 26, Nick) */
.sup-live{border:1px solid color-mix(in srgb,var(--fbs-blue) 35%,var(--line));background:color-mix(in srgb,var(--fbs-blue) 6%,var(--surface));border-radius:12px;padding:12px 14px;margin:2px 0 4px}
.sup-live-h{display:flex;align-items:center;gap:12px}
.sup-live-h svg{width:28px;height:28px;flex:none;fill:none;stroke:var(--fbs-blue);stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.sup-live-h>div{flex:1;min-width:0;display:flex;flex-direction:column;font-size:14px;color:var(--ink)}
.sup-live-h>div span{font-size:12.5px;color:var(--ink-3)}
.sup-steps{margin:10px 0 0;padding-left:20px;font-size:13px;color:var(--ink-2);display:flex;flex-direction:column;gap:3px}
.sup-steps b{color:var(--ink)}
.sup-or{display:flex;align-items:center;gap:10px;font-size:12px;color:var(--ink-3);margin:6px 0 2px}
.sup-or::before,.sup-or::after{content:"";flex:1;height:1px;background:var(--line-2)}
@media (max-width:560px){ .sup-live-h{flex-wrap:wrap} .sup-live-h .btn{width:100%} }

/* the board's chart fills the left column, drawn at its real size; the department bar stays put at the bottom
   whichever view is picked (Oct 26, Nick) */
.an-board{align-items:stretch}
.an-board-l{min-height:340px}
.an-board-chart{flex:1;min-height:240px;display:flex;flex-direction:column}
.an-board-chart>.an-chart{flex:1;display:flex;flex-direction:column;min-height:0}
.an-board-chart .an-ch-h{min-height:24px}
.an-svg-wrap.an-fill{flex:1;min-height:200px;position:relative}
.an-svg-wrap.an-fill svg{position:absolute;inset:0;width:100%;height:100%}
.an-board-chart .an-tbl{font-size:13px}

/* the support call's own window (Oct 26) */
.ss-page{position:fixed;inset:0}
.ss-host{max-width:420px;margin:0 auto;padding:22px 20px;display:flex;flex-direction:column;gap:12px;font-size:14px;color:var(--ink)}
.ss-host-h{display:flex;align-items:center;gap:10px}
.ss-host-h h1{font-family:var(--display);font-size:20px;margin:0}
.ss-host p{margin:0}
.ss-big{height:44px;font-size:15px}
.ss-status{font-size:15px}

/* Add to customer, from any email (Oct 26) */
.atc-back{position:fixed;inset:0;z-index:1250;background:rgba(13,19,28,.45);display:flex;align-items:center;justify-content:center;padding:16px}
.atc-box{position:relative;background:var(--surface);border-radius:14px;box-shadow:0 18px 50px rgba(13,19,28,.25);width:min(560px,100%);max-height:calc(100vh - 32px);overflow:auto;padding:18px 20px;display:flex;flex-direction:column;gap:12px;color:var(--ink)}
.atc-box h3{margin:0;font-family:var(--display);font-size:18px}
.atc-new{font-size:12.5px;margin-top:4px;align-self:flex-start}
.atc-box .field{display:flex;flex-direction:column}
.atc-g{gap:10px}
.atc-ok{margin:0;font-size:14px}

/* My Day's right column scrolls with the page, not on its own (Oct 26, Nick: "a middle scroll that needs to be removed") */
.md2-side{position:static;max-height:none;overflow:visible}

/* ===== Calendar (Oct 26, Nick: two calendars, Appointments like Outlook and Jobs by the day they're due) ===== */
main.main .aa-sub .apc-ic{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.apc-title{font-size:14px;white-space:nowrap;min-width:150px;text-align:center}
.apc-h{font-family:var(--display);font-size:16px;margin:0 0 8px}
.apc-wrap{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:14px;align-items:start}
/* the switch and the view bar over the calendar only; the side panel starts level with the calendar (Oct 26, Nick: "the
   toggle is just above the actual calendar itself… these lines line up") */
.apc-wrap > :is(.apc-tabs, .toolbar, .apc-main){grid-column:1}
.apc-wrap > .apc-side{grid-column:2;grid-row:3}
main.main .apc-wrap > .toolbar{margin-bottom:0}
main.main .apc-tabs{margin-bottom:10px}
main.main .apc-tabs + .toolbar{margin-top:0}
.apc-stick{position:sticky;top:0;z-index:5;background:var(--surface)}
.apc-main{padding:0;overflow:hidden}
.apc-side{position:sticky;top:12px}
.apc-tg{--hw:58px;display:flex;flex-direction:column}
.apc-hd,.apc-ad{display:grid;grid-template-columns:var(--hw) repeat(var(--n),minmax(0,1fr));border-bottom:1px solid var(--line)}
.apc-dh{text-align:center;padding:8px 4px;border-left:1px solid var(--line-2);font-size:12px;color:var(--ink-3)}
.apc-dh b{display:block;font-size:18px;color:var(--ink);font-weight:700;line-height:30px;width:30px;margin:2px auto 0;border-radius:50%}
.apc-dh.today span{color:var(--fbs-blue);font-weight:700}
.apc-dh.today b{background:var(--fbs-blue);color:#fff}
.apc-ad > div{border-left:1px solid var(--line-2);padding:4px;display:flex;flex-direction:column;gap:3px;min-width:0}
.apc-ad .apc-adl{border-left:0;font-size:11px;color:var(--ink-3);text-align:right;padding:6px 8px 0 0}
.apc-sc{max-height:min(66vh,620px);overflow-y:auto;overflow-x:hidden}
.apc-body{display:grid;grid-template-columns:var(--hw) minmax(0,1fr);position:relative}
.apc-hrs > div{position:relative;font-size:11px;color:var(--ink-3);text-align:right;padding-right:8px}
.apc-hrs > div span{position:relative;top:-7px;white-space:nowrap}
.apc-hrs > div:first-child span{visibility:hidden}
.apc-cols{display:grid;grid-template-columns:repeat(var(--n),minmax(0,1fr))}
.apc-col{position:relative;border-left:1px solid var(--line-2);cursor:copy}
.apc-col.today{background:color-mix(in srgb,var(--fbs-blue) 3%,var(--surface))}
.apc-slot{border-top:1px solid var(--line-2);box-sizing:border-box}
.apc-slot:hover{background:color-mix(in srgb,var(--fbs-blue) 5%,transparent)}
.apc-now{position:absolute;left:0;right:0;border-top:2px solid var(--danger);z-index:3;pointer-events:none}
.apc-now::before{content:"";position:absolute;left:-5px;top:-6px;width:10px;height:10px;border-radius:50%;background:var(--danger)}
.apc-ev{position:absolute;z-index:2;box-sizing:border-box;border-radius:6px;padding:3px 7px;font-size:12px;line-height:1.3;background:color-mix(in srgb,var(--fbs-blue) 13%,var(--surface));border-left:3px solid var(--fbs-blue);color:var(--ink);overflow:hidden;cursor:grab;user-select:none;touch-action:none;display:flex;flex-direction:column}
.apc-ev b{font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.apc-ev span{color:var(--ink-2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.apc-ev.sg{background:color-mix(in srgb,var(--fbs-orange,#FCB122) 14%,var(--surface));border-left:3px dashed var(--fbs-orange,#FCB122)}
.apc-ev.on{box-shadow:0 0 0 2px var(--fbs-blue)}
.apc-ev.drag{opacity:.85;cursor:grabbing;box-shadow:0 4px 12px rgba(20,29,43,.18);z-index:4}
.apc-ev.ad{position:static;cursor:pointer;font:inherit;font-size:12px;text-align:left;border:0;border-left:3px solid var(--fbs-blue);padding:3px 6px}
.apc-ev.ad.sg{border-left-style:dashed;border-left-color:var(--fbs-orange,#FCB122)}
.apc-rs{position:absolute;left:0;right:0;bottom:0;height:7px;cursor:ns-resize}
.apc-month{padding:12px 14px}
.apc-month .mc-day{cursor:pointer}
.apc-month .mc-ev{border:0;font:inherit;font-size:11.5px;text-align:left;cursor:pointer;background:color-mix(in srgb,var(--fbs-blue) 13%,var(--surface))}
.apc-month .mc-ev.sg{background:color-mix(in srgb,var(--fbs-orange,#FCB122) 18%,var(--surface))}
.apc-jobs{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px;align-items:start}
.apc-day{padding:0;overflow:hidden}
.apc-dayh{display:flex;justify-content:space-between;align-items:baseline;gap:8px;padding:10px 12px;border-bottom:1px solid var(--line)}
.apc-dayh b{font-family:var(--display);font-size:15px;white-space:nowrap}
.apc-dayh span{font-size:12px;color:var(--ink-3);white-space:nowrap}
.apc-day.today .apc-dayh{background:color-mix(in srgb,var(--fbs-blue) 8%,var(--surface));box-shadow:inset 0 -3px 0 var(--fbs-blue)}
.apc-day.late .apc-dayh b{color:var(--danger)}
.apc-none{padding:12px;font-size:12.5px}
.apc-job{display:flex;flex-direction:column;gap:2px;margin:8px;padding:8px 10px;border:1px solid var(--line-2);border-radius:var(--r,8px);text-decoration:none;color:var(--ink);font-size:14px}
.apc-job:hover{border-color:var(--fbs-blue);background:color-mix(in srgb,var(--fbs-blue) 4%,var(--surface))}
.apc-jt{display:flex;justify-content:space-between;align-items:center;gap:6px}
.apc-jt .ordno{color:var(--accent);font-weight:700;white-space:nowrap}
.apc-jt .pill{max-width:150px}
.apc-jc{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.apc-job .sub{font-size:12px;color:var(--ink-3)}
.apc-more{margin:0 12px 10px;font-size:12.5px}
@media (max-width:900px){ .apc-wrap{grid-template-columns:1fr} .apc-side{position:static} .apc-tg{--hw:44px} .apc-ev span{display:none} }
/* My Day: the Appointments / Jobs switch over its calendar (Oct 26) */
/* a two-position switch: two equal halves, the picked one filled (Oct 26, Nick: "just a two position toggle") */
main.main .md-calsw{display:grid!important;grid-template-columns:1fr 1fr;width:100%!important;margin:2px 0 10px;padding:3px!important;gap:0;border-radius:10px!important;background:var(--surface-2)!important;box-shadow:inset 0 0 0 1px var(--line-2)!important}
main.main .md-calsw > button{flex:none!important;width:100%;justify-content:center;padding:7px 10px!important;font-size:13px!important;border-radius:8px!important;box-shadow:none!important;background:transparent!important;color:var(--ink-3)!important}
main.main .md-calsw > button.on{background:var(--surface)!important;color:var(--fbs-blue)!important;box-shadow:0 1px 3px rgba(20,29,43,.14)!important}
.md-late{display:flex;width:100%;justify-content:space-between;align-items:center;border:0;background:color-mix(in srgb,var(--danger) 7%,var(--surface));color:var(--danger);font:inherit;font-size:12.5px;padding:7px 10px;border-radius:8px;cursor:pointer;margin:2px 0 6px}
.md-late span{font-size:12px;color:var(--ink-3)}
main.main .md-calsw > button small{font-size:11px;font-weight:700;min-width:18px;text-align:center;padding:1px 6px;border-radius:10px;background:var(--surface-2);color:var(--ink-3)}
main.main .md-calsw > button.on small{background:var(--fbs-blue);color:#fff}

/* ===== My Day on a phone (Oct 26, Nick OK'd the mockups): today first, five tabs along the bottom ===== */
.md-phone{padding-bottom:78px}
.mdp-pad{padding:4px 0 12px}
.mdp-hi{display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:12.5px;color:var(--ink-3)}
.mdp-h{font-family:var(--display);font-size:24px;font-weight:800;margin:2px 0 12px;line-height:1.15}
.mdp-hrow{display:flex;justify-content:space-between;align-items:center;gap:8px}
.mdp-hrow .mdp-h{margin-bottom:10px}
.mdp-note{font-size:12.5px;color:var(--ink-3)}
.mdp-tiles{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:6px}
.mdp-tiles button{all:unset;box-sizing:border-box;cursor:pointer;background:var(--surface);border:1px solid var(--line-2);border-radius:12px;padding:10px 12px;display:flex;flex-direction:column;gap:1px;box-shadow:0 1px 2px rgba(20,29,43,.04)}
.mdp-tiles b{font-size:24px;font-weight:800;color:var(--ink);line-height:1.1}
.mdp-tiles span{font-size:12px;color:var(--ink-3)}
.mdp-tiles .hot b{color:var(--fbs-blue)}
.mdp-sec{display:flex;justify-content:space-between;font-size:11.5px;font-weight:700;color:var(--ink-3);text-transform:uppercase;letter-spacing:.05em;margin:16px 2px 6px}
.mdp-card{background:var(--surface);border:1px solid var(--line-2);border-radius:12px;overflow:hidden;box-shadow:0 1px 2px rgba(20,29,43,.04)}
.mdp-row{all:unset;box-sizing:border-box;display:flex;gap:10px;align-items:center;width:100%;padding:10px 12px;border-top:1px solid var(--line-2);color:var(--ink);text-decoration:none;cursor:pointer;font-size:14px}
.mdp-card > .mdp-row:first-child,.mdp-card > :first-child .mdp-row{border-top:0}
.mdp-row:active{background:var(--surface-2)}
.mdp-m{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px}
.mdp-m b{font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mdp-m small{font-size:12.5px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mdp-m .mdp-x{text-decoration:line-through;color:var(--ink-3)}
/* the day over the time, so "Wed 8:30am" never runs into the title (Oct 26, Nick's phone) */
.mdp-t{flex:none;width:60px;display:flex;flex-direction:column;line-height:1.25;font-size:12.5px;font-weight:700;color:var(--fbs-blue);white-space:nowrap;overflow:hidden}
.mdp-t small{font-size:11px;font-weight:600;color:var(--ink-3)}
.mdp-chev{color:var(--ink-3);font-size:18px;line-height:1}
.mdp-av{flex:none;width:32px;height:32px;border-radius:50%;background:var(--surface-2);font-size:11px;font-weight:700;color:var(--ink-2);display:grid;place-items:center}
.mdp-ago{flex:none;font-size:12px;color:var(--ink-3);white-space:nowrap;text-align:right;display:flex;flex-direction:column;align-items:flex-end;gap:2px}
.mdp-ago.w{color:var(--warn);font-weight:700}
.mdp-ago i{font-style:normal;font-size:10.5px;font-weight:700;padding:0 6px;border-radius:8px;background:color-mix(in srgb,var(--warn) 15%,var(--surface));color:var(--warn)}
.mdp-box{flex:none;width:22px;height:22px;border:2px solid var(--line);border-radius:7px;background:var(--surface);display:grid;place-items:center;font-size:13px;font-weight:800;color:#fff;cursor:pointer;padding:0}
.mdp-box.on{background:var(--ok);border-color:var(--ok)}
.mdp-due{flex:none;font-size:12px;font-weight:700;color:var(--ink-3);white-space:nowrap}
.mdp-due.r{color:var(--danger)}
.mdp-more{all:unset;box-sizing:border-box;display:block;width:100%;text-align:center;padding:10px;border-top:1px solid var(--line-2);color:var(--fbs-blue);font-weight:700;font-size:13.5px;cursor:pointer}
.mdp-quiet{padding:10px 12px;font-size:13px;color:var(--ink-3)}
.mdp-link{display:block;margin:16px 2px 0;color:var(--fbs-blue);font-weight:700;font-size:13.5px;text-decoration:none;background:none;border:0;padding:0;font-family:inherit;cursor:pointer}
.mdp-sw{display:grid;grid-template-columns:1fr 1fr;background:var(--surface-2);border-radius:11px;padding:3px;margin-bottom:12px;box-shadow:inset 0 0 0 1px var(--line-2)}
.mdp-sw.three{grid-template-columns:1.3fr 1fr 1fr}
.mdp-sw button{all:unset;box-sizing:border-box;cursor:pointer;text-align:center;padding:8px 4px;border-radius:9px;font-weight:700;font-size:13.5px;color:var(--ink-3);white-space:nowrap;display:flex;justify-content:center;align-items:center;gap:5px}
.mdp-sw button.on{background:var(--surface);color:var(--fbs-blue);box-shadow:0 1px 3px rgba(20,29,43,.14)}
.mdp-sw small{font-size:10.5px;font-weight:700;padding:0 6px;border-radius:9px;background:var(--line-2);color:var(--ink-3)}
.mdp-sw .on small{background:var(--fbs-blue);color:#fff}
.mdp-week{display:grid;grid-template-columns:repeat(7,1fr);gap:4px;margin-bottom:6px}
.mdp-week button{all:unset;box-sizing:border-box;cursor:pointer;text-align:center;background:var(--surface);border:1px solid var(--line-2);border-radius:10px;padding:6px 0 4px;font-size:11px;color:var(--ink-3);display:flex;flex-direction:column;align-items:center;gap:1px}
.mdp-week b{font-size:16px;color:var(--ink);font-weight:700}
.mdp-week i{width:5px;height:5px;border-radius:50%}
.mdp-week i.dot{background:var(--fbs-blue)}
.mdp-week .today b{color:var(--fbs-blue)}
.mdp-week .on{border-color:var(--fbs-blue);background:color-mix(in srgb,var(--fbs-blue) 9%,var(--surface))}
.mdp-new{padding:10px 12px;margin:8px 0}
.mdp-dayh{display:flex;justify-content:space-between;align-items:baseline;margin:16px 2px 6px}
.mdp-dayh b{font-family:var(--display);font-size:16px}
.mdp-dayh span{font-size:12px;color:var(--ink-3);white-space:nowrap}
.mdp-blk{background:color-mix(in srgb,var(--fbs-blue) 11%,var(--surface));border-left:3px solid var(--fbs-blue);border-radius:8px;padding:8px 10px;margin:6px 0;display:flex;flex-direction:column;gap:1px}
.mdp-blk b{font-size:14px}
.mdp-blk small{font-size:12.5px;color:var(--ink-2)}
.mdp-free{font-size:12px;color:var(--ink-3);padding:2px 4px}
.mdp-late{all:unset;box-sizing:border-box;cursor:pointer;display:flex;justify-content:space-between;align-items:center;width:100%;background:color-mix(in srgb,var(--danger) 8%,var(--surface));color:var(--danger);border-radius:11px;padding:10px 12px;margin-bottom:8px;font-size:14px}
.mdp-late span{color:var(--ink-3);font-size:12.5px}
.mdp-late + .mdp-card{margin-bottom:8px}
.mdp-row .pill{flex:none;max-width:130px}
.mdp-add{display:flex;gap:8px;margin-bottom:4px}
.mdp-add input{flex:1;min-width:0;height:40px;border:1px solid var(--line);border-radius:10px;padding:0 12px;font:inherit;font-size:14px;background:var(--surface)}
.mdp-bar{position:fixed;left:0;right:0;bottom:0;z-index:60;display:grid;grid-template-columns:repeat(5,1fr);background:var(--surface);border-top:1px solid var(--line);padding:6px 4px calc(6px + env(safe-area-inset-bottom));box-shadow:0 -2px 10px rgba(20,29,43,.06)}
.mdp-bar button{all:unset;box-sizing:border-box;cursor:pointer;position:relative;display:flex;flex-direction:column;align-items:center;gap:2px;font-size:10.5px;font-weight:600;color:var(--ink-3);padding:2px 0}
.mdp-bar svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.mdp-bar button.on{color:var(--fbs-blue);font-weight:800}
.mdp-bar em{position:absolute;top:-3px;left:calc(50% + 6px);font-style:normal;font-size:9.5px;font-weight:800;line-height:15px;min-width:15px;padding:0 4px;border-radius:8px;background:var(--danger);color:#fff;text-align:center}
.an-phone{display:flex;flex-direction:column;gap:12px}
.an-phone .an-k2{grid-template-columns:1fr 1fr}
.fv-ph .fv-tk{margin-top:5px;max-width:180px}
.fv-ph-row{align-items:flex-start}

/* My Day's bottom bar on the Email page: phones only, and gone once an email is open (Oct 26) */
.mdp-only{display:none}
@media (max-width:760px){ .mdp-only{display:block;height:74px} }
html[data-phone-deep] .mdp-only{display:none}
@media (max-width:760px){ body:has(.mdp-only .mdp-bar) .ibx2-ffab{bottom:calc(80px + env(safe-area-inset-bottom))} html[data-phone-deep] body .ibx2-ffab{bottom:calc(18px + env(safe-area-inset-bottom))} }

/* Business on a phone: the sales charts one at a time, swiped left and right (Oct 26, Nick) */
.an-ph-car{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;-webkit-overflow-scrolling:touch;gap:0;border-radius:12px}
.an-ph-car::-webkit-scrollbar{display:none}
.an-ph-slide{flex:0 0 100%;scroll-snap-align:start;box-sizing:border-box;background:var(--surface);border:1px solid var(--line-2);border-radius:12px;padding:10px 12px 10px;height:340px;display:flex;flex-direction:column;overflow:hidden}
.an-ph-h{font-size:13.5px;margin-bottom:6px}
/* every slide the same height: the chart takes the room that's left after what sits under it (the department bar), so
   nothing lands on its labels and no slide has an empty half (Oct 26, Nick's phone) */
.an-ph-body{flex:1;min-height:0;display:flex;flex-direction:column;gap:10px;overflow-y:auto;overflow-x:hidden}
.an-ph-body .an-chart{flex:1;min-height:0;display:flex;flex-direction:column}
.an-ph-body .an-chart .an-ch-h b{display:none}
.an-ph-body .an-svg-wrap.an-fill{flex:1;min-height:140px}
.an-ph-body .an-split{flex:none}
.an-ph-body .an-split-h b{display:none}
.an-ph-body .an-split{margin-top:4px}
.an-ph-body .an-top,.an-ph-body ol{overflow-y:auto}
.an-ph-dots{display:flex;justify-content:center;gap:8px;margin-top:-2px}
.an-ph-dots button{all:unset;cursor:pointer;width:8px;height:8px;border-radius:50%;background:var(--line)}
.an-ph-dots button.on{background:var(--fbs-blue);width:20px;border-radius:4px}
/* the favorites, a card each (bigger, Oct 26) */
.fv-ph-list{display:flex;flex-direction:column;gap:10px}
.fv-ph-card{display:flex;flex-direction:column;gap:10px;background:var(--surface);border:1px solid var(--line-2);border-radius:14px;padding:14px;color:var(--ink);text-decoration:none;box-shadow:0 1px 2px rgba(20,29,43,.04)}
.fv-ph-top{display:flex;gap:12px;align-items:center}
.fv-ph-top .fv-av{width:42px;height:42px;font-size:14px;flex:none}
.fv-ph-who{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.fv-ph-who b{font-size:16.5px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.fv-ph-who small{font-size:12.5px;color:var(--ink-3)}
.fv-ph-who em{font-style:normal;color:var(--danger);font-weight:700}
.fv-ph-money{flex:none;text-align:right;font-weight:800;font-size:15px;display:flex;flex-direction:column;white-space:nowrap}
.fv-ph-money small{font-size:11px;font-weight:500;color:var(--ink-3)}
.fv-ph-job{display:flex;flex-direction:column;gap:2px;border-top:1px solid var(--line-2);padding-top:10px}
.fv-ph-job .fv-tk{max-width:none}
.fv-ph-card .fv-waits{display:flex;gap:6px;flex-wrap:wrap;padding:0}
